        #region grdvDescription_CellClick
        private void grdvDescription_CellClick(object sender, DataGridViewCellEventArgs e)
        {
            try
            {
                if (J_Var.J_pReportEnumIndex == (int)J_Reports.CorrectionStatement ||
                    J_Var.J_pReportEnumIndex == (int)J_Reports.CorrectionLog ||
                    J_Var.J_pReportEnumIndex == (int)J_Reports.ReturnReportCorrection)
                {
                    if (e.RowIndex != -1)
                    {
                        //--------------------------------------------------
                        foreach (DataGridViewRow row in grdvDescription.Rows)
                        {
                            if (row.Cells[0].Value == null || (bool)row.Cells[0].Value == true)
                                row.Cells[0].Value = false;
                        }
                        //--
                        DataGridViewCheckBoxCell cell = (DataGridViewCheckBoxCell)grdvDescription.Rows[e.RowIndex].Cells[0];
                        if (cell.Value == null || (bool)cell.Value == false)
                        {
                            grdvDescription.MultiSelect = false;
                            grdvDescription.Rows[e.RowIndex].Selected = true;
                            cell.Value = true;
                        }
                        else
                        {
                            grdvDescription.Rows[e.RowIndex].Selected = false;
                            cell.Value = false;
                        }
                        //--
                    }
                }
                else if(J_Var.J_pReportEnumIndex == (int)J_Reports.CorrectionStatementQuarterly)
                {
                    if (e.RowIndex != -1)
                    {
                        foreach (DataGridViewRow row in grdvDescription.Rows)
                        {
                            if (row.Cells[0].Value == null || (bool)row.Cells[0].Value == true)
                                row.Cells[0].Value = false;
                        }
                        //--
                        DataGridViewCheckBoxCell cell = (DataGridViewCheckBoxCell)grdvDescription.Rows[e.RowIndex].Cells[0];
                        if (cell.Value == null || (bool)cell.Value == false)
                        {
                            grdvDescription.MultiSelect = false;
                            grdvDescription.Rows[e.RowIndex].Selected = true;
                            cell.Value = true;
                        }
                        else
                        {
                            grdvDescription.Rows[e.RowIndex].Selected = false;
                            cell.Value = false;
                        } 
                        //--
                        DataGridViewCell cellQtr = (DataGridViewCell)grdvDescription.Rows[e.RowIndex].Cells[4];
                        DataGridViewCell cellYr = (DataGridViewCell)grdvDescription.Rows[e.RowIndex].Cells[2];
                        DataGridViewCell cellFormNo = (DataGridViewCell)grdvDescription.Rows[e.RowIndex].Cells[3];
                        //
                        if (Convert.ToString(cellFormNo.Value) == T_FormNo.F24Q)
                            rbnSort3.Text = T_TypeFilter.Employee;
                        else
                            rbnSort3.Text = T_TypeFilter.Deductee;
                        //--
                        //grpSort.Height = 130;
                        if (Convert.ToString(cellQtr.Value) == T_Qtr.Q4 && Convert.ToString(cellFormNo.Value) == T_FormNo.F24Q)
                        {
                            rbnSort4.Visible = true;
                            rbnSort4.Text = T_TypeFilter.SalaryDetails;
                            ////grpSort.Height = 120;
                            //grpSort.Height = grpSort.Height + 20;
                        }
                        else
                        {
                            rbnSort1.Checked = true;
                            rbnSort4.Visible = false;
                            ////grpSort.Height = 120;
                        }
                        //--
                        Quarter = Convert.ToString(cellQtr.Value);
                        FinancialYear = Convert.ToString(cellYr.Value);
                        FormNo = Convert.ToString(cellFormNo.Value);                        
                    }
                }
                else
                {
                    if (e.RowIndex < 0)
                    {
                        //
                        dmlService.J_ExecSql("DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED);
                        chkSelectDeselect.Checked = false;
                        lblSelected.Visible = false;
                        //            
                    }
                    blnExitGrid = true;
                    //if (e.RowIndex != -1)
                    //{
                    //    DataGridViewCheckBoxCell cell = (DataGridViewCheckBoxCell)grdvDescription.Rows[e.RowIndex].Cells[0];
                    //    if (cell.Value == null || (bool)cell.Value == false)
                    //    {
                    //        grdvDescription.MultiSelect = true;
                    //        grdvDescription.Rows[e.RowIndex].Selected = true;
                    //        cell.Value = true;
                    //    }
                    //    else
                    //    {
                    //        grdvDescription.Rows[e.RowIndex].Selected = false;
                    //        cell.Value = false;
                    //    }
                    //}
                }
            }
            catch (Exception err_Handler)
            {
                cmnService.J_UserMessage(err_Handler.Message);

            }
        }
        #endregion

