                        if (chkBox3.Checked == true)
                            strFormSQL = strFormSQL + "'" + T_FormNo.F27EQ + "',";
                        //
                        if (cmnService.J_Right(strFormSQL, 1) == ",")
                            strFormSQL = cmnService.J_Mid(strFormSQL, 0, (strFormSQL.Length - 1));
                        strFormSQL = " TRN_BASIC_INFO.FORM_NO IN (" + strFormSQL + ")";
                    }
