                    strSQL = "SELECT DISTINCT MST_SECTION.SECTION_ID," +
                        "            MST_SECTION.SECTION_NO " +
                        "     FROM   MST_SECTION," +
                        "            TRN_BASIC_INFO," +
                        "            TRN_CHALLAN," +
                        "            TRN_DEDUCTEE_DETAILS " +
                        "     WHERE  TRN_CHALLAN.BASIC_INFO_ID          = TRN_BASIC_INFO.BASIC_INFO_ID " +
                        "     AND    TRN_CHALLAN.CHALLAN_ID             = TRN_DEDUCTEE_DETAILS.CHALLAN_ID " +
                        "     AND    MST_SECTION.SECTION_ID             = TRN_DEDUCTEE_DETAILS.SECTION_ID " +
                        "     AND    TRN_DEDUCTEE_DETAILS.PAYMENT_DATE >= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(mskFromDate) + cmnService.J_DateOperator() + " " +
                        "     AND    TRN_DEDUCTEE_DETAILS.PAYMENT_DATE <= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(mskToDate) + cmnService.J_DateOperator() + " " +
