                        "            MST_SECTION.SECTION_NO " +
                        "     FROM   TRN_DEDUCTEE_DETAILS " +
                        "            INNER JOIN MST_SECTION " +
                        "            ON TRN_DEDUCTEE_DETAILS.SECTION_ID  = MST_SECTION.SECTION_ID " +
                        "     WHERE  " + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatMMYYYY) + " IN (" + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + ") " +
                        "     AND    TRN_DEDUCTEE_DETAILS.CHALLAN_ID = 0" +
                        "     AND    TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = " + lngBasicInfoID + " " +
                        "     ORDER BY MST_SECTION.SECTION_ID ";

                    if (TdsMan.T_PopulateListBox(dmlService.J_pCommand, strSQL, ref clbListBox1) == false)
                        return;

                    grpCheckedListBox1.Visible = true;
                    grpCheckedListBox1.Text = "Select Section No.";
                    grpCheckedListBox1.Location = new Point(650, 44);
                    clbListBox1.Visible = true;
                    //clbListBox1.SelectionMode = SelectionMode.MultiExtended;
                    //
