                    {
                        clbListBox1.SetItemCheckState(i, CheckState.Checked);
                    }
                    //clbListBox1.Set = true;
                    break;
                #endregion
            }
            //
            if (blnExitGrid == false) return;
            if (grdvDescription.RowCount > 0)
            {
                //foreach (DataGridViewColumn column in grdvDescription.Columns )
                //{
                //    if(column.cell
                foreach (DataGridViewRow row in grdvDescription.Rows)
                {
                    //if (row.Cells[0].Value != null && (bool)row.Cells[0].Value == true)
                    if ((bool)row.Cells[0].Selected == true)
                    {
                        //if (row.Cells[0].Value != null && (bool)row.Cells[0].Value == true)
