                        //--
                        if (blnTextGrid == false)
                        {
                            if (dmlService.J_ReturnNoOfRows("SELECT * FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED + " WHERE ITEM_ID = " + cmnService.J_ReturnInt32Value(Convert.ToString(row.Cells[1].Value)), J_QueryType.DirectQuery) == 0)
