                                //                    cmnService.J_ReturnInt32Value(Convert.ToString(row.Cells[1].Value)) + ",'" +
                                //                    cmnService.J_ReplaceQuote(Convert.ToString(row.Cells[2].Value)) + "')";
                                strSQL = "INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED + "(ITEM_ID,ITEM_NAME) VALUES(" +
                                                    cmnService.J_ReturnInt32Value(Convert.ToString(row.Cells[1].Value)) + ",'" +
                                                    cmnService.J_ReplaceQuote(Convert.ToString(row.Cells[3].Value)) + " - " + cmnService.J_ReplaceQuote(Convert.ToString(row.Cells[2].Value)) + "')";
                                dmlService.J_ExecSql(strSQL);
                                //
                                //intCount = intCount + 1;
                            }
                            else
                            {
                                strSQL = "DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED + " WHERE ITEM_ID = " + cmnService.J_ReturnInt32Value(Convert.ToString(row.Cells[1].Value)) + "";
                                dmlService.J_ExecSql(strSQL);
                                //
