                        else
                        {
                            if (dmlService.J_ReturnNoOfRows("SELECT * FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED + " WHERE ITEM_NAME ='" + Convert.ToString(row.Cells[1].Value) + " - " + Convert.ToString(row.Cells[2].Value) + "'", J_QueryType.DirectQuery) == 0)
                            {
                                strSQL = "INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED + "(ITEM_NAME) VALUES('" +
                                                    Convert.ToString(row.Cells[1].Value) + " - " + Convert.ToString(row.Cells[2].Value) + "')";
                                dmlService.J_ExecSql(strSQL);
                            }
                            else
                            {
                                strSQL = "DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED + " WHERE ITEM_NAME ='" + Convert.ToString(row.Cells[1].Value) + " - " + Convert.ToString(row.Cells[2].Value) + "'";
                                dmlService.J_ExecSql(strSQL);
                                //
                                //intCount = intCount - 1;
                            }
                        }
                        //
                    }
                    //else
                    //{
                    //    strSQL = "DELETE FROM TEMP_REPORT_GRID_ITEMS_SELECTED WHERE ITEM_ID = " + cmnService.J_ReturnInt32Value(Convert.ToString(row.Cells[1].Value)) + "";
