        #region txtSearch_TextChanged
        private void txtSearch_TextChanged(object sender, EventArgs e)
        {
            try
            {
                #region COMMENT
                //---------------------------------
                //ADDED BY DHRUB ON 07/02/2014
                //---------------------------------
                //bool blnGridMultipleColumnStyle = false;

                //switch (J_Var.J_pReportEnumIndex)
                //{
                //    case (int)J_Reports.ChallanWiseQueryReport:
                //        blnGridMultipleColumnStyle = rptService.J_pGridMultipleColumnStyle;
                //        if (blnGridMultipleColumnStyle == false)
                //            blnGridMultipleColumnStyle = true;
                //        break;
                //    default:
                //        blnGridMultipleColumnStyle = rptService.J_pGridMultipleColumnStyle;
                //        break;
                //}
                ////----
                #endregion
                //----
                if (chkSelectDeselect.Checked == true)
                {
                    blnSelectDeselect = false;
                    chkSelectDeselect.Checked = false;
                    blnSelectDeselect = true;
                }

                // for single column datagrid
                //if (blnGridMultipleColumnStyle == false)
                if (rptService.J_pGridMultipleColumnStyle == false)
                {
                    if (rptService.J_pGridDataSet == null) return;
                    DataView dvwFilter = rptService.J_pGridDataSet.Tables[0].DefaultView;
                    dvwFilter.RowFilter = rptService.J_pGridDataSet.Tables[0].Columns[1].ColumnName + " like '%" + cmnService.J_ReplaceQuote(txtSearch.Text) + "%'";
                    grdvDescription.DataSource = dvwFilter;
                }
                // for Multiple columns DatagridView
                else
                {
                    rptService.J_SearchOnDataGridView(ref grdvDescription, ref cmbSearch, txtSearch.Text, this.enmSearchType);
                    #region COMMENT
                    ////ADDED BY DHRUB ON 28/01/2014 FOR RECORD REMAIN CHECKED INTO THE GRID AFTER SEARCH 
                    ////-- LOAD SELECTION ON THE GRID
                    //if (chkSelectDeselect.Checked == false)
                    //{
                    //    foreach (DataGridViewRow row in grdvDescription.Rows)
                    //    {
                    //        //ADDED BY DHRUB on 2014/01/29 
                    //        blnDeleteTempGridRecord = true;
                    //        intRecordCount = intRecordCount + 1;
                    //        if (row.Cells[1].Value != null)
                    //        {
                    //            strSQL = "SELECT * FROM TEMP_REPORT_GRID_ITEMS_SELECTED WHERE ITEM_ID = " + cmnService.J_ReturnInt32Value(Convert.ToString(row.Cells[1].Value));
                    //            if (dmlService.J_ReturnNoOfRows(strSQL, J_QueryType.DirectQuery) > 0)
                    //            {
                    //                row.Cells[0].Value = true;
                    //            }
                    //        }
                    //    }
                    //    blnDeleteTempGridRecord = false;
                    //}
                    #endregion
                    //-- LOAD SELECTION ON THE GRID
                    foreach (DataGridViewRow row in grdvDescription.Rows)
                    {
                        if (row.Cells[1].Value != null)
                        {
                            strSQL = "SELECT * FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED + " WHERE ITEM_ID = " + cmnService.J_ReturnInt32Value(Convert.ToString(row.Cells[1].Value));
                            if (dmlService.J_ReturnNoOfRows(strSQL, J_QueryType.DirectQuery) > 0)
                            {
                                blnExitGrid = false;
                                row.Cells[0].Value = true;
                                blnExitGrid = true;
                            }
                        }
                    }
                }
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

