        #region cmbCombo2_SelectedIndexChanged
        private void cmbCombo2_SelectedIndexChanged(object sender, EventArgs e)
        {
            switch (J_Var.J_pReportEnumIndex)
            {

                #region Transactions

                case (int)J_Reports.CertForm16A26Q:
                    if (LOADgrdvDescription(J_Reports.CertForm16A26Q) == false) return;
                    break;
                //-----------------------------------------------

                case (int)J_Reports.CertForm16A27Q:
                    if (LOADgrdvDescription(J_Reports.CertForm16A27Q) == false) return;
                    break;
                //-----------------------------------------------

                case (int)J_Reports.CertForm27D27EQ:
                    if (LOADgrdvDescription(J_Reports.CertForm27D27EQ) == false) return;
                    break;
                //-----------------------------------------------

                case (int)J_Reports.PartyEmployeeWiseDetail:
                    if (cmbCombo2.Text == T_PartyEmployee.Party)
                    {
                        grpCheckBox.Visible = true;
                        grpSort.Visible = true;
                    }
                    else //if (cmbCombo1.Text == T_PartyEmployee.Employee)
                    {
                        grpCheckBox.Visible = false;
                        grpSort.Visible = false;
                    }

                    if (LOADgrdvDescription(J_Reports.PartyEmployeeWiseDetail) == false) return;

                    break;

                case (int)J_Reports.PartyEmployeeWiseSummary:
                    //if (cmbCombo2.Text == T_PartyEmployee.Party)
                    //    grpCheckBox.Visible = true;
                    //else //if (cmbCombo1.Text == T_PartyEmployee.Employee)
                    //    grpCheckBox.Visible = false;
                    if (LOADgrdvDescription(J_Reports.PartyEmployeeWiseSummary) == false) return;

                    break;

                case (int)J_Reports.ChallanReport:
                    //--
                    if (Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) >= T_FinancialYearID.F2013_14ID)
                    {
                        rbnSort4.Visible = false;
                        rbnSort1.Select();
                    }
                    else
                    {
                        rbnSort4.Visible = true;
                        rbnSort1.Select();
                    }
                    //--
                    if (LOADgrdvDescription(J_Reports.ChallanReport) == false) return;
                    break;
                case (int)J_Reports.ChallanWiseQueryReport:
                    //--
                    if (Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) >= T_FinancialYearID.F2013_14ID)
                    {
                        rbnSort4.Visible = false;
                        rbnSort1.Select();
                    }
                    else
                    {
                        rbnSort4.Visible = true;
                        rbnSort1.Select();
                    }
                    if (LOADgrdvDescription(J_Reports.ChallanWiseQueryReport) == false) return;

                    break;

                case (int)J_Reports.DeducteeWiseQueryReport:
                    if (cmbCombo2.Text == T_PartyEmployee.Party)
                    {
                        lblComparisonBoxTitle3.Text = "Rate";
                        grpCheckBox.Visible = true;
                        //
                        grpSort.Visible = true;
                        rbnSort1.Visible = true;
                        rbnSort2.Visible = true;
                        //grpSort.Height = 71;
                        //grpSort.Height = 123;
                    }
                    else //if (cmbCombo1.Text == T_PartyEmployee.Employee)
                    {
                        lblComparisonBoxTitle3.Text = "Cess"; 
                        grpCheckBox.Visible = false;
                        //
                        grpSort.Visible = false;
                    }
                    if (LOADgrdvDescription(J_Reports.DeducteeWiseQueryReport) == false) return;
                    break;

                case (int)J_Reports.CertForm1624Q:
                    //-- GROUP SELECTION
                    if (cmbCombo2.SelectedIndex > 0)
                    {
                        if (TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_EDITION
                            || TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_ULTIMATE_EDITION
                            || TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.PROFESSIONAL_EDITION
                            || TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.COMMERCIAL_LAW_HOUSE //-- 2022/04/11
                                || TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION)
                        {
                            if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) FROM MST_EMPLOYEE_GROUP WHERE COMPANY_ID = " + cmnService.J_GetComboBoxItemId(ref cmbCombo2, cmbCombo2.SelectedIndex)))) > 0)
                            {
                                if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) FROM MST_EMPLOYEE WHERE EMPLOYEE_GROUP_ID > 0 AND COMPANY_ID = " + cmnService.J_GetComboBoxItemId(ref cmbCombo2, cmbCombo2.SelectedIndex)))) > 0)
                                {
                                    //////grpCombo.Height = 130;
                                    lblComboTitle3.Visible = true;
                                    //
                                    cmbCombo3.Visible = true;
                                    lblComboTitle3.Text = "Group Name";
                                    //
                                    strSQL = "SELECT EMPLOYEE_GROUP_ID, EMPLOYEE_GROUP_DESC FROM MST_EMPLOYEE_GROUP WHERE COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " ";
                                    dmlService.J_PopulateComboBox(strSQL, ref cmbCombo3, TDSMAN.Classes.TDSMAN.T_AllEmployeesGroupSelectionCertificates);
                                }
                                else
                                {
                                    strSQL = "SELECT EMPLOYEE_GROUP_ID, EMPLOYEE_GROUP_DESC FROM MST_EMPLOYEE_GROUP WHERE 1 = 2";
                                    dmlService.J_PopulateComboBox(strSQL, ref cmbCombo3);
                                    //
                                    lblComboTitle3.Visible = false;
                                    cmbCombo3.Visible = false;
                                    //
                                    //////grpCombo.Height = 100;
                                }
                            }
                            else
                            {
                                strSQL = "SELECT EMPLOYEE_GROUP_ID, EMPLOYEE_GROUP_DESC FROM MST_EMPLOYEE_GROUP WHERE 1 = 2";
                                dmlService.J_PopulateComboBox(strSQL, ref cmbCombo3);
                                //
                                lblComboTitle3.Visible = false;
                                cmbCombo3.Visible = false;
                                //////grpCombo.Height = 100;
                            }
                        }
                    }
                    //-----------------------------------------------
                    if (LOADgrdvDescription(J_Reports.CertForm1624Q) == false) return; 
                    rbnExport_CheckedChanged(sender, e);
                    //ADDED BY ANIK ON 20/03/2014 FOR INITIALIZE THE COMPANY PLACE AND CURRENT DATE
                    //--------------------------------------------------------------------------------
                    strSQL = @"SELECT MST_COMPANY.ADDRESS3
                                   FROM   MST_COMPANY
                                   WHERE  MST_COMPANY.COMPANY_ID=" + cmnService.J_GetComboBoxItemId(ref cmbCombo2, cmbCombo2.SelectedIndex) + " ";
                    txtTextBox1.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                        
                    break;
                case (int)J_Reports.CertForm1624QPartB:

                    //-- GROUP SELECTION
                    if (cmbCombo2.SelectedIndex > 0)
                    {
                        if (TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_EDITION
                            || TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_ULTIMATE_EDITION
                            || TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.PROFESSIONAL_EDITION
                            || TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.COMMERCIAL_LAW_HOUSE //-- 2022/04/11
                                || TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION)
                        {
                            if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) FROM MST_EMPLOYEE_GROUP WHERE COMPANY_ID = " + cmnService.J_GetComboBoxItemId(ref cmbCombo2, cmbCombo2.SelectedIndex)))) > 0)
                            {
                                if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) FROM MST_EMPLOYEE WHERE EMPLOYEE_GROUP_ID > 0 AND COMPANY_ID = " + cmnService.J_GetComboBoxItemId(ref cmbCombo2, cmbCombo2.SelectedIndex)))) > 0)
                                {
                                    grpCombo.Height = 130;
                                    lblComboTitle3.Visible = true;
                                    //
                                    cmbCombo3.Visible = true;
                                    lblComboTitle3.Text = "Group Name";
                                    //
                                    strSQL = "SELECT EMPLOYEE_GROUP_ID, EMPLOYEE_GROUP_DESC FROM MST_EMPLOYEE_GROUP WHERE COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " ";
                                    dmlService.J_PopulateComboBox(strSQL, ref cmbCombo3, TDSMAN.Classes.TDSMAN.T_AllEmployeesGroupSelectionCertificates);
                                }
                                else
                                {
                                    strSQL = "SELECT EMPLOYEE_GROUP_ID, EMPLOYEE_GROUP_DESC FROM MST_EMPLOYEE_GROUP WHERE 1 = 2";
                                    dmlService.J_PopulateComboBox(strSQL, ref cmbCombo3);
                                    //
                                    lblComboTitle3.Visible = false;
                                    cmbCombo3.Visible = false;
                                    //
                                    grpCombo.Height = 100;
                                }
                            }
                            else
                            {
                                strSQL = "SELECT EMPLOYEE_GROUP_ID, EMPLOYEE_GROUP_DESC FROM MST_EMPLOYEE_GROUP WHERE 1 = 2";
                                dmlService.J_PopulateComboBox(strSQL, ref cmbCombo3);
                                //
                                lblComboTitle3.Visible = false;
                                cmbCombo3.Visible = false;
                                grpCombo.Height = 100;
                            }
                        }
                    }
                    //-----------------------------------------------
                    if (LOADgrdvDescription(J_Reports.CertForm1624QPartB) == false) return;
                    rbnExport_CheckedChanged(sender, e);
                    //ADDED BY DHRUB ON 06/01/2014 FOR INITIALIZE THE COMPANY PLACE AND CURRENT DATE
                    //--------------------------------------------------------------------------------
                    strSQL = @"SELECT MST_COMPANY.ADDRESS3
                                   FROM   MST_COMPANY
                                   WHERE  MST_COMPANY.COMPANY_ID=" + cmnService.J_GetComboBoxItemId(ref cmbCombo2, cmbCombo2.SelectedIndex) + " ";
                    txtTextBox1.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));

                    break;
                //-----------------------------------------------
                case (int)J_Reports.DeducteeEntriesWithoutChallan:
                    if (LOADgrdvDescription(J_Reports.DeducteeEntriesWithoutChallan) == false) return;

                    break;
                //-- 2016/06/24
                case (int)J_Reports.QuarterWiseReport:
                    //-- 
                    if (cmbCombo3.Text != "" && cmbCombo4.Text != "")
                        if (LOADgrdvDescription(J_Reports.QuarterWiseReport) == false) return;
                    break; 

                case (int)J_Reports.EmailDetailReport:
                    if (LOADgrdvDescription(J_Reports.EmailDetailReport) == false) return;
                    break;

                    #endregion
            }
        }
