                    // ADD/REPLACE "Deductee/Employee"
                    if (cmbCombo3.Text == T_FormNo.F24Q)
                        rbnSort3.Text = T_TypeFilter.Employee;
                    else if (cmbCombo3.Text == T_FormNo.F27EQ)
                        rbnSort3.Text = T_TypeFilter.Collectee;
                    else
                        rbnSort3.Text = T_TypeFilter.Deductee;
                    //--
                    // ADD/REPLACE "SalaryDetails"
                    if (cmbCombo3.Text == T_FormNo.F24Q && cmbCombo4.Text == T_Qtr.Q4)
                    {
                        //////grpSort.Height = 121;
                        rbnSort4.Visible = true;
                        rbnSort4.Text = T_TypeFilter.SalaryDetails;
                    }
                    else
                    {
                        //////grpSort.Height = 121;
                        rbnSort4.Visible = false;
                        //
                        if(rbnSort4.Checked == true)
                            rbnSort1.Checked = true;
                    }
                    //-- 2016/06/24
                    //-- 
                    if (cmbCombo3.Text != "" && cmbCombo4.Text != "")
                        if (LOADgrdvDescription(J_Reports.QuarterWiseReport) == false) return;
                    break;

                case (int)J_Reports.DeducteeEntriesWithoutChallan:
                    if (LOADgrdvDescription(J_Reports.DeducteeEntriesWithoutChallan) == false) return;

                    break;
                
                #endregion
            }
