        #region grdvDescription1_CellClick
        private void grdvDescription1_CellClick(object sender, DataGridViewCellEventArgs e)
        {
            try
            {
                if (J_Var.J_pReportEnumIndex == (int)J_Reports.CorrectionCertForm16A26Q)
                {
                    if (e.RowIndex != -1)
                    {
                        //--------------------------------------------------
                        foreach (DataGridViewRow row in grdvDescription1.Rows)
                        {
                            if (row.Cells[0].Value == null || (bool)row.Cells[0].Value == true)
                                row.Cells[0].Value = false;
                        }
                        //--
                        DataGridViewCheckBoxCell cell = (DataGridViewCheckBoxCell)grdvDescription1.Rows[e.RowIndex].Cells[0];
                        if (cell.Value == null || (bool)cell.Value == false)
                        {
                            grdvDescription1.MultiSelect = false;
                            grdvDescription1.Rows[e.RowIndex].Selected = true;
                            blnExitGrid = false; 
                            cell.Value = true;
                            blnExitGrid = true;
                        }
                        else
                        {
                            grdvDescription1.Rows[e.RowIndex].Selected = false;
                            cell.Value = false;
                        }
                        //--
                    }
                }
                else if (J_Var.J_pReportEnumIndex == (int)J_Reports.CorrectionCertForm16A27Q)
                {
                    if (e.RowIndex != -1)
                    {
                        //--------------------------------------------------
                        foreach (DataGridViewRow row in grdvDescription1.Rows)
                        {
                            if (row.Cells[0].Value == null || (bool)row.Cells[0].Value == true)
                                row.Cells[0].Value = false;
                        }
                        //--
                        DataGridViewCheckBoxCell cell = (DataGridViewCheckBoxCell)grdvDescription1.Rows[e.RowIndex].Cells[0];
                        if (cell.Value == null || (bool)cell.Value == false)
                        {
                            grdvDescription1.MultiSelect = false;
                            grdvDescription1.Rows[e.RowIndex].Selected = true;
                            //blnExitGrid = false; 
                            cell.Value = true;
                            //blnExitGrid = true;
                        }
                        else
                        {
                            grdvDescription1.Rows[e.RowIndex].Selected = false;
                            cell.Value = false;
                        }
                        //--
                    }
                }
                else if (J_Var.J_pReportEnumIndex == (int)J_Reports.CorrectionCertForm27D27EQ)
                {
                    if (e.RowIndex != -1)
                    {
                        //--------------------------------------------------
                        foreach (DataGridViewRow row in grdvDescription1.Rows)
                        {
                            if (row.Cells[0].Value == null || (bool)row.Cells[0].Value == true)
                                row.Cells[0].Value = false;
                        }
                        //--
                        DataGridViewCheckBoxCell cell = (DataGridViewCheckBoxCell)grdvDescription1.Rows[e.RowIndex].Cells[0];
                        if (cell.Value == null || (bool)cell.Value == false)
                        {
                            grdvDescription1.MultiSelect = false;
                            grdvDescription1.Rows[e.RowIndex].Selected = true;
                            //blnExitGrid = false; 
                            cell.Value = true;
                            //blnExitGrid = true;
                        }
                        else
                        {
                            grdvDescription1.Rows[e.RowIndex].Selected = false;
                            cell.Value = false;
                        }
                        //--
                    }
                }
                else
                {
                    if (e.RowIndex != -1)
                    {
                        DataGridViewCheckBoxCell cell = (DataGridViewCheckBoxCell)grdvDescription1.Rows[e.RowIndex].Cells[0];
                        if (cell.Value == null || (bool)cell.Value == false)
                        {
                            grdvDescription1.MultiSelect = true;
                            grdvDescription1.Rows[e.RowIndex].Selected = true;
                            cell.Value = true;
                        }
                        else
                        {
                            grdvDescription1.Rows[e.RowIndex].Selected = false;
                            cell.Value = false;
                        }
                    }
                }                
            }
            catch (Exception err_Handler)
            {
                cmnService.J_UserMessage(err_Handler.Message);

            }
        }
