                    //-----------------------------------------------------------------------------------------
                    strOutputFolderPath = cmnService.J_OpenFolderDialog("Please choose the Traces Certificate path.");
                    if (strOutputFolderPath == "")
                    {
                        return;
                    }
                    //------------------------------------------------------------------------------------------
                    txtCertificatePath.Text = strOutputFolderPath.Trim();
                    break;
                #endregion
            }
        }
