        #region chkNewSelectDeselect_CheckedChanged
        private void chkNewSelectDeselect_CheckedChanged(object sender, System.EventArgs e)
        {
            try
            {
                if (grdvNewDescription.Visible == false) { chkSelectDeselect.Checked = false; return; }
                if (blnSelectDeselect == false) return;
                //--
                this.Cursor = Cursors.WaitCursor;
                blnDeleteTempGridRecord = true;
                foreach (DataGridViewRow row in grdvNewDescription.Rows)
                {
                    if (chkNewSelectDeselect.Checked == true)//checked all checkbox
                    {
                        if (row.Cells[0].Value == null || (bool)row.Cells[0].Value == false)
                        {
                            row.Cells[0].Value = true;
                        }
                    }
                    else//Unchecked all checkbox
                    {
                        if (row.Cells[0].Value == null || (bool)row.Cells[0].Value == true)
                        {
                            blnExitGrid = false;
                            row.Cells[0].Value = false;
                            blnExitGrid = false;
                        }
                        strSelectedLabel = "";
                    }
                }
                blnDeleteTempGridRecord = false;

                //ADDED BY DHRUB ON 07/02/2014
                if ((blnDeleteTempGridRecord == false) && (grdvNewDescription.Rows.Count > 0))
                    SelectedGridItemsWithSearchData(cmnService.J_GenerateDataGridViewSelectedId(grdvNewDescription));
