                            //-- Modified On 25/10/2017 --
                            lblCertificateShowSelected.Visible = true;
                            lblCertificateShowSelected.Text = intCount + " record(s) selected";
                            //----------------------------
                        }
                        else
                            lblCertificateShowSelected.Visible = false;
                        //--
                    }

