        #region USER DEFINED FUNCTION

        #region ValidateFields
        public bool ValidateFields(J_Reports enmReport)
        {
            try
            {
                switch (enmReport)
                {
                    //==============================================================
                    //-- Start Master Listing Reports ------------------------------
                    //==============================================================
                    //-- Developed By ----------------------------------------------
                    //==============================================================
                    case J_Reports.Listing:
                        break;

                    //==============================================================
                    //-- End Master Listing Reports --------------------------------
                    //==============================================================
                    //==============================================================
                    //-- Start Master Reports --------------------------------------
                    //==============================================================
                    //-- Developed By ----------------------------------------------
                    //==============================================================
                    case J_Reports.Master:
                        break;

                    //==============================================================
                    //-- End Master Reports ----------------------------------------
                    //==============================================================
                    //-- Start Transaction Reports ---------------------------------
                    //==============================================================
                    //-- Developed By ----------------------------------------------
                    //==============================================================
                    case J_Reports.Transaction:
                        break;


                    case J_Reports.ReceiptNoMaster:
                        if (cmbCombo1.SelectedIndex <= 0)
                        {
                            cmnService.J_UserMessage("Company - Cannot be Blank");
                            cmbCombo1.Select();
                            return false;
                        }
                        break;
                        
                    case J_Reports.Form24QSDComparisionReport:
                        if (cmbCombo2.Text == "")
                        {
                            cmnService.J_UserMessage("Financial Year - Cannot be Blank");
                            cmbCombo2.Select();
                            return false;
                        }
                        if (cmbCombo2.SelectedIndex <= 0)
                        {
                            cmnService.J_UserMessage("Financial Year - Invalid");
                            cmbCombo2.Select();
                            return false;
                        }
                        //-------------------------------------------------
                        if (cmbCombo1.Text == "")
                        {
