        #region SetProgressBar
        private void SetProgressBar()
        {
            for (int i = 0; i < 100; i++)
            {
                if (i != 90)
                    ((ToolStripProgressBar)J_Var.frmMain.stbMessage.Items[(int)J_PanelIndex.e06_ProgressBar]).Value = i;
                else
                    break;
                Thread.Sleep(100);
            }
        }
        #endregion

        #region ThreadTask
        private void ThreadTask()
        {
            Invoke(new MyDelegate(SetProgressBar));
        }
        #endregion

        #region LOADgrdvDescription
        public bool LOADgrdvDescription(J_Reports enmReport)
        {
            blPartPrinting = false; intPartPrinting = 0; intTotalRowCount = 0;
            try
            {
                //
                dmlService.J_ExecSql("DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED);
                lblSelected.Visible = false;
                //
                lblCertificateShowSelected.Visible = false;   //-- Modified By Abhishek Dey On 26/10/2017 --//
                J_Var.J_pReportEnumIndex = (int)enmReport;
                //
                switch (enmReport)
                {
                    //case J_Reports.CertForm16A26Q:
                    //    break;
                    #region Transactions
                    //--
                    case J_Reports.CertForm16A26Q:
                        #region CertForm16A26Q
                        //-----------------------------------------------
                        //if (cmbCombo1.SelectedIndex < 0) return false;

                        //if (cmbCombo2.SelectedIndex < 0) return false;

                        //if (cmbCombo3.SelectedIndex < 0) return false;
                        //+++++++++++++++++++++++++++++++++++++++++++++++++++++
                        //-- ADDED BY DHRUB ON 2015-09-15
                        //+++++++++++++++++++++++++++++++++++++++++++++++++++++
                        if (cmbCombo1.SelectedIndex <= 0 || cmbCombo2.SelectedIndex < 0 || cmbCombo3.SelectedIndex <= 0)
                        {
                            rbnScreen.Checked = true;
                            grpPrint.Enabled = false;
                            return false;
