        #region Report_Title_Wise_BookMark
        //ADDED BY DHRUB FOR BOOK MARK DETAILS ON 05/12/2013
        public void ReportTitleWiseBookMark(J_Reports enmReport)
        {
            try
            {
                //Declare the Data Reader 
                IDataReader drdBookMark = null;

                string strFormNo = "";
                string strFAYear = "";
                string strCompanyName = "";
                string strQuarter = "";

                J_Var.J_pReportEnumIndex = (int)enmReport;
                //----
                switch (enmReport)
                {
                    #region Transaction

                    case J_Reports.CertForm1624Q:
                        if (dmlService.J_IsRecordExist("MST_BOOKMARK_DETAIL") == true)
                        {
                            strSQL = @"SELECT           MST_BOOKMARK_DETAIL.ASST_ID,
                                                        MST_ASSESSMENT.FA_YEAR,
                                                        MST_BOOKMARK_DETAIL.QUARTER,
                                                        MST_BOOKMARK_DETAIL.FORM_NAME,
                                                        MST_BOOKMARK_DETAIL.COMPANY_ID,
                                                        MST_COMPANY.COMPANY_NAME + ' [' + MST_COMPANY.TAN_NO + ']' AS COMPANY_NAME ,
                                                        MST_BOOKMARK_DETAIL.LOG_DATE,
                                                        MST_COMPANY.PAN_NO 
                                       FROM             MST_BOOKMARK_DETAIL,
                                                        MST_COMPANY,
                                                        MST_ASSESSMENT
                                       WHERE            MST_BOOKMARK_DETAIL.COMPANY_ID=MST_COMPANY.COMPANY_ID
                                       AND              MST_BOOKMARK_DETAIL.ASST_ID= MST_ASSESSMENT.ASST_ID
                                       AND              MST_BOOKMARK_DETAIL.FORM_NAME = '" + T_FormNo.F24Q + "'" +
                                     " ORDER BY         MST_BOOKMARK_DETAIL.LOG_DATE  DESC";

                            drdBookMark = dmlService.J_ExecSqlReturnReader(strSQL);
                        }
                        if (drdBookMark == null)
                        {
                            blnCheck = false;
                            return;
                        }
                        while (drdBookMark.Read())
                        {
                            //--------------------------------------
                            //INITIALIZE FA_YEAR
                            strFAYear = Convert.ToString(drdBookMark["FA_YEAR"]);

                            //INITIALIZE COMAPNY
                            strCompanyName = Convert.ToString(drdBookMark["COMPANY_NAME"]);

                            //
                            blnCheck = true;
                            //chkSelectDeselect.Checked = true;
                        }
                        drdBookMark.Close();
                        drdBookMark.Dispose();
                        //
                        cmbCombo1.Text = strFAYear;
                        cmbCombo2.Text = strCompanyName;
                        //--------------------------------------------------------------------------------
                        //ADDED BY DHRUB ON 06/01/2014 FOR INITIALIZE THE COMPANY PLACE AND CURRENT DATE
                        //--------------------------------------------------------------------------------
                        strSQL = @"SELECT MST_COMPANY.ADDRESS3
                                   FROM   MST_COMPANY
                                   WHERE  MST_COMPANY.COMPANY_ID=" + cmnService.J_GetComboBoxItemId(ref cmbCombo2, cmbCombo2.SelectedIndex) + " ";
                        txtTextBox1.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                        //--
                        if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                        {
                            strSQL = @"SELECT Format (NOW()," + "\"dd/MM/yyyy\"" + ")";
                            txtTextBox2.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                        }
                        else if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                        {
                            txtTextBox2.Text = J_ReturnServerDate();
                        }
                        //--
                        break;
                    case J_Reports.CertForm1624QPartB:
                        if (dmlService.J_IsRecordExist("MST_BOOKMARK_DETAIL") == true)
                        {
                            strSQL = @"SELECT           MST_BOOKMARK_DETAIL.ASST_ID,
                                                        MST_ASSESSMENT.FA_YEAR,
                                                        MST_BOOKMARK_DETAIL.QUARTER,
                                                        MST_BOOKMARK_DETAIL.FORM_NAME,
                                                        MST_BOOKMARK_DETAIL.COMPANY_ID,
                                                        MST_COMPANY.COMPANY_NAME + ' [' + MST_COMPANY.TAN_NO + ']' AS COMPANY_NAME ,
                                                        MST_BOOKMARK_DETAIL.LOG_DATE,
                                                        MST_COMPANY.PAN_NO 
                                       FROM             MST_BOOKMARK_DETAIL,
                                                        MST_COMPANY,
                                                        MST_ASSESSMENT
                                       WHERE            MST_BOOKMARK_DETAIL.COMPANY_ID=MST_COMPANY.COMPANY_ID
                                       AND              MST_BOOKMARK_DETAIL.ASST_ID= MST_ASSESSMENT.ASST_ID
                                       AND              MST_BOOKMARK_DETAIL.FORM_NAME = '" + T_FormNo.F24Q + "'" +
                                     " ORDER BY         MST_BOOKMARK_DETAIL.LOG_DATE  DESC";

                            drdBookMark = dmlService.J_ExecSqlReturnReader(strSQL);
                        }
                        if (drdBookMark == null)
                        {
                            blnCheck = false;
                            return;
                        }
                        while (drdBookMark.Read())
                        {
                            //--------------------------------------
                            //INITIALIZE FA_YEAR
