        #region SelectedGridItemsWithSearchData
        public void SelectedGridItemsWithSearchData(string SelectedGridItemID)
        {
            //
            DataSet dsSelectedGridData;
            //
            string[] strGridItem = SelectedGridItemID.Split(',');

            //------------DHRUB ON 05/02/2014
            //string strSelectedGridItemsWithSearchTEMP = "";

            strSQL = "SELECT Count(*) FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED;
            if (Convert.ToInt64(dmlService.J_ExecSqlReturnScalar(strSQL)) > Convert.ToInt64(strGridItem.Length))
            {
                dsSelectedGridData = new DataSet();

                strSQL = "SELECT ITEM_ID,ITEM_DETAIL FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED;
                dsSelectedGridData = dmlService.J_ExecSqlReturnDataSet(strSQL);
                for (int i = 0; i <= dsSelectedGridData.Tables[0].Rows.Count - 1; i++)
                {
                    strSelectedGridItemsWithSearch = strSelectedGridItemsWithSearch + Convert.ToString(dsSelectedGridData.Tables[0].Rows[i]["ITEM_ID"]) + ",";
                }
                if (strSelectedGridItemsWithSearch != "")
                    strSelectedGridItemsWithSearch = strSelectedGridItemsWithSearch.Substring(0, (strSelectedGridItemsWithSearch.Length - 1));
            }
            else
                strSelectedGridItemsWithSearch = cmnService.J_GenerateDataGridViewSelectedId(grdvDescription);

            string[] strTotalGridItems = strSelectedGridItemsWithSearch.Split(',');

            //if (Convert.ToInt64(strTotalGridItems.Length) > Convert.ToInt64(SelectedGridItemID.Length))
            //    strSelectedGridItemsWithSearch = strSelectedGridItemsWithSearchTEMP;

        }
