        #region PrintReceiptNoMasterList
        private void PrintReceiptNoMasterList()
        {
            strQueryString = "SELECT TRN_BASIC_INFO.BASIC_INFO_ID  AS BASIC_INFO_ID," +
                      "              MST_ASSESSMENT.FA_YEAR        AS FA_YEAR," +
                      "              TRN_BASIC_INFO.FORM_NO        AS FORM_NO," +
                      "              TRN_BASIC_INFO.QTR            AS QTR," +
                      "              MST_COMPANY.COMPANY_NAME      AS COMPANY_NAME," +
                      "              MST_COMPANY.TAN_NO            AS TAN_NO," +
                      "              TRN_BASIC_INFO.PRN_NO         AS TOKEN_NO," +
                      "              " + cmnService.J_SQLDBFormat(cmnService.J_SQLDBFormat("TRN_BASIC_INFO.DATE_OF_FILING", J_SQLColFormat.DateFormatDDMMYYYY), J_SQLColFormat.ConvertToString) + " AS DATE_OF_FILING," +
                      "              TRN_BASIC_INFO.RECEIPT_NO     AS RECEIPT_NO " +
                      "       FROM   TRN_BASIC_INFO," +
                      "              MST_COMPANY," +
                      "              MST_ASSESSMENT " +
                      "       WHERE  TRN_BASIC_INFO.COMPANY_ID = MST_COMPANY.COMPANY_ID " +
                      "       AND    TRN_BASIC_INFO.ASST_ID    = MST_ASSESSMENT.ASST_ID ";
                      
            if (cmbCombo1.SelectedIndex > 0)
                strQueryString = strQueryString + " AND TRN_BASIC_INFO.COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " ";

            strQueryString = strQueryString + " ORDER BY MST_ASSESSMENT.FA_YEAR, TRN_BASIC_INFO.QTR, MST_COMPANY.COMPANY_NAME, TRN_BASIC_INFO.FORM_NO";
            crReceiptNoMasterList rptReceiptNoMasterList = new crReceiptNoMasterList();
            rptcls = (ReportClass)rptReceiptNoMasterList;

            //TextObject objtxtValue;
            string[,] strArry = { { "txtReportTitle", "Receipt No. List" } };
            rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
        }
