                                                   {"MST_EMPLOYEE.CATEGORY = ''", "F", "", "T"}};



            strQueryString = "SELECT MST_COMPANY.COMPANY_ID," +
                "                    MST_COMPANY.COMPANY_NAME," +
                "                    MST_COMPANY.TAN_NO," +
                "                    MST_EMPLOYEE.EMPLOYEE_ID," +
                "                    MST_EMPLOYEE.EMPLOYEE_NAME," +
                "                    MST_EMPLOYEE.EMPLOYEE_PAN," +
                "                    MST_EMPLOYEE.DESIGNATION, " +
                " " + cmnService.J_SQLDBFormat(strShowHelpEmployeeMatrix, J_SQLColFormat.Case_End) + " AS CATEGORY, " +
                "                    MST_EMPLOYEE.EMPLOYEE_REF " +
