                strQueryString = "SELECT     MST_DEDUCTEE.DEDUCTEE_ID," +
                                 "           MST_DEDUCTEE.DEDUCTEE_NAME," +
                                 "           " + cmnService.J_SQLDBFormat(strShowHelpEmployeeMatrix, J_SQLColFormat.Case_End) + " AS DEDUCTEE_CODE, " +
                                 "           MST_DEDUCTEE.DEDUCTEE_PAN," +
                                 "           MST_DEDUCTEE.ADDRESS1," +
                                 "           MST_DEDUCTEE.ADDRESS2," +
                                 "           MST_DEDUCTEE.ADDRESS3," +
                                 "           MST_DEDUCTEE.ADDRESS4," +
                                 "           MST_DEDUCTEE.ADDRESS5," +
                                 "           " + cmnService.J_SQLDBFormat("MST_STATE.STATE_NAME", J_ColumnType.String, J_SQLColFormat.NullCheck) + " AS STATE_NAME," +
                                 "           MST_DEDUCTEE.PIN_CODE," +
                                 "           MST_DEDUCTEE.MOBILE_NO," +
                                 "           MST_DEDUCTEE.EMAIL " +
                                 "FROM       MST_DEDUCTEE " +
