                                 "       MST_DEDUCTEE.MOBILE_NO," +
                                 "       MST_DEDUCTEE.EMAIL " +
                                 "FROM   ((((MST_DEDUCTEE " +
                                 "INNER JOIN TRN_DEDUCTEE_DETAILS " +
                                 "   ON TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_DEDUCTEE.DEDUCTEE_ID) " +
                                 "INNER JOIN TRN_BASIC_INFO " +
                                 "   ON TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID) " +
                                 "INNER JOIN MST_COMPANY " +
                                 "   ON TRN_BASIC_INFO.COMPANY_ID          = MST_COMPANY.COMPANY_ID) " +
                                 "LEFT JOIN MST_STATE " +
                                 "   ON MST_DEDUCTEE.STATE_ID              = MST_STATE.STATE_ID) " +
                                 "WHERE TRN_BASIC_INFO.FORM_NO            <> '" + T_FormNo.F24Q + "'" +
                                 "AND   TRN_BASIC_INFO.COMPANY_ID  = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex));

                strSQL = "SELECT TAN_NO FROM MST_COMPANY WHERE COMPANY_ID=" + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex));

