                    strTanNo = "All Deductors";
                    strHeading = "";
                }
                ////SETTING REPORT TITLE
                //strArry = new string[,] { { "txtReportTitle", "Deductee List (With Address)" },
                //                          { "txtTanNo", strTanNo },  
                //                          { "txtCompanyName", strHeading }};

