                                      { "HeaderTAN", strTanNo },
                                      { "HeaderReportCD", strHeading }
                                        };

                J_PreviewReportRDLC("\\Reports\\crCompanyWiseDeducteeListWithAddress.rdlc", "DataSet1", strQueryString, strArry);

            } // IF WITHOUT ADDRESS
            else if (rbnSort2.Checked == true)
            {

                //crCompanyWiseDeducteeListWithoutAddress rptCompanyWiseDeducteeList1 = new crCompanyWiseDeducteeListWithoutAddress();
                //rptcls = (ReportClass)rptCompanyWiseDeducteeList1;


                if (cmbCombo1.SelectedIndex > 0)
                {
                    strHeading = cmnService.J_Left(cmbCombo1.Text, cmbCombo1.Text.Length - 12);// cmbCombo1.Text;
                    strTanNo = "TAN : " + cmnService.J_Left(cmnService.J_Right(cmbCombo1.Text, 11), 10);
                }
                else
                {
                    strTanNo = "All Deductors";
                    strHeading = " ";
                }
                ////SETTING REPORT TITLE
                //strArry = new string[,] { { "txtReportTitle", "Deductee List" },
                //                          { "txtTanNo", strTanNo }, 
                //                          { "txtCompanyName", strHeading }};

