                                      { "HeaderReportCD", "Deductee List" }
                                        };

                J_PreviewReportRDLC("\\Reports\\crCompanyWiseDeducteeListWithoutAddress.rdlc", "DataSet1", strQueryString, strArry);
            }
            //
            //rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);

        }


