                        rptcls.OpenSubreport("crSubRptChallanEntry").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSubRptChallanEntry).Tables[0]);

                        //--
                        //GENERATE PDF FILE 
                        if (rptService.J_ExportReport(ref rptcls, this, strQueryString, T_ExportReportFormat.PortableDocFormat, strDeducteeId, strGeneratePDFPath) == false)
                        {
                            Directory.Delete(strGeneratePDFPath);
                            txtOutputFolderPath.Select();
                            return;
                        }
                        //--
                        PdfReader pdfReader = new PdfReader(Path.Combine(strGeneratePDFPath, strDeducteeId + ".pdf"));
                        int numberOfPages = pdfReader.NumberOfPages;
                        //--
                        //----------------------------------------------------------------------------------------
                        //Creating a different filename if file with same name exists in the selected folder
                        //----------------------------------------------------------------------------------------
                        if (rbnExport.Checked == true)
                        {
                            //-- 2015-01-06
                            if (Create_Signature(PDFSign,
                                                Path.Combine(strGeneratePDFPath, strDeducteeId + ".pdf"),
                                                Path.Combine(strSignPDFPath, strEmployeePAN) + ".pdf",
                                                txtSignaturePassword.Text,
                                                400,
                                                10,
                                                100,
                                                50,
                                                numberOfPages) == false)
                            {
                                File.Delete(Path.Combine(strGeneratePDFPath, strDeducteeId) + ".pdf");
                                Directory.Delete(strGeneratePDFPath);
                                txtSignaturePath.Select();
                                return;
                            }
                        }
                        else
                        {
                            int intIncrement = 0;
                            do
                            {
                                if (cmnService.J_IsFileExist(Path.Combine(txtOutputFolderPath.Text, strEmployeePAN) + ".pdf") == true)
                                {
                                    intIncrement++;
                                    strEmployeePAN = strEmployeePAN.Substring(0, 10) + "_" + intIncrement;
                                }

                            } while (cmnService.J_IsFileExist(Path.Combine(txtOutputFolderPath.Text, strEmployeePAN) + ".pdf") == true);
                            //--------------------------------------------------------------------------------------
                            File.Copy(Path.Combine(strGeneratePDFPath, strDeducteeId) + ".pdf", Path.Combine(txtOutputFolderPath.Text, strEmployeePAN) + ".pdf");
                        }
                        //--------------------------------------------------------------------------------------
                        File.Delete(Path.Combine(strGeneratePDFPath, strDeducteeId) + ".pdf");
                        //-----------------------------------------------------------------------
                        lngCounter = lngCounter + 1;
                        lblExportPDFStatus.Text = Convert.ToString(lngCounter) + "/" + Convert.ToString(lngListOfItems) + "  " + strUserMassage;
                        lblExportPDFStatus.Visible = true;
                        //--
                        rptcls.Close();
                        rptcls.Dispose();
                        //--
                        //EMPLOYEE PAN COUNTER
                        intEmployeePANCounter = intEmployeePANCounter + 1;
                    }

                    lblExportPDFStatus.Text = "All PDF Exported";
