                    //--

                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtEndDate"];
                    objtxtValue.Text = TdsMan.T_ReturnQuarterEndDate(cmbCombo2.Text, cmbCombo1.Text);
                    //}
                    //else if (cmbCombo2.Text == "Q2")
                    //{
                    //    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtStartDate"];
                    //    objtxtValue.Text = TdsMan.T_ReturnQuarterStartDate(cmbCombo2.Text, cmbCombo1.Text);
