        #region PrintForm24QSDComparisionReport
        private void PrintForm24QSDComparisionReport()
        {
            try
            {
                //"           " + cmnService.J_SQLDBFormat(strShowHelpEmployeeMatrix, J_SQLColFormat.Case_End) + " AS DEDUCTEE_CODE, " +
                string[,] strQ1_PAYMENTMatrix = {{"TRN_BASIC_INFO.QTR = 'Q1'", "F", "TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT", "F"},
                                                {"TRN_BASIC_INFO.QTR <> 'Q1'", "F", "0", "T"}};
                string[,] strQ1_TDSMatrix = {{"TRN_BASIC_INFO.QTR = 'Q1'", "F", "TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT", "F"},
                                                {"TRN_BASIC_INFO.QTR <> 'Q1'", "F", "0", "T"}};
                //
                string[,] strQ2_PAYMENTMatrix = {{"TRN_BASIC_INFO.QTR = 'Q2'", "F", "TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT", "F"},
                                                {"TRN_BASIC_INFO.QTR <> 'Q2'", "F", "0", "T"}};
                string[,] strQ2_TDSMatrix = {{"TRN_BASIC_INFO.QTR = 'Q2'", "F", "TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT", "F"},
                                                {"TRN_BASIC_INFO.QTR <> 'Q2'", "F", "0", "T"}};
                //
                string[,] strQ3_PAYMENTMatrix = {{"TRN_BASIC_INFO.QTR = 'Q3'", "F", "TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT", "F"},
                                                {"TRN_BASIC_INFO.QTR <> 'Q3'", "F", "0", "T"}};
                string[,] strQ3_TDSMatrix = {{"TRN_BASIC_INFO.QTR = 'Q3'", "F", "TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT", "F"},
                                                {"TRN_BASIC_INFO.QTR <> 'Q3'", "F", "0", "T"}};
                //
                string[,] strQ4_PAYMENTMatrix = {{"TRN_BASIC_INFO.QTR = 'Q4'", "F", "TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT", "F"},
                                                {"TRN_BASIC_INFO.QTR <> 'Q4'", "F", "0", "T"}};
                string[,] strQ4_TDSMatrix = {{"TRN_BASIC_INFO.QTR = 'Q4'", "F", "TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT", "F"},
                                                {"TRN_BASIC_INFO.QTR <> 'Q4'", "F", "0", "T"}};
                //
                string strTotalSalary = "", strTotalSalaryText = "";
                if(rbnSort1.Checked==true)
                {
                    strTotalSalaryText = "Sum of Section 17";
                    strTotalSalary = "TRN_SALARY_DETAILS.TS_GS_TOTAL";
                }
                else if (rbnSort2.Checked == true)
                {
                    strTotalSalaryText = "After deduction u/s 10";
                    strTotalSalary = "TRN_SALARY_DETAILS.TS_BALANCE";
                }
                //
                strQueryString = @"SELECT PARTY_ID,
                                   PARTY_NAME,
                                   PARTY_PAN,
                                   SUM(Q1_PAYMENT)      AS Q1_PAMENT,
                                   SUM(Q1_TDS)          AS Q1_TD,
                                   SUM(Q2_PAYMENT)      AS Q2_PAMENT,
                                   SUM(Q2_TDS)          AS Q2_TD,
                                   SUM(Q3_PAYMENT)      AS Q3_PAMENT,
                                   SUM(Q3_TDS)          AS Q3_TD,
                                   SUM(Q4_PAYMENT)      AS Q4_PAMENT,
                                   SUM(Q4_TDS)          AS Q4_TD,
                                   SUM(TOTAL_PAYMENT)   AS TOTAL_PAMENT,
                                   SUM(TOTAL_TDS)       AS TOTAL_TD,
                                   SUM(FORM_16_PAYMENT) AS FORM_16_PAMENT,
                                   SUM(FORM_16_TDS)     AS FORM_16_TD,
                                   SUM(TOTAL_PAYMENT) - SUM(FORM_16_PAYMENT) AS DIFF_PAMENT,
                                   SUM(TOTAL_TDS)     - SUM(FORM_16_TDS)     AS DIFF_TD
                            FROM (
                            SELECT TRN_DEDUCTEE_DETAILS.PARTY_ID,
                                   MST_EMPLOYEE.EMPLOYEE_NAME AS PARTY_NAME,
                                   MST_EMPLOYEE.EMPLOYEE_PAN  AS PARTY_PAN," +
                                   "SUM(" + cmnService.J_SQLDBFormat(strQ1_PAYMENTMatrix, J_SQLColFormat.Case_End) + ") AS Q1_PAYMENT, " +
                                   "SUM(" + cmnService.J_SQLDBFormat(strQ1_TDSMatrix, J_SQLColFormat.Case_End) + ") AS Q1_TDS, " +
                                   "SUM(" + cmnService.J_SQLDBFormat(strQ2_PAYMENTMatrix, J_SQLColFormat.Case_End) + ") AS Q2_PAYMENT, " +
                                   "SUM(" + cmnService.J_SQLDBFormat(strQ2_TDSMatrix, J_SQLColFormat.Case_End) + ") AS Q2_TDS, " +
                                   "SUM(" + cmnService.J_SQLDBFormat(strQ3_PAYMENTMatrix, J_SQLColFormat.Case_End) + ") AS Q3_PAYMENT, " +
                                   "SUM(" + cmnService.J_SQLDBFormat(strQ3_TDSMatrix, J_SQLColFormat.Case_End) + ") AS Q3_TDS, " +
                                   "SUM(" + cmnService.J_SQLDBFormat(strQ4_PAYMENTMatrix, J_SQLColFormat.Case_End) + ") AS Q4_PAYMENT, " +
                                   "SUM(" + cmnService.J_SQLDBFormat(strQ4_TDSMatrix, J_SQLColFormat.Case_End) + @") AS Q4_TDS," +
                                   "    " + cmnService.J_SQLDBFormat("SUM(TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT)", J_ColumnType.Double, J_SQLColFormat.NullCheck) + " AS TOTAL_PAYMENT," +
                                   "    " + cmnService.J_SQLDBFormat("SUM(TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT)", J_ColumnType.Double, J_SQLColFormat.NullCheck) + @" AS TOTAL_TDS,
                                   0                                                                                                  AS FORM_16_PAYMENT,
                                   0                                                                                                  AS FORM_16_TDS
                            FROM  ((TRN_DEDUCTEE_DETAILS INNER JOIN TRN_BASIC_INFO
                            ON TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID)
	                            INNER JOIN MST_EMPLOYEE
	                            ON TRN_DEDUCTEE_DETAILS.PARTY_ID = MST_EMPLOYEE.EMPLOYEE_ID)
                            WHERE TRN_BASIC_INFO.COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + @"
                            AND   TRN_BASIC_INFO.ASST_ID    = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + @" 
                            AND   TRN_BASIC_INFO.FORM_NO = '24Q'
                            GROUP BY TRN_DEDUCTEE_DETAILS.PARTY_ID,
                                     MST_EMPLOYEE.EMPLOYEE_NAME,
                                     MST_EMPLOYEE.EMPLOYEE_PAN
                            UNION 
                            SELECT TRN_SALARY_DETAILS.EMPLOYEE_ID AS PARTY_ID,
                                   MST_EMPLOYEE.EMPLOYEE_NAME     AS PARTY_NAME,
                                   MST_EMPLOYEE.EMPLOYEE_PAN      AS PARTY_PAN,
                                   0 AS Q1_PAYMENT,
                                   0 AS Q1_TDS,
                                   0 AS Q2_PAYMENT,
                                   0 AS Q2_TDS,
                                   0 AS Q3_PAYMENT,
                                   0 AS Q3_TDS,
                                   0 AS Q4_PAYMENT,
                                   0 AS Q4_TDS,
                                   0 AS TOTAL_PAYMENT,
                                   0 AS TOTAL_TDS,
                                   " + strTotalSalary + @"                      AS FORM_16_PAYMENT,
                                   TRN_SALARY_DETAILS.TOTAL_TAX_DEDUCTED_AMOUNT AS FORM_16_TDS
                            FROM   ((TRN_SALARY_DETAILS  INNER JOIN TRN_BASIC_INFO
                            ON TRN_SALARY_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID)
	                            INNER JOIN MST_EMPLOYEE
	                            ON TRN_SALARY_DETAILS.EMPLOYEE_ID = MST_EMPLOYEE.EMPLOYEE_ID)
                            WHERE TRN_BASIC_INFO.COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + @"
                            AND   TRN_BASIC_INFO.ASST_ID    = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + @" 
                             ) AS SUMMARY
                            GROUP BY PARTY_ID,
                                     PARTY_NAME,
                                     PARTY_PAN
                            ORDER BY PARTY_NAME";
                //--
                crForm24QSDComparisionReport rptForm24QSDComparisionReport = new crForm24QSDComparisionReport();
                rptcls = (ReportClass)rptForm24QSDComparisionReport;
                //--
                TextObject objtxtValue;
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToDate"];
                objtxtValue.Text = "Salary Amount (Form 16) : " + strTotalSalaryText;

                string[,] strArry = { { "txtReportTitle", "Salary & TDS Summary - FA Year : " + cmbCombo2.Text + "\n Company : " + cmbCombo1.Text } };
                rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                //--
            }
            catch(Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

