                                   "    " + cmnService.J_SQLDBFormat("SUM(TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT)", J_ColumnType.Double, J_SQLColFormat.NullCheck) + " AS TOTAL_PAYMENT," +
                                   "    " + cmnService.J_SQLDBFormat("SUM(TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT)", J_ColumnType.Double, J_SQLColFormat.NullCheck) + @" AS TOTAL_TDS,
                                   0                                                                                                  AS FORM_16_PAYMENT,
                                   0                                                                                                  AS FORM_16_TDS
                            FROM  ((TRN_DEDUCTEE_DETAILS INNER JOIN TRN_BASIC_INFO
