                    //else if (cmbCombo2.Text == "Q2")
                    //{
                    //    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtStartDate"];
                    //    objtxtValue.Text = TdsMan.T_ReturnQuarterStartDate(cmbCombo2.Text, cmbCombo1.Text);
                    //    //--
                    //    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtEndDate"];
                    //    objtxtValue.Text = TdsMan.T_ReturnQuarterEndDate(cmbCombo2.Text, cmbCombo1.Text);
                    //}
                    //else if (cmbCombo2.Text == "Q3")
                    //{
                    //    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtStartDate"];
                    //    objtxtValue.Text = TdsMan.T_ReturnQuarterStartDate(cmbCombo2.Text, cmbCombo1.Text);
                    //    //--
                    //    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtEndDate"];
                    //    objtxtValue.Text = TdsMan.T_ReturnQuarterEndDate(cmbCombo2.Text, cmbCombo1.Text);
                    //}
                    //else if (cmbCombo2.Text == "Q4")
                    //{
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtStartDate"];
                    objtxtValue.Text = TdsMan.T_ReturnQuarterStartDate(cmbCombo2.Text, cmbCombo1.Text);
                    //--
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtEndDate"];
                    objtxtValue.Text = TdsMan.T_ReturnQuarterEndDate(cmbCombo2.Text, cmbCombo1.Text);
                    //}
                    //--
                    //--
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtPlace"];
                    objtxtValue.Text = txtTextBox1.Text;
                    //--
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtDate"];
                    objtxtValue.Text = txtTextBox2.Text;
                    //--
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtDesignation"];
                    //objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT DESIGNATION FROM MST_COMPANY WHERE COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo3, cmbCombo3.SelectedIndex))));
                    objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT DESIGNATION FROM TRN_COMPANY_INFO WHERE BASIC_INFO_ID = " + lngBasicInfoID));
                    //--
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFullName"];
                    //objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT PERSON_NAME FROM MST_COMPANY WHERE COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo3, cmbCombo3.SelectedIndex))));
                    objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT PERSON_NAME FROM TRN_COMPANY_INFO WHERE BASIC_INFO_ID = " + lngBasicInfoID));
                    //------------------------------------------------- 
                    // SUB REPORT
                    rptcls.OpenSubreport("crSubRptSummaryOfPayment").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSubRptSummaryOfPayment).Tables[0]);
                    rptcls.OpenSubreport("crSubRptChlnDetails").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSubRptChlnDetails).Tables[0]);
                    rptcls.OpenSubreport("crSubRptBookEntry").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSubRptBookEntry).Tables[0]);
                    rptcls.OpenSubreport("crSubRptAnnextureSummaryOfPayment").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSubRptSummaryOfPaymentAnnexture).Tables[0]);
                    rptcls.OpenSubreport("crSubRptChallanEntry").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSubRptChallanEntry).Tables[0]);
                    // MAIN REPORT
                    rptService.J_PreviewReport(ref rptcls, this, strQueryString);
                    //---------------------------
