        #region PrintCertForm27D27EQ
        //-- MODIFIED BY DHRUB ON 2015-09-16
        //--

        private void PrintCertForm27D27EQ()
        {
            try
            {
                //string SelectedItems = "";
                //--
                string strGeneratePDFPath = "";
                string strUserMassage = "";
                string strDeducteePAN = "";
                string strForm16AOutputPDFPath = "";

                string strSignPDFPath = "", strSignatureFilePath = "", strForm16OutputSignPDFPath = "";
                //--
                long lngListOfItems = 0;
                long lngCounter = 0;
                //--
                int intEmployeePANCounter = 0;
                //--
                bool blnFetchPAN = true;
                DataSet dsSelectedGridData;

                string[] strSelectedDeducteeID = cmnService.J_GenerateDataGridViewSelectedId(grdvNewDescription).Split(',');//-- Modified By Abhishek Dey On 25/10/2017 --
                string[] strSelectedDeducteePAN = new string[strSelectedDeducteeID.Length];
                //--
                strSelectedGridItemsWithSearch = "";
                //--
                if (dmlService.J_ReturnNoOfRows("SELECT Count(*) FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED, J_QueryType.DirectQuery) > Convert.ToInt64(strSelectedDeducteeID.Length))
                {
                    dsSelectedGridData = new DataSet();
                    //--
                    //strSQL = "SELECT ITEM_ID,ITEM_DETAIL FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED;
                    //-- ANIK @ 2017/10/26
                    strSQL = "SELECT ITEM_ID, ITEM_DETAIL, ITEM_NAME FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED;
                    dsSelectedGridData = dmlService.J_ExecSqlReturnDataSet(strSQL);

                    //REINITIALIZE STRING ARRAY FOR EXPORT
                    blnFetchPAN = false;
                    strSelectedDeducteeID = new string[dsSelectedGridData.Tables[0].Rows.Count];
                    strSelectedDeducteePAN = new string[dsSelectedGridData.Tables[0].Rows.Count];

                    for (int i = 0; i <= dsSelectedGridData.Tables[0].Rows.Count - 1; i++)
                    {
                        strSelectedGridItemsWithSearch = strSelectedGridItemsWithSearch + Convert.ToString(dsSelectedGridData.Tables[0].Rows[i]["ITEM_ID"]) + ",";
                        //FOR EXPORT TO PDF
                        strSelectedDeducteeID[i] = Convert.ToString(dsSelectedGridData.Tables[0].Rows[i]["ITEM_ID"]);
                        //strSelectedDeducteePAN[i] = Convert.ToString(dsSelectedGridData.Tables[0].Rows[i]["ITEM_DETAIL"]);
                        //-- ANIK @ 2017/10/26
                        strSelectedDeducteePAN[i] = cmnService.J_Left(Convert.ToString(dsSelectedGridData.Tables[0].Rows[i]["ITEM_NAME"]), 10);
                    }
                    strSelectedGridItemsWithSearch = strSelectedGridItemsWithSearch.Substring(0, (strSelectedGridItemsWithSearch.Length - 1));
                }
                else
                    strSelectedGridItemsWithSearch = cmnService.J_GenerateDataGridViewSelectedId(grdvNewDescription);//-- Modified By Abhishek Dey On 25/10/2017 --
                //strSelectedGridItemsWithSearch = cmnService.J_GenerateDataGridViewSelectedId(grdvDescription);

                //----------------------------------------------------
                //--------------- BLOCK FOR EXPORT TO PDF-------------
                //----------------------------------------------------
                if (rbnPrinter.Checked == true || rbnExport.Checked == true)
                {
                    //--------------------------------------------
                    //FETCHING EMPLOYEE PAN [ IF SEARCH ENABLED ]
                    //--------------------------------------------
                    if (blnFetchPAN == true)
                    {
                        foreach (DataGridViewRow row in grdvNewDescription.Rows)//-- Modified By Abhishek Dey On 25/10/2017 --
                        {
                            if (row.Cells[0].Value != null && (bool)row.Cells[0].Value == true)
                            {
                                strSelectedDeducteePAN[intEmployeePANCounter] = row.Cells[3].Value.ToString();
                                intEmployeePANCounter = intEmployeePANCounter + 1;
                            }
                        }
                    }
                    //-- 
                    intEmployeePANCounter = 0;
                    //--
                    //--------------------------------------------
                    //TAKING COMPANY TAN FROM COMBO
                    //--------------------------------------------
                    string[] strCompanyTAN = cmbCombo3.Text.Split('[', ']');
                    //--
                    //-------------------------------
                    //FETCHING LOCAL MY DOCUMENT PATH 
                    //-------------------------------
                    string strLocalPath = System.Environment.GetFolderPath(System.Environment.SpecialFolder.Personal);
                    //--
                    //-----------------------------------------------
                    //INITIALIZE FOLDER NAME REPORT TITLE WISE 
                    //-----------------------------------------------
                    strForm16AOutputPDFPath = Path.Combine(strCompanyTAN[1] + "_" + cmbCombo1.Text, Path.Combine("Form16A[27Q]", "Temp"));
                    //--
                    //GENERATE PDF PATH
                    if (strLocalPath == txtOutputFolderPath.Text)
                        strGeneratePDFPath = Path.Combine(txtOutputFolderPath.Text, strForm16AOutputPDFPath);
                    else
                        strGeneratePDFPath = Path.Combine(txtOutputFolderPath.Text, "Temp");
                    //--
                    if (rbnExport.Checked == true)
                    {
                        strForm16OutputSignPDFPath = Path.Combine(strCompanyTAN[1] + "_" + cmbCombo1.Text, "Form16A-26Q");
                        //--
                        //GENERATE SIGNED PDF PATH 
                        //--
                        if (strLocalPath == txtOutputFolderPath.Text)
                            strSignPDFPath = Path.Combine(txtOutputFolderPath.Text, strForm16OutputSignPDFPath);
                        else
                            strSignPDFPath = txtOutputFolderPath.Text;
                        //--
                        //DHRUB ADDED ON 07/02/2014 
                        //--
                        if (Directory.Exists(strSignPDFPath) == true)
                        {
                            if (cmnService.J_UserMessage("A folder with same name already exists\nDo you want to replace it ?", MessageBoxButtons.YesNo) == DialogResult.No) return;
                            //-- DELETE THE FOLDER
                            Directory.Delete(strSignPDFPath, true);
                        }
                    }
                    else //--@@ MODIFIED BY DHRUB ON 2015-09-07 [IF OPTION - FOR PDF file]
                    {
                        if (Directory.Exists(txtOutputFolderPath.Text) == true)
                        {
                            if (cmnService.J_UserMessage("A folder with same name already exists\nDo you want to replace it ?", MessageBoxButtons.YesNo) == DialogResult.No) return;
                            //-- DELETE THE FOLDER
                            Directory.Delete(txtOutputFolderPath.Text, true);
                        }
                    }
                    //-------------------------------------------------
                    //FETCH NUMBER OF DATA SELECTED INTO THE GRID
                    //-------------------------------------------------
                    lngListOfItems = strSelectedDeducteeID.Length;
                    //-------------------------------------------------
                    //--
                    //--
                    //PROGRESS STATUS VISIBILITY  
                    lblExportPDFStatus.Text = "";
                    strUserMassage = "PDF(S) Processed...";
                    //--
                    //--CREATING DIRECTORY [WHILE EXPORT TO PDF ONLY WITHOUT SIGNATURE]
                    Directory.CreateDirectory(strGeneratePDFPath);
                    //--
                    global2.PDFSign PDFSign;
                    if (rbnExport.Checked == true)
                    {
                        //strSignatureFilePath = Directory.GetLogicalDrives(txtSignaturePath.Text);
                        strSignatureFilePath = txtSignaturePath.Text;

                        //--CREATING DIRECTORY
                        Directory.CreateDirectory(strSignPDFPath);
                        PDFSign = ReturnDSC(txtSignaturePath.Text.Trim(), txtSignaturePassword.Text.Trim());
                        //--
                        if (PDFSign == null) return;
                    }
                    else
                        PDFSign = null;
                    //---------------------------------------------
                    //LOOP TO GENERATE PDF INDIVIDUALLY 
                    //---------------------------------------------
                    foreach (string strDeducteeId in strSelectedDeducteeID)
                    {
                        //-----------------------------------------------------------------------
                        //FETCHING EMPLOYEE PAN FROM ARRAY
                        //-----------------------------------------------------------------------
                        strDeducteePAN = strSelectedDeducteePAN[intEmployeePANCounter];
                        //-----------------------------------------------------------------------
                        //--
                        #region QUERY PART TO GENERATE PDF

                        strQueryString = "SELECT  TRN_COMPANY_INFO.COMPANY_ID          AS COMPANY_ID," +
                                     "        TRN_COMPANY_INFO.COMPANY_NAME        AS COMPANY_NAME," +
                                     "        TRN_COMPANY_INFO.TAN_NO              AS TAN_NO," +
                                     "        TRN_COMPANY_INFO.PAN_NO              AS PAN_NO," +
                                     "        TRN_COMPANY_INFO.ADDRESS1            AS ADDRESS1," +
                                     "        " + cmnService.J_SQLDBFormat("TRN_COMPANY_INFO.ADDRESS2", J_ColumnType.String, J_SQLColFormat.NullCheck) + " AS ADDRESS2," +
                                     "        " + cmnService.J_SQLDBFormat("TRN_COMPANY_INFO.ADDRESS3", J_ColumnType.String, J_SQLColFormat.NullCheck) + " AS ADDRESS3," +
                                     "        " + cmnService.J_SQLDBFormat("TRN_COMPANY_INFO.ADDRESS4", J_ColumnType.String, J_SQLColFormat.NullCheck) + " AS ADDRESS4," +
                                     "        " + cmnService.J_SQLDBFormat("TRN_COMPANY_INFO.ADDRESS5", J_ColumnType.String, J_SQLColFormat.NullCheck) + " AS ADDRESS5," +
                                     "        TRN_COMPANY_INFO.STATE_ID            AS STATE_ID," +
                                     "        MST_STATE.STATE_NAME                 AS STATE_NAME," +
                                     "        TRN_COMPANY_INFO.PIN_CODE            AS PIN_CODE," +
                                     "        TRN_COMPANY_INFO.PHONE               AS PHONE," +
                                     "        TRN_COMPANY_INFO.STD                 AS STD," +
                                     "        TRN_COMPANY_INFO.EMAIL               AS EMAIL," +
                                     "        " + cmnService.J_SQLDBFormat("MST_COMPANY.CIT_TDS_ADDRESS", J_ColumnType.String, J_SQLColFormat.NullCheck) + " AS CIT_TDS_ADDRESS," +
                                     "        " + cmnService.J_SQLDBFormat("MST_COMPANY.CIT_TDS_CITY", J_ColumnType.String, J_SQLColFormat.NullCheck) + "    AS CIT_TDS_CITY," +
                                     "        " + cmnService.J_SQLDBFormat("MST_COMPANY.CIT_TDS_PINCODE", J_ColumnType.String, J_SQLColFormat.NullCheck) + " AS CIT_TDS_PINCODE," +
                                     "        " + cmnService.J_SQLDBFormat("TRN_COMPANY_INFO.PERSON_NAME", J_ColumnType.String, J_SQLColFormat.NullCheck) + "     AS PERSON_NAME," +
                                     "        " + cmnService.J_SQLDBFormat("MST_COMPANY.FATHER_NAME", J_ColumnType.String, J_SQLColFormat.NullCheck) + "     AS FATHER_NAME," +
                                     "        " + cmnService.J_SQLDBFormat("TRN_COMPANY_INFO.DESIGNATION", J_ColumnType.String, J_SQLColFormat.NullCheck) + "     AS DESIGNATION," +
                                     "        MST_ASSESSMENT.ASST_YEAR            AS ASST_YEAR," +
                                     "        MST_ASSESSMENT.START_DATE           AS START_DATE," +
                                     "        MST_ASSESSMENT.END_DATE             AS END_DATE," +
                                     "        MST_DEDUCTEE.DEDUCTEE_ID            AS DEDUCTEE_ID," +
                                     "        MST_DEDUCTEE.DEDUCTEE_CODE          AS DEDUCTEE_CODE," +
                                     "        MST_DEDUCTEE.DEDUCTEE_NAME          AS DEDUCTEE_NAME," +
                                     "        MST_DEDUCTEE.DEDUCTEE_PAN           AS DEDUCTEE_PAN," +
                                     "        MST_DEDUCTEE.ADDRESS1               AS D_ADDRESS1," +
                                     "        " + cmnService.J_SQLDBFormat("MST_DEDUCTEE.ADDRESS2", J_ColumnType.String, J_SQLColFormat.NullCheck) + "  AS D_ADDRESS2," +
                                     "        " + cmnService.J_SQLDBFormat("MST_DEDUCTEE.ADDRESS3", J_ColumnType.String, J_SQLColFormat.NullCheck) + "  AS D_ADDRESS3," +
                                     "        " + cmnService.J_SQLDBFormat("MST_DEDUCTEE.ADDRESS4", J_ColumnType.String, J_SQLColFormat.NullCheck) + "  AS D_ADDRESS4," +
                                     "        " + cmnService.J_SQLDBFormat("MST_DEDUCTEE.ADDRESS5", J_ColumnType.String, J_SQLColFormat.NullCheck) + "  AS D_ADDRESS5," +
                                     "        " + cmnService.J_SQLDBFormat("MST_DEDUCTEE.STATE_ID", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + " AS D_STATE_ID," +
                                     "        " + cmnService.J_SQLDBFormat("MST_STATE_D.STATE_NAME", J_ColumnType.String, J_SQLColFormat.NullCheck) + " AS D_STATE_NAME," +
                                     "        MST_DEDUCTEE.PIN_CODE               AS D_PIN_CODE," +
                                     "        MST_DEDUCTEE.MOBILE_NO              AS D_MOBILE_NO," +
                                     "        MST_DEDUCTEE.EMAIL                  AS D_EMAIL," +
                                     "        TRN_CHALLAN.CHALLAN_ID              AS CHALLAN_ID," +
                                     "        TRN_CHALLAN.SECTION_ID              AS SECTION_ID," +
                                     "        TRN_CHALLAN.DEPOSIT_DATE            AS DEPOSIT_DATE," +
                                     "        TRN_CHALLAN.BSR_CODE                AS BSR_CODE," +
                                     "        TRN_CHALLAN.CHALLAN_NO              AS CHALLAN_NO," +
                                     "        TRN_CHALLAN.TRANSFER_VOUCHER_NO     AS TRANSFER_VOUCHER_NO," +
                                     "        TRN_DEDUCTEE_DETAILS.PARTY_ID       AS PARTY_ID," +
                                     "        SUM(TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT) AS DEDUCTEE_TOTAL," +
                                     "        TRN_CHALLAN.BOOK_ENTRY              AS BOOK_ENTRY," +
                                     "       '" + TDSMAN.Classes.TDSMAN.T_CERTIFICATE_TDSMAN_FOOTER_ENABLE_OPTION + "' AS CERTIFICATE_TDSMAN_FOOTER_ENABLE_OPTION," +
                                     "       '" + TDSMAN.Classes.TDSMAN.T_CERTIFICATE_SECOND_FOOTER_ENABLE_OPTION + "' AS CERTIFICATE_SECOND_FOOTER_ENABLE_OPTION," +
                                     "       '" + TDSMAN.Classes.TDSMAN.T_CERTIFICATE_SECOND_FOOTER_TEXT + "'          AS CERTIFICATE_SECOND_FOOTER_TEXT " +
                                     "FROM   ((((((((TRN_COMPANY_INFO INNER JOIN MST_COMPANY " +
                                     "              ON TRN_COMPANY_INFO.COMPANY_ID   = MST_COMPANY.COMPANY_ID) " +
                                     "        INNER JOIN MST_STATE " +
                                     "              ON TRN_COMPANY_INFO.STATE_ID     = MST_STATE.STATE_ID) " +
                                     "        INNER JOIN TRN_BASIC_INFO " +
                                     "             ON TRN_COMPANY_INFO.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID) " +
                                     "        INNER JOIN MST_ASSESSMENT " +
                                     "             ON TRN_BASIC_INFO.ASST_ID         = MST_ASSESSMENT.ASST_ID) " +
                                     "        INNER JOIN TRN_CHALLAN " +
                                     "             ON TRN_BASIC_INFO.BASIC_INFO_ID   = TRN_CHALLAN.BASIC_INFO_ID) " +
                                     "        INNER JOIN TRN_DEDUCTEE_DETAILS " +
                                     "             ON TRN_CHALLAN.CHALLAN_ID         = TRN_DEDUCTEE_DETAILS.CHALLAN_ID) " +
                                     "        INNER JOIN MST_DEDUCTEE " +
                                     "             ON TRN_DEDUCTEE_DETAILS.PARTY_ID  = MST_DEDUCTEE.DEDUCTEE_ID) " +
                                     "        LEFT JOIN  MST_STATE AS MST_STATE_D " +
                                     "            ON MST_DEDUCTEE.STATE_ID         = MST_STATE_D.STATE_ID) " +
                                     "WHERE  TRN_BASIC_INFO.BASIC_INFO_ID          = " + lngBasicInfoID + " " +
                                     "AND    TRN_DEDUCTEE_DETAILS.PARTY_ID IN     (" + strDeducteeId + ") " +
                                     "GROUP BY TRN_COMPANY_INFO.COMPANY_ID," +
                                     "       TRN_COMPANY_INFO.COMPANY_NAME," +
                                     "       TRN_COMPANY_INFO.TAN_NO," +
                                     "       TRN_COMPANY_INFO.PAN_NO," +
                                     "       TRN_COMPANY_INFO.ADDRESS1," +
                                     "       TRN_COMPANY_INFO.ADDRESS2," +
                                     "       TRN_COMPANY_INFO.ADDRESS3," +
                                     "       TRN_COMPANY_INFO.ADDRESS4," +
                                     "       TRN_COMPANY_INFO.ADDRESS5," +
                                     "       TRN_COMPANY_INFO.STATE_ID," +
                                     "       MST_STATE.STATE_NAME," +
                                     "       TRN_COMPANY_INFO.PIN_CODE," +
                                     "       TRN_COMPANY_INFO.PHONE," +
                                     "       TRN_COMPANY_INFO.STD," +
                                     "       TRN_COMPANY_INFO.EMAIL," +
                                     "       MST_COMPANY.CIT_TDS_ADDRESS," +
                                     "       MST_COMPANY.CIT_TDS_CITY," +
                                     "       MST_COMPANY.CIT_TDS_PINCODE," +
                                     "       TRN_COMPANY_INFO.PERSON_NAME," +
                                     "       MST_COMPANY.FATHER_NAME," +
                                     "       TRN_COMPANY_INFO.DESIGNATION," +
                                     "       MST_ASSESSMENT.ASST_YEAR," +
                                     "       MST_ASSESSMENT.START_DATE," +
                                     "       MST_ASSESSMENT.END_DATE," +
                                     "       MST_DEDUCTEE.DEDUCTEE_ID," +
                                     "       MST_DEDUCTEE.DEDUCTEE_CODE," +
                                     "       MST_DEDUCTEE.DEDUCTEE_NAME," +
                                     "       MST_DEDUCTEE.DEDUCTEE_PAN," +
                                     "       MST_DEDUCTEE.ADDRESS1," +
                                     "       MST_DEDUCTEE.ADDRESS2," +
                                     "       MST_DEDUCTEE.ADDRESS3," +
                                     "       MST_DEDUCTEE.ADDRESS4," +
                                     "       MST_DEDUCTEE.ADDRESS5," +
                                     "       MST_DEDUCTEE.STATE_ID," +
                                     "       MST_STATE_D.STATE_NAME," +
                                     "       MST_DEDUCTEE.PIN_CODE," +
                                     "       MST_DEDUCTEE.MOBILE_NO," +
                                     "       MST_DEDUCTEE.EMAIL," +
                                     "       TRN_CHALLAN.CHALLAN_ID," +
                                     "       TRN_CHALLAN.SECTION_ID," +
                                     "       TRN_CHALLAN.DEPOSIT_DATE," +
                                     "       TRN_CHALLAN.BSR_CODE," +
                                     "       TRN_CHALLAN.CHALLAN_NO," +
                                     "       TRN_CHALLAN.TRANSFER_VOUCHER_NO," +
                            //"       TRN_CHALLAN.TOT_TAX," +
                            //"       TRN_CHALLAN.CTRL_TOT_TAX," +
                                     "       TRN_DEDUCTEE_DETAILS.PARTY_ID," +
                            //"       TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT," +
                                     "       TRN_CHALLAN.BOOK_ENTRY " +
                                     "ORDER BY MST_DEDUCTEE.DEDUCTEE_NAME, MST_DEDUCTEE.DEDUCTEE_ID," +
                                     "       TRN_CHALLAN.SECTION_ID,TRN_CHALLAN.DEPOSIT_DATE" +
                            //"       TRN_CHALLAN.CHALLAN_ID," + 
                                     "       ";
                        //------------------------------------------------- 
                        //-- SUB REPORTS
                        //-------------------------------------------------
                        // FOR SUMMARY OF PAYMENT
                        string strSubRptSummaryOfPayment = "SELECT TRN_CHALLAN.CHALLAN_ID              AS CHALLAN_ID," +
                                                    "              TRN_DEDUCTEE_DETAILS.PARTY_ID       AS PARTY_ID," +
                                                    "              TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT AS PAYMENT_AMOUNT," +
                                                    "              TRN_CHALLAN.SECTION_ID              AS SECTION_ID," +
                                                    "              MST_SECTION.SECTION_NO              AS SECTION_NO," +
                                                    "              MST_SECTION.SECTION_NAME            AS SECTION_NAME," +
                                                    "              MST_SECTION.SECTION_DESCRIPTION     AS SECTION_DESCRIPTION," +
                                                    "              TRN_DEDUCTEE_DETAILS.PAYMENT_DATE   AS PAYMENT_DATE " +
                                                    "        FROM  (((TRN_BASIC_INFO INNER JOIN TRN_CHALLAN " +
                                                    "              ON TRN_BASIC_INFO.BASIC_INFO_ID     = TRN_CHALLAN.BASIC_INFO_ID)" +
                                                    "              INNER JOIN TRN_DEDUCTEE_DETAILS " +
                                                    "              ON TRN_CHALLAN.CHALLAN_ID           = TRN_DEDUCTEE_DETAILS.CHALLAN_ID)" +
                                                    "              LEFT JOIN MST_SECTION " +
                                                    "              ON TRN_DEDUCTEE_DETAILS.SECTION_ID  = MST_SECTION.SECTION_ID)" +
                            //"       FROM   TRN_BASIC_INFO," +
                            //"              TRN_CHALLAN," +
                            //"              TRN_DEDUCTEE_DETAILS," +
                            //"              MST_SECTION " +
