                                              {"HeaderFromToDate", "From : " + mskFromDate.Text + " To : " + mskToDate.Text }
                                                };
                        J_PreviewReportRDLC("\\Reports\\crEmployeeWiseDetail.rdlc", "DataSet1", strQueryString, strArryQuarterWiseDeducteeReport);
                    }
                    //
                }
                //-----------------------------------------------------------------------
                //---------------------------
