                else if (rbnSort1_2.Checked == true) // EMPLOYEE
                {
                    //crEmployeeWiseSummary rptEmployeeWiseSummary = new crEmployeeWiseSummary();
                    //rptcls = (ReportClass)rptEmployeeWiseSummary;
                    //// FROM & TO PERIOD
                    //TextObject objtxtValue;
                    //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToPeriod"];
                    // MONTHLY
                    if (rbnSort1.Checked == true)
                    {
                        //DateTime.MinValue
                        //getl
                        //strSELECT = "DATENAME(MONTH,TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE) AS PERIOD," +
                        //        "    MONTH(TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE)          AS MONTH_ID ";
                        //strSELECT = "FORMAT(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,'mmm') AS PERIOD," +
                        //        "    MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE)        AS MONTH_ID ";
                        if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                            strSELECT = "DATENAME(MONTH, CAST(CONVERT(CHAR(10),TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,101) AS DATETIME)) AS PERIOD," +
                                    "    DATEPART(M, CAST(CONVERT(CHAR(10), TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 101) AS DATETIME))   AS MONTH_ID ";
                        else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                            strSELECT = "FORMAT(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,'mmm') AS PERIOD," +
                                    "    MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE)        AS MONTH_ID ";//
                        //strWHERE = " AND MONTH(TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE) >= " + Convert.ToInt32(Support.GetItemData(cmbCombo3, cmbCombo3.SelectedIndex)) + " " +
                        //    "        AND MONTH(TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE) >= " + Convert.ToInt32(Support.GetItemData(cmbCombo3, cmbCombo3.SelectedIndex)) + " " +
                        if (Convert.ToInt32(Support.GetItemData(cmbCombo3, cmbCombo3.SelectedIndex)) <= 3)
                            intYearFrom = Convert.ToInt16(cmnService.J_Left(cmbCombo2.Text, 2) + cmnService.J_Right(cmbCombo2.Text, 2));
                        else
                            intYearFrom = Convert.ToInt16(cmnService.J_Left(cmbCombo2.Text, 4));

                        if (Convert.ToInt32(Support.GetItemData(cmbCombo4, cmbCombo4.SelectedIndex)) <= 3)
                            intYearTo = Convert.ToInt16(cmnService.J_Left(cmbCombo2.Text, 2) + cmnService.J_Right(cmbCombo2.Text, 2));
                        else
                            intYearTo = Convert.ToInt16(cmnService.J_Left(cmbCombo2.Text, 4));

                        strWHERE = " AND TRN_DEDUCTEE_DETAILS.PAYMENT_DATE >= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(Convert.ToString(TdsMan.GetFirstDayOfMonth(Convert.ToInt32(Support.GetItemData(cmbCombo3, cmbCombo3.SelectedIndex)), intYearFrom))) + cmnService.J_DateOperator() + " " +
                        "            AND TRN_DEDUCTEE_DETAILS.PAYMENT_DATE <= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(Convert.ToString(TdsMan.GetLastDayOfMonth(Convert.ToInt32(Support.GetItemData(cmbCombo4, cmbCombo4.SelectedIndex)), intYearTo))) + cmnService.J_DateOperator() + " ";
                        //
                        if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                            strGROUP_BY = "DATENAME(MONTH, CAST(CONVERT(CHAR(10),TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,101) AS DATETIME))," +
                                    "    DATEPART(M, CAST(CONVERT(CHAR(10), TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 101) AS DATETIME)) ";
                        else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                            strGROUP_BY = "FORMAT(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,'mmm')," +
                                    "    MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE) ";
                        //strGROUP_BY = "FORMAT(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,'mmm')," +
                        //        "      MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE)";
                        //strGROUP_BY = "FORMAT(TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE,'mmm')," +
                        //        "      MONTH(TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE)," +
                        //        "      TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE";
                        //
                        strORDER_BY = " ORDER BY MST_EMPLOYEE.EMPLOYEE_NAME,IIF(Month(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE)>3, 0, 1), MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE)";
                        //strORDER_BY = "TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE";
                        // FROM & TO PERIOD
                        strSortText = "From : " + cmbCombo3.Text + " To : " + cmbCombo4.Text;

                        strSummaryFilter = rbnSort1.Text;
                        //string[,] strArry = { { "txtReportTitle", "Deductee Transactions - " + rbnSort1.Text + " Summary" } };
                        //strArry = { { "txtReportTitle", "Deductee Transactions - " + rbnSort1.Text + " Summary" } };
                    }
                    // QUARTERLY
                    else if (rbnSort2.Checked == true)
                    {
                        strSELECT = "TRN_BASIC_INFO.QTR AS PERIOD," +
                                "    0                  AS MONTH_ID ";
                        //
                        if (cmbCombo3.Text == T_Qtr.Q1)
                            strQTR = "'" + T_Qtr.Q1 + "',";
                        if (cmbCombo3.Text == T_Qtr.Q2)
                            strQTR = "'" + T_Qtr.Q2 + "',";
                        if (cmbCombo3.Text == T_Qtr.Q3)
                            strQTR = "'" + T_Qtr.Q3 + "',";
                        if (cmbCombo3.Text == T_Qtr.Q4)
                            strQTR = "'" + T_Qtr.Q4 + "',";

                        if (cmbCombo4.Text == T_Qtr.Q1)
                            strQTR = "'" + T_Qtr.Q1 + "',";
                        else if (cmbCombo4.Text == T_Qtr.Q2)
                        {
                            if (cmbCombo3.Text == T_Qtr.Q1)
                                strQTR = strQTR + "'" + T_Qtr.Q2 + "',";
                            else if (cmbCombo3.Text == T_Qtr.Q2)
                                strQTR = "'" + T_Qtr.Q2 + "',";
                        }
                        else if (cmbCombo4.Text == T_Qtr.Q3)
                        {
                            if (cmbCombo3.Text == T_Qtr.Q1)
                                strQTR = "'" + T_Qtr.Q1 + "'," + "'" + T_Qtr.Q2 + "'," + "'" + T_Qtr.Q3 + "',";
                            else if (cmbCombo3.Text == T_Qtr.Q2)
                                strQTR = "'" + T_Qtr.Q2 + "'," + "'" + T_Qtr.Q3 + "',";
                            else if (cmbCombo3.Text == T_Qtr.Q3)
                                strQTR = "'" + T_Qtr.Q3 + "',";
                        }
                        else if (cmbCombo4.Text == T_Qtr.Q4)
                        {
                            if (cmbCombo3.Text == T_Qtr.Q1)
                                strQTR = "'" + T_Qtr.Q1 + "'," + "'" + T_Qtr.Q2 + "'," + "'" + T_Qtr.Q3 + "'," + "'" + T_Qtr.Q4 + "',";
                            else if (cmbCombo3.Text == T_Qtr.Q2)
                                strQTR = "'" + T_Qtr.Q2 + "'," + "'" + T_Qtr.Q3 + "'," + "'" + T_Qtr.Q4 + "',";
                            else if (cmbCombo3.Text == T_Qtr.Q3)
                                strQTR = "'" + T_Qtr.Q3 + "'," + "'" + T_Qtr.Q4 + "',";
                            else if (cmbCombo3.Text == T_Qtr.Q4)
                                strQTR = "'" + T_Qtr.Q4 + "',";
                        }
                        //
                        if (cmnService.J_Right(strQTR, 1) == ",")
                            strQTR = cmnService.J_Mid(strQTR, 0, (strQTR.Length - 1));

                        strWHERE = " AND TRN_BASIC_INFO.QTR IN (" + strQTR + ")";
                        //
                        strGROUP_BY = "TRN_BASIC_INFO.QTR";
                        //
                        strORDER_BY = " ORDER BY MST_EMPLOYEE.EMPLOYEE_NAME, TRN_BASIC_INFO.QTR";
                        //strORDER_BY = "TRN_BASIC_INFO.QTR";
                        // FROM & TO PERIOD
                        strSortText = "From : Quarter " + cmnService.J_Right(cmbCombo3.Text, 1) + " To : Quarter " + cmnService.J_Right(cmbCombo4.Text, 1);

                        strSummaryFilter = rbnSort2.Text;

                        //string[,] strArry = { { "txtReportTitle", "Deductee Transactions - " + rbnSort2.Text + " Summary" } };
                    }
                    // ANNUAL
                    else if (rbnSort3.Checked == true)
                    {
                        strSELECT = "MST_ASSESSMENT.FA_YEAR AS PERIOD," +
