                        //
                        strWHERE = "";
                        //
                        strGROUP_BY = "MST_ASSESSMENT.FA_YEAR";
                        //
                        //strORDER_BY = "MST_ASSESSMENT.FA_YEAR";
                        strORDER_BY = " ORDER BY MST_EMPLOYEE.EMPLOYEE_NAME, MST_ASSESSMENT.FA_YEAR";
                        // FROM & TO PERIOD
                        strSortText = "";

                        strSummaryFilter = rbnSort3.Text;

                        //string[,] strArry = { { "txtReportTitle", "Deductee Transactions - " + rbnSort3.Text + " Summary" } };
                    }
                    // MAIN SQL
                    // Modified by Ripan Paul on 01-07-2013
                    // now section linked with deductee detail table
                    strQueryString = "SELECT MST_COMPANY.COMPANY_ID                         AS COMPANY_ID," +
                               "             MST_COMPANY.COMPANY_NAME                       AS COMPANY_NAME," +
                               "             MST_COMPANY.TAN_NO                             AS TAN_NO," +
                               "             MST_ASSESSMENT.FA_YEAR                         AS FA_YEAR," +
                               "             MST_EMPLOYEE.EMPLOYEE_ID                       AS DEDUCTEE_ID," +
                               "             MST_EMPLOYEE.EMPLOYEE_NAME                     AS DEDUCTEE_NAME," +
                               "             MST_EMPLOYEE.EMPLOYEE_PAN                      AS DEDUCTEE_PAN," +
                               "             MST_SECTION.SECTION_NO                         AS SECTION_NO," +
                               "             SUM(TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT)       AS PAYMENT_AMOUNT," +
                               "             SUM(TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT)           AS TAX_AMOUNT," +
                               "             SUM(TRN_DEDUCTEE_DETAILS.CESS_AMOUNT)          AS CESS_AMOUNT," +
                               "             SUM(TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT)         AS TOTAL_AMOUNT," +
                               "             SUM(TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT) AS TAX_DEPOSITED_AMOUNT,";

                    //strQueryString = strQueryString + strSELECT +
                    //           "      FROM   TRN_BASIC_INFO," +
                    //           "             TRN_CHALLAN," +
                    //           "             TRN_DEDUCTEE_DETAILS," +
                    //           "             MST_COMPANY," +
                    //           "             MST_EMPLOYEE," +
                    //           "             MST_SECTION," +
                    //           "             MST_ASSESSMENT " +
                    //           "      WHERE  TRN_BASIC_INFO.BASIC_INFO_ID       = TRN_CHALLAN.BASIC_INFO_ID " +
                    //           "      AND    TRN_CHALLAN.CHALLAN_ID             = TRN_DEDUCTEE_DETAILS.CHALLAN_ID " +
                    //           "      AND    TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_EMPLOYEE.EMPLOYEE_ID " +
                    //           "      AND    TRN_DEDUCTEE_DETAILS.SECTION_ID    = MST_SECTION.SECTION_ID " +
                    //           "      AND    MST_COMPANY.COMPANY_ID             = TRN_BASIC_INFO.COMPANY_ID " +
                    //           "      AND    TRN_BASIC_INFO.ASST_ID             = MST_ASSESSMENT.ASST_ID " +
                    //           "      AND    TRN_BASIC_INFO.FORM_NO            IN(" + strFormNoSelected + ") " +
                    //           "      AND    TRN_DEDUCTEE_DETAILS.PARTY_ID     IN(" + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + ") " +
                    //           "      AND    TRN_BASIC_INFO.COMPANY_ID          = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                    //           "      AND    TRN_BASIC_INFO.ASST_ID             = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " ";


                    strQueryString = strQueryString + strSELECT +
                                    " FROM (((((((TRN_BASIC_INFO  " +
                                    " INNER JOIN TRN_CHALLAN  " +
                                    "      ON TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID) " +
                                    " INNER JOIN TRN_DEDUCTEE_DETAILS " +
                                    "      ON TRN_CHALLAN.CHALLAN_ID = TRN_DEDUCTEE_DETAILS.CHALLAN_ID) " +
                                    " INNER JOIN MST_EMPLOYEE  " +
                                    "      ON TRN_DEDUCTEE_DETAILS.PARTY_ID = MST_EMPLOYEE.EMPLOYEE_ID) " +
                                    " INNER JOIN MST_SECTION  " +
                                    "      ON TRN_DEDUCTEE_DETAILS.SECTION_ID = MST_SECTION.SECTION_ID) " +
                                    " INNER JOIN MST_COMPANY " +
                                    "      ON MST_COMPANY.COMPANY_ID = TRN_BASIC_INFO.COMPANY_ID) " +
                                    " INNER JOIN MST_ASSESSMENT " +
                                    "      ON TRN_BASIC_INFO.ASST_ID = MST_ASSESSMENT.ASST_ID) " +
                                    " INNER JOIN " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED + " TSEL " +
                                    "      ON TSEL.ITEM_ID = TRN_DEDUCTEE_DETAILS.PARTY_ID) " +
                                    " WHERE TRN_BASIC_INFO.FORM_NO IN (" + strFormNoSelected + ") " +
                                    " AND TRN_BASIC_INFO.COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                                    " AND TRN_BASIC_INFO.ASST_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " ";


                    strQueryString = strQueryString + strWHERE +
                               "      GROUP BY MST_COMPANY.COMPANY_ID," +
                               "             MST_COMPANY.COMPANY_NAME," +
                               "             MST_COMPANY.TAN_NO," +
                               "             MST_ASSESSMENT.FA_YEAR," +
                               "             MST_EMPLOYEE.EMPLOYEE_ID," +
                               "             MST_EMPLOYEE.EMPLOYEE_NAME," +
                               "             MST_EMPLOYEE.EMPLOYEE_PAN," +
                               "             MST_SECTION.SECTION_NO, ";

                    strQueryString = strQueryString + strGROUP_BY;

                    strQueryString = strQueryString + strORDER_BY;

                    //string[,] strArry = { { "txtReportTitle", "Employee Transactions - " + strSummaryFilter + " Summary" } };
                    //rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                    //string strFAYearSQL = "SELECT MST_ASSESSMENT.FA_YEAR AS FA_YEAR " +
                    //                "     FROM   MST_ASSESSMENT," +
                    //                "            TRN_CHALLAN," +
                    //                "            TRN_DEDUCTEE_DETAILS," +
                    //                "            TRN_BASIC_INFO " +
                    //                "     WHERE  TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID " +
                    //                "     AND    TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID " +
                    //                "     AND    TRN_CHALLAN.CHALLAN_ID       = TRN_DEDUCTEE_DETAILS.CHALLAN_ID " +
                    //                "     AND    TRN_BASIC_INFO.FORM_NO      IN(" + strFormNoSelected + ") " +
                    //                "     AND    TRN_BASIC_INFO.COMPANY_ID    = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                    //                "     AND    TRN_DEDUCTEE_DETAILS.PARTY_ID     IN(" + strSelectedGridItemsWithSearch + ") " +
                    //                "     AND    TRN_DEDUCTEE_DETAILS.PAYMENT_DATE  >= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(mskFromDate) + cmnService.J_DateOperator() + " " +
                    //                "     AND    TRN_DEDUCTEE_DETAILS.PAYMENT_DATE  <= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(mskToDate) + cmnService.J_DateOperator() + " ";
                    if (TDSMAN.Classes.TDSMAN.T_EXPORT_REPORTS_CSV == true)
                    {
                        //
                        string strCSVPath = "", strCSVFileName = "PartyWiseDetail_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".csv";
                        // Create a new instance of FolderBrowserDialog.
                        FolderBrowserDialog folderBrowserDlg = new FolderBrowserDialog();
                        // A new folder button will display in FolderBrowserDialog.
                        folderBrowserDlg.ShowNewFolderButton = true;
                        //Show FolderBrowserDialog
                        DialogResult dlgResult = folderBrowserDlg.ShowDialog();
                        if (dlgResult.Equals(DialogResult.OK))
                        {
                            //Show selected folder path in textbox1.
                            strCSVPath = folderBrowserDlg.SelectedPath;
                            //Browsing start from root folder.
                            Environment.SpecialFolder rootFolder = folderBrowserDlg.RootFolder;
                        }
                        //
                        //string fullPath = Path.Combine(strCSVPath, strfolderName);
                        //// Create the directory
                        //Directory.CreateDirectory(fullPath);
                        //
                        if (strCSVPath != "")
                        {
                            ExportToCSV(strQueryString, Path.Combine(strCSVPath, strCSVFileName));
                            //
                            cmnService.J_UserMessage("Export completed");
                            //
                            System.Diagnostics.Process.Start(Path.Combine(strCSVPath, strCSVFileName));
                        }
                    }
                    else
                    {
                        //RDLC Report
                        string[,] strArryQuarterWiseDeducteeReport = { {"HeaderCompanyName", cmnService.J_Left(cmbCombo1.Text, cmbCombo1.Text.Length - 12) },
                                              {"HeaderTANFaYear", "TAN : " + cmnService.J_Left(cmnService.J_Right(cmbCombo1.Text,11),10) + " FA Year : " + cmbCombo2.Text },
                                              {"HeaderReportCD", "Employee Transactions - " + strSummaryFilter + " Summary"  },
                                              {"HeaderFromToDate", strSortText }
                                                };
                        J_PreviewReportRDLC("\\Reports\\crEmployeeWiseSummary.rdlc", "DataSet1", strQueryString, strArryQuarterWiseDeducteeReport);
                    }
                }
                //-----------------------------------------------------------------------

            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
