        #region PrintChallanReport
        //---------------------------------------------------
        //-- ANIK(2010-12-21)
        //---------------------------------------------------
        private void PrintChallanReport()
        {
            try
            {
                //-- Added By Abhishek Dey On 26/03/2018 --
                //CREATING TEMP TABLE FOR INSERTING REPORT DATA
                #region tblTEMP_CHALLAN_DETAILS_REPORT
                if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT) == false)
                {
                    dmlService.J_BeginTransaction();
                    // CREATE TEMP TABLE
                    strSQL = "CREATE TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + "(" +
                         "                 " + cmnService.J_GetDataType("CHALLAN_DETAILS_REPORT_ID", J_Identity.YES) + "," +
                         "                 " + cmnService.J_GetDataType("COMPANY_ID", J_ColumnType.Long, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("COMPANY_NAME", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("TAN_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("FA_YEAR", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("CHALLAN_ID", J_ColumnType.Long, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("FORM_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("QTR", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("DEPOSIT_DATE", J_ColumnType.DateTime, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SECTION_ID", J_ColumnType.Long, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SECTION_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SECTION_DESCRIPTION", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("BSR_CODE", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("CHALLAN_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("TDS", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SURCHARGE", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("EDUCATION_CESS", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("OTHERS", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("INTEREST", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("TOT_TAX", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("LATE_FEE", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("REMARKS", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("NOTE_SYMBOL", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("INTEREST_ALLOCATED", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("OTHERS_ALLOCATED", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("CHALLAN_BALANCE", J_ColumnType.Double, J_DefaultValue.YES) + ")";
                    //
                    dmlService.J_ExecSql(strSQL);
                    //
                    dmlService.J_Commit();
                }
                else
                {
                    dmlService.J_BeginTransaction();
                    //
                    strSQL = @"DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT;
                    dmlService.J_ExecSql(strSQL);
                    //
                    dmlService.J_Commit();
                    //--
                    dmlService.J_BeginTransaction();
                    //
                    #region T_tblTEMP_CHALLAN_DETAILS_REPORT(INTEREST_ALLOCATED)
                    if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT, "INTEREST_ALLOCATED") == false)
                    {
                        strSQL = "ALTER TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + " ADD COLUMN INTEREST_ALLOCATED MONEY DEFAULT 0";
                        dmlService.J_ExecSql(strSQL);
                        strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + " SET INTEREST_ALLOCATED = 0";
                        dmlService.J_ExecSql(strSQL);
                    }
                    #endregion
                    //
                    #region T_tblTEMP_CHALLAN_DETAILS_REPORT(OTHERS_ALLOCATED)
                    if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT, "OTHERS_ALLOCATED") == false)
                    {
                        strSQL = "ALTER TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + " ADD COLUMN OTHERS_ALLOCATED MONEY DEFAULT 0";
                        dmlService.J_ExecSql(strSQL);
                        strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + " SET OTHERS_ALLOCATED = 0";
                        dmlService.J_ExecSql(strSQL);
                    }
                    #endregion
                    //
                    #region T_tblTEMP_CHALLAN_DETAILS_REPORT(CHALLAN_BALANCE)
                    if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT, "CHALLAN_BALANCE") == false)
                    {
                        strSQL = "ALTER TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + " ADD COLUMN CHALLAN_BALANCE MONEY DEFAULT 0";
                        dmlService.J_ExecSql(strSQL);
                        strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + " SET CHALLAN_BALANCE = 0";
                        dmlService.J_ExecSql(strSQL);
                    }
                    #endregion
                    //
                    dmlService.J_Commit();
                }
                #endregion
                //-----------------------------------------
                //

                // UPDATE FOR BOOK ENTRY
                //TdsMan.T_UpdateBookEntry(dmlService.J_pCommand, lngBasicInfoID);
                // FORM NO
                string strFormNo = "";
                foreach (int indexChecked in clbListBox1.CheckedIndices)
                {
                    strFormNo = strFormNo + "'" + clbListBox1.Items[indexChecked] + "',";
                }
                if (cmnService.J_Right(strFormNo, 1) == ",")
                    strFormNo = cmnService.J_Mid(strFormNo, 0, (strFormNo.Length - 1));

                // QUARTER
                string strQtr = "";
                foreach (int indexChecked in clbListBox2.CheckedIndices)
                {
                    strQtr = strQtr + "'" + clbListBox2.Items[indexChecked] + "',";
                }
                if (cmnService.J_Right(strQtr, 1) == ",")
                    strQtr = cmnService.J_Mid(strQtr, 0, (strQtr.Length - 1));

                string[,] strChallanNoMatrix = {{"TRN_CHALLAN.BOOK_ENTRY = 1", "F", "TRN_CHALLAN.TRANSFER_VOUCHER_NO", "F"},
                                                {"TRN_CHALLAN.BOOK_ENTRY = 0", "F", "TRN_CHALLAN.CHALLAN_NO", "F"}};

                string[,] strNILBkEntryMatrix = {{"TRN_CHALLAN.BOOK_ENTRY = 1 ", "F", "BE", "T"},
                                                 {"TRN_CHALLAN.TOT_TAX    = 0 ", "F", "NIL", "T"},
                                                 {"TRN_CHALLAN.BOOK_ENTRY > 1 ", "F", "", "T"}}; //ELSE PART

                string[,] strChallanBalanceTot = {{"TRN_CHALLAN.CHALLAN_NO = ''", "F", "TRN_CHALLAN.TOT_TAX - TRN_CHALLAN.INTEREST_ALLOCATED - TRN_CHALLAN.OTHERS_ALLOCATED", "F"},
                                                 {"TRN_CHALLAN.TRANSFER_VOUCHER_NO = ''", "F", "TRN_CHALLAN.TOT_TAX - TRN_CHALLAN.INTEREST_ALLOCATED - TRN_CHALLAN.OTHERS_ALLOCATED- TRN_CHALLAN.LATE_FEE", "F"}};


                // MAIN SQL
                strQueryString = "SELECT MST_COMPANY.COMPANY_ID          AS COMPANY_ID," +
                    "                    MST_COMPANY.COMPANY_NAME        AS COMPANY_NAME," +
                    "                    MST_COMPANY.TAN_NO              AS TAN_NO," +
                    "                    MST_ASSESSMENT.FA_YEAR          AS FA_YEAR," +
                    "                    TRN_CHALLAN.CHALLAN_ID          AS CHALLAN_ID," +
                    "                    TRN_BASIC_INFO.FORM_NO          AS FORM_NO," +
                    "                    TRN_BASIC_INFO.QTR              AS QTR," +
                    "                    TRN_CHALLAN.DEPOSIT_DATE        AS DEPOSIT_DATE," +
                    "                    MST_SECTION.SECTION_ID          AS SECTION_ID," +
                    "                    MST_SECTION.SECTION_NO          AS SECTION_NO," +
                    "                    MST_SECTION.SECTION_DESCRIPTION AS SECTION_DESCRIPTION," +
                    "                    TRN_CHALLAN.BSR_CODE            AS BSR_CODE," +
                    "                  " + cmnService.J_SQLDBFormat(strChallanNoMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_NO," +
                    "                    TRN_CHALLAN.TDS                 AS TDS," +
                    "                    TRN_CHALLAN.SURCHARGE           AS SURCHARGE," +
                    "                    TRN_CHALLAN.EDUCATION_CESS      AS EDUCATION_CESS," +
                    "                    TRN_CHALLAN.OTHERS              AS OTHERS," +
                    "                    TRN_CHALLAN.INTEREST            AS INTEREST," +
                    "                    TRN_CHALLAN.TOT_TAX             AS TOT_TAX," +
                    "                    TRN_CHALLAN.LATE_FEE            AS LATE_FEE," +
                    "                  " + cmnService.J_SQLDBFormat(strNILBkEntryMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + " AS REMARKS," +
                    "                    TRN_CHALLAN.INTEREST_ALLOCATED  AS INTEREST_ALLOCATED," +
                    "                    TRN_CHALLAN.OTHERS_ALLOCATED    AS OTHERS_ALLOCATED, " +
                    "                    (" + cmnService.J_SQLDBFormat(strChallanBalanceTot, J_SQLColFormat.Case_End) + " - TRN_CHALLAN.CTRL_TOT_TAX) as CHALLAN_BALANCE " +
                    "             FROM   ((((TRN_CHALLAN INNER JOIN TRN_BASIC_INFO " +
                    "                    ON TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID) " +
                    "                    LEFT JOIN MST_SECTION " +
                    "                    ON MST_SECTION.SECTION_ID       = TRN_CHALLAN.SECTION_ID) " +
                    "                    INNER JOIN MST_COMPANY " +
                    "                    ON TRN_BASIC_INFO.COMPANY_ID    = MST_COMPANY.COMPANY_ID) " +
                    "                    INNER JOIN MST_ASSESSMENT " +
                    "                    ON TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID) " +
                    "             WHERE  TRN_BASIC_INFO.COMPANY_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                    "             AND    TRN_BASIC_INFO.ASST_ID          = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " " +
                    "             AND    TRN_BASIC_INFO.QTR             IN (" + strQtr + ") " +
                    "             AND    TRN_BASIC_INFO.FORM_NO         IN (" + strFormNo + ") ";
                //--
                if (Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) < T_FinancialYearID.F2013_14ID)
                    strQueryString = strQueryString + "AND    MST_SECTION.SECTION_ID       IN (" + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + ") ";

                // CHALLAN TYPE
                if (cmbCombo3.Text == T_ChallanTypeFilter.BankChallan)
                    strQueryString = strQueryString + "AND TRN_CHALLAN.BOOK_ENTRY = 0 " +
                                                      "AND TRN_CHALLAN.TOT_TAX    > 0 ";
                else if (cmbCombo3.Text == T_ChallanTypeFilter.BookEntry)
                    strQueryString = strQueryString + "AND TRN_CHALLAN.BOOK_ENTRY = 1 ";
                else if (cmbCombo3.Text == T_ChallanTypeFilter.NILChallan)
                    strQueryString = strQueryString + "AND TRN_CHALLAN.TOT_TAX = 0 ";

                // DATE
                if (rbnSort1.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_CHALLAN.DEPOSIT_DATE, TRN_CHALLAN.CHALLAN_ID";
                // FORM NO
                else if (rbnSort2.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_BASIC_INFO.FORM_NO, TRN_CHALLAN.CHALLAN_ID";
                // QTR
                else if (rbnSort3.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_BASIC_INFO.QTR, TRN_CHALLAN.CHALLAN_ID";
                // SECTION
                else if (rbnSort4.Checked == true)
                    strQueryString = strQueryString + " ORDER BY MST_SECTION.SECTION_NO, TRN_CHALLAN.CHALLAN_ID";


                //-- Added By Abhishek Dey On 26/03/2018 --
                // INSERT DATA INTO TEMP TABLE
                dmlService.J_BeginTransaction();
                //
                strSQL = "INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + "(" +
                                      " COMPANY_ID, " +
                                      " COMPANY_NAME, " +
                                      " TAN_NO, " +
                                      " FA_YEAR, " +
                                      " CHALLAN_ID, " +
                                      " FORM_NO, " +
                                      " QTR, " +
                                      " DEPOSIT_DATE, " +
                                      " SECTION_ID, " +
                                      " SECTION_NO, " +
                                      " SECTION_DESCRIPTION, " +
                                      " BSR_CODE, " +
                                      " CHALLAN_NO, " +
                                      " TDS, " +
                                      " SURCHARGE, " +
                                      " EDUCATION_CESS, " +
                                      " OTHERS, " +
                                      " INTEREST, " +
                                      " TOT_TAX, " +
                                      " LATE_FEE, " +
                                      " REMARKS, " +
                                      " INTEREST_ALLOCATED, " +
                                      " OTHERS_ALLOCATED, " +
                                      " CHALLAN_BALANCE ) ";
                //
                strSQL = strSQL + strQueryString;
                //
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return;
                }
                //
                dmlService.J_Commit();
                //
                // DELETE ALL DUPLICATE CHALLAN NO EXCEPT ONE FROM TEMP TABLE
                dmlService.J_BeginTransaction();
                //
                strSQL = "DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @"
                          WHERE CHALLAN_DETAILS_REPORT_ID NOT IN
                                                               (SELECT   MIN(CHALLAN_DETAILS_REPORT_ID) 
                                                                FROM  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @"  
                                                                GROUP BY CHALLAN_NO, 
                                                                         BSR_CODE,
                                                                         DEPOSIT_DATE,  
                                                                         TOT_TAX, FORM_NO)";
                //
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return;
                }
                //
                dmlService.J_Commit();
                //               
                strSQL = @" SELECT " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + ".CHALLAN_ID " +
                          " FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @"
                            INNER JOIN 
                            (SELECT CHALLAN_NO,
                            BSR_CODE,
                            DEPOSIT_DATE,
                            TOT_TAX
                            FROM TRN_CHALLAN
                            GROUP BY CHALLAN_NO,
                            BSR_CODE,
                            DEPOSIT_DATE,
                            TOT_TAX
                            HAVING COUNT(*) > 1)AS CHALLAN
                            ON CHALLAN.CHALLAN_NO = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @".CHALLAN_NO
                            AND CHALLAN.BSR_CODE = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @".BSR_CODE
                            AND CHALLAN.DEPOSIT_DATE = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @".DEPOSIT_DATE
                            AND CHALLAN.TOT_TAX =  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @".TOT_TAX";
                //                
                DataSet dsChallanNo = new DataSet();
                dsChallanNo = dmlService.J_ExecSqlReturnDataSet(strSQL);
                for (int i = 0; i <= dsChallanNo.Tables[0].Rows.Count - 1; i++)
                {
                    dmlService.J_BeginTransaction();
                    //
                    strSQL = " UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @"
                                  SET    NOTE_SYMBOL = '***'
                                  WHERE  CHALLAN_ID = " + Convert.ToInt32(dsChallanNo.Tables[0].Rows[i]["CHALLAN_ID"].ToString());
                    //
                    dmlService.J_ExecSql(strSQL);
                    //
                    dmlService.J_Commit();
                }
                //
                dsChallanNo.Dispose();
                //                                
                //
                strQueryString = @"SELECT COMPANY_ID,          
                                          COMPANY_NAME,      
                                          TAN_NO,              
                                          FA_YEAR,          
                                          CHALLAN_ID,        
                                          FORM_NO,         
                                          QTR,              
                                          DEPOSIT_DATE,        
                                          SECTION_ID,          
                                          SECTION_NO,         
                                          SECTION_DESCRIPTION, 
                                          BSR_CODE,           
                                          CHALLAN_NO,
                                          TDS,
                                          SURCHARGE,
                                          EDUCATION_CESS,
                                          OTHERS,
                                          INTEREST,
                                          TOT_TAX,
                                          LATE_FEE,
                                          REMARKS,
                                          NOTE_SYMBOL,
                                          INTEREST_ALLOCATED,
                                          OTHERS_ALLOCATED,
                                          CHALLAN_BALANCE
                                   FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT;
                //-----------------------------------------

                crChallanReport rptChallanReport = new crChallanReport();
                rptcls = (ReportClass)rptChallanReport;
                // FORM SELECTED
                TextObject objtxtValue;

                strFormNo = strFormNo.Replace("'", "");
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFormSelected"];
                objtxtValue.Text = "FORMS : " + strFormNo;
                // QTR SELECTED
                strQtr = strQtr.Replace("'", "");
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtQtrSelected"];
                objtxtValue.Text = "QUARTERS : " + strQtr;

                string[,] strArry = { { "txtReportTitle", "Challan Report" } };
                rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                //
                //-- Added By Abhishek Dey On 27/03/2018 --
                // DELETE TEMP TABLE
                ////
                //dmlService.J_BeginTransaction();
                ////
                //strSQL = @" DROP TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT;
                //dmlService.J_ExecSql(strSQL);
                ////
                //dmlService.J_Commit();
                dmlService.J_BeginTransaction();
                //
                strSQL = @"DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT;
                //
                dmlService.J_ExecSql(strSQL);
                //
                dmlService.J_Commit();
                //-----------------------------------------
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

        #region PrintChallanReport_RDLC
        //---------------------------------------------------
        //-- ANIK(2010-12-21)
        //---------------------------------------------------
        private void PrintChallanReport_RDLC()
        {
            try
            {
                //-- Added By Abhishek Dey On 26/03/2018 --
                //CREATING TEMP TABLE FOR INSERTING REPORT DATA
                #region tblTEMP_CHALLAN_DETAILS_REPORT
                if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT) == false)
                {
                    dmlService.J_BeginTransaction();
                    // CREATE TEMP TABLE
                    strSQL = "CREATE TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + "(" +
                         "                 " + cmnService.J_GetDataType("CHALLAN_DETAILS_REPORT_ID", J_Identity.YES) + "," +
                         "                 " + cmnService.J_GetDataType("COMPANY_ID", J_ColumnType.Long, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("COMPANY_NAME", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("TAN_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("FA_YEAR", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("CHALLAN_ID", J_ColumnType.Long, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("FORM_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("QTR", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("DEPOSIT_DATE", J_ColumnType.DateTime, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SECTION_ID", J_ColumnType.Long, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SECTION_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SECTION_DESCRIPTION", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("BSR_CODE", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("CHALLAN_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("TDS", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SURCHARGE", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("EDUCATION_CESS", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("OTHERS", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("INTEREST", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("TOT_TAX", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("LATE_FEE", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("REMARKS", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("NOTE_SYMBOL", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("INTEREST_ALLOCATED", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("OTHERS_ALLOCATED", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("CHALLAN_BALANCE", J_ColumnType.Double, J_DefaultValue.YES) + ")";
                    //
                    dmlService.J_ExecSql(strSQL);
                    //
                    dmlService.J_Commit();
                }
                else
                {
                    dmlService.J_BeginTransaction();
                    //
                    strSQL = @"DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT;
                    dmlService.J_ExecSql(strSQL);
                    //
                    dmlService.J_Commit();
                    //--
                    dmlService.J_BeginTransaction();
                    //
                    #region T_tblTEMP_CHALLAN_DETAILS_REPORT(INTEREST_ALLOCATED)
                    if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT, "INTEREST_ALLOCATED") == false)
                    {
                        strSQL = "ALTER TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + " ADD COLUMN INTEREST_ALLOCATED MONEY DEFAULT 0";
                        dmlService.J_ExecSql(strSQL);
                        strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + " SET INTEREST_ALLOCATED = 0";
                        dmlService.J_ExecSql(strSQL);
                    }
                    #endregion
                    //
                    #region T_tblTEMP_CHALLAN_DETAILS_REPORT(OTHERS_ALLOCATED)
                    if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT, "OTHERS_ALLOCATED") == false)
                    {
                        strSQL = "ALTER TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + " ADD COLUMN OTHERS_ALLOCATED MONEY DEFAULT 0";
                        dmlService.J_ExecSql(strSQL);
                        strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + " SET OTHERS_ALLOCATED = 0";
                        dmlService.J_ExecSql(strSQL);
                    }
                    #endregion
                    //
                    #region T_tblTEMP_CHALLAN_DETAILS_REPORT(CHALLAN_BALANCE)
                    if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT, "CHALLAN_BALANCE") == false)
                    {
                        strSQL = "ALTER TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + " ADD COLUMN CHALLAN_BALANCE MONEY DEFAULT 0";
                        dmlService.J_ExecSql(strSQL);
                        strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + " SET CHALLAN_BALANCE = 0";
                        dmlService.J_ExecSql(strSQL);
                    }
                    #endregion
                    //
                    dmlService.J_Commit();
                }
                #endregion
                //-----------------------------------------
                //

                // UPDATE FOR BOOK ENTRY
                //TdsMan.T_UpdateBookEntry(dmlService.J_pCommand, lngBasicInfoID);
                // FORM NO
                //string strFormNo = "";
                //foreach (int indexChecked in clbListBox1.CheckedIndices)
                //{
                //    strFormNo = strFormNo + "'" + clbListBox1.Items[indexChecked] + "',";
                //}
                //if (cmnService.J_Right(strFormNo, 1) == ",")
                //    strFormNo = cmnService.J_Mid(strFormNo, 0, (strFormNo.Length - 1));
                string strFormNo = "";

                foreach (int indexChecked in clbListBox1.CheckedIndices)
                {
                    string strItem = clbListBox1.Items[indexChecked].ToString();

                    int startIndex = strItem.IndexOf("(");
                    int endIndex = strItem.IndexOf(")");

                    if (startIndex >= 0 && endIndex > startIndex)
                    {
                        string formNo = strItem.Substring(
                            startIndex + 1,
                            endIndex - startIndex - 1);

                        strFormNo += "'" + formNo + "',";
                    }
                }

                if (cmnService.J_Right(strFormNo, 1) == ",")
                {
                    strFormNo = cmnService.J_Mid(
                        strFormNo,
                        0,
                        strFormNo.Length - 1);
                }
                // QUARTER
                string strQtr = "";
                foreach (int indexChecked in clbListBox2.CheckedIndices)
                {
                    strQtr = strQtr + "'" + clbListBox2.Items[indexChecked] + "',";
                }
                if (cmnService.J_Right(strQtr, 1) == ",")
                    strQtr = cmnService.J_Mid(strQtr, 0, (strQtr.Length - 1));

                string[,] strChallanNoMatrix = {{"TRN_CHALLAN.BOOK_ENTRY = 1", "F", "TRN_CHALLAN.TRANSFER_VOUCHER_NO", "F"},
                                                {"TRN_CHALLAN.BOOK_ENTRY = 0", "F", "TRN_CHALLAN.CHALLAN_NO", "F"}};

                string[,] strNILBkEntryMatrix = {{"TRN_CHALLAN.BOOK_ENTRY = 1 ", "F", "BE", "T"},
                                                 {"TRN_CHALLAN.TOT_TAX    = 0 ", "F", "NIL", "T"},
                                                 {"TRN_CHALLAN.BOOK_ENTRY > 1 ", "F", "", "T"}}; //ELSE PART

                string[,] strChallanBalanceTot = {{"TRN_CHALLAN.CHALLAN_NO = ''", "F", "TRN_CHALLAN.TOT_TAX - TRN_CHALLAN.INTEREST_ALLOCATED - TRN_CHALLAN.OTHERS_ALLOCATED", "F"},
                                                 {"TRN_CHALLAN.TRANSFER_VOUCHER_NO = ''", "F", "TRN_CHALLAN.TOT_TAX - TRN_CHALLAN.INTEREST_ALLOCATED - TRN_CHALLAN.OTHERS_ALLOCATED- TRN_CHALLAN.LATE_FEE", "F"}};


                // MAIN SQL
                strQueryString = "SELECT MST_COMPANY.COMPANY_ID          AS COMPANY_ID," +
                    "                    MST_COMPANY.COMPANY_NAME        AS COMPANY_NAME," +
                    "                    MST_COMPANY.TAN_NO              AS TAN_NO," +
                    "                    MST_ASSESSMENT.FA_YEAR          AS FA_YEAR," +
                    "                    TRN_CHALLAN.CHALLAN_ID          AS CHALLAN_ID," +
                    "                    TRN_BASIC_INFO.FORM_NO          AS FORM_NO," +
                    "                    TRN_BASIC_INFO.QTR              AS QTR," +
                    "                    TRN_CHALLAN.DEPOSIT_DATE        AS DEPOSIT_DATE," +
                    "                    MST_SECTION.SECTION_ID          AS SECTION_ID," +
                    "                    MST_SECTION.SECTION_NO          AS SECTION_NO," +
                    "                    MST_SECTION.SECTION_DESCRIPTION AS SECTION_DESCRIPTION," +
                    "                    TRN_CHALLAN.BSR_CODE            AS BSR_CODE," +
                    "                  " + cmnService.J_SQLDBFormat(strChallanNoMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_NO," +
                    "                    TRN_CHALLAN.TDS                 AS TDS," +
                    "                    TRN_CHALLAN.SURCHARGE           AS SURCHARGE," +
                    "                    TRN_CHALLAN.EDUCATION_CESS      AS EDUCATION_CESS," +
                    "                    TRN_CHALLAN.OTHERS              AS OTHERS," +
                    "                    TRN_CHALLAN.INTEREST            AS INTEREST," +
                    "                    TRN_CHALLAN.TOT_TAX             AS TOT_TAX," +
                    "                    TRN_CHALLAN.LATE_FEE            AS LATE_FEE," +
                    "                  " + cmnService.J_SQLDBFormat(strNILBkEntryMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + " AS REMARKS," +
                    "                    TRN_CHALLAN.INTEREST_ALLOCATED  AS INTEREST_ALLOCATED," +
                    "                    TRN_CHALLAN.OTHERS_ALLOCATED    AS OTHERS_ALLOCATED, " +
                    "                    (" + cmnService.J_SQLDBFormat(strChallanBalanceTot, J_SQLColFormat.Case_End) + " - TRN_CHALLAN.CTRL_TOT_TAX) as CHALLAN_BALANCE " +
                    "             FROM   ((((TRN_CHALLAN INNER JOIN TRN_BASIC_INFO " +
                    "                    ON TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID) " +
                    "                    LEFT JOIN MST_SECTION " +
                    "                    ON MST_SECTION.SECTION_ID       = TRN_CHALLAN.SECTION_ID) " +
                    "                    INNER JOIN MST_COMPANY " +
                    "                    ON TRN_BASIC_INFO.COMPANY_ID    = MST_COMPANY.COMPANY_ID) " +
                    "                    INNER JOIN MST_ASSESSMENT " +
                    "                    ON TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID) " +
                    "             WHERE  TRN_BASIC_INFO.COMPANY_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                    "             AND    TRN_BASIC_INFO.ASST_ID          = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " " +
                    "             AND    TRN_BASIC_INFO.QTR             IN (" + strQtr + ") " +
                    "             AND    TRN_BASIC_INFO.FORM_NO         IN (" + strFormNo + ") ";
                //--
                if (Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) < T_FinancialYearID.F2013_14ID)
                    strQueryString = strQueryString + "AND    MST_SECTION.SECTION_ID       IN (" + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + ") ";

                // CHALLAN TYPE
                if (cmbCombo3.Text == T_ChallanTypeFilter.BankChallan)
                    strQueryString = strQueryString + "AND TRN_CHALLAN.BOOK_ENTRY = 0 " +
                                                      "AND TRN_CHALLAN.TOT_TAX    > 0 ";
                else if (cmbCombo3.Text == T_ChallanTypeFilter.BookEntry)
                    strQueryString = strQueryString + "AND TRN_CHALLAN.BOOK_ENTRY = 1 ";
                else if (cmbCombo3.Text == T_ChallanTypeFilter.NILChallan)
                    strQueryString = strQueryString + "AND TRN_CHALLAN.TOT_TAX = 0 ";

                // DATE
                if (rbnSort1.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_CHALLAN.DEPOSIT_DATE, TRN_CHALLAN.CHALLAN_ID";
                // FORM NO
                else if (rbnSort2.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_BASIC_INFO.FORM_NO, TRN_CHALLAN.CHALLAN_ID";
                // QTR
                else if (rbnSort3.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_BASIC_INFO.QTR, TRN_CHALLAN.CHALLAN_ID";
                // SECTION
                else if (rbnSort4.Checked == true)
                    strQueryString = strQueryString + " ORDER BY MST_SECTION.SECTION_NO, TRN_CHALLAN.CHALLAN_ID";


                //-- Added By Abhishek Dey On 26/03/2018 --
                // INSERT DATA INTO TEMP TABLE
                dmlService.J_BeginTransaction();
                //
                strSQL = "INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + "(" +
                                      " COMPANY_ID, " +
                                      " COMPANY_NAME, " +
                                      " TAN_NO, " +
                                      " FA_YEAR, " +
                                      " CHALLAN_ID, " +
                                      " FORM_NO, " +
                                      " QTR, " +
                                      " DEPOSIT_DATE, " +
                                      " SECTION_ID, " +
                                      " SECTION_NO, " +
                                      " SECTION_DESCRIPTION, " +
                                      " BSR_CODE, " +
                                      " CHALLAN_NO, " +
                                      " TDS, " +
                                      " SURCHARGE, " +
                                      " EDUCATION_CESS, " +
                                      " OTHERS, " +
                                      " INTEREST, " +
                                      " TOT_TAX, " +
                                      " LATE_FEE, " +
                                      " REMARKS, " +
                                      " INTEREST_ALLOCATED, " +
                                      " OTHERS_ALLOCATED, " +
                                      " CHALLAN_BALANCE ) ";
                //
                strSQL = strSQL + strQueryString;
                //
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return;
                }
                //
                dmlService.J_Commit();
                //
                // DELETE ALL DUPLICATE CHALLAN NO EXCEPT ONE FROM TEMP TABLE
                dmlService.J_BeginTransaction();
                //
                strSQL = "DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @"
                          WHERE CHALLAN_DETAILS_REPORT_ID NOT IN
                                                               (SELECT   MIN(CHALLAN_DETAILS_REPORT_ID) 
                                                                FROM  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @"  
                                                                GROUP BY CHALLAN_NO, 
                                                                         BSR_CODE,
                                                                         DEPOSIT_DATE,  
                                                                         TOT_TAX, FORM_NO)";
                //
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return;
                }
                //
                dmlService.J_Commit();
                //               
                strSQL = @" SELECT " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + ".CHALLAN_ID " +
                          " FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @"
                            INNER JOIN 
                            (SELECT CHALLAN_NO,
                            BSR_CODE,
                            DEPOSIT_DATE,
                            TOT_TAX
                            FROM TRN_CHALLAN
                            GROUP BY CHALLAN_NO,
                            BSR_CODE,
                            DEPOSIT_DATE,
                            TOT_TAX
                            HAVING COUNT(*) > 1)AS CHALLAN
                            ON CHALLAN.CHALLAN_NO = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @".CHALLAN_NO
                            AND CHALLAN.BSR_CODE = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @".BSR_CODE
                            AND CHALLAN.DEPOSIT_DATE = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @".DEPOSIT_DATE
                            AND CHALLAN.TOT_TAX =  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @".TOT_TAX";
                //                
                DataSet dsChallanNo = new DataSet();
                dsChallanNo = dmlService.J_ExecSqlReturnDataSet(strSQL);
                for (int i = 0; i <= dsChallanNo.Tables[0].Rows.Count - 1; i++)
                {
                    dmlService.J_BeginTransaction();
                    //
                    strSQL = " UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT + @"
                                  SET    NOTE_SYMBOL = '***'
                                  WHERE  CHALLAN_ID = " + Convert.ToInt32(dsChallanNo.Tables[0].Rows[i]["CHALLAN_ID"].ToString());
                    //
                    dmlService.J_ExecSql(strSQL);
                    //
                    dmlService.J_Commit();
                }
                //
                dsChallanNo.Dispose();
                //                                
                //
                strQueryString = @"SELECT COMPANY_ID,          
                                          COMPANY_NAME,      
                                          TAN_NO,              
                                          FA_YEAR,          
                                          CHALLAN_ID,        
                                          FORM_NO,         
                                          QTR,              
                                          DEPOSIT_DATE,        
                                          SECTION_ID,          
                                          SECTION_NO,         
                                          SECTION_DESCRIPTION, 
                                          BSR_CODE,           
                                          CHALLAN_NO,
                                          TDS,
                                          SURCHARGE,
                                          EDUCATION_CESS,
                                          OTHERS,
                                          INTEREST,
                                          TOT_TAX,
                                          LATE_FEE,
                                          REMARKS,
                                          NOTE_SYMBOL,
                                          INTEREST_ALLOCATED,
                                          OTHERS_ALLOCATED,
                                          CHALLAN_BALANCE
                                   FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT;
                //-----------------------------------------
                strFormNo = strFormNo.Replace("'", ""); strQtr = strQtr.Replace("'", "");
                string[,] strArryChallanReport = { {"HeaderCompanyName", cmnService.J_Left(cmbCombo1.Text, cmbCombo1.Text.Length - 12) },
                                              {"HeaderTANFaYear", "TAN : " + cmnService.J_Left(cmnService.J_Right(cmbCombo1.Text,11),10) + " FA Year : " + cmbCombo2.Text },
                                              {"HeaderReportCD", "Challan Report" },
                                              {"HeaderFromToDate", "FORMS : " + strFormNo },
                                              {"HeaderQtr", "QUARTERS : " + strQtr }
                                                };

                J_PreviewReportRDLC("\\Reports\\crChallanReport.rdlc", "DataSet1", strQueryString, strArryChallanReport);

                //crChallanReport rptChallanReport = new crChallanReport();
                //rptcls = (ReportClass)rptChallanReport;
                //// FORM SELECTED
                //TextObject objtxtValue;

                //strFormNo = strFormNo.Replace("'", "");
                //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFormSelected"];
                //objtxtValue.Text = "FORMS : " + strFormNo;

                //// QTR SELECTED
                //strQtr = strQtr.Replace("'", "");
                //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtQtrSelected"];
                //objtxtValue.Text = "QUARTERS : " + strQtr;

                //string[,] strArry = { { "txtReportTitle", "Challan Report" } };
                //rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                //
                //-- Added By Abhishek Dey On 27/03/2018 --
                // DELETE TEMP TABLE
                ////
                //dmlService.J_BeginTransaction();
                ////
                //strSQL = @" DROP TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT;
                //dmlService.J_ExecSql(strSQL);
                ////
                //dmlService.J_Commit();
                dmlService.J_BeginTransaction();
                //
                strSQL = @"DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT;
                //
                dmlService.J_ExecSql(strSQL);
                //
                dmlService.J_Commit();
                //-----------------------------------------
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

        #region PrintQuarterWiseChallanReport
        //---------------------------------------------------
        //-- ANIK(2010-12-22)
        //---------------------------------------------------
        private void PrintQuarterWiseChallanReport()
        {
            try
            {
                string[,] strChallanNoMatrix = {{"TRN_CHALLAN.CHALLAN_NO = ''", "F", "TRN_CHALLAN.TRANSFER_VOUCHER_NO", "F"},
                                                {"TRN_CHALLAN.TRANSFER_VOUCHER_NO = ''", "F", "TRN_CHALLAN.CHALLAN_NO", "F"}};

                string[,] strNILBkEntryMatrix = {{"TRN_CHALLAN.BOOK_ENTRY = 1 ", "F", "BE", "T"},
                                                 {"TRN_CHALLAN.TOT_TAX    = 0 ", "F", "NIL", "T"},
                                                 {"TRN_CHALLAN.BOOK_ENTRY > 1 ", "F", "", "T"}};
                // MAIN SQL
                strQueryString = "SELECT MST_COMPANY.COMPANY_ID          AS COMPANY_ID," +
                    "                    MST_COMPANY.COMPANY_NAME        AS COMPANY_NAME," +
                    "                    MST_COMPANY.TAN_NO              AS TAN_NO," +
                    "                    MST_ASSESSMENT.FA_YEAR          AS FA_YEAR," +
                    "                    TRN_CHALLAN.CHALLAN_ID          AS CHALLAN_ID," +
                    "                    TRN_BASIC_INFO.FORM_NO          AS FORM_NO," +
                    "                    TRN_BASIC_INFO.QTR              AS QTR," +
                    "                    TRN_CHALLAN.DEPOSIT_DATE        AS DEPOSIT_DATE," +
                    "                    MST_SECTION.SECTION_ID          AS SECTION_ID," +
                    "                    MST_SECTION.SECTION_NO          AS SECTION_NO," +
                    "                    MST_SECTION.SECTION_DESCRIPTION AS SECTION_DESCRIPTION," +
                    "                    TRN_CHALLAN.BSR_CODE            AS BSR_CODE," +
                    "                  " + cmnService.J_SQLDBFormat(strChallanNoMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_NO," +
                    "                    TRN_CHALLAN.CHEQUE_NO           AS CHEQUE_NO," +
                    "                    TRN_CHALLAN.TDS                 AS TDS," +
                    "                    TRN_CHALLAN.SURCHARGE           AS SURCHARGE," +
                    "                    TRN_CHALLAN.EDUCATION_CESS      AS EDUCATION_CESS," +
                    "                    TRN_CHALLAN.OTHERS              AS OTHERS," +
                    "                    TRN_CHALLAN.INTEREST            AS INTEREST," +
                    "                    TRN_CHALLAN.TOT_TAX             AS TOT_TAX," +
                    "                  " + cmnService.J_SQLDBFormat(strNILBkEntryMatrix, J_SQLColFormat.Case_End) + " AS REMARKS," +
                    "                    TRN_CHALLAN.SL_NO               AS SL_NO " +
                    "             FROM   MST_SECTION," +
                    "                    TRN_CHALLAN," +
                    "                    TRN_BASIC_INFO," +
                    "                    MST_COMPANY," +
                    "                    MST_ASSESSMENT " +
                    "             WHERE  MST_SECTION.SECTION_ID       = TRN_CHALLAN.SECTION_ID " +
                    "             AND    TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID " +
                    "             AND    TRN_BASIC_INFO.COMPANY_ID    = MST_COMPANY.COMPANY_ID " +
                    "             AND    TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID " +
                    "             AND    TRN_BASIC_INFO.COMPANY_ID    = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                    "             AND    TRN_BASIC_INFO.ASST_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " " +
                    "             AND    TRN_BASIC_INFO.FORM_NO       ='" + cmbCombo3.Text + "' " +
                    "             AND    TRN_BASIC_INFO.QTR           ='" + cmbCombo4.Text + "' ";

                // DATE
                if (rbnSort1.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_CHALLAN.DEPOSIT_DATE, TRN_CHALLAN.CHALLAN_ID";
                // SECTION
                else if (rbnSort2.Checked == true)
                    strQueryString = strQueryString + " ORDER BY MST_SECTION.SECTION_NO, TRN_CHALLAN.CHALLAN_ID";

                // SECTION
                else if (rbnSort3.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_CHALLAN.CHALLAN_ID";


                crQuarterWiseChallanReport rptQuarterWiseChallanReport = new crQuarterWiseChallanReport();
                rptcls = (ReportClass)rptQuarterWiseChallanReport;
                // FORM SELECTED
                TextObject objtxtValue;

                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToDate"];
                objtxtValue.Text = "From : " + TdsMan.T_ReturnQuarterStartDate(cmbCombo4.Text, cmbCombo2.Text) + " To : " + TdsMan.T_ReturnQuarterEndDate(cmbCombo4.Text, cmbCombo2.Text);

                string[,] strArry = { { "txtReportTitle", "Form No. " + cmbCombo3.Text + " - Challan Details" } };
                rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);

            }
            catch (Exception err_handler)
