        #region PrintQuarterWiseDeducteeReport
        //---------------------------------------------------
        //-- ANIK(2010-12-22)
        //---------------------------------------------------
        private void PrintQuarterWiseDeducteeReport()
        {
            try
            {
                string[,] strChallanNoMatrix = {{"TRN_CHALLAN.CHALLAN_NO = ''", "F", "TRN_CHALLAN.TRANSFER_VOUCHER_NO", "F"},
                                                {"TRN_CHALLAN.TRANSFER_VOUCHER_NO = ''", "F", "TRN_CHALLAN.CHALLAN_NO", "F"}};


                string[,] strChallanNoTextMatrix = {{"TRN_CHALLAN.BOOK_ENTRY = 1 ", "F", "TRANSFER_VOUCHER_NO", "T"},
                                                 {"TRN_CHALLAN.BOOK_ENTRY = 0 ", "F", "CHALLAN_NO", "T"}};

                // MAIN SQL
                strQueryString = "SELECT MST_COMPANY.COMPANY_ID                    AS COMPANY_ID," +
                    "                    MST_COMPANY.COMPANY_NAME                  AS COMPANY_NAME," +
                    "                    MST_COMPANY.TAN_NO                        AS TAN_NO," +
                    "                    TRN_CHALLAN.CHALLAN_ID                    AS CHALLAN_ID," +
                    "                   " + cmnService.J_SQLDBFormat(strChallanNoMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_NO," +
                    "                   " + cmnService.J_SQLDBFormat(strChallanNoTextMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_NO_TEXT," +
                    "                    TRN_CHALLAN.BSR_CODE                      AS BSR_CODE," +
                    "                    TRN_CHALLAN.DEPOSIT_DATE                  AS DEPOSIT_DATE," +
                    "                    MST_DEDUCTEE.DEDUCTEE_ID                  AS DEDUCTEE_ID," +
                    "                    MST_DEDUCTEE.DEDUCTEE_NAME                AS DEDUCTEE_NAME," +
                    "                    MST_DEDUCTEE.DEDUCTEE_PAN                 AS DEDUCTEE_PAN," +
                    "                    TRN_DEDUCTEE_DETAILS.PAYMENT_DATE         AS DEDUCTED_DATE," +
                    "                    MST_SECTION.SECTION_NO                    AS SECTION_NO," +
                    "                    TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT       AS PAYMENT_AMOUNT," +
                    "                    TRN_DEDUCTEE_DETAILS.RATE                 AS RATE," +
                    "                    TRN_DEDUCTEE_DETAILS.TAX_AMOUNT           AS TAX_AMOUNT," +
                    "                    TRN_DEDUCTEE_DETAILS.SURCHARGE_AMOUNT     AS SURCHARGE_AMOUNT," +
                    "                    TRN_DEDUCTEE_DETAILS.CESS_AMOUNT          AS CESS_AMOUNT," +
                    "                    TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT         AS TOTAL_AMOUNT," +
                    "                    TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT AS TAX_DEPOSITED_AMOUNT," +
                    "                    TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG   AS NON_DEDUCTION_FLAG," +
                    "                    MST_ASSESSMENT.FA_YEAR                    AS FA_YEAR," +
                    "                    TRN_CHALLAN.TOT_TAX                       AS TOT_TAX " +
                    "             FROM   TRN_BASIC_INFO," +
                    "                    TRN_CHALLAN," +
                    "                    TRN_DEDUCTEE_DETAILS," +
                    "                    MST_COMPANY," +
                    "                    MST_DEDUCTEE," +
                    "                    MST_SECTION," +
                    "                    MST_CATEGORY," +
                    "                    MST_ASSESSMENT " +
                    "             WHERE  TRN_BASIC_INFO.BASIC_INFO_ID       = TRN_CHALLAN.BASIC_INFO_ID " +
                    "             AND    TRN_CHALLAN.CHALLAN_ID             = TRN_DEDUCTEE_DETAILS.CHALLAN_ID " +
                    "             AND    TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_DEDUCTEE.DEDUCTEE_ID " +
                    "             AND    TRN_CHALLAN.SECTION_ID             = MST_SECTION.SECTION_ID " +
                    "             AND    MST_COMPANY.COMPANY_ID             = TRN_BASIC_INFO.COMPANY_ID " +
                    "             AND    MST_CATEGORY.CATEGORY_ID           = MST_COMPANY.D_CATEGORY_ID " +
                    "             AND    TRN_BASIC_INFO.ASST_ID             = MST_ASSESSMENT.ASST_ID " +
                    "             AND    TRN_BASIC_INFO.COMPANY_ID          = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                    "             AND    TRN_BASIC_INFO.ASST_ID             = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " " +
                    "             AND    TRN_BASIC_INFO.FORM_NO             ='" + cmbCombo3.Text + "' " +
                    "             AND    TRN_BASIC_INFO.QTR                 ='" + cmbCombo4.Text + "' ";

                // DEDUCTEE NAME
                if (rbnSort1.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_CHALLAN.CHALLAN_ID, MST_DEDUCTEE.DEDUCTEE_NAME, TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID";
                // DATE
                else if (rbnSort2.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_CHALLAN.CHALLAN_ID, TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID";
                // SECTION
                else if (rbnSort3.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_CHALLAN.CHALLAN_ID, TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID";


                //crQuarterWiseDeducteeReport rptQuarterWiseDeducteeReport = new crQuarterWiseDeducteeReport();
                //rptcls = (ReportClass)rptQuarterWiseDeducteeReport;
                //// FORM SELECTED
                TextObject objtxtValue;

                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToDate"];
                objtxtValue.Text = "From : " + TdsMan.T_ReturnQuarterStartDate(cmbCombo4.Text, cmbCombo2.Text) + " To : " + TdsMan.T_ReturnQuarterEndDate(cmbCombo4.Text, cmbCombo2.Text);

                string[,] strArry = { { "txtReportTitle", "Form No. " + cmbCombo3.Text + " - Deductee Details" } };
                rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);

            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion               

