        #region PrintChallanWiseQueryReport_RDLC
        //---------------------------------------------------
        //-- 
        //---------------------------------------------------
        private void PrintChallanWiseQueryReport_RDLC()
        {
            try
            {
                //-- Added By Abhishek Dey On 31/03/2018 --
                //CREATING TEMP TABLE FOR INSERTING REPORT DATA
                #region tblTEMP_CHALLAN_DETAILS_REPORT_QUERY
                if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY) == false)
                {
                    dmlService.J_BeginTransaction();
                    // CREATE TEMP TABLE
                    strSQL = "CREATE TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + "(" +
                         "                 " + cmnService.J_GetDataType("CHALLAN_DETAILS_REPORT_ID", J_Identity.YES) + "," +
                         "                 " + cmnService.J_GetDataType("COMPANY_ID", J_ColumnType.Long, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("COMPANY_NAME", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("TAN_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("FA_YEAR", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("ASST_ID", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("CHALLAN_ID", J_ColumnType.Long, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("FORM_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("QTR", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("DEPOSIT_DATE", J_ColumnType.DateTime, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SECTION_ID", J_ColumnType.Long, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SECTION_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SECTION_DESCRIPTION", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("BSR_CODE", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("CHALLAN_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("TDS", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SURCHARGE", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("EDUCATION_CESS", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("OTHERS", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("INTEREST", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("TOT_TAX", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("LATE_FEE", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("REMARKS", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("NOTE_SYMBOL", J_ColumnType.String, 255, J_DefaultValue.YES) + ")";
                    //
                    dmlService.J_ExecSql(strSQL);
                    //
                    dmlService.J_Commit();
                }
                else
                {
                    dmlService.J_BeginTransaction();
                    //
                    strSQL = @"DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY;
                    //
                    dmlService.J_ExecSql(strSQL);
                    //
                    if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY, "ASST_ID") == false)
                    {
                        strSQL = dmlService.ReturnALTERSyntaxSequelServer(TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY, "ASST_ID", "NUMBER", "", "", "0");
                        dmlService.J_ExecSql(strSQL);
                        //
                    }
                    //
                    dmlService.J_Commit();
                }
                #endregion
                //-----------------------------------------
                //

                //--------------------------------
                //ADDED BY DHRUB ON 05/02/2014 
                //--------------------------------
                SelectedGridItemsWithSearchData(cmnService.J_GenerateDataGridViewSelectedId(grdvDescription));
                //--------------------------------

                // UPDATE FOR BOOK ENTRY
                //TdsMan.T_UpdateBookEntry(dmlService.J_pCommand, lngBasicInfoID);
                // FORM NO
                //string strFormNo = "";
                //foreach (int indexChecked in clbListBox1.CheckedIndices)
                //{
                //    strFormNo = strFormNo + "'" + clbListBox1.Items[indexChecked] + "',";
                //}
                //if (cmnService.J_Right(strFormNo, 1) == ",")
                //    strFormNo = cmnService.J_Mid(strFormNo, 0, (strFormNo.Length - 1));
                string strFormNo = "";

                foreach (int indexChecked in clbListBox1.CheckedIndices)
                {
                    string strItem = clbListBox1.Items[indexChecked].ToString();

                    int startIndex = strItem.IndexOf("(");
                    int endIndex = strItem.IndexOf(")");

                    if (startIndex >= 0 && endIndex > startIndex)
                    {
                        string formNo = strItem.Substring(
                            startIndex + 1,
                            endIndex - startIndex - 1);

                        strFormNo += "'" + formNo + "',";
                    }
                }

                if (cmnService.J_Right(strFormNo, 1) == ",")
                {
                    strFormNo = cmnService.J_Mid(
                        strFormNo,
                        0,
                        strFormNo.Length - 1);
                }
                // QUARTER
                string strQtr = "";
                foreach (int indexChecked in clbListBox2.CheckedIndices)
                {
                    strQtr = strQtr + "'" + clbListBox2.Items[indexChecked] + "',";
                }
                if (cmnService.J_Right(strQtr, 1) == ",")
                    strQtr = cmnService.J_Mid(strQtr, 0, (strQtr.Length - 1));

                string[,] strChallanNoMatrix = {{"TRN_CHALLAN.CHALLAN_NO = ''", "F", "TRN_CHALLAN.TRANSFER_VOUCHER_NO", "F"},
                                                {"TRN_CHALLAN.TRANSFER_VOUCHER_NO = ''", "F", "TRN_CHALLAN.CHALLAN_NO", "F"}};

                string[,] strNILBkEntryMatrix = {{"TRN_CHALLAN.BOOK_ENTRY = 1 ", "F", "BE", "T"},
                                                 {"TRN_CHALLAN.TOT_TAX    = 0 ", "F", "NIL", "T"},
                                                 {"TRN_CHALLAN.BOOK_ENTRY > 1 ", "F", "", "T"}};
                // MAIN SQL
                strQueryString = "SELECT MST_COMPANY.COMPANY_ID          AS COMPANY_ID," +
                    "                    MST_COMPANY.COMPANY_NAME        AS COMPANY_NAME," +
                    "                    MST_COMPANY.TAN_NO              AS TAN_NO," +
                    "                    MST_ASSESSMENT.FA_YEAR          AS FA_YEAR," +
                    "                    MST_ASSESSMENT.ASST_ID          AS ASST_ID," +
                    "                    TRN_CHALLAN.CHALLAN_ID          AS CHALLAN_ID," +
                    "                    TRN_BASIC_INFO.FORM_NO          AS FORM_NO," +
                    "                    TRN_BASIC_INFO.QTR              AS QTR," +
                    "                    TRN_CHALLAN.DEPOSIT_DATE        AS DEPOSIT_DATE," +
                    "                    MST_SECTION.SECTION_ID          AS SECTION_ID," +
                    "                    MST_SECTION.SECTION_NO          AS SECTION_NO," +
                    "                    MST_SECTION.SECTION_DESCRIPTION AS SECTION_DESCRIPTION," +
                    "                    TRN_CHALLAN.BSR_CODE            AS BSR_CODE," +
                    "                  " + cmnService.J_SQLDBFormat(strChallanNoMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_NO," +
                    "                    TRN_CHALLAN.TDS                 AS TDS," +
                    "                    TRN_CHALLAN.SURCHARGE           AS SURCHARGE," +
                    "                    TRN_CHALLAN.EDUCATION_CESS      AS EDUCATION_CESS," +
                    "                    TRN_CHALLAN.OTHERS              AS OTHERS," +
                    "                    TRN_CHALLAN.INTEREST            AS INTEREST," +
                    "                    TRN_CHALLAN.TOT_TAX             AS TOT_TAX," +
                    "                  " + cmnService.J_SQLDBFormat(strNILBkEntryMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + " AS REMARKS " +
                    "             FROM   ((((TRN_CHALLAN INNER JOIN TRN_BASIC_INFO " +
                    "                    ON TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID) " +
                    "                    LEFT JOIN MST_SECTION " +
                    "                    ON MST_SECTION.SECTION_ID       = TRN_CHALLAN.SECTION_ID) " +
                    "                    INNER JOIN MST_COMPANY " +
                    "                    ON TRN_BASIC_INFO.COMPANY_ID    = MST_COMPANY.COMPANY_ID) " +
                    "                    INNER JOIN MST_ASSESSMENT " +
                    "                    ON TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID) " +
                    //"             FROM   MST_SECTION," +
                    //"                    TRN_CHALLAN," +
                    //"                    TRN_BASIC_INFO," +
                    //"                    MST_COMPANY," +
                    //"                    MST_ASSESSMENT " +
                    //"             WHERE  MST_SECTION.SECTION_ID       = TRN_CHALLAN.SECTION_ID " +
                    //"             AND    TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID " +
                    //"             AND    TRN_BASIC_INFO.COMPANY_ID    = MST_COMPANY.COMPANY_ID " +
                    //"             AND    TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID " +
                    "             WHERE  TRN_BASIC_INFO.COMPANY_ID    = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                    "             AND    TRN_BASIC_INFO.ASST_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " " +
                    "             AND    TRN_BASIC_INFO.QTR           IN (" + strQtr + ") " +
                    "             AND    TRN_BASIC_INFO.FORM_NO       IN (" + strFormNo + ") ";
                //--
                if (Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) < T_FinancialYearID.F2013_14ID)
                    strQueryString = strQueryString + "AND MST_SECTION.SECTION_ID IN (" + strSelectedGridItemsWithSearch + ") ";

                // CHALLAN TYPE
                if (cmbCombo3.Text == T_ChallanTypeFilter.BankChallan)
                    strQueryString = strQueryString + "AND TRN_CHALLAN.BOOK_ENTRY = 0 " +
                                                      "AND TRN_CHALLAN.TOT_TAX    > 0 ";
                else if (cmbCombo3.Text == T_ChallanTypeFilter.BookEntry)
                    strQueryString = strQueryString + "AND TRN_CHALLAN.BOOK_ENTRY = 1 ";
                else if (cmbCombo3.Text == T_ChallanTypeFilter.NILChallan)
                    strQueryString = strQueryString + "AND TRN_CHALLAN.TOT_TAX = 0 ";

                // BSR CODE
                if (cmbComparisonCombo1.SelectedIndex > 0)
                    strQueryString = strQueryString + " AND TRN_CHALLAN.BSR_CODE ='" + cmbComparisonCombo1.Text + "'";

                if (cmbComparisonCombo2.Text == T_TypeComparison.Equal)
                {
                    if (string.IsNullOrEmpty(txtComparisonTextBox2.Text.Trim()))  //-- Added By Abhishek Dey On 03/04/2018 --
                        txtComparisonTextBox2.Text = "0.00";
                    strQueryString = strQueryString + "AND TRN_CHALLAN.TOT_TAX =  " + Convert.ToDouble(txtComparisonTextBox2.Text);
                }
                else if (cmbComparisonCombo2.Text == T_TypeComparison.Greater)
                {
                    if (string.IsNullOrEmpty(txtComparisonTextBox2.Text.Trim()))  //-- Added By Abhishek Dey On 03/04/2018 --
                        txtComparisonTextBox2.Text = "0.00";
                    strQueryString = strQueryString + "AND TRN_CHALLAN.TOT_TAX >  " + Convert.ToDouble(txtComparisonTextBox2.Text);
                }
                else if (cmbComparisonCombo2.Text == T_TypeComparison.Less)
                {
                    if (string.IsNullOrEmpty(txtComparisonTextBox2.Text.Trim()))   //-- Added By Abhishek Dey On 03/04/2018 --
                        txtComparisonTextBox2.Text = "0.00";
                    strQueryString = strQueryString + "AND TRN_CHALLAN.TOT_TAX <  " + Convert.ToDouble(txtComparisonTextBox2.Text);
                }


                // DATE
                if (rbnSort1.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_CHALLAN.DEPOSIT_DATE, TRN_CHALLAN.CHALLAN_ID";
                // FORM NO
                else if (rbnSort2.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_BASIC_INFO.FORM_NO, TRN_CHALLAN.CHALLAN_ID";
                // QTR
                else if (rbnSort3.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_BASIC_INFO.QTR, TRN_CHALLAN.CHALLAN_ID";
                // SECTION
                else if (rbnSort4.Checked == true)
                    strQueryString = strQueryString + " ORDER BY MST_SECTION.SECTION_NO, TRN_CHALLAN.CHALLAN_ID";
                //

                //-- Added By Abhishek Dey On 31/03/2018 --
                // INSERT DATA INTO TEMP TABLE
                dmlService.J_BeginTransaction();
                //
                strSQL = "INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + "(" +
                                      " COMPANY_ID, " +
                                      " COMPANY_NAME, " +
                                      " TAN_NO, " +
                                      " FA_YEAR, " +
                                      " ASST_ID, " +
                                      " CHALLAN_ID, " +
                                      " FORM_NO, " +
                                      " QTR, " +
                                      " DEPOSIT_DATE, " +
                                      " SECTION_ID, " +
                                      " SECTION_NO, " +
                                      " SECTION_DESCRIPTION, " +
                                      " BSR_CODE, " +
                                      " CHALLAN_NO, " +
                                      " TDS, " +
                                      " SURCHARGE, " +
                                      " EDUCATION_CESS, " +
                                      " OTHERS, " +
                                      " INTEREST, " +
                                      " TOT_TAX, " +
                    //" LATE_FEE, " +
                                      " REMARKS ) ";
                //
                strSQL = strSQL + strQueryString;
                //
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return;
                }
                //
                dmlService.J_Commit();
                //
                // DELETE ALL DUPLICATE CHALLAN NO EXCEPT ONE FROM TEMP TABLE
                dmlService.J_BeginTransaction();
                //
                strSQL = "DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @"
                          WHERE CHALLAN_DETAILS_REPORT_ID NOT IN
                                (SELECT   MIN(CHALLAN_DETAILS_REPORT_ID) 
                                FROM  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @"  
                                GROUP BY CHALLAN_NO, 
                                         BSR_CODE,
                                         DEPOSIT_DATE,  
                                         TOT_TAX)";
                //
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return;
                }
                //
                dmlService.J_Commit();
                //               
                strSQL = @" SELECT " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + ".CHALLAN_ID " +
                          " FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @"
                            INNER JOIN 
                            (SELECT  CHALLAN_NO,
                                     BSR_CODE,
                                     DEPOSIT_DATE,
                                     TOT_TAX
                            FROM     TRN_CHALLAN
                            GROUP BY CHALLAN_NO,
                                     BSR_CODE,
                                     DEPOSIT_DATE,
                                     TOT_TAX
                            HAVING   COUNT(*) > 1) AS CHALLAN
                            ON      CHALLAN.CHALLAN_NO   = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @".CHALLAN_NO
                            AND     CHALLAN.BSR_CODE     = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @".BSR_CODE
                            AND     CHALLAN.DEPOSIT_DATE = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @".DEPOSIT_DATE
                            AND     CHALLAN.TOT_TAX      = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @".TOT_TAX";
                //                
                DataSet dsChallanNo = new DataSet();
                dsChallanNo = dmlService.J_ExecSqlReturnDataSet(strSQL);
                for (int i = 0; i <= dsChallanNo.Tables[0].Rows.Count - 1; i++)
                {
                    dmlService.J_BeginTransaction();
                    //
                    strSQL = " UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @"
                               SET    NOTE_SYMBOL = '***'
                               WHERE  CHALLAN_ID  = " + Convert.ToInt32(dsChallanNo.Tables[0].Rows[i]["CHALLAN_ID"].ToString());
                    //
                    dmlService.J_ExecSql(strSQL);
                    //
                    dmlService.J_Commit();
                }
                //
                dsChallanNo.Dispose();
                //                                
                //
                strQueryString = @"SELECT COMPANY_ID,          
                                          COMPANY_NAME,      
                                          TAN_NO,              
                                          FA_YEAR,  
                                          ASST_ID,
                                          CHALLAN_ID,        
                                          FORM_NO,         
                                          QTR,              
                                          DEPOSIT_DATE,        
                                          SECTION_ID,          
                                          SECTION_NO,         
                                          SECTION_DESCRIPTION, 
                                          BSR_CODE,           
                                          CHALLAN_NO,
                                          TDS,
                                          SURCHARGE,
                                          EDUCATION_CESS,
                                          OTHERS,
                                          INTEREST,
                                          TOT_TAX,
                                          LATE_FEE,
                                          REMARKS,
                                          NOTE_SYMBOL
                                   FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY;
                //-----------------------------------------
                //////crChallanWiseQueryReport rptChallanWiseQueryReport = new crChallanWiseQueryReport();
                //////rptcls = (ReportClass)rptChallanWiseQueryReport;

                //////TextObject objtxtValue;

                //////// FORM SELECTED
                //////strFormNo = strFormNo.Replace("'", "");
                //////objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFormSelected"];
                //////objtxtValue.Text = "Form No. : " + strFormNo;
                //////// QTR SELECTED 
                //////strQtr = strQtr.Replace("'", "");
                //////objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtQtrSelected"];
                //////objtxtValue.Text = "Quarter : " + strQtr;
                //////// BSR CODE SELECTED
                //////objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtBSRCodeSelected"];
                //////objtxtValue.Text = "BSR Code Selected : " + cmbComparisonCombo1.Text;
                // BSR CODE SELECTED
                string strFooterSelectedTotalAmountComparision = "";
                if (txtComparisonTextBox2.Enabled == true)
                {
                    //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtTotalAmountComparison"];
                    strFooterSelectedTotalAmountComparision = "Total Amount : " + cmbComparisonCombo2.Text + " - " + txtComparisonTextBox2.Text;
                }
                //////// SECTION SELECTED
                //////objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtSectionSelected"];
                //////objtxtValue.Text = "Section Selected : " + TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription, 2);
                ////////
                //////string[,] strArry = { { "txtReportTitle", "Challan Query Report" } };
                //////rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                string[,] strArryChallanWiseReport = { {"HeaderCompanyName", cmnService.J_Left(cmbCombo1.Text, cmbCombo1.Text.Length - 12) },
                                              {"HeaderTANFaYear", "TAN : " + cmnService.J_Left(cmnService.J_Right(cmbCombo1.Text,11),10) + " FA Year : " + cmbCombo2.Text },
                                              {"HeaderReportCD", "Challan Query Report" },
                                              {"FooterSelectedForm", "Form No. : " + strFormNo },
                                              {"FooterSelectedQtr", "Quarter : " + strQtr },
                                              {"FooterSelectedBSR", "BSR Code Selected : " + cmbComparisonCombo1.Text },
                                              {"FooterSelectedTotalAmountComparision", strFooterSelectedTotalAmountComparision },
                                              {"FooterSelectedSection", "Section Selected : " + TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription, 2) }
                                                };
                J_PreviewReportRDLC("\\Reports\\crChallanWiseQueryReport.rdlc", "DataSet1", strQueryString, strArryChallanWiseReport);
                //---------------------------
                //ADDED BY DHRUB ON 07/02/2014 FOR RECORD REMAIN CHECKED INTO THE GRID AFTER SEARCH 
                dmlService.J_BeginTransaction();
                dmlService.J_ExecSql("DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED);
                dmlService.J_Commit();
                //--
                //-- Added By Abhishek Dey On 31/03/2018 --
                dmlService.J_BeginTransaction();
                //
                strSQL = @"DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY;
                //
                dmlService.J_ExecSql(strSQL);
                //
                dmlService.J_Commit();
                //------------------------------------------
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

        #region PrintChallanWiseQueryReport
        //---------------------------------------------------
        //-- ARUP(2011-01-04)
        //---------------------------------------------------
        private void PrintChallanWiseQueryReport()
        {
            try
            {
                //-- Added By Abhishek Dey On 31/03/2018 --
                //CREATING TEMP TABLE FOR INSERTING REPORT DATA
                #region tblTEMP_CHALLAN_DETAILS_REPORT_QUERY
                if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY) == false)
                {
                    dmlService.J_BeginTransaction();
                    // CREATE TEMP TABLE
                    strSQL = "CREATE TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + "(" +
                         "                 " + cmnService.J_GetDataType("CHALLAN_DETAILS_REPORT_ID", J_Identity.YES) + "," +
                         "                 " + cmnService.J_GetDataType("COMPANY_ID", J_ColumnType.Long, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("COMPANY_NAME", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("TAN_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("FA_YEAR", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("CHALLAN_ID", J_ColumnType.Long, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("FORM_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("QTR", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("DEPOSIT_DATE", J_ColumnType.DateTime, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SECTION_ID", J_ColumnType.Long, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SECTION_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SECTION_DESCRIPTION", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("BSR_CODE", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("CHALLAN_NO", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("TDS", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("SURCHARGE", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("EDUCATION_CESS", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("OTHERS", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("INTEREST", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("TOT_TAX", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("LATE_FEE", J_ColumnType.Double, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("REMARKS", J_ColumnType.String, 255, J_DefaultValue.YES) + "," +
                         "                 " + cmnService.J_GetDataType("NOTE_SYMBOL", J_ColumnType.String, 255, J_DefaultValue.YES) + ")";
                    //
                    dmlService.J_ExecSql(strSQL);
                    //
                    dmlService.J_Commit();
                }
                else
                {
                    dmlService.J_BeginTransaction();
                    //
                    strSQL = @"DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY;
                    //
                    dmlService.J_ExecSql(strSQL);
                    //
                    dmlService.J_Commit();
                }
                #endregion
                //-----------------------------------------
                //

                //--------------------------------
                //ADDED BY DHRUB ON 05/02/2014 
                //--------------------------------
                SelectedGridItemsWithSearchData(cmnService.J_GenerateDataGridViewSelectedId(grdvDescription));
                //--------------------------------

                // UPDATE FOR BOOK ENTRY
                //TdsMan.T_UpdateBookEntry(dmlService.J_pCommand, lngBasicInfoID);
                // FORM NO
                string strFormNo = "";
                foreach (int indexChecked in clbListBox1.CheckedIndices)
                {
                    strFormNo = strFormNo + "'" + clbListBox1.Items[indexChecked] + "',";
                }
                if (cmnService.J_Right(strFormNo, 1) == ",")
                    strFormNo = cmnService.J_Mid(strFormNo, 0, (strFormNo.Length - 1));

                // QUARTER
                string strQtr = "";
                foreach (int indexChecked in clbListBox2.CheckedIndices)
                {
                    strQtr = strQtr + "'" + clbListBox2.Items[indexChecked] + "',";
                }
                if (cmnService.J_Right(strQtr, 1) == ",")
                    strQtr = cmnService.J_Mid(strQtr, 0, (strQtr.Length - 1));

                string[,] strChallanNoMatrix = {{"TRN_CHALLAN.CHALLAN_NO = ''", "F", "TRN_CHALLAN.TRANSFER_VOUCHER_NO", "F"},
                                                {"TRN_CHALLAN.TRANSFER_VOUCHER_NO = ''", "F", "TRN_CHALLAN.CHALLAN_NO", "F"}};

                string[,] strNILBkEntryMatrix = {{"TRN_CHALLAN.BOOK_ENTRY = 1 ", "F", "BE", "T"},
                                                 {"TRN_CHALLAN.TOT_TAX    = 0 ", "F", "NIL", "T"},
                                                 {"TRN_CHALLAN.BOOK_ENTRY > 1 ", "F", "", "T"}};
                // MAIN SQL
                strQueryString = "SELECT MST_COMPANY.COMPANY_ID          AS COMPANY_ID," +
                    "                    MST_COMPANY.COMPANY_NAME        AS COMPANY_NAME," +
                    "                    MST_COMPANY.TAN_NO              AS TAN_NO," +
                    "                    MST_ASSESSMENT.FA_YEAR          AS FA_YEAR," +
                    "                    TRN_CHALLAN.CHALLAN_ID          AS CHALLAN_ID," +
                    "                    TRN_BASIC_INFO.FORM_NO          AS FORM_NO," +
                    "                    TRN_BASIC_INFO.QTR              AS QTR," +
                    "                    TRN_CHALLAN.DEPOSIT_DATE        AS DEPOSIT_DATE," +
                    "                    MST_SECTION.SECTION_ID          AS SECTION_ID," +
                    "                    MST_SECTION.SECTION_NO          AS SECTION_NO," +
                    "                    MST_SECTION.SECTION_DESCRIPTION AS SECTION_DESCRIPTION," +
                    "                    TRN_CHALLAN.BSR_CODE            AS BSR_CODE," +
                    "                  " + cmnService.J_SQLDBFormat(strChallanNoMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_NO," +
                    "                    TRN_CHALLAN.TDS                 AS TDS," +
                    "                    TRN_CHALLAN.SURCHARGE           AS SURCHARGE," +
                    "                    TRN_CHALLAN.EDUCATION_CESS      AS EDUCATION_CESS," +
                    "                    TRN_CHALLAN.OTHERS              AS OTHERS," +
                    "                    TRN_CHALLAN.INTEREST            AS INTEREST," +
                    "                    TRN_CHALLAN.TOT_TAX             AS TOT_TAX," +
                    "                  " + cmnService.J_SQLDBFormat(strNILBkEntryMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + " AS REMARKS " +
                    "             FROM   ((((TRN_CHALLAN INNER JOIN TRN_BASIC_INFO " +
                    "                    ON TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID) " +
                    "                    LEFT JOIN MST_SECTION " +
                    "                    ON MST_SECTION.SECTION_ID       = TRN_CHALLAN.SECTION_ID) " +
                    "                    INNER JOIN MST_COMPANY " +
                    "                    ON TRN_BASIC_INFO.COMPANY_ID    = MST_COMPANY.COMPANY_ID) " +
                    "                    INNER JOIN MST_ASSESSMENT " +
                    "                    ON TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID) " +
                    //"             FROM   MST_SECTION," +
                    //"                    TRN_CHALLAN," +
                    //"                    TRN_BASIC_INFO," +
                    //"                    MST_COMPANY," +
                    //"                    MST_ASSESSMENT " +
                    //"             WHERE  MST_SECTION.SECTION_ID       = TRN_CHALLAN.SECTION_ID " +
                    //"             AND    TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID " +
                    //"             AND    TRN_BASIC_INFO.COMPANY_ID    = MST_COMPANY.COMPANY_ID " +
                    //"             AND    TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID " +
                    "             WHERE  TRN_BASIC_INFO.COMPANY_ID    = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                    "             AND    TRN_BASIC_INFO.ASST_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " " +
                    "             AND    TRN_BASIC_INFO.QTR           IN (" + strQtr + ") " +
                    "             AND    TRN_BASIC_INFO.FORM_NO       IN (" + strFormNo + ") ";
                //--
                if (Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) < T_FinancialYearID.F2013_14ID)
                    strQueryString = strQueryString + "AND MST_SECTION.SECTION_ID IN (" + strSelectedGridItemsWithSearch + ") ";

                // CHALLAN TYPE
                if (cmbCombo3.Text == T_ChallanTypeFilter.BankChallan)
                    strQueryString = strQueryString + "AND TRN_CHALLAN.BOOK_ENTRY = 0 " +
                                                      "AND TRN_CHALLAN.TOT_TAX    > 0 ";
                else if (cmbCombo3.Text == T_ChallanTypeFilter.BookEntry)
                    strQueryString = strQueryString + "AND TRN_CHALLAN.BOOK_ENTRY = 1 ";
                else if (cmbCombo3.Text == T_ChallanTypeFilter.NILChallan)
                    strQueryString = strQueryString + "AND TRN_CHALLAN.TOT_TAX = 0 ";

                // BSR CODE
                if (cmbComparisonCombo1.SelectedIndex > 0)
                    strQueryString = strQueryString + " AND TRN_CHALLAN.BSR_CODE ='" + cmbComparisonCombo1.Text + "'";

                if (cmbComparisonCombo2.Text == T_TypeComparison.Equal)
                {
                    if (string.IsNullOrEmpty(txtComparisonTextBox2.Text.Trim()))  //-- Added By Abhishek Dey On 03/04/2018 --
                        txtComparisonTextBox2.Text = "0.00";
                    strQueryString = strQueryString + "AND TRN_CHALLAN.TOT_TAX =  " + Convert.ToDouble(txtComparisonTextBox2.Text);
                }
                else if (cmbComparisonCombo2.Text == T_TypeComparison.Greater)
                {
                    if (string.IsNullOrEmpty(txtComparisonTextBox2.Text.Trim()))  //-- Added By Abhishek Dey On 03/04/2018 --
                        txtComparisonTextBox2.Text = "0.00";
                    strQueryString = strQueryString + "AND TRN_CHALLAN.TOT_TAX >  " + Convert.ToDouble(txtComparisonTextBox2.Text);
                }
                else if (cmbComparisonCombo2.Text == T_TypeComparison.Less)
                {
                    if (string.IsNullOrEmpty(txtComparisonTextBox2.Text.Trim()))   //-- Added By Abhishek Dey On 03/04/2018 --
                        txtComparisonTextBox2.Text = "0.00";
                    strQueryString = strQueryString + "AND TRN_CHALLAN.TOT_TAX <  " + Convert.ToDouble(txtComparisonTextBox2.Text);
                }


                // DATE
                if (rbnSort1.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_CHALLAN.DEPOSIT_DATE, TRN_CHALLAN.CHALLAN_ID";
                // FORM NO
                else if (rbnSort2.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_BASIC_INFO.FORM_NO, TRN_CHALLAN.CHALLAN_ID";
                // QTR
                else if (rbnSort3.Checked == true)
                    strQueryString = strQueryString + " ORDER BY TRN_BASIC_INFO.QTR, TRN_CHALLAN.CHALLAN_ID";
                // SECTION
                else if (rbnSort4.Checked == true)
                    strQueryString = strQueryString + " ORDER BY MST_SECTION.SECTION_NO, TRN_CHALLAN.CHALLAN_ID";
                //

                //-- Added By Abhishek Dey On 31/03/2018 --
                // INSERT DATA INTO TEMP TABLE
                dmlService.J_BeginTransaction();
                //
                strSQL = "INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + "(" +
                                      " COMPANY_ID, " +
                                      " COMPANY_NAME, " +
                                      " TAN_NO, " +
                                      " FA_YEAR, " +
                                      " CHALLAN_ID, " +
                                      " FORM_NO, " +
                                      " QTR, " +
                                      " DEPOSIT_DATE, " +
                                      " SECTION_ID, " +
                                      " SECTION_NO, " +
                                      " SECTION_DESCRIPTION, " +
                                      " BSR_CODE, " +
                                      " CHALLAN_NO, " +
                                      " TDS, " +
                                      " SURCHARGE, " +
                                      " EDUCATION_CESS, " +
                                      " OTHERS, " +
                                      " INTEREST, " +
                                      " TOT_TAX, " +
                                      //" LATE_FEE, " +
                                      " REMARKS ) ";
                //
                strSQL = strSQL + strQueryString;
                //
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return;
                }
                //
                dmlService.J_Commit();
                //
                // DELETE ALL DUPLICATE CHALLAN NO EXCEPT ONE FROM TEMP TABLE
                dmlService.J_BeginTransaction();
                //
                strSQL = "DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @"
                          WHERE CHALLAN_DETAILS_REPORT_ID NOT IN
                                (SELECT   MIN(CHALLAN_DETAILS_REPORT_ID) 
                                FROM  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @"  
                                GROUP BY CHALLAN_NO, 
                                         BSR_CODE,
                                         DEPOSIT_DATE,  
                                         TOT_TAX)";
                //
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return;
                }
                //
                dmlService.J_Commit();
                //               
                strSQL = @" SELECT " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + ".CHALLAN_ID " +
                          " FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @"
                            INNER JOIN 
                            (SELECT  CHALLAN_NO,
                                     BSR_CODE,
                                     DEPOSIT_DATE,
                                     TOT_TAX
                            FROM     TRN_CHALLAN
                            GROUP BY CHALLAN_NO,
                                     BSR_CODE,
                                     DEPOSIT_DATE,
                                     TOT_TAX
                            HAVING   COUNT(*) > 1) AS CHALLAN
                            ON      CHALLAN.CHALLAN_NO   = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @".CHALLAN_NO
                            AND     CHALLAN.BSR_CODE     = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @".BSR_CODE
                            AND     CHALLAN.DEPOSIT_DATE = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @".DEPOSIT_DATE
                            AND     CHALLAN.TOT_TAX      = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @".TOT_TAX";
                //                
                DataSet dsChallanNo = new DataSet();
                dsChallanNo = dmlService.J_ExecSqlReturnDataSet(strSQL);
                for (int i = 0; i <= dsChallanNo.Tables[0].Rows.Count - 1; i++)
                {
                    dmlService.J_BeginTransaction();
                    //
                    strSQL = " UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY + @"
                               SET    NOTE_SYMBOL = '***'
                               WHERE  CHALLAN_ID  = " + Convert.ToInt32(dsChallanNo.Tables[0].Rows[i]["CHALLAN_ID"].ToString());
                    //
                    dmlService.J_ExecSql(strSQL);
                    //
                    dmlService.J_Commit();
                }
                //
                dsChallanNo.Dispose();
                //                                
                //
                strQueryString = @"SELECT COMPANY_ID,          
                                          COMPANY_NAME,      
                                          TAN_NO,              
                                          FA_YEAR,          
                                          CHALLAN_ID,        
                                          FORM_NO,         
                                          QTR,              
                                          DEPOSIT_DATE,        
                                          SECTION_ID,          
                                          SECTION_NO,         
                                          SECTION_DESCRIPTION, 
                                          BSR_CODE,           
                                          CHALLAN_NO,
                                          TDS,
                                          SURCHARGE,
                                          EDUCATION_CESS,
                                          OTHERS,
                                          INTEREST,
                                          TOT_TAX,
                                          LATE_FEE,
                                          REMARKS,
                                          NOTE_SYMBOL
                                   FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY;
                //-----------------------------------------
                crChallanWiseQueryReport rptChallanWiseQueryReport = new crChallanWiseQueryReport();
                rptcls = (ReportClass)rptChallanWiseQueryReport;

                TextObject objtxtValue;

                // FORM SELECTED
                strFormNo = strFormNo.Replace("'", "");
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFormSelected"];
                objtxtValue.Text = "Form No. : " + strFormNo;
                // QTR SELECTED 
                strQtr = strQtr.Replace("'", "");
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtQtrSelected"];
                objtxtValue.Text = "Quarter : " + strQtr;
                // BSR CODE SELECTED
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtBSRCodeSelected"];
                objtxtValue.Text = "BSR Code Selected : " + cmbComparisonCombo1.Text;
                // BSR CODE SELECTED
                if (txtComparisonTextBox2.Enabled == true)
                {
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtTotalAmountComparison"];
                    objtxtValue.Text = "Total Amount : " + cmbComparisonCombo2.Text + " - " + txtComparisonTextBox2.Text;
                }
                // SECTION SELECTED
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtSectionSelected"];
                objtxtValue.Text = "Section Selected : " + TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription, 2);
                //
                string[,] strArry = { { "txtReportTitle", "Challan Query Report" } };
                rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                //---------------------------
                //ADDED BY DHRUB ON 07/02/2014 FOR RECORD REMAIN CHECKED INTO THE GRID AFTER SEARCH 
                dmlService.J_BeginTransaction();
                dmlService.J_ExecSql("DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED);
                dmlService.J_Commit();
                //--
                //-- Added By Abhishek Dey On 31/03/2018 --
                dmlService.J_BeginTransaction();
                //
                strSQL = @"DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS_REPORT_QUERY;
                //
                dmlService.J_ExecSql(strSQL);
                //
                dmlService.J_Commit();
                //------------------------------------------
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

        #region PrintDeducteeWiseQueryReport
        //---------------------------------------------------
        //-- ANIK(2011-01-06)
        //---------------------------------------------------
        private void PrintDeducteeWiseQueryReport()
        {
            try
            {
                //ADDED BY DHRUB ON 05/02/2014 
                SelectedGridItemsWithSearchData(cmnService.J_GenerateDataGridViewSelectedId(grdvDescription));

                if (cmbCombo2.Text == T_PartyEmployee.Party)
                {
                    string strSectionNo = "";
                    foreach (int indexChecked in clbListBox1.CheckedIndices)
                    {
                        strSectionNo = strSectionNo + "'" + clbListBox1.Items[indexChecked] + "',";
                    }
                    if (strSectionNo != "")
                        if (cmnService.J_Right(strSectionNo, 1) == ",")
                            strSectionNo = cmnService.J_Mid(strSectionNo, 0, (strSectionNo.Length - 1));

                    // FORM NO
                    strFormNoSelected = "";

                    if (chkBox1.Checked == true)
                        strFormNoSelected = "'" + T_FormNo.F26Q + "',";
                    if (chkBox2.Checked == true)
                        strFormNoSelected = strFormNoSelected + "'" + T_FormNo.F27Q + "',";
                    if (chkBox3.Checked == true)
                        strFormNoSelected = strFormNoSelected + "'" + T_FormNo.F27EQ + "',";
                    //
                    if (strFormNoSelected == "")
                    {
                        strFormNoSelected = "'JAYA'";
                    }
                    if (cmnService.J_Right(strFormNoSelected, 1) == ",")
                        strFormNoSelected = cmnService.J_Mid(strFormNoSelected, 0, (strFormNoSelected.Length - 1));

                    //-------------------------------------------------
                    // (0) Data Value in DataTable
                    // (1) Data Type in DataTable (T = TEXT MATCHING, F = FIELD MATCHING,)
                    // (2) Display Text in Front-end
                    // (3) Display Text Type (T = TEXT MATCHING, F = FIELD MATCHING,)
                    string[,] strDeducteeCodeMatrix = {{"='01'", "T", "Company", "T"},
                                                       {"='02'", "T", "Non-Company", "T"}};

                    string[,] strChallanNoMatrix = {{"TRN_CHALLAN.CHALLAN_NO = ''", "F", "TRN_CHALLAN.TRANSFER_VOUCHER_NO", "F"},
                                                    {"TRN_CHALLAN.TRANSFER_VOUCHER_NO = ''", "F", "TRN_CHALLAN.CHALLAN_NO", "F"}};
                    //----------
                    strQueryString = "SELECT MST_COMPANY.COMPANY_ID                    AS COMPANY_ID," +
                                     "       MST_COMPANY.COMPANY_NAME                  AS COMPANY_NAME," +
                                     "       MST_COMPANY.TAN_NO                        AS TAN_NO," +
                                     "       MST_CATEGORY.CATEGORY_CODE + ' - ' + " +
                                     "               MST_CATEGORY.CATEGORY_DESCRIPTION AS CATEGORY," +
                                     "       MST_DEDUCTEE.DEDUCTEE_ID                  AS DEDUCTEE_ID," +
                                     "      " + cmnService.J_SQLDBFormat("MST_DEDUCTEE.DEDUCTEE_CODE", J_SQLColFormat.Case_End, strDeducteeCodeMatrix) + " AS DEDUCTEE_CODE," +
                                     "       MST_DEDUCTEE.DEDUCTEE_NAME                AS DEDUCTEE_NAME," +
                                     "       MST_DEDUCTEE.DEDUCTEE_PAN                 AS DEDUCTEE_PAN," +
                                     "       TRN_DEDUCTEE_DETAILS.PAYMENT_DATE         AS DEDUCTED_DATE," +
                                     "       MST_SECTION.SECTION_NO                    AS SECTION_NO," +
                                     "       TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT       AS PAYMENT_AMOUNT," +
                                     "       TRN_DEDUCTEE_DETAILS.RATE                 AS RATE," +
                                     "       TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT         AS TOTAL_AMOUNT," +
                                     "       TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT AS TAX_DEPOSITED_AMOUNT," +
                                     "       " + cmnService.J_SQLDBFormat(strChallanNoMatrix, J_SQLColFormat.Case_End) + " AS PAY_DOC_NO," +
                                     "       TRN_CHALLAN.DEPOSIT_DATE                  AS PAY_DOC_DATE," +
                                     "       TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG   AS NON_DEDUCTION_FLAG," +
                                     "       MST_ASSESSMENT.FA_YEAR                    AS FA_YEAR " +
                                     "FROM   TRN_BASIC_INFO," +
                                     "       TRN_CHALLAN," +
                                     "       TRN_DEDUCTEE_DETAILS," +
                                     "       MST_COMPANY," +
                                     "       MST_DEDUCTEE," +
                                     "       MST_SECTION," +
                                     "       MST_CATEGORY," +
                                     "       MST_ASSESSMENT " +
                                     "WHERE  TRN_BASIC_INFO.BASIC_INFO_ID       = TRN_CHALLAN.BASIC_INFO_ID " +
                                     "AND    TRN_CHALLAN.CHALLAN_ID             = TRN_DEDUCTEE_DETAILS.CHALLAN_ID " +
                                     "AND    TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_DEDUCTEE.DEDUCTEE_ID " +
                                     "AND    TRN_DEDUCTEE_DETAILS.SECTION_ID    = MST_SECTION.SECTION_ID " +
                                     "AND    MST_COMPANY.COMPANY_ID             = TRN_BASIC_INFO.COMPANY_ID " +
                                     "AND    MST_CATEGORY.CATEGORY_ID           = MST_COMPANY.D_CATEGORY_ID " +
                                     "AND    TRN_BASIC_INFO.ASST_ID             = MST_ASSESSMENT.ASST_ID " +
                                     "AND    MST_SECTION.SECTION_NO             IN(" + strSectionNo + ") " +
                                     "AND    TRN_BASIC_INFO.FORM_NO             IN(" + strFormNoSelected + ") " +
                                     "AND    TRN_DEDUCTEE_DETAILS.PARTY_ID      IN(" + strSelectedGridItemsWithSearch + ") " +
                                     "AND    TRN_BASIC_INFO.COMPANY_ID           = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                                     "AND    TRN_DEDUCTEE_DETAILS.PAYMENT_DATE  >= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(mskFromDate) + cmnService.J_DateOperator() + " " +
                                     "AND    TRN_DEDUCTEE_DETAILS.PAYMENT_DATE  <= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(mskToDate) + cmnService.J_DateOperator() + " ";
                    // COMPARISON FILTER
                    // AMOUNT PAID FILTER
                    if (cmbComparisonCombo1.Text == T_TypeComparison.Equal)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT =  " + Convert.ToDouble(txtComparisonTextBox1.Text);
                    else if (cmbComparisonCombo1.Text == T_TypeComparison.Greater)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT >  " + Convert.ToDouble(txtComparisonTextBox1.Text);
                    else if (cmbComparisonCombo1.Text == T_TypeComparison.Less)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT <  " + Convert.ToDouble(txtComparisonTextBox1.Text);
                    // TDS AMOUNT FILTER
                    if (cmbComparisonCombo2.Text == T_TypeComparison.Equal)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT =  " + Convert.ToDouble(txtComparisonTextBox2.Text);
                    else if (cmbComparisonCombo2.Text == T_TypeComparison.Greater)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT >  " + Convert.ToDouble(txtComparisonTextBox2.Text);
                    else if (cmbComparisonCombo2.Text == T_TypeComparison.Less)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT <  " + Convert.ToDouble(txtComparisonTextBox2.Text);
                    // RATE
                    if (cmbComparisonCombo3.Text == T_TypeComparison.Equal)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.RATE  =  " + Convert.ToDouble(txtComparisonTextBox3.Text);
                    else if (cmbComparisonCombo3.Text == T_TypeComparison.Greater)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.RATE  >  " + Convert.ToDouble(txtComparisonTextBox3.Text);
                    else if (cmbComparisonCombo3.Text == T_TypeComparison.Less)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.RATE  <  " + Convert.ToDouble(txtComparisonTextBox3.Text);

                    // SORT
                    if (rbnSort1.Checked == true)
                    {
                        strQueryString = strQueryString + " ORDER BY MST_DEDUCTEE.DEDUCTEE_NAME," +
                            "            TRN_DEDUCTEE_DETAILS.PAYMENT_DATE," +
                            "            MST_SECTION.SECTION_NO," +
                            "            TRN_CHALLAN.CHALLAN_ID";
                    }
                    else if (rbnSort2.Checked == true)
                    {
                        strQueryString = strQueryString + " ORDER BY MST_DEDUCTEE.DEDUCTEE_NAME," +
                            "            MST_SECTION.SECTION_NO," +
                            "            TRN_DEDUCTEE_DETAILS.PAYMENT_DATE," +
                            "            TRN_CHALLAN.CHALLAN_ID";
                    }

                    crDeducteeWiseQueryReport rptDeducteeWiseQueryReport = new crDeducteeWiseQueryReport();
                    rptcls = (ReportClass)rptDeducteeWiseQueryReport;

                    TextObject objtxtValue;
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromDate"];
                    objtxtValue.Text = mskFromDate.Text;
                    //
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtToDate"];
                    objtxtValue.Text = mskToDate.Text;
                    // FORM SELECTED
                    strFormNoSelected = strFormNoSelected.Replace("'", "");
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFormSelected"];
                    objtxtValue.Text = "Form No. : " + strFormNoSelected;
                    // SECTION SELECTED
                    strSectionNo = strSectionNo.Replace("'", "");
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtSectionNoSelected"];
                    objtxtValue.Text = "Section No. selected: " + strSectionNo;
                    // AMOUNT PAID FILTER 
                    if (txtComparisonTextBox1.Enabled == true)
                    {
                        objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtAmountPaidFilter"];
                        objtxtValue.Text = "Amount Paid : " + cmbComparisonCombo1.Text + " - " + txtComparisonTextBox1.Text;
                    }
                    // TDS AMOUNT FILTER 
                    if (txtComparisonTextBox2.Enabled == true)
                    {
                        objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtTDSAmountFilter"];
                        objtxtValue.Text = "TDS Amount : " + cmbComparisonCombo2.Text + " - " + txtComparisonTextBox2.Text;
                    }
                    // RATE FILTER 
                    if (txtComparisonTextBox3.Enabled == true)
                    {
                        objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtRateFilter"];
                        objtxtValue.Text = "Rate : " + cmbComparisonCombo3.Text + " - " + txtComparisonTextBox3.Text;
                    }
                    //

                    string[,] strArry = { { "txtReportTitle", "Deductee Wise Query Report" } };
                    rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                }
                else if (cmbCombo2.Text == T_PartyEmployee.Employee)
                {
                    string strSectionNo = "";
                    foreach (int indexChecked in clbListBox1.CheckedIndices)
                    {
                        strSectionNo = strSectionNo + "'" + clbListBox1.Items[indexChecked] + "',";
                    }
                    if (strSectionNo != "")
                        if (cmnService.J_Right(strSectionNo, 1) == ",")
                            strSectionNo = cmnService.J_Mid(strSectionNo, 0, (strSectionNo.Length - 1));

                    // FORM NO
                    strFormNoSelected = "'" + T_FormNo.F24Q + "'";

                    //if (chkBox1.Checked == true)
                    //    strFormNoSelected = "'" + T_FormNo.F26Q + "',";
                    //if (chkBox2.Checked == true)
                    //    strFormNoSelected = strFormNoSelected + "'" + T_FormNo.F27Q + "',";
                    //if (chkBox3.Checked == true)
                    //    strFormNoSelected = strFormNoSelected + "'" + T_FormNo.F27EQ + "',";
                    ////
                    //if (strFormNoSelected == "")
                    //{
                    //    strFormNoSelected = "'JAYA'";
                    //}
                    //if (cmnService.J_Right(strFormNoSelected, 1) == ",")
                    //    strFormNoSelected = cmnService.J_Mid(strFormNoSelected, 0, (strFormNoSelected.Length - 1));

                    //-------------------------------------------------
                    // (0) Data Value in DataTable
                    // (1) Data Type in DataTable (T = TEXT MATCHING, F = FIELD MATCHING,)
                    // (2) Display Text in Front-end
                    // (3) Display Text Type (T = TEXT MATCHING, F = FIELD MATCHING,)
                    string[,] strEmployeeCategoryMatrix = {{"='W'", "T", T_EmployeeCategory.Woman, "T"},
                                                           {"='S'", "T", T_EmployeeCategory.SeniorCitizen, "T"},
                                                           {"='G'", "T", T_EmployeeCategory.General, "T"},
                                                           {"='O'", "T", T_EmployeeCategory.SuperSeniorCitizen, "T"},
                                                           {"=''", "T", "", "T"}};

                    string[,] strChallanNoMatrix = {{"TRN_CHALLAN.CHALLAN_NO = ''", "F", "TRN_CHALLAN.TRANSFER_VOUCHER_NO", "F"},
                                                    {"TRN_CHALLAN.TRANSFER_VOUCHER_NO = ''", "F", "TRN_CHALLAN.CHALLAN_NO", "F"}};
                    //----------
                    strQueryString = "SELECT MST_COMPANY.COMPANY_ID                    AS COMPANY_ID," +
                                     "       MST_COMPANY.COMPANY_NAME                  AS COMPANY_NAME," +
                                     "       MST_COMPANY.TAN_NO                        AS TAN_NO," +
                                     "       MST_CATEGORY.CATEGORY_CODE + ' - ' + " +
                                     "               MST_CATEGORY.CATEGORY_DESCRIPTION AS CATEGORY," +
                                     "       MST_EMPLOYEE.EMPLOYEE_ID                  AS DEDUCTEE_ID," +
                                     "      " + cmnService.J_SQLDBFormat("MST_EMPLOYEE.CATEGORY", J_SQLColFormat.Case_End, strEmployeeCategoryMatrix) + " AS DEDUCTEE_CODE," +
                                     "       MST_EMPLOYEE.EMPLOYEE_NAME                AS DEDUCTEE_NAME," +
                                     "       MST_EMPLOYEE.EMPLOYEE_PAN                 AS DEDUCTEE_PAN," +
                                     "       TRN_DEDUCTEE_DETAILS.PAYMENT_DATE         AS DEDUCTED_DATE," +
                                     "       MST_SECTION.SECTION_NO                    AS SECTION_NO," +
                                     "       TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT       AS PAYMENT_AMOUNT," +
                                     "       TRN_DEDUCTEE_DETAILS.CESS_AMOUNT          AS CESS_AMOUNT," +
                                     "       TRN_DEDUCTEE_DETAILS.TAX_AMOUNT           AS TAX_AMOUNT," +
                                     "       TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT         AS TOTAL_AMOUNT," +
                                     "       TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT AS TAX_DEPOSITED_AMOUNT," +
                                     "       " + cmnService.J_SQLDBFormat(strChallanNoMatrix, J_SQLColFormat.Case_End) + " AS PAY_DOC_NO," +
                                     "       TRN_CHALLAN.DEPOSIT_DATE                  AS PAY_DOC_DATE," +
                                     "       TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG   AS NON_DEDUCTION_FLAG," +
                                     "       MST_ASSESSMENT.FA_YEAR                    AS FA_YEAR," +
                                     "       TRN_BASIC_INFO.FORM_NO                    AS FORM_NO " +
                                     "FROM   TRN_BASIC_INFO," +
                                     "       TRN_CHALLAN," +
                                     "       TRN_DEDUCTEE_DETAILS," +
                                     "       MST_COMPANY," +
                                     "       MST_EMPLOYEE," +
                                     "       MST_SECTION," +
                                     "       MST_CATEGORY," +
                                     "       MST_ASSESSMENT " +
                                     "WHERE  TRN_BASIC_INFO.BASIC_INFO_ID       = TRN_CHALLAN.BASIC_INFO_ID " +
                                     "AND    TRN_CHALLAN.CHALLAN_ID             = TRN_DEDUCTEE_DETAILS.CHALLAN_ID " +
                                     "AND    TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_EMPLOYEE.EMPLOYEE_ID " +
