                                     "AND    TRN_CHALLAN.CHALLAN_ID             = TRN_DEDUCTEE_DETAILS.CHALLAN_ID " +
                                     "AND    TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_EMPLOYEE.EMPLOYEE_ID " +
                                     "AND    TRN_DEDUCTEE_DETAILS.SECTION_ID    = MST_SECTION.SECTION_ID " +
                                     "AND    MST_COMPANY.COMPANY_ID             = TRN_BASIC_INFO.COMPANY_ID " +
                                     "AND    MST_CATEGORY.CATEGORY_ID           = MST_COMPANY.D_CATEGORY_ID " +
                                     "AND    TRN_BASIC_INFO.ASST_ID             = MST_ASSESSMENT.ASST_ID " +
                                     "AND    MST_SECTION.SECTION_NO            IN(" + strSectionNo + ") " +
                                     "AND    TRN_BASIC_INFO.FORM_NO            IN(" + strFormNoSelected + ") " +
                                     //"AND    TRN_DEDUCTEE_DETAILS.PARTY_ID     IN(" + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + ") " +
                                     "AND    TRN_DEDUCTEE_DETAILS.PARTY_ID     IN(" + strSelectedGridItemsWithSearch + ") " +
                                     "AND    TRN_BASIC_INFO.COMPANY_ID           = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                                     "AND    TRN_DEDUCTEE_DETAILS.PAYMENT_DATE  >= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(mskFromDate) + cmnService.J_DateOperator() + " " +
                                     "AND    TRN_DEDUCTEE_DETAILS.PAYMENT_DATE  <= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(mskToDate) + cmnService.J_DateOperator() + " ";
                    // COMPARISON FILTER
                    // AMOUNT PAID FILTER
                    if (cmbComparisonCombo1.Text == T_TypeComparison.Equal)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT =  " + Convert.ToDouble(txtComparisonTextBox1.Text);
                    else if (cmbComparisonCombo1.Text == T_TypeComparison.Greater)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT >  " + Convert.ToDouble(txtComparisonTextBox1.Text);
                    else if (cmbComparisonCombo1.Text == T_TypeComparison.Less)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT <  " + Convert.ToDouble(txtComparisonTextBox1.Text);
                    // TDS AMOUNT FILTER
                    if (cmbComparisonCombo2.Text == T_TypeComparison.Equal)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT =  " + Convert.ToDouble(txtComparisonTextBox2.Text);
                    else if (cmbComparisonCombo2.Text == T_TypeComparison.Greater)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT >  " + Convert.ToDouble(txtComparisonTextBox2.Text);
                    else if (cmbComparisonCombo2.Text == T_TypeComparison.Less)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT <  " + Convert.ToDouble(txtComparisonTextBox2.Text);
                    // CESS
                    if (cmbComparisonCombo3.Text == T_TypeComparison.Equal)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.CESS_AMOUNT  =  " + Convert.ToDouble(txtComparisonTextBox3.Text);
                    else if (cmbComparisonCombo3.Text == T_TypeComparison.Greater)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.CESS_AMOUNT  >  " + Convert.ToDouble(txtComparisonTextBox3.Text);
                    else if (cmbComparisonCombo3.Text == T_TypeComparison.Less)
                        strQueryString = strQueryString + "AND TRN_DEDUCTEE_DETAILS.CESS_AMOUNT  <  " + Convert.ToDouble(txtComparisonTextBox3.Text);

                    // SORT
                    if (rbnSort1.Checked == true)
                    {
                        strQueryString = strQueryString + " ORDER BY MST_EMPLOYEE.EMPLOYEE_NAME," +
                            "            TRN_DEDUCTEE_DETAILS.PAYMENT_DATE," +
                            "            TRN_CHALLAN.CHALLAN_ID";
                    }
                    else if (rbnSort2.Checked == true)
                    {
                        strQueryString = strQueryString + " ORDER BY MST_EMPLOYEE.EMPLOYEE_NAME," +
                            "            TRN_DEDUCTEE_DETAILS.PAYMENT_DATE," +
                            "            TRN_CHALLAN.CHALLAN_ID";
                    }

                    //crEmployeeWiseQueryReport rptEmployeeWiseQueryReport = new crEmployeeWiseQueryReport();
                    //rptcls = (ReportClass)rptEmployeeWiseQueryReport;

                    //TextObject objtxtValue;
                    //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromDate"];
                    //objtxtValue.Text = mskFromDate.Text;
                    ////
                    //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtToDate"];
                    //objtxtValue.Text = mskToDate.Text;
                    //// FORM SELECTED
                    //strFormNoSelected = strFormNoSelected.Replace("'", "");
                    //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFormSelected"];
                    //objtxtValue.Text = "Form No. : " + strFormNoSelected;
                    //// SECTION SELECTED
                    //strSectionNo = strSectionNo.Replace("'", "");
                    //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtSectionNoSelected"];
                    //objtxtValue.Text = "Section No. selected: " + strSectionNo;
                    // AMOUNT PAID FILTER 
                    string strAmountPaidFilter = "";
                    if (txtComparisonTextBox1.Enabled == true)
                    {
                        //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtAmountPaidFilter"];
                        strAmountPaidFilter = "Amount Paid : " + cmbComparisonCombo1.Text + " - " + txtComparisonTextBox1.Text;
                    }
                    // TDS AMOUNT FILTER 
                    string strTDSAmountFilter = "";
                    if (txtComparisonTextBox2.Enabled == true)
                    {
                        //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtTDSAmountFilter"];
                        strTDSAmountFilter = "TDS Amount : " + cmbComparisonCombo2.Text + " - " + txtComparisonTextBox2.Text;
                    }
                    // RATE FILTER 
                    string strRateFilter = "";
                    if (txtComparisonTextBox3.Enabled == true)
                    {
                        //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtRateFilter"];
                        strRateFilter = "Cess : " + cmbComparisonCombo3.Text + " - " + txtComparisonTextBox3.Text;
                    }
                    //

                    //string[,] strArry = { { "txtReportTitle", "Employee Wise Query Report" } };
                    //rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                    if (TDSMAN.Classes.TDSMAN.T_EXPORT_REPORTS_CSV == true)
                    {
                        //
                        string strCSVPath = "", strCSVFileName = "PartyWiseDetail_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".csv";
                        // Create a new instance of FolderBrowserDialog.
                        FolderBrowserDialog folderBrowserDlg = new FolderBrowserDialog();
                        // A new folder button will display in FolderBrowserDialog.
                        folderBrowserDlg.ShowNewFolderButton = true;
                        //Show FolderBrowserDialog
                        DialogResult dlgResult = folderBrowserDlg.ShowDialog();
                        if (dlgResult.Equals(DialogResult.OK))
                        {
                            //Show selected folder path in textbox1.
                            strCSVPath = folderBrowserDlg.SelectedPath;
                            //Browsing start from root folder.
                            Environment.SpecialFolder rootFolder = folderBrowserDlg.RootFolder;
                        }
                        //
                        //string fullPath = Path.Combine(strCSVPath, strfolderName);
                        //// Create the directory
                        //Directory.CreateDirectory(fullPath);
                        //
                        if (strCSVPath != "")
                        {
                            ExportToCSV(strQueryString, Path.Combine(strCSVPath, strCSVFileName));
                            //
                            cmnService.J_UserMessage("Export completed");
                            //
                            System.Diagnostics.Process.Start(Path.Combine(strCSVPath, strCSVFileName));
                        }
                    }
                    else
                    {
                        string[,] strArryChallanWiseReport = { {"HeaderCompanyName", cmnService.J_Left(cmbCombo1.Text, cmbCombo1.Text.Length - 12) },
                                              {"HeaderTANFaYear", "TAN : " + cmnService.J_Left(cmnService.J_Right(cmbCombo1.Text,11),10) + " FA Year : " + cmbCombo2.Text },
                                              {"HeaderReportCD", "Employee Wise Query Report" },
                                              {"HeaderFromToDate", "From Date : " + mskFromDate.Text + " To :" + mskToDate.Text },
                                              {"FooterSelectedForm", "Form No. : " + strFormNoSelected },
                                              {"FooterSelectedSection", "Section No. selected: " + strSectionNo },
                                              {"FooterAmountPaid", strAmountPaidFilter },
                                              {"FooterSelectedTDSAmount", strTDSAmountFilter },
                                              {"FooterSelectedRate", strRateFilter }
                                                };
                        J_PreviewReportRDLC("\\Reports\\crEmployeeWiseQueryReport.rdlc", "DataSet1", strQueryString, strArryChallanWiseReport);
                    }
                }
                //-----------------------------------------------------------------------
                //---------------------------
                //ADDED BY DHRUB ON 07/02/2014 FOR RECORD REMAIN CHECKED INTO THE GRID AFTER SEARCH 
                dmlService.J_BeginTransaction();
                dmlService.J_ExecSql("DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED);
                dmlService.J_Commit();
                //--
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

        #region PrintForm27A
        //---------------------------------------------------
        //-- ANIK(2011-01-07)
        //---------------------------------------------------
        public void PrintForm27A(long BasicInfoID, string Qtr, string FYear, string FormNo, string PrintDate)
        {
            try
            {
                if (PrintDate.Trim() == "/  /")
                    PrintDate = "";
                    
                string[,] strAddressChangeMatrix = {{"TRN_BASIC_INFO.ADDRESS_CHANGE = 1", "F", "Yes", "T"},
                                                    {"TRN_BASIC_INFO.ADDRESS_CHANGE = 0", "F", "No", "T"}};

                string[,] strPAddressChangeMatrix = {{"TRN_BASIC_INFO.P_ADDRESS_CHANGE = 1", "F", "Yes", "T"},
                                                     {"TRN_BASIC_INFO.P_ADDRESS_CHANGE = 0", "F", "No", "T"}};

                string[,] strMinistryMatrix = {{"TRN_COMPANY_INFO.MINISTRY_ID > 0", "F", "MST_MINISTRY.MINISTRY_NAME", "F"},
                                               {"TRN_COMPANY_INFO.MINISTRY_ID = 0", "F", "TRN_COMPANY_INFO.MINISTRY_OTHER", "F"}};

                strQueryString = "SELECT  TRN_COMPANY_INFO.COMPANY_ID            AS COMPANY_ID," +
                    "                     TRN_COMPANY_INFO.COMPANY_NAME          AS COMPANY_NAME," +
                    "                     TRN_COMPANY_INFO.TAN_NO                AS TAN_NO," +
                    "                     TRN_COMPANY_INFO.PAN_NO                AS PAN_NO," +
                    "                     TRN_COMPANY_INFO.BRANCH_DIV            AS BRANCH_DIV," +
                    "                     TRN_COMPANY_INFO.D_CATEGORY_ID         AS D_CATEGORY_ID," +
                    "                     MST_CATEGORY.CATEGORY_DESCRIPTION      AS CATEGORY_DESCRIPTION," +
                    "                     MST_CATEGORY.CATEGORY_CODE             AS CATEGORY_CODE," +
                    "                  " + cmnService.J_SQLDBFormat(strAddressChangeMatrix, J_SQLColFormat.Case_End) + " AS ADDRESS_CHANGE," +
                    "                     TRN_COMPANY_INFO.ADDRESS1              AS ADDRESS1," +
                    "                     TRN_COMPANY_INFO.ADDRESS2              AS ADDRESS2," +
                    "                     TRN_COMPANY_INFO.ADDRESS3              AS ADDRESS3," +
                    "                     TRN_COMPANY_INFO.ADDRESS4              AS ADDRESS4," +
                    "                     TRN_COMPANY_INFO.ADDRESS5              AS ADDRESS5," +
                    "                     TRN_COMPANY_INFO.STATE_ID              AS STATE_ID," +
                    "                     MST_STATE.STATE_NAME                   AS STATE_NAME," +
                    "                     TRN_COMPANY_INFO.PIN_CODE              AS PIN_CODE," +
                    "                     TRN_COMPANY_INFO.STD                   AS STD," +
                    "                     TRN_COMPANY_INFO.PHONE                 AS PHONE," +
                    "                     TRN_COMPANY_INFO.EMAIL                 AS EMAIL," +
                    "                     TRN_COMPANY_INFO.PERSON_NAME           AS PERSON_NAME," +
                    "                     TRN_COMPANY_INFO.DESIGNATION           AS DESIGNATION," +
                    "                     TRN_COMPANY_INFO.FATHER_NAME           AS FATHER_NAME," +
                    "                  " + cmnService.J_SQLDBFormat(strPAddressChangeMatrix, J_SQLColFormat.Case_End) + " AS P_ADDRESS_CHANGE," +
                    "                     TRN_COMPANY_INFO.P_ADDRESS1            AS P_ADDRESS1," +
                    "                     TRN_COMPANY_INFO.P_ADDRESS2            AS P_ADDRESS2," +
                    "                     TRN_COMPANY_INFO.P_ADDRESS3            AS P_ADDRESS3," +
                    "                     TRN_COMPANY_INFO.P_ADDRESS4            AS P_ADDRESS4," +
                    "                     TRN_COMPANY_INFO.P_ADDRESS5            AS P_ADDRESS5," +
                    "                     TRN_COMPANY_INFO.P_STATE_ID            AS P_STATE_ID," +
                    "                     RP_STATE.STATE_NAME                    AS RP_STATE_NAME," +
                    "                     TRN_COMPANY_INFO.P_PIN_CODE            AS P_PIN_CODE," +
                    "                     TRN_COMPANY_INFO.P_PHONE               AS P_PHONE," +
                    "                     TRN_COMPANY_INFO.P_STD                 AS P_STD," +
                    "                     TRN_COMPANY_INFO.P_EMAIL               AS P_EMAIL," +
                    "                     TRN_COMPANY_INFO.P_MOBILE              AS P_MOBILE," +
                    "                     TRN_COMPANY_INFO.PAO_CODE              AS PAO_CODE," +
                    "                     TRN_COMPANY_INFO.PAO_REG_NO            AS PAO_REG_NO," +
                    "                     TRN_COMPANY_INFO.DDO_CODE              AS DDO_CODE," +
                    "                     TRN_COMPANY_INFO.DDO_REG_NO            AS DDO_REG_NO," +
                    "                     TRN_COMPANY_INFO.D_STATE_ID            AS D_STATE_ID," +
                    "                     D_STATE.STATE_NAME                     AS D_STATE_NAME," +
                    "                  " + cmnService.J_SQLDBFormat(strMinistryMatrix, J_SQLColFormat.Case_End) + " AS MINISTRY," +
                    "                     TRN_BASIC_INFO.RECEIPT_NO              AS RECEIPT_NO," +
                    "                  " + cmnService.J_SQLDBFormat("TRN_BASIC_INFO.DATE_OF_FILING", J_SQLColFormat.DateFormatDDMMYYYY) + " AS DATE_OF_FILING," +             
		            "                     MST_ASSESSMENT.ASST_YEAR               AS ASST_YEAR," +
		            "                     MST_ASSESSMENT.FA_YEAR                 AS FA_YEAR," +
		            "                     TRN_BASIC_INFO.FORM_NO                 AS FORM_NO," +
                    "                     '" + PrintDate + "'                    AS PRINT_DATE " +
                    "             FROM    (((((((TRN_COMPANY_INFO INNER JOIN MST_CATEGORY " +
                    "                     ON TRN_COMPANY_INFO.D_CATEGORY_ID = MST_CATEGORY.CATEGORY_ID) " +
                    "                     INNER JOIN MST_STATE " +
                    "                     ON TRN_COMPANY_INFO.STATE_ID      = MST_STATE.STATE_ID) " +
                    "                     INNER JOIN MST_STATE AS RP_STATE " +
                    "                     ON TRN_COMPANY_INFO.P_STATE_ID    = RP_STATE.STATE_ID) " +
                    "                     LEFT JOIN  MST_STATE AS D_STATE " +
                    "                     ON TRN_COMPANY_INFO.D_STATE_ID    = D_STATE.STATE_ID) " +
                    "                     LEFT JOIN  MST_MINISTRY " +
                    "                     ON TRN_COMPANY_INFO.MINISTRY_ID   = MST_MINISTRY.MINISTRY_ID)" +
                    "                     INNER JOIN TRN_BASIC_INFO " +
                    "                     ON TRN_COMPANY_INFO.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID) " +             
		            "                     INNER JOIN MST_ASSESSMENT " +
		            "                     ON MST_ASSESSMENT.ASST_ID         = TRN_BASIC_INFO.ASST_ID) " +
                    "             WHERE   TRN_BASIC_INFO.BASIC_INFO_ID      = " + BasicInfoID + " ";

                if (FormNo == T_FormNo.F27EQ)
                {
                    crForm27B rptForm27B = new crForm27B();
                    rptcls = (ReportClass)rptForm27B;
                }
                else
                {
                    crForm27A rptForm27A = new crForm27A();
                    rptcls = (ReportClass)rptForm27A;
                }
                // FORM SELECTED
                TextObject objtxtValue;

                //strSQL = "SELECT COUNT(CHALLAN_ID) AS COUNT_CHALLAN_ID " +
                //    "     FROM   TRN_CHALLAN," +
                //    "            TRN_BASIC_INFO " +
                //    "     WHERE  TRN_CHALLAN.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID " +
                //    "     AND    TRN_BASIC_INFO.BASIC_INFO_ID = " + BasicInfoID + " ";

                //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[3].ReportObjects["txtNoOfChallan"];
                //objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[3].ReportObjects["txtFrom"];
                objtxtValue.Text = TdsMan.T_ReturnQuarterStartDate(Qtr,FYear);

                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[3].ReportObjects["txtTo"];
                objtxtValue.Text = TdsMan.T_ReturnQuarterEndDate(Qtr, FYear) + ")";

                strSQL = "SELECT IIF(ISNULL(SUM(PAYMENT_AMOUNT)),'0',SUM(PAYMENT_AMOUNT)) AS SUM_PAYMENT_AMOUNT " +
                    "     FROM   TRN_DEDUCTEE_DETAILS," +
                    "            TRN_BASIC_INFO " +
                    "     WHERE  TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID " +
                    "     AND    TRN_BASIC_INFO.BASIC_INFO_ID = " + BasicInfoID + " ";

                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[3].ReportObjects["txtTotalTax"];
                objtxtValue.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))));

                strSQL = "SELECT COUNT(DEDUCTEE_DETAIL_ID) AS COUNT_DEDUCTEE_DETAIL_ID " +
                    "     FROM   TRN_DEDUCTEE_DETAILS," +
                    "            TRN_BASIC_INFO " +
                    "     WHERE  TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID " +
                    "     AND    TRN_BASIC_INFO.BASIC_INFO_ID = " + BasicInfoID + " ";

                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[3].ReportObjects["txtNoOfDeducteeRecords"];
                objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));

                strSQL = "SELECT IIF(ISNULL(SUM(TOTAL_AMOUNT)),'0',SUM(TOTAL_AMOUNT)) AS SUM_TOTAL_AMOUNT " +
                    "     FROM   TRN_DEDUCTEE_DETAILS," +
                    "            TRN_BASIC_INFO " +
                    "     WHERE  TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID " +
                    "     AND    TRN_BASIC_INFO.BASIC_INFO_ID = " + BasicInfoID + " ";

                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[3].ReportObjects["txtTotalTDS"];
                objtxtValue.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))));

                //strSQL = "SELECT IIF(ISNULL(SUM(TAX_DEPOSITED_AMOUNT)),'0',SUM(TAX_DEPOSITED_AMOUNT)) AS SUM_TAX_DEPOSITED_AMOUNT " +
                //    "     FROM   TRN_DEDUCTEE_DETAILS," +
                //    "            TRN_BASIC_INFO " +
                //    "     WHERE  TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID " +
                //    "     AND    TRN_BASIC_INFO.BASIC_INFO_ID = " + BasicInfoID + " ";

                strSQL = "SELECT IIF(ISNULL(SUM(TOT_TAX)),'0',SUM(TOT_TAX)) AS SUM_TAX_DEPOSITED_AMOUNT " +
                    "     FROM   TRN_CHALLAN," +
                    "            TRN_BASIC_INFO " +
                    "     WHERE  TRN_CHALLAN.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID " +
                    "     AND    TRN_BASIC_INFO.BASIC_INFO_ID = " + BasicInfoID + " ";

                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[3].ReportObjects["txtTaxDeposited"];
                objtxtValue.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))));

                if (FormNo == T_FormNo.F27EQ)
                {
                    string[,] strArry1 = { { "txtReportTitle", "Form 27B" } };

                    //Modified by Shrey Kejriwal on 13/03/2012
                    rptService.J_PreviewReport(ref rptcls, TDSMAN.Classes.TDSMAN.T_pCurrentForm, strQueryString, strArry1);
                }
                else
                {
                    string[,] strArry = { { "txtReportTitle", "Form 27A" } };

                    //Modified by Shrey Kejriwal on 13/03/2012
                    rptService.J_PreviewReport(ref rptcls, TDSMAN.Classes.TDSMAN.T_pCurrentForm, strQueryString, strArry);
                }
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

        #region PrintCorrForm27A
        //---------------------------------------------------
        //-- ANIK(2011-03-11)
