        //QUERY MODIFIED BY SHREY KEJRIWAL ON 02/03/2012

        public void PrintCorrForm27A(long BatchID, string Qtr, string FYear, string FormNo,string PrintDate)
        {
            try
            {
                if (PrintDate.Trim() == "/  /")
                    PrintDate = "";

                string[,] strAddressChangeMatrix = {{"COR_TRN_COMPANY.ADDRESS_CHANGE = 1", "F", "Yes", "T"},
                                                    {"COR_TRN_COMPANY.ADDRESS_CHANGE = 0", "F", "No", "T"}};

                string[,] strPAddressChangeMatrix = {{"COR_TRN_COMPANY.P_ADDRESS_CHANGE = 1", "F", "Yes", "T"},
