        #region PrintDeductionSummaryReport_RDLC

        //ADDED BY ARUP - 2011-01-05
        private void PrintDeductionSummaryReport_RDLC()
        {
            try
            {
                string strSELECT = "";
                string strGROUP_BY = "";
                string strGROUP_BY1 = "";
                string strWHERE = "";
                string strMonthFormat = "";
                string strJoiningClause = "";
                string strSubQuerySelect = "";
                string strSubQuerySelect1 = "";
                string strOrderBy = "";
                int intYearFrom = 0;
                int intYearTo = 0;
                string strQTR = "";
                string strSummaryFilter = "";
                string strFromYear = "";
                string strToYear = "";
                string strForMonthly = ""; //-- 2016/03/28
                string strReportHeaderLeft = "";
                //---------------------------------strReportHeaderLeft----------------------
                //crDeductionSummary rptDeductionSummary = new crDeductionSummary();
                //rptcls = (ReportClass)rptDeductionSummary;

                //// FROM & TO PERIOD
                //TextObject objtxtValue;
                //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToPeriod"];

                //---------------------------------------------------------
                // FORM NO
                //string strFormNo = "";
                //foreach (int indexChecked in clbListBox1.CheckedIndices)
                //{
                //    strFormNo = strFormNo + "'" + clbListBox1.Items[indexChecked] + "',";
                //}
                //if (cmnService.J_Right(strFormNo, 1) == ",")
                //    strFormNo = cmnService.J_Mid(strFormNo, 0, (strFormNo.Length - 1));
                string strFormNo = "";

                foreach (int indexChecked in clbListBox1.CheckedIndices)
                {
                    string strItem = clbListBox1.Items[indexChecked].ToString();

                    int startIndex = strItem.IndexOf("(");
                    int endIndex = strItem.IndexOf(")");

                    if (startIndex >= 0 && endIndex > startIndex)
                    {
                        string formNo = strItem.Substring(
                            startIndex + 1,
                            endIndex - startIndex - 1);

                        strFormNo += "'" + formNo + "',";
                    }
                }

                if (cmnService.J_Right(strFormNo, 1) == ",")
                {
                    strFormNo = cmnService.J_Mid(
                        strFormNo,
                        0,
                        strFormNo.Length - 1);
                }
                //-------------------------------------------------------------------
                //SETTING SORTING ORDER 
                if (rbnSort1.Checked == true)   // MONTHLY
                {
                    if (Convert.ToInt32(Support.GetItemData(cmbCombo3, cmbCombo3.SelectedIndex)) <= 3)
                        intYearFrom = Convert.ToInt16(cmnService.J_Left(cmbCombo2.Text, 2) + cmnService.J_Right(cmbCombo2.Text, 2));
                    else
                        intYearFrom = Convert.ToInt16(cmnService.J_Left(cmbCombo2.Text, 4));

                    if (Convert.ToInt32(Support.GetItemData(cmbCombo4, cmbCombo4.SelectedIndex)) <= 3)
                        intYearTo = Convert.ToInt16(cmnService.J_Left(cmbCombo2.Text, 2) + cmnService.J_Right(cmbCombo2.Text, 2));
                    else
                        intYearTo = Convert.ToInt16(cmnService.J_Left(cmbCombo2.Text, 4));


                    strSELECT = "   MASTER.MONTH_NAME AS PERIOD," +
                        "          MASTER.MONTH_NUMBER,";

                    //-- 2016/03/28
                    strForMonthly = "MONTH_NUMBER,";
                    //strMonthFormat = "  FORMAT(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 'MMM') AS MONTH_NAME," +
                    //"                   MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE) AS MONTH_NUMBER,";

                    //strGROUP_BY = "     ,MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE)," +
                    //"                   FORMAT(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 'MMM')";

                    if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                        strMonthFormat = "  DATENAME(MONTH, CAST(CONVERT(CHAR(10),TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,101) AS DATETIME)) AS MONTH_NAME," +
                        "                   DATEPART(M, CAST(CONVERT(CHAR(10), TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 101) AS DATETIME)) AS MONTH_NUMBER,";
                    else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                        strMonthFormat = "  FORMAT(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 'MMM') AS MONTH_NAME," +
                        "                   MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE) AS MONTH_NUMBER,";

                    if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                        strGROUP_BY = " ,DATEPART(M,CAST(CONVERT(CHAR(10),TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,101) AS DATETIME))," +
                         "               DATENAME(MONTH,CAST(CONVERT(CHAR(10),TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,101) AS DATETIME))";
                    else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                        strGROUP_BY = " ,MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE)," +
                         "                   FORMAT(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 'MMM')";                    

                    strWHERE = " AND TRN_DEDUCTEE_DETAILS.PAYMENT_DATE >= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(Convert.ToString(TdsMan.GetFirstDayOfMonth(Convert.ToInt32(Support.GetItemData(cmbCombo3, cmbCombo3.SelectedIndex)), intYearFrom))) + cmnService.J_DateOperator() + " " +
                      "            AND TRN_DEDUCTEE_DETAILS.PAYMENT_DATE <= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(Convert.ToString(TdsMan.GetLastDayOfMonth(Convert.ToInt32(Support.GetItemData(cmbCombo4, cmbCombo4.SelectedIndex)), intYearTo))) + cmnService.J_DateOperator() + " ";


                    strSubQuerySelect = "  MONTH_NAME," +
                    "                      MONTH_NUMBER,";

                    strJoiningClause = "  AND MASTER.MONTH_NUMBER = DEDUCTEE_RECORDS.MONTH_NUMBER ";

                    //EDITED BY SHREY ON 2011-05-04 TO IMPROVE ORDER BY--
                    //strOrderBy = "IIF(MASTER.MONTH_NUMBER>3,0,1), MASTER.MONTH_NUMBER,MASTER.FORM_NO,MASTER.SECTION_NO";
                    string[,] strOrderByMatrix = {{"MASTER.MONTH_NUMBER > 3", "F", "0", "T"},
                                                  {"MASTER.MONTH_NUMBER <= 3", "F", "1", "T"}};
                    strOrderBy = cmnService.J_SQLDBFormat(strOrderByMatrix, J_SQLColFormat.Case_End) + ", MASTER.SECTION_NO";
                    //-- 2020/11/28
                    if (rbnSort1_1.Checked == true) //-- PERIOD WISE
                    {
                        strOrderBy = cmnService.J_SQLDBFormat(strOrderByMatrix, J_SQLColFormat.Case_End) + ", MASTER.MONTH_NUMBER, MASTER.FORM_NO, MASTER.SECTION_NO"; //"MASTER.FA_YEAR,MASTER.FORM_NO,MASTER.SECTION_NO";
                    }
                    else if (rbnSort1_2.Checked == true) //-- FORM NO WISE
                    {
                        strOrderBy = "MASTER.FORM_NO," + cmnService.J_SQLDBFormat(strOrderByMatrix, J_SQLColFormat.Case_End) + ", MASTER.SECTION_NO";
                    }
                    else if (rbnSort1_3.Checked == true) //-- SECTION WISE
                    {
                        strOrderBy = "MASTER.SECTION_NO," + cmnService.J_SQLDBFormat(strOrderByMatrix, J_SQLColFormat.Case_End) + ", MASTER.FORM_NO";
                    }
                    // setting from to heading

                    strFromYear = cmbCombo2.Text.Substring(0, 4);
                    strToYear = cmbCombo2.Text.Substring(5, 2);
                    strToYear = "20" + strToYear;

                    strSummaryFilter = rbnSort1.Text;
                    //objtxtValue.Text = "From : " + cmbCombo3.Text + " - " + strFromYear + " To : " + cmbCombo4.Text + " - " + strToYear;
                    strReportHeaderLeft = "From : " + cmbCombo3.Text + " - " + strFromYear + " To : " + cmbCombo4.Text + " - " + strToYear;

                }
                // QUARTERLY
                else if (rbnSort2.Checked == true)
                {
                    //
                    if (cmbCombo3.Text == T_Qtr.Q1)
                        strQTR = "'" + T_Qtr.Q1 + "',";
                    if (cmbCombo3.Text == T_Qtr.Q2)
                        strQTR = "'" + T_Qtr.Q2 + "',";
                    if (cmbCombo3.Text == T_Qtr.Q3)
                        strQTR = "'" + T_Qtr.Q3 + "',";
                    if (cmbCombo3.Text == T_Qtr.Q4)
                        strQTR = "'" + T_Qtr.Q4 + "',";

                    if (cmbCombo4.Text == T_Qtr.Q1)
                        strQTR = "'" + T_Qtr.Q1 + "',";
                    else if (cmbCombo4.Text == T_Qtr.Q2)
                    {
                        if (cmbCombo3.Text == T_Qtr.Q1)
                            strQTR = strQTR + "'" + T_Qtr.Q2 + "',";
                        else if (cmbCombo3.Text == T_Qtr.Q2)
                            strQTR = "'" + T_Qtr.Q2 + "',";
                    }
                    else if (cmbCombo4.Text == T_Qtr.Q3)
                    {
                        if (cmbCombo3.Text == T_Qtr.Q1)
                            strQTR = "'" + T_Qtr.Q1 + "'," + "'" + T_Qtr.Q2 + "'," + "'" + T_Qtr.Q3 + "',";
                        else if (cmbCombo3.Text == T_Qtr.Q2)
                            strQTR = "'" + T_Qtr.Q2 + "'," + "'" + T_Qtr.Q3 + "',";
                        else if (cmbCombo3.Text == T_Qtr.Q3)
                            strQTR = "'" + T_Qtr.Q3 + "',";
                    }
                    else if (cmbCombo4.Text == T_Qtr.Q4)
                    {
                        if (cmbCombo3.Text == T_Qtr.Q1)
                            strQTR = "'" + T_Qtr.Q1 + "'," + "'" + T_Qtr.Q2 + "'," + "'" + T_Qtr.Q3 + "'," + "'" + T_Qtr.Q4 + "',";
                        else if (cmbCombo3.Text == T_Qtr.Q2)
                            strQTR = "'" + T_Qtr.Q2 + "'," + "'" + T_Qtr.Q3 + "'," + "'" + T_Qtr.Q4 + "',";
                        else if (cmbCombo3.Text == T_Qtr.Q3)
                            strQTR = "'" + T_Qtr.Q3 + "'," + "'" + T_Qtr.Q4 + "',";
                        else if (cmbCombo3.Text == T_Qtr.Q4)
                            strQTR = "'" + T_Qtr.Q4 + "',";
                    }
                    //
                    if (cmnService.J_Right(strQTR, 1) == ",")
                        strQTR = cmnService.J_Mid(strQTR, 0, (strQTR.Length - 1));

                    strWHERE = " AND TRN_BASIC_INFO.QTR IN (" + strQTR + ")";

                    strSELECT = "    MASTER.QTR AS PERIOD,";
                    strGROUP_BY = " ,TRN_BASIC_INFO.QTR ";
                    strGROUP_BY1 = " ,DEDUCTEE.QTR ";

                    strMonthFormat = " TRN_BASIC_INFO.QTR, ";
                    strJoiningClause = "  AND MASTER.QTR = DEDUCTEE_RECORDS.QTR ";

                    strSubQuerySelect = " TRN_BASIC_INFO.QTR,";
                    strSubQuerySelect1 = " DEDUCTEE.QTR,";
                    //strOrderBy = "MASTER.QTR,MASTER.FORM_NO,MASTER.SECTION_NO";
                    //-- 2020/11/28
                    if (rbnSort1_1.Checked == true) //-- PERIOD WISE
                    {
                        strOrderBy = "MASTER.QTR,MASTER.FORM_NO,MASTER.SECTION_NO";
                    }
                    else if (rbnSort1_2.Checked == true) //-- FORM NO WISE
                    {
                        strOrderBy = "MASTER.FORM_NO,MASTER.QTR,MASTER.SECTION_NO";
                    }
                    else if (rbnSort1_3.Checked == true) //-- SECTION WISE
                    {
                        strOrderBy = "MASTER.SECTION_NO,MASTER.QTR,MASTER.FORM_NO";
                    }

                    strSummaryFilter = rbnSort2.Text;
                    //objtxtValue.Text = "From : Quarter " + cmnService.J_Right(cmbCombo3.Text, 1) + " To : Quarter " + cmnService.J_Right(cmbCombo4.Text, 1);
                    strReportHeaderLeft = "From : Quarter " + cmnService.J_Right(cmbCombo3.Text, 1) + " To : Quarter " + cmnService.J_Right(cmbCombo4.Text, 1);

                }
                // ANNUALLY
                else if (rbnSort3.Checked == true)
                {
                    strSELECT = "  MASTER.FA_YEAR AS PERIOD,";

                    //strOrderBy = "MASTER.FA_YEAR,MASTER.FORM_NO,MASTER.SECTION_NO";
                    //-- 2020/11/28
                    if(rbnSort1_1.Checked==true) //-- PERIOD WISE
                    {
                        strOrderBy = "MASTER.FA_YEAR,MASTER.FORM_NO,MASTER.SECTION_NO";
                    }
                    else if (rbnSort1_2.Checked == true) //-- FORM NO WISE
                    {
                        strOrderBy = "MASTER.FORM_NO,MASTER.FA_YEAR,MASTER.SECTION_NO";
                    }
                    else if (rbnSort1_3.Checked == true) //-- SECTION WISE
                    {
                        strOrderBy = "MASTER.SECTION_NO,MASTER.FA_YEAR,MASTER.FORM_NO";
                    }
                    // FROM & TO PERIOD
                    //objtxtValue.Text = "";
                    strReportHeaderLeft = "";
                    strSummaryFilter = rbnSort3.Text;
                }
                //------------------------------------------------------------------------
                strQueryString = "SELECT MASTER.COMPANY_ID, " +
                    "                    MASTER.COMPANY_NAME, " +
                    "                    MASTER.FA_YEAR," +
                    "                    MASTER.TAN_NO, " +
                    "                    MASTER.FORM_NO, " +
                    "                    MASTER.SECTION_NO, " +
                    "                    MASTER.PAYMENT_AMOUNT," +
                    "                    MASTER.TAX_AMOUNT," +
                    "                    MASTER.NO_OF_DEDUCTION,";
                strQueryString += strSELECT + 
                    " DEDUCTEE_RECORDS.No_Of_Deductee_Record " +
                    "           FROM( SELECT MST_COMPANY.COMPANY_ID," +
                    "                        MST_COMPANY.COMPANY_Name," +
                    "                        MST_COMPANY.TAN_NO," +
                    "                        MST_ASSESSMENT.FA_YEAR," +
                    "                        TRN_BASIC_INFO.FORM_NO," +
                    "                        MST_SECTION.SECTION_NO,";
                strQueryString += strMonthFormat + 
                    "                        SUM(TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT)       AS PAYMENT_AMOUNT," +
                    "                        SUM(TRN_DEDUCTEE_DETAILS.TAX_AMOUNT)           AS TAX_AMOUNT," +
                    "                        COUNT(TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID) AS NO_OF_DEDUCTION " +
                    "                 FROM MST_ASSESSMENT," +
                    "                      MST_COMPANY," +
                    "                      MST_SECTION," +
                    "                      TRN_BASIC_INFO," +
                    "                      TRN_CHALLAN," +
                    "                      TRN_DEDUCTEE_DETAILS " +
                    "                  WHERE MST_COMPANY.COMPANY_ID       = TRN_BASIC_INFO.COMPANY_ID " +
                    "                  AND   TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID " +
                    "                  AND   TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID " +
                    "                  AND   TRN_CHALLAN.CHALLAN_ID       = TRN_DEDUCTEE_DETAILS.CHALLAN_ID " +
                    //"                  AND   MST_SECTION.SECTION_ID       = TRN_CHALLAN.SECTION_ID " +
                    "                  AND   MST_SECTION.SECTION_ID       = TRN_DEDUCTEE_DETAILS.SECTION_ID " +
                    "                  AND   MST_COMPANY.COMPANY_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                    "                  AND   MST_ASSESSMENT.ASST_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " ";
                strQueryString += strWHERE + 
                    "                  AND   TRN_BASIC_INFO.FORM_NO IN (" + strFormNo + ") " +
                    "                  GROUP BY  MST_COMPANY.COMPANY_ID," +
                    "                        MST_COMPANY.COMPANY_Name," +
                    "                        MST_COMPANY.TAN_NO," +
                    "                        MST_ASSESSMENT.FA_YEAR," +
                    "                        TRN_BASIC_INFO.FORM_NO," +
                    "                        MST_SECTION.SECTION_NO ";
                strQueryString += strGROUP_BY + 
                    "                 ) AS MASTER " +
                    "                 INNER JOIN " +
                    "                 (SELECT COMPANY_ID, " +
                    "                          TAN_NO," +
                    "                          FA_YEAR," +
                    "                          FORM_NO," +
                    "                          SECTION_NO, " + strForMonthly ; //-- 2016/03/28 ' MONTH_NUMBER,'
                strQueryString += strSubQuerySelect1 + 
                    "                          COUNT(PARTY) AS No_Of_Deductee_Record " +
                    "                  FROM   (SELECT MST_COMPANY.COMPANY_ID," +
                    "                                 MST_COMPANY.TAN_NO," +
                    "                                 MST_ASSESSMENT.FA_YEAR," +
                    "                                 TRN_BASIC_INFO.FORM_NO," +
                    "                                 MST_SECTION.SECTION_NO,";
                strQueryString += strMonthFormat + 
                    "                                 PARTY_ID," +
                    "                                 COUNT(PARTY_ID) AS PARTY " +
                    "                          FROM MST_ASSESSMENT," +
                    "                               MST_COMPANY," +
                    "                               MST_SECTION," +
                    "                               TRN_BASIC_INFO," +
                    "                               TRN_CHALLAN," +
                    "                               TRN_DEDUCTEE_DETAILS " +
                    "                          WHERE MST_COMPANY.COMPANY_ID       = TRN_BASIC_INFO.COMPANY_ID " +
                    "                          AND   TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID " +
                    "                          AND   TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID " +
                    "                          AND   TRN_CHALLAN.CHALLAN_ID       = TRN_DEDUCTEE_DETAILS.CHALLAN_ID " +
                    //"                          AND   MST_SECTION.SECTION_ID       = TRN_CHALLAN.SECTION_ID " +
                    "                          AND   MST_SECTION.SECTION_ID       = TRN_DEDUCTEE_DETAILS.SECTION_ID " +
                    "                          AND   MST_COMPANY.COMPANY_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                    "                          AND   MST_ASSESSMENT.ASST_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " ";
                strQueryString += strWHERE + 
                    "                          AND   TRN_BASIC_INFO.FORM_NO    IN (" + strFormNo + ") " +
                    "                          GROUP BY  MST_COMPANY.COMPANY_ID," +
                    "                                    MST_COMPANY.TAN_NO," +
                    "                                    MST_ASSESSMENT.FA_YEAR," +
                    "                                    TRN_BASIC_INFO.FORM_NO," +
                    "                                    MST_SECTION.SECTION_NO ";
                strQueryString += strGROUP_BY + 
                    "                                    ,PARTY_ID)  AS DEDUCTEE " +
                    "           GROUP BY TAN_NO," +
                    "                    FA_YEAR, " +
                    "                    FORM_NO," +
                    "                    SECTION_NO, " + strForMonthly; //-- 2016/03/28 ' MONTH_NUMBER,'
                strQueryString += strSubQuerySelect1 + 
                    "                    COMPANY_ID)DEDUCTEE_RECORDS " +
                    "           ON  MASTER.COMPANY_ID = DEDUCTEE_RECORDS.COMPANY_ID " +
                    "           AND MASTER.TAN_NO     = DEDUCTEE_RECORDS.TAN_NO " +
                    "           AND MASTER.FA_YEAR    = DEDUCTEE_RECORDS.FA_YEAR " +
                    "           AND MASTER.FORM_NO    = DEDUCTEE_RECORDS.FORM_NO " +
                    "           AND MASTER.SECTION_NO = DEDUCTEE_RECORDS.SECTION_NO ";
                strQueryString += strJoiningClause + " ORDER BY " + strOrderBy;

                //call crystal report to display Report
                //---------------------------------------------------------------------------------
                //string[,] strArry = { { "txtReportTitle", "Deductions - " + strSummaryFilter + " Summary" } };
                //rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                //-----------------------------------------------------------------------------------
                string[,] strArryChallanReport = { {"HeaderCompanyName", cmnService.J_Left(cmbCombo1.Text, cmbCombo1.Text.Length - 12) },
                                              {"HeaderTANFaYear", "TAN : " + cmnService.J_Left(cmnService.J_Right(cmbCombo1.Text,11),10) + " FA Year : " + cmbCombo2.Text },
                                              {"HeaderLeft", strReportHeaderLeft },
                                              {"HeaderReportCD", "Deductions - " + strSummaryFilter + " Summary" }
                                                };
                J_PreviewReportRDLC("\\Reports\\crDeductionSummary.rdlc", "DataSet1", strQueryString, strArryChallanReport);

            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }



        #endregion

        #region PrintDeductionSummaryReport

        //ADDED BY ARUP - 2011-01-05
        private void PrintDeductionSummaryReport()
        {
            try
            {
                string strSELECT = "";
                string strGROUP_BY = "";
                string strGROUP_BY1 = "";
                string strWHERE = "";
                string strMonthFormat = "";
                string strJoiningClause = "";
                string strSubQuerySelect = "";
                string strSubQuerySelect1 = "";
                string strOrderBy = "";
                int intYearFrom = 0;
                int intYearTo = 0;
                string strQTR = "";
                string strSummaryFilter = "";
                string strFromYear = "";
                string strToYear = "";
                string strForMonthly = ""; //-- 2016/03/28
                //-------------------------------------------------------
                crDeductionSummary rptDeductionSummary = new crDeductionSummary();
                rptcls = (ReportClass)rptDeductionSummary;

                // FROM & TO PERIOD
                TextObject objtxtValue;
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToPeriod"];

                //---------------------------------------------------------
                // FORM NO
                string strFormNo = "";
                foreach (int indexChecked in clbListBox1.CheckedIndices)
                {
                    strFormNo = strFormNo + "'" + clbListBox1.Items[indexChecked] + "',";
                }
                if (cmnService.J_Right(strFormNo, 1) == ",")
                    strFormNo = cmnService.J_Mid(strFormNo, 0, (strFormNo.Length - 1));

                //-------------------------------------------------------------------
                //SETTING SORTING ORDER 
                if (rbnSort1.Checked == true)   // MONTHLY
                {
                    if (Convert.ToInt32(Support.GetItemData(cmbCombo3, cmbCombo3.SelectedIndex)) <= 3)
                        intYearFrom = Convert.ToInt16(cmnService.J_Left(cmbCombo2.Text, 2) + cmnService.J_Right(cmbCombo2.Text, 2));
                    else
                        intYearFrom = Convert.ToInt16(cmnService.J_Left(cmbCombo2.Text, 4));

                    if (Convert.ToInt32(Support.GetItemData(cmbCombo4, cmbCombo4.SelectedIndex)) <= 3)
                        intYearTo = Convert.ToInt16(cmnService.J_Left(cmbCombo2.Text, 2) + cmnService.J_Right(cmbCombo2.Text, 2));
                    else
                        intYearTo = Convert.ToInt16(cmnService.J_Left(cmbCombo2.Text, 4));


                    strSELECT = "   MASTER.MONTH_NAME AS PERIOD," +
                        "          MASTER.MONTH_NUMBER,";

                    //-- 2016/03/28
                    strForMonthly = "MONTH_NUMBER,";
                    //strMonthFormat = "  FORMAT(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 'MMM') AS MONTH_NAME," +
                    //"                   MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE) AS MONTH_NUMBER,";

                    //strGROUP_BY = "     ,MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE)," +
                    //"                   FORMAT(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 'MMM')";

                    if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                        strMonthFormat = "  DATENAME(MONTH, CAST(CONVERT(CHAR(10),TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,101) AS DATETIME)) AS MONTH_NAME," +
                        "                   DATEPART(M, CAST(CONVERT(CHAR(10), TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 101) AS DATETIME)) AS MONTH_NUMBER,";
                    else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                        strMonthFormat = "  FORMAT(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 'MMM') AS MONTH_NAME," +
                        "                   MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE) AS MONTH_NUMBER,";

                    if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                        strGROUP_BY = " ,DATEPART(M,CAST(CONVERT(CHAR(10),TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,101) AS DATETIME))," +
                         "               DATENAME(MONTH,CAST(CONVERT(CHAR(10),TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,101) AS DATETIME))";
                    else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                        strGROUP_BY = " ,MONTH(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE)," +
                         "                   FORMAT(TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 'MMM')";

                    strWHERE = " AND TRN_DEDUCTEE_DETAILS.PAYMENT_DATE >= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(Convert.ToString(TdsMan.GetFirstDayOfMonth(Convert.ToInt32(Support.GetItemData(cmbCombo3, cmbCombo3.SelectedIndex)), intYearFrom))) + cmnService.J_DateOperator() + " " +
                      "            AND TRN_DEDUCTEE_DETAILS.PAYMENT_DATE <= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(Convert.ToString(TdsMan.GetLastDayOfMonth(Convert.ToInt32(Support.GetItemData(cmbCombo4, cmbCombo4.SelectedIndex)), intYearTo))) + cmnService.J_DateOperator() + " ";


                    strSubQuerySelect = "  MONTH_NAME," +
                    "                      MONTH_NUMBER,";

                    strJoiningClause = "  AND MASTER.MONTH_NUMBER = DEDUCTEE_RECORDS.MONTH_NUMBER ";

                    //EDITED BY SHREY ON 2011-05-04 TO IMPROVE ORDER BY--
                    //strOrderBy = "IIF(MASTER.MONTH_NUMBER>3,0,1), MASTER.MONTH_NUMBER,MASTER.FORM_NO,MASTER.SECTION_NO";
                    string[,] strOrderByMatrix = {{"MASTER.MONTH_NUMBER > 3", "F", "0", "T"},
                                                  {"MASTER.MONTH_NUMBER <= 3", "F", "1", "T"}};
                    strOrderBy = cmnService.J_SQLDBFormat(strOrderByMatrix, J_SQLColFormat.Case_End) + ", MASTER.SECTION_NO";
                    //-- 2020/11/28
                    if (rbnSort1_1.Checked == true) //-- PERIOD WISE
                    {
                        strOrderBy = cmnService.J_SQLDBFormat(strOrderByMatrix, J_SQLColFormat.Case_End) + ", MASTER.MONTH_NUMBER, MASTER.FORM_NO, MASTER.SECTION_NO"; //"MASTER.FA_YEAR,MASTER.FORM_NO,MASTER.SECTION_NO";
                    }
                    else if (rbnSort1_2.Checked == true) //-- FORM NO WISE
                    {
                        strOrderBy = "MASTER.FORM_NO," + cmnService.J_SQLDBFormat(strOrderByMatrix, J_SQLColFormat.Case_End) + ", MASTER.SECTION_NO";
                    }
                    else if (rbnSort1_3.Checked == true) //-- SECTION WISE
                    {
                        strOrderBy = "MASTER.SECTION_NO," + cmnService.J_SQLDBFormat(strOrderByMatrix, J_SQLColFormat.Case_End) + ", MASTER.FORM_NO";
                    }
                    // setting from to heading

                    strFromYear = cmbCombo2.Text.Substring(0, 4);
                    strToYear = cmbCombo2.Text.Substring(5, 2);
                    strToYear = "20" + strToYear;

                    strSummaryFilter = rbnSort1.Text;
                    objtxtValue.Text = "From : " + cmbCombo3.Text + " - " + strFromYear + " To : " + cmbCombo4.Text + " - " + strToYear;

                }
                // QUARTERLY
                else if (rbnSort2.Checked == true)
                {
                    //
                    if (cmbCombo3.Text == T_Qtr.Q1)
                        strQTR = "'" + T_Qtr.Q1 + "',";
                    if (cmbCombo3.Text == T_Qtr.Q2)
                        strQTR = "'" + T_Qtr.Q2 + "',";
                    if (cmbCombo3.Text == T_Qtr.Q3)
                        strQTR = "'" + T_Qtr.Q3 + "',";
                    if (cmbCombo3.Text == T_Qtr.Q4)
                        strQTR = "'" + T_Qtr.Q4 + "',";

                    if (cmbCombo4.Text == T_Qtr.Q1)
                        strQTR = "'" + T_Qtr.Q1 + "',";
                    else if (cmbCombo4.Text == T_Qtr.Q2)
                    {
                        if (cmbCombo3.Text == T_Qtr.Q1)
                            strQTR = strQTR + "'" + T_Qtr.Q2 + "',";
                        else if (cmbCombo3.Text == T_Qtr.Q2)
                            strQTR = "'" + T_Qtr.Q2 + "',";
                    }
                    else if (cmbCombo4.Text == T_Qtr.Q3)
                    {
                        if (cmbCombo3.Text == T_Qtr.Q1)
                            strQTR = "'" + T_Qtr.Q1 + "'," + "'" + T_Qtr.Q2 + "'," + "'" + T_Qtr.Q3 + "',";
                        else if (cmbCombo3.Text == T_Qtr.Q2)
                            strQTR = "'" + T_Qtr.Q2 + "'," + "'" + T_Qtr.Q3 + "',";
                        else if (cmbCombo3.Text == T_Qtr.Q3)
                            strQTR = "'" + T_Qtr.Q3 + "',";
                    }
                    else if (cmbCombo4.Text == T_Qtr.Q4)
                    {
                        if (cmbCombo3.Text == T_Qtr.Q1)
                            strQTR = "'" + T_Qtr.Q1 + "'," + "'" + T_Qtr.Q2 + "'," + "'" + T_Qtr.Q3 + "'," + "'" + T_Qtr.Q4 + "',";
                        else if (cmbCombo3.Text == T_Qtr.Q2)
                            strQTR = "'" + T_Qtr.Q2 + "'," + "'" + T_Qtr.Q3 + "'," + "'" + T_Qtr.Q4 + "',";
                        else if (cmbCombo3.Text == T_Qtr.Q3)
                            strQTR = "'" + T_Qtr.Q3 + "'," + "'" + T_Qtr.Q4 + "',";
                        else if (cmbCombo3.Text == T_Qtr.Q4)
                            strQTR = "'" + T_Qtr.Q4 + "',";
                    }
                    //
                    if (cmnService.J_Right(strQTR, 1) == ",")
                        strQTR = cmnService.J_Mid(strQTR, 0, (strQTR.Length - 1));

                    strWHERE = " AND TRN_BASIC_INFO.QTR IN (" + strQTR + ")";

                    strSELECT = "    MASTER.QTR AS PERIOD,";
                    strGROUP_BY = " ,TRN_BASIC_INFO.QTR ";
                    strGROUP_BY1 = " ,DEDUCTEE.QTR ";

                    strMonthFormat = " TRN_BASIC_INFO.QTR, ";
                    strJoiningClause = "  AND MASTER.QTR = DEDUCTEE_RECORDS.QTR ";

                    strSubQuerySelect = " TRN_BASIC_INFO.QTR,";
                    strSubQuerySelect1 = " DEDUCTEE.QTR,";
                    //strOrderBy = "MASTER.QTR,MASTER.FORM_NO,MASTER.SECTION_NO";
                    //-- 2020/11/28
                    if (rbnSort1_1.Checked == true) //-- PERIOD WISE
                    {
                        strOrderBy = "MASTER.QTR,MASTER.FORM_NO,MASTER.SECTION_NO";
                    }
                    else if (rbnSort1_2.Checked == true) //-- FORM NO WISE
                    {
                        strOrderBy = "MASTER.FORM_NO,MASTER.QTR,MASTER.SECTION_NO";
                    }
                    else if (rbnSort1_3.Checked == true) //-- SECTION WISE
                    {
                        strOrderBy = "MASTER.SECTION_NO,MASTER.QTR,MASTER.FORM_NO";
                    }

                    strSummaryFilter = rbnSort2.Text;
                    objtxtValue.Text = "From : Quarter " + cmnService.J_Right(cmbCombo3.Text, 1) + " To : Quarter " + cmnService.J_Right(cmbCombo4.Text, 1);

                }
                // ANNUALLY
                else if (rbnSort3.Checked == true)
                {
                    strSELECT = "  MASTER.FA_YEAR AS PERIOD,";

                    //strOrderBy = "MASTER.FA_YEAR,MASTER.FORM_NO,MASTER.SECTION_NO";
                    //-- 2020/11/28
                    if (rbnSort1_1.Checked == true) //-- PERIOD WISE
                    {
                        strOrderBy = "MASTER.FA_YEAR,MASTER.FORM_NO,MASTER.SECTION_NO";
                    }
                    else if (rbnSort1_2.Checked == true) //-- FORM NO WISE
                    {
                        strOrderBy = "MASTER.FORM_NO,MASTER.FA_YEAR,MASTER.SECTION_NO";
                    }
                    else if (rbnSort1_3.Checked == true) //-- SECTION WISE
                    {
                        strOrderBy = "MASTER.SECTION_NO,MASTER.FA_YEAR,MASTER.FORM_NO";
                    }
                    // FROM & TO PERIOD
                    objtxtValue.Text = "";
                    strSummaryFilter = rbnSort3.Text;
                }
                //------------------------------------------------------------------------
                strQueryString = "SELECT MASTER.COMPANY_ID, " +
                    "                    MASTER.COMPANY_NAME, " +
                    "                    MASTER.FA_YEAR," +
                    "                    MASTER.TAN_NO, " +
                    "                    MASTER.FORM_NO, " +
                    "                    MASTER.SECTION_NO, " +
                    "                    MASTER.PAYMENT_AMOUNT," +
                    "                    MASTER.TAX_AMOUNT," +
                    "                    MASTER.NO_OF_DEDUCTION,";
                strQueryString += strSELECT +
                    " DEDUCTEE_RECORDS.No_Of_Deductee_Record " +
                    "           FROM( SELECT MST_COMPANY.COMPANY_ID," +
                    "                        MST_COMPANY.COMPANY_Name," +
                    "                        MST_COMPANY.TAN_NO," +
                    "                        MST_ASSESSMENT.FA_YEAR," +
                    "                        TRN_BASIC_INFO.FORM_NO," +
                    "                        MST_SECTION.SECTION_NO,";
                strQueryString += strMonthFormat +
                    "                        SUM(TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT)       AS PAYMENT_AMOUNT," +
                    "                        SUM(TRN_DEDUCTEE_DETAILS.TAX_AMOUNT)           AS TAX_AMOUNT," +
                    "                        COUNT(TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID) AS NO_OF_DEDUCTION " +
                    "                 FROM MST_ASSESSMENT," +
                    "                      MST_COMPANY," +
                    "                      MST_SECTION," +
                    "                      TRN_BASIC_INFO," +
                    "                      TRN_CHALLAN," +
                    "                      TRN_DEDUCTEE_DETAILS " +
                    "                  WHERE MST_COMPANY.COMPANY_ID       = TRN_BASIC_INFO.COMPANY_ID " +
                    "                  AND   TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID " +
                    "                  AND   TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID " +
                    "                  AND   TRN_CHALLAN.CHALLAN_ID       = TRN_DEDUCTEE_DETAILS.CHALLAN_ID " +
                    //"                  AND   MST_SECTION.SECTION_ID       = TRN_CHALLAN.SECTION_ID " +
                    "                  AND   MST_SECTION.SECTION_ID       = TRN_DEDUCTEE_DETAILS.SECTION_ID " +
                    "                  AND   MST_COMPANY.COMPANY_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                    "                  AND   MST_ASSESSMENT.ASST_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " ";
                strQueryString += strWHERE +
                    "                  AND   TRN_BASIC_INFO.FORM_NO IN (" + strFormNo + ") " +
                    "                  GROUP BY  MST_COMPANY.COMPANY_ID," +
                    "                        MST_COMPANY.COMPANY_Name," +
                    "                        MST_COMPANY.TAN_NO," +
                    "                        MST_ASSESSMENT.FA_YEAR," +
                    "                        TRN_BASIC_INFO.FORM_NO," +
                    "                        MST_SECTION.SECTION_NO ";
                strQueryString += strGROUP_BY +
                    "                 ) AS MASTER " +
                    "                 INNER JOIN " +
                    "                 (SELECT COMPANY_ID, " +
                    "                          TAN_NO," +
                    "                          FA_YEAR," +
                    "                          FORM_NO," +
                    "                          SECTION_NO, " + strForMonthly; //-- 2016/03/28 ' MONTH_NUMBER,'
                strQueryString += strSubQuerySelect1 +
                    "                          COUNT(PARTY) AS No_Of_Deductee_Record " +
                    "                  FROM   (SELECT MST_COMPANY.COMPANY_ID," +
                    "                                 MST_COMPANY.TAN_NO," +
                    "                                 MST_ASSESSMENT.FA_YEAR," +
                    "                                 TRN_BASIC_INFO.FORM_NO," +
                    "                                 MST_SECTION.SECTION_NO,";
                strQueryString += strMonthFormat +
                    "                                 PARTY_ID," +
                    "                                 COUNT(PARTY_ID) AS PARTY " +
                    "                          FROM MST_ASSESSMENT," +
                    "                               MST_COMPANY," +
                    "                               MST_SECTION," +
                    "                               TRN_BASIC_INFO," +
                    "                               TRN_CHALLAN," +
                    "                               TRN_DEDUCTEE_DETAILS " +
                    "                          WHERE MST_COMPANY.COMPANY_ID       = TRN_BASIC_INFO.COMPANY_ID " +
                    "                          AND   TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID " +
                    "                          AND   TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID " +
                    "                          AND   TRN_CHALLAN.CHALLAN_ID       = TRN_DEDUCTEE_DETAILS.CHALLAN_ID " +
                    //"                          AND   MST_SECTION.SECTION_ID       = TRN_CHALLAN.SECTION_ID " +
                    "                          AND   MST_SECTION.SECTION_ID       = TRN_DEDUCTEE_DETAILS.SECTION_ID " +
                    "                          AND   MST_COMPANY.COMPANY_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                    "                          AND   MST_ASSESSMENT.ASST_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " ";
                strQueryString += strWHERE +
                    "                          AND   TRN_BASIC_INFO.FORM_NO    IN (" + strFormNo + ") " +
                    "                          GROUP BY  MST_COMPANY.COMPANY_ID," +
                    "                                    MST_COMPANY.TAN_NO," +
                    "                                    MST_ASSESSMENT.FA_YEAR," +
                    "                                    TRN_BASIC_INFO.FORM_NO," +
                    "                                    MST_SECTION.SECTION_NO ";
                strQueryString += strGROUP_BY +
                    "                                    ,PARTY_ID)  AS DEDUCTEE " +
                    "           GROUP BY TAN_NO," +
                    "                    FA_YEAR, " +
                    "                    FORM_NO," +
                    "                    SECTION_NO, " + strForMonthly; //-- 2016/03/28 ' MONTH_NUMBER,'
                strQueryString += strSubQuerySelect1 +
                    "                    COMPANY_ID)DEDUCTEE_RECORDS " +
                    "           ON  MASTER.COMPANY_ID = DEDUCTEE_RECORDS.COMPANY_ID " +
                    "           AND MASTER.TAN_NO     = DEDUCTEE_RECORDS.TAN_NO " +
                    "           AND MASTER.FA_YEAR    = DEDUCTEE_RECORDS.FA_YEAR " +
                    "           AND MASTER.FORM_NO    = DEDUCTEE_RECORDS.FORM_NO " +
                    "           AND MASTER.SECTION_NO = DEDUCTEE_RECORDS.SECTION_NO ";
                strQueryString += strJoiningClause + " ORDER BY " + strOrderBy;

                //call crystal report to display Report
                //---------------------------------------------------------------------------------
                string[,] strArry = { { "txtReportTitle", "Deductions - " + strSummaryFilter + " Summary" } };
                rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                //-----------------------------------------------------------------------------------
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }



        #endregion

