            //    "                       ON  CHALLAN.COMPANY_ID    = DEDUCTEE.COMPANY_ID" +
            //    "                       AND CHALLAN.BASIC_INFO_ID = DEDUCTEE.BASIC_INFO_ID" +
            //    "                       AND CHALLAN.FORM_NO       = DEDUCTEE.FORM_NO" +
            //    "                       AND CHALLAN.QTR = DEDUCTEE.QTR) AS TOTAL_DEDUCTEE" +
            //    "            ON  DEDUCTEE.COMPANY_ID    = TOTAL_DEDUCTEE.COMPANY_ID" +
            //    "            AND DEDUCTEE.BASIC_INFO_ID = TOTAL_DEDUCTEE.BASIC_INFO_ID" +
            //    "            AND DEDUCTEE.FORM_NO       = TOTAL_DEDUCTEE.FORM_NO" +
            //    "            AND DEDUCTEE.QTR           = TOTAL_DEDUCTEE.QTR";
            strQueryString = @"SELECT TRN_BASIC_INFO.BASIC_INFO_ID,
                                            TRN_BASIC_INFO.COMPANY_ID,
			                                MST_COMPANY.TAN_NO,
			                                MST_COMPANY.COMPANY_NAME,
			                                TRN_BASIC_INFO.ASST_ID,
			                                MST_ASSESSMENT.FA_YEAR,
			                                TRN_BASIC_INFO.QTR,
			                                TRN_BASIC_INFO.FORM_NO," +
                                            cmnService.J_SQLDBFormat("CHALLANS.TOTAL_CHALLANS", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + " AS TOTAL_CHALLANS," +
                                            cmnService.J_SQLDBFormat("CHALLANS.CHALLAN_TOT_TAX", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + " AS CHALLAN_TOT_TAX," +
                                            cmnService.J_SQLDBFormat("DEDUCTEES.TOTAL_DEDUCTEES", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + " AS TOTAL_DEDUCTEES," +
                                            cmnService.J_SQLDBFormat("UNIQUE_DEDUCTEES.TOTAL_UNIQUE_DEDUCTEES", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + @" AS TOTAL_UNIQUE_DEDUCTEES 
                                FROM((((( TRN_BASIC_INFO
                                INNER JOIN MST_COMPANY 
                                           ON MST_COMPANY.COMPANY_ID = TRN_BASIC_INFO.COMPANY_ID)
                                INNER JOIN MST_ASSESSMENT 
                                           ON MST_ASSESSMENT.ASST_ID = TRN_BASIC_INFO.ASST_ID)
                                LEFT JOIN (SELECT BASIC_INFO_ID,
                                                             COUNT(*) AS TOTAL_CHALLANS,
							                                 SUM(TOT_TAX) AS CHALLAN_TOT_TAX
				                                 FROM TRN_CHALLAN
				                                 GROUP BY BASIC_INFO_ID) AS CHALLANS
                                           ON CHALLANS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID)
                                LEFT JOIN (SELECT BASIC_INFO_ID,
                                                             COUNT(*) AS TOTAL_DEDUCTEES
				                                 FROM TRN_DEDUCTEE_DETAILS
				                                 GROUP BY BASIC_INFO_ID) AS DEDUCTEES
                                           ON DEDUCTEES.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID)
                                LEFT JOIN (SELECT BASIC_INFO_ID,
                                                             COUNT(*) AS TOTAL_UNIQUE_DEDUCTEES
                                                 FROM (SELECT BASIC_INFO_ID,
                                                                        PARTY_ID
                                                            FROM TRN_DEDUCTEE_DETAILS
                                                            GROUP BY BASIC_INFO_ID,
                                                                            PARTY_ID) AS SUMM
                                                  GROUP BY BASIC_INFO_ID ) AS UNIQUE_DEDUCTEES
                                          ON UNIQUE_DEDUCTEES.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID)
                                WHERE    TRN_BASIC_INFO.ASST_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " ";
            //SETTING SORTING ORDER 
            if (rbnSort1.Checked == true)
            {
                strOrderBy = "MST_COMPANY.COMPANY_NAME,TRN_BASIC_INFO.FORM_NO,TRN_BASIC_INFO.QTR";
            }
            else if (rbnSort2.Checked == true)
            {
                strOrderBy = "TRN_BASIC_INFO.FORM_NO,MST_COMPANY.COMPANY_NAME,TRN_BASIC_INFO.QTR";

            }
            else if (rbnSort3.Checked == true)
            {
                strOrderBy = "TRN_BASIC_INFO.QTR,MST_COMPANY.COMPANY_NAME,TRN_BASIC_INFO.FORM_NO";
            }

            strQueryString += " ORDER BY " + strOrderBy;

            crAllDeductionSummary rptQuarterWiseChallanReport = new crAllDeductionSummary();
            rptcls = (ReportClass)rptQuarterWiseChallanReport;
            // FORM SELECTED
            //TextObject objtxtValue;

            //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToDate"];
            //objtxtValue.Text = "From : " + TdsMan.T_ReturnQuarterStartDate(cmbCombo1.Text, cmbCombo2.Text) + " To : " + TdsMan.T_ReturnQuarterEndDate(cmbCombo4.Text, cmbCombo2.Text);

            string[,] strArry = { { "txtReportTitle", "All Deductors Summary" } };
            rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);


        }

