        #region PrintFileGenerationLog
        private void PrintFileGenerationLog()
        {
            //ADDED BY DHRUB ON 05/02/2014 
            SelectedGridItemsWithSearchData(cmnService.J_GenerateDataGridViewSelectedId(grdvDescription));
            string strOrderBy = "";
            //-- ANIK @ 2016/02/25
            string strFormNo = "";
            string strQtr = "";
            //--
            foreach (int indexChecked in clbListBox1.CheckedIndices)
            {
                strFormNo = strFormNo + "'" + clbListBox1.Items[indexChecked] + "',";
            }
            if (cmnService.J_Right(strFormNo, 1) == ",")
                strFormNo = cmnService.J_Mid(strFormNo, 0, (strFormNo.Length - 1));

            // QUARTER
            foreach (int indexChecked in clbListBox2.CheckedIndices)
            {
                strQtr = strQtr + "'" + clbListBox2.Items[indexChecked] + "',";
            }
            if (cmnService.J_Right(strQtr, 1) == ",")
                strQtr = cmnService.J_Mid(strQtr, 0, (strQtr.Length - 1));

            //--
            string[,] strStatusMatrix = {{"(TRN_FILE_GENERATION_LOG.AUTO_CSI_FILE_DOWNLOAD=0 AND TRN_FILE_GENERATION_LOG.VALIDATION_STATUS=1) ", "F", "OK-CNV", "T"},
                                         {"(TRN_FILE_GENERATION_LOG.AUTO_CSI_FILE_DOWNLOAD=1 AND TRN_FILE_GENERATION_LOG.VALIDATION_STATUS=1)", "F", "OK", "T"},
                                         {"(TRN_FILE_GENERATION_LOG.AUTO_CSI_FILE_DOWNLOAD=1 AND TRN_FILE_GENERATION_LOG.VALIDATION_STATUS=2)", "F", "OK-CM", "T"}};//,
            //{"JAYA", "T", "", "T"}};

            strQueryString = "SELECT MST_COMPANY.COMPANY_ID," +
                "                    TRN_FILE_GENERATION_LOG.FG_LOG_ID," +
                "                    MST_COMPANY.COMPANY_NAME," +
                "                   (TRN_BASIC_INFO.FORM_NO +'-' + TRN_BASIC_INFO.QTR) AS FORM_QTR," +
                "                    TRN_FILE_GENERATION_LOG.NO_OF_CHALLAN," +
                "                    TRN_FILE_GENERATION_LOG.NO_OF_DEDUCTEES, " +
                "                    TRN_FILE_GENERATION_LOG.INPUT_FILE_NAME," +
                "                    TRN_FILE_GENERATION_LOG.DATE_TIME_OF_CREATION," +
                "                    TRN_FILE_GENERATION_LOG.VALIDATION_STATUS," +
                "                    TRN_FILE_GENERATION_LOG.AUTO_CSI_FILE_DOWNLOAD," +
                "                  " + cmnService.J_SQLDBFormat(strStatusMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + " AS STATUS,";
            //
            if (TDSMAN.Classes.TDSMAN.T_PackageType == T_PACKAGE_TYPE.MULTI_USER)
                strQueryString = strQueryString + "TRN_FILE_GENERATION_LOG.MACHINE_NAME AS MACHINE_NAME ";
            else
                strQueryString = strQueryString + "'' AS MACHINE_NAME ";
            //
            strQueryString = strQueryString + "FROM   TRN_FILE_GENERATION_LOG," +
               "                    TRN_BASIC_INFO," +
               "                    MST_COMPANY" +
               "             WHERE TRN_FILE_GENERATION_LOG.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID " +
               "             AND   TRN_BASIC_INFO.COMPANY_ID             = MST_COMPANY.COMPANY_ID " +
               "             AND   MST_COMPANY.COMPANY_ID  IN (" + strSelectedGridItemsWithSearch + ") " +
               "             AND  (TRN_FILE_GENERATION_LOG.VALIDATION_STATUS <> 3 " +
               "             AND   TRN_FILE_GENERATION_LOG.VALIDATION_STATUS <> 0 ) " +
               "             AND   TRN_BASIC_INFO.ASST_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " + //-- ANIK @ 2016/02/25
               "             AND   TRN_BASIC_INFO.FORM_NO IN (" + strFormNo + ") " +
               "             AND   TRN_BASIC_INFO.QTR     IN (" + strQtr + ") ";

            if (cmbCombo2.SelectedIndex > 0)
                strQueryString = strQueryString + " AND TRN_FILE_GENERATION_LOG.MACHINE_NAME ='" + cmbCombo2.Text + "'";

            if (rbnSort1.Checked == true)
            {
                strOrderBy = "TRN_FILE_GENERATION_LOG.DATE_TIME_OF_CREATION DESC,MST_COMPANY.COMPANY_NAME,TRN_FILE_GENERATION_LOG.FG_LOG_ID DESC ";
            }
            else if (rbnSort2.Checked == true)
            {
                strOrderBy = " MST_COMPANY.COMPANY_NAME, TRN_FILE_GENERATION_LOG.DATE_TIME_OF_CREATION DESC,TRN_FILE_GENERATION_LOG.FG_LOG_ID DESC ";
            }
            strQueryString += " ORDER BY " + strOrderBy;

            crFileGenerationLog rptFileGenerationLog = new crFileGenerationLog();
            rptcls = (ReportClass)rptFileGenerationLog;
            // FORM SELECTED
            TextObject objtxtValue;
            objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFAYear"];
            objtxtValue.Text = cmbCombo1.Text;
            //
            string[,] strArry = { { "txtReportTitle", "File Generation Log" } };
            rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
            //---------------------------
            //ADDED BY DHRUB ON 07/02/2014 FOR RECORD REMAIN CHECKED INTO THE GRID AFTER SEARCH 
            dmlService.J_BeginTransaction();
            dmlService.J_ExecSql("DELETE FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED);
            dmlService.J_Commit();
            //--
        }

