                        "                     MST_COMPANY.ADDRESS2," +
                        "                     MST_COMPANY.ADDRESS3," +
                        "                     MST_COMPANY.ADDRESS4," +
                        "                     MST_COMPANY.ADDRESS5," +
                        "                     MST_STATE.STATE_NAME," +
                        "                     MST_COMPANY.PIN_CODE," +
                        "                     MST_COMPANY.PERSON_NAME," +
                        "                    " + cmnService.J_SQLDBFormat("MST_COMPANY.FATHER_NAME", J_ColumnType.String, J_SQLColFormat.NullCheck) + "     AS FATHER_NAME," +
                        "                    " + cmnService.J_SQLDBFormat("MST_COMPANY.DESIGNATION", J_ColumnType.String, J_SQLColFormat.NullCheck) + "     AS PERSON_DESIGNATION," +
                        "                     MST_EMPLOYEE.EMPLOYEE_ID," +
                        "                     MST_EMPLOYEE.EMPLOYEE_NAME," +
                        "                     MST_EMPLOYEE.EMPLOYEE_PAN," +
                        "                     MST_EMPLOYEE.EMPLOYEE_REF," +
                        "                    " + cmnService.J_SQLDBFormat("MST_EMPLOYEE.DESIGNATION", J_ColumnType.String, J_SQLColFormat.NullCheck) + "     AS DESIGNATION," +
                        "                     MST_COMPANY.CIT_TDS_ADDRESS," +
                        "                     MST_COMPANY.CIT_TDS_CITY," +
                        "                     MST_COMPANY.CIT_TDS_PINCODE," +
                        "                     MST_ASSESSMENT.ASST_YEAR," +
                        "                    " + cmnService.J_SQLDBFormat("TRN_SALARY_DETAILS.FROM_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatDDMMYYYY) + "  AS FROM_DATE," +
                        "                    " + cmnService.J_SQLDBFormat("TRN_SALARY_DETAILS.TO_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatDDMMYYYY) + "  AS TO_DATE," +
                        "                     TRN_SALARY_DETAILS.TOTAL_TDS_DEDUCTED," +
                        "                     TRN_SALARY_DETAILS.SALARY_DETAILS_ID," +
                        "                   '" + TDSMAN.Classes.TDSMAN.T_CERTIFICATE_TDSMAN_FOOTER_ENABLE_OPTION + "' AS CERTIFICATE_TDSMAN_FOOTER_ENABLE_OPTION," +
                        "                   '" + TDSMAN.Classes.TDSMAN.T_CERTIFICATE_SECOND_FOOTER_ENABLE_OPTION + "' AS CERTIFICATE_SECOND_FOOTER_ENABLE_OPTION," +
                        "                   '" + TDSMAN.Classes.TDSMAN.T_CERTIFICATE_SECOND_FOOTER_TEXT + "'          AS CERTIFICATE_SECOND_FOOTER_TEXT" +
                        "             FROM    MST_COMPANY," +
                        "                     MST_EMPLOYEE," +
                        "                     TRN_BASIC_INFO," +
                        "                     MST_STATE," +
                        "                     MST_ASSESSMENT," +
                        "                     TRN_SALARY_DETAILS" +
                        "             WHERE  TRN_BASIC_INFO.BASIC_INFO_ID = TRN_SALARY_DETAILS.BASIC_INFO_ID " +
                        "             AND    TRN_BASIC_INFO.COMPANY_ID = MST_COMPANY.COMPANY_ID" +
                        "             AND    TRN_BASIC_INFO.ASST_ID = MST_ASSESSMENT.ASST_ID" +
                        "             AND    MST_COMPANY.COMPANY_ID = MST_EMPLOYEE.COMPANY_ID" +
                        "             AND    MST_EMPLOYEE.EMPLOYEE_ID = TRN_SALARY_DETAILS.EMPLOYEE_ID" +
                        //"             AND    MST_EMPLOYEE.EMPLOYEE_ID IN (" + strSelectedGridItemsWithSearch + ") " +
                        "             AND    MST_EMPLOYEE.EMPLOYEE_PAN IN (" + strSelectedGridItemsWithSearch + ") " +
                        "             AND    MST_ASSESSMENT.ASST_ID  =  " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                        "             AND    TRN_BASIC_INFO.FORM_NO  ='" + T_FormNo.F24Q + "' " +
                        "             AND    MST_COMPANY.STATE_ID = MST_STATE.STATE_ID ) AS MASTER" +
                        "       LEFT JOIN" +
                        "            (SELECT TRN_DEDUCTEE_DETAILS.PARTY_ID                  AS EMPLOYEE_ID," +
                        "                    TRN_BASIC_INFO.ASST_ID                         AS ASST_ID ," +
                        "                    SUM(TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT)       AS PAYMENT_AMOUNT," +
                        "                    SUM(TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT)         AS TOTAL_AMOUNT," +
                        "                    SUM(TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT) AS TAX_DEPOSITED_AMOUNT" +
                        "             FROM   TRN_BASIC_INFO," +
                        "                    TRN_DEDUCTEE_DETAILS," +
                        "                    MST_EMPLOYEE " +
                        "             WHERE  TRN_BASIC_INFO.BASIC_INFO_ID     = TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID" +
                        "             AND    MST_EMPLOYEE.EMPLOYEE_ID         = TRN_DEDUCTEE_DETAILS.PARTY_ID " +
                        "             AND    TRN_BASIC_INFO.ASST_ID           =  " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                        "             AND    TRN_BASIC_INFO.COMPANY_ID        =  " + Convert.ToInt32(Support.GetItemData(cmbCombo2, cmbCombo2.SelectedIndex)) + " " +
                        //"             AND    TRN_DEDUCTEE_DETAILS.PARTY_ID IN (" + strSelectedGridItemsWithSearch + ") " +
                        "             AND    MST_EMPLOYEE.EMPLOYEE_PAN IN (" + strSelectedGridItemsWithSearch + ") " +
                        "             AND    TRN_BASIC_INFO.FORM_NO  ='" + T_FormNo.F24Q + "' " +
                        "             GROUP BY TRN_DEDUCTEE_DETAILS.PARTY_ID," +
                        "                      TRN_BASIC_INFO.ASST_ID ) AS DEDUCTEE" +
                        "       ON  MASTER.EMPLOYEE_ID = DEDUCTEE.EMPLOYEE_ID " +
                        "       AND MASTER.ASST_ID = DEDUCTEE.ASST_ID";// +
                    //"       ORDER BY MASTER.EMPLOYEE_NAME,MASTER.EMPLOYEE_ID";

