                        "                               SUM(TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT)         AS TOTAL_AMOUNT," +
                        "                               SUM(TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT) AS TAX_DEPOSITED_AMOUNT" +
