                            "             AND    MST_COMPANY.STATE_ID         = MST_STATE.STATE_ID ) AS MASTER " +
                            "       LEFT JOIN" +
                            "            (SELECT TRN_DEDUCTEE_DETAILS.PARTY_ID                  AS EMPLOYEE_ID," +
