                    strSQL = "SELECT COUNT(TRN_CHALLAN.CHALLAN_ID) AS COUNT_CHALLAN_ID " +
                        "     FROM   TRN_CHALLAN," +
                        "            TRN_BASIC_INFO " +
                        "     WHERE  TRN_CHALLAN.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID " +
