                    else if (rbnSort1_2.Checked == true)
                        strQueryString = strQueryString + " ORDER BY MST_EMPLOYEE.EMPLOYEE_PAN, TRN_SALARY_DETAILS.SALARY_DETAILS_ID";
                    else if (rbnSort1_3.Checked == true)
                        strQueryString = strQueryString + " ORDER BY TRN_SALARY_DETAILS.SALARY_DETAILS_ID";



                    //crSalaryDetails rptSalaryDetails = new crSalaryDetails();
                    //rptcls = (ReportClass)rptSalaryDetails;
                    //// FORM SELECTED
                    //TextObject objtxtValue;

                    //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFAYear"];
                    //objtxtValue.Text = cmbCombo2.Text;

                    //string[,] strArry = { { "txtReportTitle", "Form No. " + cmbCombo3.Text + " - Salary Details" } };
                    //rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                    if (TDSMAN.Classes.TDSMAN.T_EXPORT_REPORTS_CSV == true)
                    {
                        //
                        string strCSVPath = "", strCSVFileName = "QuarterWiseSD_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".csv";
                        // Create a new instance of FolderBrowserDialog.
                        FolderBrowserDialog folderBrowserDlg = new FolderBrowserDialog();
                        // A new folder button will display in FolderBrowserDialog.
                        folderBrowserDlg.ShowNewFolderButton = true;
                        //Show FolderBrowserDialog
                        DialogResult dlgResult = folderBrowserDlg.ShowDialog();
                        if (dlgResult.Equals(DialogResult.OK))
                        {
                            //Show selected folder path in textbox1.
                            strCSVPath = folderBrowserDlg.SelectedPath;
                            //Browsing start from root folder.
                            Environment.SpecialFolder rootFolder = folderBrowserDlg.RootFolder;
                        }
                        //
                        //string fullPath = Path.Combine(strCSVPath, strfolderName);
                        //// Create the directory
                        //Directory.CreateDirectory(fullPath);
                        //
                        if (strCSVPath != "")
                        {
                            ExportToCSV(strQueryString, Path.Combine(strCSVPath, strCSVFileName));
                            //
                            cmnService.J_UserMessage("Export completed");
                            //
                            System.Diagnostics.Process.Start(Path.Combine(strCSVPath, strCSVFileName));
                        }
                    }
                    else
                    {
                        string[,] strArrySalaryDetailsReport = { {"HeaderCompanyName", cmbCombo1.Text },
                                              {"HeaderTANFaYear", "TAN : " + cmnService.J_Left(cmnService.J_Right(cmbCombo1.Text,11),10) + " FA Year : " + cmbCombo2.Text },
                                              {"HeaderReportCD", "Form No. " + cmbCombo3.Text + " - Salary Details" }
                                                };
                        //
                        J_PreviewReportRDLC("\\Reports\\crSalaryDetails.rdlc", "DataSet1", strQueryString, strArrySalaryDetailsReport);
                    }
                    #endregion
                }
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
