                    "                    COR_TRN_DEDUCTEE_DETAILS.CERTIFICATE_NO         AS CERTIFICATE_NO," +
                    "                    COR_TRN_DEDUCTEE_DETAILS.EMAIL                AS EMAIL," +
                    "                    COR_TRN_DEDUCTEE_DETAILS.MOBILE_NO            AS MOBILE_NO," +
                    "                    COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_ADDRESS     AS DEDUCTEE_ADDRESS," +
                    "                    COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_TAX_ID      AS DEDUCTEE_TAX_ID, " +
                    "                    MST_REMITTANCE.REMITTANCE_DESC                AS REMITTANCE_DESC," +
                    "                    MST_COUNTRY.COUNTRY_DESC                      AS COUNTRY_DESC " +
                    "             FROM   (((((((COR_TRN_CHALLAN INNER JOIN COR_HDR_BATCH " +
                    "                    ON COR_TRN_CHALLAN.BATCH_HEADER_ID = COR_HDR_BATCH.BATCH_HEADER_ID) " +
                    "                    INNER JOIN COR_TRN_DEDUCTEE_DETAILS " +
                    "                    ON COR_TRN_CHALLAN.TRN_CHALLAN_ID  = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID) " +
                    "                    INNER JOIN COR_TRN_COMPANY " +
                    "                    ON COR_TRN_COMPANY.BATCH_HEADER_ID = COR_TRN_CHALLAN.BATCH_HEADER_ID) " +
                    "                    LEFT JOIN MST_SECTION " +
                    "                    ON COR_TRN_CHALLAN.SECTION_ID      = MST_SECTION.SECTION_ID) " +
                    "                    LEFT JOIN MST_REASON " +
                    "                    ON COR_TRN_DEDUCTEE_DETAILS.REASON_ID      = MST_REASON.REASON_ID) " +
                    "                    LEFT JOIN MST_REMITTANCE " +
                    "                    ON COR_TRN_DEDUCTEE_DETAILS.REMITTANCE_ID = MST_REMITTANCE.REMITTANCE_ID) " +
                    "                    LEFT JOIN MST_COUNTRY " +
                    "                    ON COR_TRN_DEDUCTEE_DETAILS.COUNTRY_ID = MST_COUNTRY.COUNTRY_ID) " +
                    "             WHERE  COR_TRN_COMPANY.BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " " +
                    "             AND   (COR_TRN_DEDUCTEE_DETAILS.MODE   <> '' " +
                    "                    OR COR_TRN_DEDUCTEE_DETAILS.PAN_UPDATION_INDICATOR = 1) " +
                    //"             FROM   COR_TRN_CHALLAN," +
                    //"                    COR_TRN_DEDUCTEE_DETAILS," +
                    //"                    COR_TRN_COMPANY," +
                    //"                    MST_SECTION, " +
                    //"                    COR_HDR_BATCH " +
                    //"             WHERE  COR_TRN_COMPANY.BATCH_HEADER_ID = COR_TRN_CHALLAN.BATCH_HEADER_ID " +
                    //"             AND    COR_TRN_CHALLAN.TRN_CHALLAN_ID  = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID " +
                    //"             AND    COR_TRN_CHALLAN.SECTION_ID      = MST_SECTION.SECTION_ID " +
                    //"             AND    COR_TRN_COMPANY.BATCH_HEADER_ID = COR_HDR_BATCH.BATCH_HEADER_ID " +
                    //"             AND    COR_TRN_COMPANY.BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " " +
                    //"             AND   (COR_TRN_DEDUCTEE_DETAILS.MODE   <> '' " +
                    //"                    OR COR_TRN_DEDUCTEE_DETAILS.PAN_UPDATION_INDICATOR = 1) " +
                    "             ORDER BY COR_TRN_DEDUCTEE_DETAILS.TRN_DEDUCTEE_DETAIL_ID";



