                //    "                            OR     COR_TRN_SALARY_DETAILS.PAN_UPDATION_INDICATOR = 1) " +
                //    "                            ORDER BY COR_TRN_SALARY_DETAILS.TRN_SALARY_DETAILS_ID";


                if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strCountChallanDetails))) > 0)
                    rptcls.OpenSubreport("crSubRptChallanDetails").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSubRptChallanDetails).Tables[0]);

                if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strCountDeducteeDetails))) > 0)
