                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[3].ReportObjects["txtFAYearPH"];
                objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));

                string[,] strArry = { { "txtReportTitle","Form No. " + TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription, 3) + " - Correction Statement" } };
                rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);

