                    "                  " + cmnService.J_SQLDBFormat(strChallanMode, J_SQLColFormat.Case_End) + " AS CHALLAN_MODE," +
                    "                    COR_TRN_CHALLAN.CHALLAN_UPDATION_INDICATOR    AS CHALLAN_UPDATION_INDICATOR," +
                    "                    MST_SECTION.SECTION_ID                        AS SECTION_ID," +
                    "                    MST_SECTION.SECTION_NO                        AS SECTION_NO," +
                    "                    MST_SECTION.SECTION_DESCRIPTION               AS SECTION_DESCRIPTION," +
                    "                    COR_TRN_CHALLAN.BSR_CODE                      AS BSR_CODE," +
                    "                  " + cmnService.J_SQLDBFormat(strChallanNoMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_NO," +
                    "                    COR_TRN_CHALLAN.CHEQUE_NO                     AS CHEQUE_NO," +
                    "                    COR_TRN_CHALLAN.TDS                           AS TDS," +
                    "                    COR_TRN_CHALLAN.SURCHARGE                     AS SURCHARGE," +
                    "                    COR_TRN_CHALLAN.EDUCATION_CESS                AS EDUCATION_CESS," +
                    "                    COR_TRN_CHALLAN.OTHERS                        AS OTHERS," +
                    "                    COR_TRN_CHALLAN.INTEREST                      AS INTEREST," +
                    "                    COR_TRN_CHALLAN.TOT_TAX                       AS TOT_TAX," +
                    "                  " + cmnService.J_SQLDBFormat(strNILBkEntryMatrix, J_SQLColFormat.Case_End) + " AS REMARKS," +
                    "                    COR_TRN_CHALLAN.INTEREST_ALLOCATED            AS INTEREST_ALLOCATED," +
                    "                    COR_TRN_CHALLAN.OTHERS_ALLOCATED              AS OTHERS_ALLOCATED " +
                "             FROM   (((COR_TRN_CHALLAN LEFT JOIN MST_SECTION " +
                "                    ON COR_TRN_CHALLAN.SECTION_ID   = MST_SECTION.SECTION_ID) " +
                "                    INNER JOIN COR_HDR_BATCH " +
                "                    ON COR_HDR_BATCH.BATCH_HEADER_ID = COR_TRN_CHALLAN.BATCH_HEADER_ID) " +
                "                    INNER JOIN COR_TRN_COMPANY " +
                "                    ON COR_HDR_BATCH.BATCH_HEADER_ID = COR_TRN_COMPANY.BATCH_HEADER_ID) " +
                "             WHERE  COR_HDR_BATCH.BATCH_HEADER_ID             = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " " +
                "             AND    (COR_TRN_CHALLAN.CHALLAN_UPDATION_INDICATOR = 1 " +
                "             OR     COR_TRN_CHALLAN.MODE                      = '" + T_CorrectionMode.C9 + "') " +
                    "             ORDER BY COR_TRN_CHALLAN.TRN_CHALLAN_ID";


                //
                string[,] strChallanNoDeducteeDetailsMatrix = {{"COR_TRN_CHALLAN.CHALLAN_NO = ''", "F", "COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO", "F"},
                                                {"COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO = ''", "F", "COR_TRN_CHALLAN.CHALLAN_NO", "F"}};

                string[,] strChallanNoTextDeducteeDetailsMatrix = {{"COR_TRN_CHALLAN.BOOK_ENTRY = 1 ", "F", "TRANSFER_VOUCHER_NO", "T"},
                                                 {"COR_TRN_CHALLAN.BOOK_ENTRY = 0 ", "F", "CHALLAN_NO", "T"}};

                string[,] strDeducteeMode = {{"COR_TRN_DEDUCTEE_DETAILS.MODE ='" + T_CorrectionMode.Modify + "'" , "F", "Update", "T"},
                                            {"COR_TRN_DEDUCTEE_DETAILS.MODE ='" + T_CorrectionMode.Delete + "'" , "F", "Delete", "T"},
                                            {"COR_TRN_DEDUCTEE_DETAILS.MODE ='" + T_CorrectionMode.Add + "'" , "F", "Add", "T"},
                                            {"COR_TRN_DEDUCTEE_DETAILS.MODE ='" + T_CorrectionMode.C9Mode + "'" , "F", "Add", "T"},
                                            {"COR_TRN_DEDUCTEE_DETAILS.PAN_UPDATION_INDICATOR = 1 ", "F", "Update", "T"},
                                            {"COR_TRN_DEDUCTEE_DETAILS.MODE = '' AND COR_TRN_DEDUCTEE_DETAILS.PAN_UPDATION_INDICATOR = 0 ", "T", "", "T"}};

                string[,] strCashBookMatrix = {{"COR_TRN_DEDUCTEE_DETAILS.CASH_BOOK_ENTRY = 1", "F", "Yes", "T"},
                                            {"COR_TRN_DEDUCTEE_DETAILS.CASH_BOOK_ENTRY    = 0", "F", "No", "T"}};

                string strSubRptDeducteeDetails = "SELECT COR_TRN_COMPANY.TRN_COMPANY_ID AS COMPANY_ID," +
                    "                    COR_TRN_COMPANY.COMPANY_NAME                    AS COMPANY_NAME," +
                    "                    COR_TRN_COMPANY.TAN_NO                          AS TAN_NO," +
                    "                    COR_TRN_CHALLAN.TRN_CHALLAN_ID                  AS CHALLAN_ID," +
