        #region UpdateTotalCorrection
        private void UpdateTotalCorrection()
        {
            string[,] strTotalCorrection;
            IDataReader drdTotalCorrection = null;
            long lngBatchHeaderCount = 0;
            //-----------------------------------------------------------
            //strSQL = "SELECT COUNT(BATCH_HEADER_ID) AS COUNT_BATCH_HEADER_ID FROM COR_HDR_BATCH";
            //lngBatchHeaderCount = Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL));
            lngBatchHeaderCount = 10;
            strTotalCorrection = new string[lngBatchHeaderCount, 1];
            //
            strSQL = "SELECT TOP 10 BATCH_HEADER_ID FROM COR_HDR_BATCH ORDER BY BATCH_HEADER_ID DESC";
            drdTotalCorrection = dmlService.J_ExecSqlReturnReader(strSQL);
            if (drdTotalCorrection == null)
            {
                return;
            }
            long lngArrayCounter = 0;
            while (drdTotalCorrection.Read())
            {
                strTotalCorrection[lngArrayCounter, 0] = drdTotalCorrection["BATCH_HEADER_ID"].ToString();
                lngArrayCounter++;

            }
            drdTotalCorrection.Close();

            if (lngArrayCounter > 0)
            {
                long lngBATCH_UPDATION_INDICATOR = 0;
                long lngCHALLAN_UPDATION_INDICATOR = 0;
                long lngDeducteeUpdates = 0;
                long lngPANUpdates = 0;
                long lngNewChallanAdded = 0;
                long lngNewDeducteeAdded = 0;
                //
                long lngSDPANUpdates = 0;
                long lngSDUpdates = 0;
                //-------------------------------------------------------------------------
                for (long lngCounter = 0; lngCounter <= lngArrayCounter - 1; lngCounter++)
                {
                    lngBATCH_UPDATION_INDICATOR = 0;
                    lngCHALLAN_UPDATION_INDICATOR = 0;
                    lngDeducteeUpdates = 0;
                    lngPANUpdates = 0;
                    lngNewChallanAdded = 0;
                    lngNewDeducteeAdded = 0;
                    //
                    lngSDPANUpdates = 0;
                    lngSDUpdates = 0;
                    //

                    //
                    lngBATCH_UPDATION_INDICATOR = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT BATCH_UPDATION_INDICATOR FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID = " + cmnService.J_ReturnInt32Value(strTotalCorrection[lngCounter, 0]))));
                    lngCHALLAN_UPDATION_INDICATOR = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(CHALLAN_UPDATION_INDICATOR) FROM COR_TRN_CHALLAN WHERE CHALLAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + cmnService.J_ReturnInt32Value(strTotalCorrection[lngCounter, 0]))));
                    lngDeducteeUpdates = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE IN ('" + T_CorrectionMode.Modify + "','" + T_CorrectionMode.Delete + "','" + T_CorrectionMode.Add + "') AND BATCH_HEADER_ID = " + cmnService.J_ReturnInt32Value(strTotalCorrection[lngCounter, 0]))));
                    lngPANUpdates = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE PAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + cmnService.J_ReturnInt32Value(strTotalCorrection[lngCounter, 0]))));
                    lngNewChallanAdded = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_CHALLAN_ID) FROM COR_TRN_CHALLAN WHERE HDR_CHALLAN_ID =0 AND BATCH_HEADER_ID = " + cmnService.J_ReturnInt32Value(strTotalCorrection[lngCounter, 0]))));
                    lngNewDeducteeAdded = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE = '" + T_CorrectionMode.C9Mode + "'  AND BATCH_HEADER_ID = " + cmnService.J_ReturnInt32Value(strTotalCorrection[lngCounter, 0]))));
                    lngSDPANUpdates = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_SALARY_DETAILS_ID) FROM COR_TRN_SALARY_DETAILS WHERE PAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + cmnService.J_ReturnInt32Value(strTotalCorrection[lngCounter, 0]))));
                    lngSDUpdates = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_SALARY_DETAILS_ID) FROM COR_TRN_SALARY_DETAILS WHERE MODE <> '' AND BATCH_HEADER_ID = " + cmnService.J_ReturnInt32Value(strTotalCorrection[lngCounter, 0]))));
                    //
                    strSQL = "UPDATE COR_HDR_BATCH SET  " +
                        "            TOTAL_CORRECTION = " + (lngBATCH_UPDATION_INDICATOR + lngCHALLAN_UPDATION_INDICATOR + lngDeducteeUpdates + lngPANUpdates + lngNewChallanAdded + lngNewDeducteeAdded + lngSDPANUpdates + lngSDUpdates) + " " +
                        "     WHERE  BATCH_HEADER_ID  = " + cmnService.J_ReturnInt32Value(strTotalCorrection[lngCounter, 0]);
                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        return;
                    }
                }
            }
            //-----------------------------------------------------------
        }
        #endregion

        #region UpdateTotalCorrectionBatchWise
        private bool UpdateTotalCorrectionBatchWise(long BatchHeaderID)
        {
            try
            {                
                long lngBATCH_UPDATION_INDICATOR = 0;
                long lngCHALLAN_UPDATION_INDICATOR = 0;
                long lngDeducteeUpdates = 0;
                long lngPANUpdates = 0;
                long lngNewChallanAdded = 0;
                long lngNewDeducteeAdded = 0;
                //
                long lngSDPANUpdates = 0;
                long lngSDUpdates = 0;
                //-------------------------------------------------------------------------                
                lngBATCH_UPDATION_INDICATOR = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT BATCH_UPDATION_INDICATOR FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID = " + BatchHeaderID)));
                lngCHALLAN_UPDATION_INDICATOR = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(CHALLAN_UPDATION_INDICATOR) FROM COR_TRN_CHALLAN WHERE CHALLAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + BatchHeaderID)));
                lngDeducteeUpdates = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE IN ('" + T_CorrectionMode.Modify + "','" + T_CorrectionMode.Delete + "','" + T_CorrectionMode.Add + "') AND BATCH_HEADER_ID = " + BatchHeaderID)));
                lngPANUpdates = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE PAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + BatchHeaderID)));
                lngNewChallanAdded = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_CHALLAN_ID) FROM COR_TRN_CHALLAN WHERE HDR_CHALLAN_ID =0 AND BATCH_HEADER_ID = " + BatchHeaderID)));
                lngNewDeducteeAdded = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE = '" + T_CorrectionMode.C9Mode + "'  AND BATCH_HEADER_ID = " + BatchHeaderID)));
                lngSDPANUpdates = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_SALARY_DETAILS_ID) FROM COR_TRN_SALARY_DETAILS WHERE PAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + BatchHeaderID)));
                lngSDUpdates = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_SALARY_DETAILS_ID) FROM COR_TRN_SALARY_DETAILS WHERE MODE <> '' AND BATCH_HEADER_ID = " + BatchHeaderID)));
                //
                strSQL = "UPDATE COR_HDR_BATCH SET  " +
                    "            TOTAL_CORRECTION = " + (lngBATCH_UPDATION_INDICATOR + lngCHALLAN_UPDATION_INDICATOR + lngDeducteeUpdates + lngPANUpdates + lngNewChallanAdded + lngNewDeducteeAdded + lngSDPANUpdates + lngSDUpdates) + " " +
                    "     WHERE  BATCH_HEADER_ID  = " + BatchHeaderID;
                if (dmlService.J_ExecSql(strSQL) == false)
                    return false;
                //
                if( cmnService.J_ReturnInt64Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT TOTAL_CORRECTION FROM COR_HDR_BATCH WHERE BATCH_HEADER_ID  = " + BatchHeaderID))) > 0)
                    return true;
                else
                    return false;
            }
            catch
            {
                return false;
            }
            //-----------------------------------------------------------
        }
        #endregion

        #region PrintCorrectionLog
