                        string[,] strChallanNoDeducteeDetailsMatrix = {{"COR_TRN_CHALLAN.CHALLAN_NO = ''", "F", "COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO", "F"},
                                                {"COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO = ''", "F", "COR_TRN_CHALLAN.CHALLAN_NO", "F"}};

                        string[,] strChallanNoTextDeducteeDetailsMatrix = {{"COR_TRN_CHALLAN.BOOK_ENTRY = 1 ", "F", "TRANSFER_VOUCHER_NO", "T"},
                                                 {"COR_TRN_CHALLAN.BOOK_ENTRY = 0 ", "F", "CHALLAN_NO", "T"}};

                        string[,] strDeducteeMode = {{"COR_TRN_DEDUCTEE_DETAILS.MODE ='" + T_CorrectionMode.Modify + "'" , "F", "Update", "T"},
                                            {"COR_TRN_DEDUCTEE_DETAILS.MODE ='" + T_CorrectionMode.Delete + "'" , "F", "Delete", "T"},
                                            {"COR_TRN_DEDUCTEE_DETAILS.MODE ='" + T_CorrectionMode.Add + "'" , "F", "Add", "T"},
                                            {"COR_TRN_DEDUCTEE_DETAILS.MODE ='" + T_CorrectionMode.C9Mode + "'" , "F", "Add", "T"},
                                            {"COR_TRN_DEDUCTEE_DETAILS.PAN_UPDATION_INDICATOR = 1 ", "F", "Update", "T"}};//,
                                            //{"JAYA", "T", "", "T"}};

                        string strSubRptDeducteeDetails = "SELECT COR_TRN_COMPANY.TRN_COMPANY_ID AS COMPANY_ID," +
                            "                    COR_TRN_COMPANY.COMPANY_NAME                    AS COMPANY_NAME," +
                            "                    COR_TRN_COMPANY.TAN_NO                          AS TAN_NO," +
                            "                    COR_TRN_CHALLAN.TRN_CHALLAN_ID                  AS CHALLAN_ID," +
                            "                   " + cmnService.J_SQLDBFormat(strChallanNoDeducteeDetailsMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_NO," +
                            "                   " + cmnService.J_SQLDBFormat(strChallanNoTextDeducteeDetailsMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_NO_TEXT," +
                            "                    COR_TRN_CHALLAN.BSR_CODE                        AS BSR_CODE," +
                            "                    COR_TRN_DEDUCTEE_DETAILS.SL_NO                  AS DEDUCTEE_SL_NO," +
                            "                  " + cmnService.J_SQLDBFormat(strDeducteeMode, J_SQLColFormat.Case_End) + " AS MODE," +
                            "                  " + cmnService.J_SQLDBFormat("COR_TRN_CHALLAN.DEPOSIT_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatDDMMYYYY) + "  AS DEPOSIT_DATE," +
                            "                    COR_TRN_DEDUCTEE_DETAILS.TRN_DEDUCTEE_DETAIL_ID AS TRN_DEDUCTEE_DETAIL_ID," +
                            "                    COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME          AS DEDUCTEE_NAME," +
                            "                    COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN           AS DEDUCTEE_PAN," +
                            "                  " + cmnService.J_SQLDBFormat("COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatDDMMYYYY) + "  AS DEDUCTED_DATE," +
                            "                    MST_SECTION.SECTION_NO                          AS SECTION_NO," +
                            "                    COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT         AS PAYMENT_AMOUNT," +
                            "                    COR_TRN_DEDUCTEE_DETAILS.RATE                   AS RATE," +
                            "                    COR_TRN_DEDUCTEE_DETAILS.TAX_AMOUNT             AS TAX_AMOUNT," +
                            "                    COR_TRN_DEDUCTEE_DETAILS.SURCHARGE_AMOUNT       AS SURCHARGE_AMOUNT," +
                            "                    COR_TRN_DEDUCTEE_DETAILS.CESS_AMOUNT            AS CESS_AMOUNT," +
                            "                    COR_TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT           AS TOTAL_AMOUNT," +
                            "                    COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT   AS TAX_DEPOSITED_AMOUNT," +
                            //"                    COR_TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG     AS NON_DEDUCTION_FLAG," +
                            "                    MST_REASON.REASON                               AS NON_DEDUCTION_FLAG," +
                            "                    COR_TRN_DEDUCTEE_DETAILS.PAN_UPDATION_INDICATOR AS PAN_UPDATION_INDICATOR " +
                            "             FROM   ((((COR_TRN_CHALLAN INNER JOIN COR_TRN_DEDUCTEE_DETAILS " +
                            "                    ON COR_TRN_CHALLAN.TRN_CHALLAN_ID  = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID) " +
                            "                    INNER JOIN COR_TRN_COMPANY " +
                            "                    ON COR_TRN_COMPANY.BATCH_HEADER_ID = COR_TRN_CHALLAN.BATCH_HEADER_ID) " +
                            "                    LEFT JOIN MST_SECTION " +
                            "                    ON COR_TRN_CHALLAN.SECTION_ID      = MST_SECTION.SECTION_ID) " +
                            "                    LEFT JOIN MST_REASON " +
                            "                    ON COR_TRN_DEDUCTEE_DETAILS.REASON_ID      = MST_REASON.REASON_ID) " +
                            "             WHERE  COR_TRN_COMPANY.BATCH_HEADER_ID= " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " " +
                            "             AND    COR_TRN_DEDUCTEE_DETAILS.MODE IN ('" + T_CorrectionMode.Add + "','" + T_CorrectionMode.Delete + "','" + T_CorrectionMode.C9Mode + "')" +
                            //"             FROM   COR_TRN_CHALLAN," +
                            //"                    COR_TRN_DEDUCTEE_DETAILS," +
                            //"                    COR_TRN_COMPANY," +
                            //"                    MST_SECTION " +
                            //"             WHERE  COR_TRN_COMPANY.BATCH_HEADER_ID = COR_TRN_CHALLAN.BATCH_HEADER_ID " +
                            //"             AND    COR_TRN_CHALLAN.TRN_CHALLAN_ID = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID " +
                            //"             AND    COR_TRN_CHALLAN.SECTION_ID     = MST_SECTION.SECTION_ID " +
                            //"             AND    COR_TRN_COMPANY.BATCH_HEADER_ID= " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " " +
                            //"             AND    COR_TRN_DEDUCTEE_DETAILS.MODE IN ('" + T_CorrectionMode.Add + "','" + T_CorrectionMode.Delete + "','" + T_CorrectionMode.C9Mode + "')" +
                            "             ORDER BY COR_TRN_DEDUCTEE_DETAILS.TRN_DEDUCTEE_DETAIL_ID";

                        rptcls.OpenSubreport("crSubRptDeducteeDetails").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSubRptDeducteeDetails).Tables[0]);

                    }
                    #endregion

                #region SALARY DETAILS
                if (lngSDPANUpdates > 0 || lngSDUpdates > 0)
                {
                    //Added by Shrey on 10/08/2011 to modify tax aggregate field
                    strSQL = "UPDATE COR_TRN_SALARY_DETAILS " +
                        "     SET TAX_PAYABLE_AGGREGATE = TAX_TOTAL_INCOME + SCHG_TOTAL_INCOME + ECESS_TOTAL_INCOME";
                    dmlService.J_ExecSql(strSQL);
                    //-- ANIK @ 2019/10/17
                    strSQL = "UPDATE COR_TRN_SALARY_DETAILS " +
                        "     SET    TS_GS_TOTAL      = TS_GS_SEC_17_1 + TS_GS_SEC_17_2 + TS_GS_SEC_17_3 " +
                        "     WHERE  BATCH_HEADER_ID  = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription);
                    dmlService.J_ExecSql(strSQL);

                    //----------Query ADDED BY SHREY For Salary Details(18/03/2011)-----------------------------------

                    string[,] strCatyegoryMatrix = {{"COR_TRN_SALARY_DETAILS.EMPLOYEE_CATEGORY = 'G'", "F", T_EmployeeCategory.General, "T"},
                                            {"COR_TRN_SALARY_DETAILS.EMPLOYEE_CATEGORY = 'W'", "F", T_EmployeeCategory.Woman, "T"},
                                            {"COR_TRN_SALARY_DETAILS.EMPLOYEE_CATEGORY = 'S'", "F", T_EmployeeCategory.SeniorCitizen, "T"},
                                            {"COR_TRN_SALARY_DETAILS.EMPLOYEE_CATEGORY = 'O'", "F", T_EmployeeCategory.SuperSeniorCitizen, "T"}};

                    string[,] strSalaryDetailMode = {{"COR_TRN_SALARY_DETAILS.MODE ='" + T_CorrectionMode.Delete + "'" , "F", "Delete", "T"},
                                                {"COR_TRN_SALARY_DETAILS.MODE ='" + T_CorrectionMode.Add + "'" , "F", "Add", "T"},
                                                {"COR_TRN_SALARY_DETAILS.PAN_UPDATION_INDICATOR = 1 ", "F", "PAN Update", "T"}};//,
                                                //{"JAYA", "T", "", "T"}};

                    //## ANIK 2013/04/26
                    string[,] str80CCMatrix = {{"COR_HDR_BATCH.ASST_ID >= " + T_FinancialYearID.F2012_13ID, "F", "COR_TRN_SALARY_DETAILS.CVIA_SEC80CCG_DED_AMOUNT", "F"},
                                            {"COR_HDR_BATCH.ASST_ID >= " + T_FinancialYearID.F2010_11ID + " AND COR_HDR_BATCH.ASST_ID <= " + T_FinancialYearID.F2011_12ID, "F", "COR_TRN_SALARY_DETAILS.CVIA_SEC80CCF_DED_AMOUNT", "F"}};
                    //--
                    string[,] str80CCTextMatrix = {{"COR_HDR_BATCH.ASST_ID >= " + T_FinancialYearID.F2012_13ID, "F", "Deductions U/s 80CCG :", "T"},
                                            {"COR_HDR_BATCH.ASST_ID < " + T_FinancialYearID.F2012_13ID, "F", "Deductions U/s 80CCF :", "T"}};
                    //##
                    string strSubRptSalaryDetails = "SELECT COR_TRN_SALARY_DETAILS.TRN_SALARY_DETAILS_ID          AS TRN_SALARY_DETAILS_ID," +
                        "                                   " + cmnService.J_SQLDBFormat(strSalaryDetailMode, J_SQLColFormat.Case_End) + " AS MODE," +
                        "                                   COR_TRN_SALARY_DETAILS.SL_NO                          AS SL_NO," +
                        "                                   COR_TRN_SALARY_DETAILS.EMPLOYEE_NAME                  AS EMPLOYEE_NAME," +
                        "                                   COR_TRN_SALARY_DETAILS.EMPLOYEE_PAN                   AS EMPLOYEE_PAN," +
                        "                           " + cmnService.J_SQLDBFormat(strCatyegoryMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + " AS CATEGORY," +
                        "                           " + cmnService.J_SQLDBFormat("COR_TRN_SALARY_DETAILS.FROM_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatDDMMYYYY) + "  AS FROM_DATE," +
                        "                           " + cmnService.J_SQLDBFormat("COR_TRN_SALARY_DETAILS.TO_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatDDMMYYYY) + "  AS TO_DATE," +
                        "                                   COR_TRN_SALARY_DETAILS.TS_BALANCE                     AS TS_BALANCE," +
                        "                                   COR_TRN_SALARY_DETAILS.US_16_EA                       AS US_16_EA," +
                        "                                   COR_TRN_SALARY_DETAILS.US_16_TE                       AS US_16_TE," +
                        "                                   COR_TRN_SALARY_DETAILS.US_16_AGGREGATE                AS US_16_AGGREGATE," +
                        "                                   COR_TRN_SALARY_DETAILS.INCOME_CHARGEABLE              AS INCOME_CHARGEABLE," +
                        "                                   COR_TRN_SALARY_DETAILS.AIS_Total                      AS AIS_Total," +
                        "                                   COR_TRN_SALARY_DETAILS.GROSS_TOTAL_INCOME             AS GROSS_TOTAL_INCOME," +
                        "                                   COR_TRN_SALARY_DETAILS.CVIA_SEC80CCE_TOTAL_DED_AMOUNT AS CVIA_SEC80CCE_TOTAL_DED_AMOUNT," +
                        "                                   COR_TRN_SALARY_DETAILS.CVIA_OTH_DED_TOTAL             AS CVIA_OTH_DED_TOTAL," +
                        "                                   COR_TRN_SALARY_DETAILS.CVIA_DED_TOTAL                 AS CVIA_DED_TOTAL," +
                        "                                   COR_TRN_SALARY_DETAILS.TOTAL_INCOME                   AS TOTAL_INCOME," +
                        "                                   COR_TRN_SALARY_DETAILS.TAX_TOTAL_INCOME               AS TAX_TOTAL_INCOME," +
                        "                                   COR_TRN_SALARY_DETAILS.SCHG_TOTAL_INCOME              AS SCHG_TOTAL_INCOME," +
                        "                                   COR_TRN_SALARY_DETAILS.ECESS_TOTAL_INCOME             AS ECESS_TOTAL_INCOME," +
                        "                                   COR_TRN_SALARY_DETAILS.TAX_PAYABLE_AGGREGATE          AS TAX_PAYABLE_AGGREGATE," +
                        "                                   COR_TRN_SALARY_DETAILS.US_89_LESS                     AS US_89_LESS," +
                        "                                   COR_TRN_SALARY_DETAILS.TAX_PAYABLE                    AS TAX_PAYABLE," +
                        "                                   COR_TRN_SALARY_DETAILS.TOTAL_TDS_DEDUCTED             AS TOTAL_TDS_DEDUCTED," +
                        "                                   COR_TRN_SALARY_DETAILS.SHORTFALL_TAX                  AS SHORTFALL_TAX," +
                        "                                   COR_TRN_SALARY_DETAILS.PAN_UPDATION_INDICATOR         AS PAN_UPDATION_INDICATOR," +
                        "" + cmnService.J_SQLDBFormat(str80CCMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + " AS CVIA_SEC80CCF_DED_AMOUNT," +
                        "                                   COR_HDR_BATCH.ASST_ID," +
                        "" + cmnService.J_SQLDBFormat(str80CCTextMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + " AS CVIA_SEC80CCF_DED_TEXT," +
                        "                                   COR_TRN_SALARY_DETAILS.TS_GS_TOTAL                    AS TS_GS_TOTAL," +
                        "                                   COR_TRN_SALARY_DETAILS.SEC10_TOTAL_AMOUNT             AS SEC10_TOTAL_AMOUNT," +
                        "                                   COR_TRN_SALARY_DETAILS.US_16_IA                       AS US_16_IA " +
                        "                            FROM   COR_HDR_BATCH," +
                        "                                   COR_TRN_SALARY_DETAILS" +
                        "                            WHERE  COR_HDR_BATCH.BATCH_HEADER_ID    = COR_TRN_SALARY_DETAILS.BATCH_HEADER_ID" +
                        "                            AND    COR_TRN_SALARY_DETAILS.BATCH_HEADER_ID  = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " " +
                        "                            AND    COR_HDR_BATCH.FORM_NO    = '" + T_FormNo.F24Q + "'" +
                        "                            AND    COR_HDR_BATCH.QTR        = '" + T_Qtr.Q4 + "'" +
                        "                            AND   (COR_TRN_SALARY_DETAILS.MODE    <> ''" +
                        "                            OR     COR_TRN_SALARY_DETAILS.PAN_UPDATION_INDICATOR = 1) " +
                        "                            ORDER BY COR_TRN_SALARY_DETAILS.TRN_SALARY_DETAILS_ID";

                    rptcls.OpenSubreport("crSubRptSalaryDetails").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSubRptSalaryDetails).Tables[0]);
                }
                #endregion

                // QUERY FOR COMPANY DETAILS
                //FROM DATE AND TO DATE
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtDatePH"];
                objtxtValue.Text = "From : " + TdsMan.T_ReturnQuarterStartDate(TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription, 4), TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription, 2)) +
                                   " To : " + TdsMan.T_ReturnQuarterEndDate(TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription, 4), TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription, 2));

                
                //FA YEAR
                strSQL = "SELECT FA_YEAR " +
                    "     FROM   COR_HDR_BATCH," +
                    "            MST_ASSESSMENT " +
                    "     WHERE  COR_HDR_BATCH.ASST_ID         = MST_ASSESSMENT.ASST_ID " +
                    "     AND    COR_HDR_BATCH.BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription);

                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFAYear"];
                objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));

                strQueryString = "SELECT  COR_TRN_COMPANY.TRN_COMPANY_ID               AS COMPANY_ID," +
                    "                     COR_TRN_COMPANY.BATCH_HEADER_ID              AS BATCH," +
                    "                     COR_TRN_COMPANY.COMPANY_NAME                 AS COMPANY," +
                    "                     COR_TRN_COMPANY.TAN_NO                       AS TAN," +
                    "                     COR_HDR_BATCH.FORM_NO                        AS FORM," +
                    "                     COR_HDR_BATCH.QTR                            AS QTR," +
                    "                     " + lngBATCH_UPDATION_INDICATOR + "          AS BATCH_UPDATE," +
                    "                    '" + strBATCH_UPDATION_INDICATOR + "'         AS BATCH_UPDATE_VALUE," +
                    "                     " + lngCHALLAN_UPDATION_INDICATOR + "        AS CHALLAN_UPDATES," +
                    "                     " + lngDeducteeUpdates + "                   AS DEDUCTEE_UPDATES," +
                    "                     " + lngDeducteeChanges + "                   AS TOTAL_C3_CHANGES," +
                    "                     " + lngDeducteeAddDelete + "                 AS DEDUCTEE_ADD_DELETE," +
                    "                     " + lngPANUpdates + "                 AS PAN_UPDATES," +
                    "                     " + lngNewChallanAdded + "            AS NEW_CHALLAN_ADDED," +
                    "                     " + lngNewDeducteeAdded + "           AS DEDUCTEES_ADDED_NEW_CHALLAN," +
                    "                     " + lngSDPANUpdates + "               AS SD_PAN_UPDATES," +
                    "                     " + lngSDUpdates + "                  AS SD_UPDATES" +
                    "             FROM    COR_TRN_COMPANY," +
                    "                     COR_HDR_BATCH" +
                    "             WHERE   COR_HDR_BATCH.BATCH_HEADER_ID = COR_TRN_COMPANY.BATCH_HEADER_ID" +
                    "             AND     COR_HDR_BATCH.BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " ";

                string[,] strArry = { { "txtReportTitle", "Form No. " + TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription, 3) + " - Correction Log" } };
                rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);

            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

        #region PrintCorrectionLog_RDLC
        //---------------------------------------------------
        //-- ANIK 2024/05/25
        //---------------------------------------------------
        private void PrintCorrectionLog_RDLC()
        {
            try
            {
                long lngBATCH_UPDATION_INDICATOR = 0;
                long lngCHALLAN_UPDATION_INDICATOR = 0;
                long lngDeducteeChanges = 0;
                long lngPANUpdates = 0;
                long lngNewChallanAdded = 0;
                long lngNewDeducteeAdded = 0;
                long lngSDPANUpdates = 0;
                long lngSDUpdates = 0;
                long lngTotalCorrections = 0;
                string strBATCH_UPDATION_INDICATOR = "";
                //
                long lngDeducteeUpdates = 0;
                //
                long lngDeducteeAddDelete = 0;

                IDataReader drdCorChallanUpdates = null;
                IDataReader drdCorDeducteeUpdates = null;
                //
                string strCompanyTableName = "", strChallanTableName = "", strDeducteeTableName = "";
                string strCompanyDetailQueryString = "", strChallanUpdateDetailQueryString = "", strDeducteeUpdateDetailQueryString = "", strNewChallanDetailsQueryString = "", strDeducteeDetailsQueryString = "", strSalaryDetailsQueryString = "";
                //
                lngBATCH_UPDATION_INDICATOR = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT BATCH_UPDATION_INDICATOR FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " ")));
                lngCHALLAN_UPDATION_INDICATOR = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(CHALLAN_UPDATION_INDICATOR) FROM COR_TRN_CHALLAN WHERE CHALLAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " ")));
                lngDeducteeChanges = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE IN ('" + T_CorrectionMode.Modify + "','" + T_CorrectionMode.Delete + "','" + T_CorrectionMode.Add + "') AND BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " ")));
                lngPANUpdates = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE PAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " ")));
                lngNewChallanAdded = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_CHALLAN_ID) FROM COR_TRN_CHALLAN WHERE HDR_CHALLAN_ID =0 AND BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " ")));
                lngNewDeducteeAdded = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE = '" + T_CorrectionMode.C9Mode + "'  AND BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " ")));
                lngSDPANUpdates = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_SALARY_DETAILS_ID) FROM COR_TRN_SALARY_DETAILS WHERE PAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " ")));
                lngSDUpdates = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_SALARY_DETAILS_ID) FROM COR_TRN_SALARY_DETAILS WHERE MODE <> '' AND BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " ")));

                //Only Deductee Updates
                lngDeducteeUpdates = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE = '" + T_CorrectionMode.Modify + "' AND BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " ")));

                //Deductee Add / Delete
                lngDeducteeAddDelete = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE IN ('" + T_CorrectionMode.Delete + "','" + T_CorrectionMode.Add + "') AND BATCH_HEADER_ID = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + " ")));

                lngTotalCorrections = lngBATCH_UPDATION_INDICATOR + lngCHALLAN_UPDATION_INDICATOR + lngDeducteeChanges + lngPANUpdates;
                lngTotalCorrections = lngTotalCorrections + lngNewChallanAdded + lngNewDeducteeAdded + lngSDPANUpdates + lngSDUpdates;

                if (lngBATCH_UPDATION_INDICATOR == 1)
                    strBATCH_UPDATION_INDICATOR = "Yes";
                else
                    strBATCH_UPDATION_INDICATOR = "No";

                //////crCorrectionLog rptCorrectionLog = new crCorrectionLog();
                //////rptcls = (ReportClass)rptCorrectionLog;
                //////TextObject objtxtValue;

                #region BATCH_UPDATION_INDICATOR_LOG
                if (lngBATCH_UPDATION_INDICATOR == 1)
                {
                    //-----------------------------------------------------------------------
                    //TEMP TABLE FOR COMPANY DETAILS 
                    //-----------------------------------------------------------------------
                    //string strCompanyTableName = "";
                    //strCompanyTableName = "TMP_CORRECTION_COMPANY_LOG_" + string.Format("{0:ddMMyy}", System.DateTime.Now.Date) + "_" + string.Format("{0:HHmmss}", System.DateTime.Now);
                    //Indrajit on 2013-02-26
                    strCompanyTableName = "TMP_CORRECTION_COMPANY_LOG_" + string.Format("{0:ddMMyy}", System.DateTime.Now.Date) + "_" + string.Format("{0:HHmmss}", System.DateTime.Now) + "_" + TDSMAN.Classes.TDSMAN.T_pProductSerial;
                    //-----------------------------------------------------------------------
                    //CREATE THE TEMPORARY TABLE
                    //-----------------------------------------------------------------------           
                    strSQL = "CREATE TABLE " + strCompanyTableName + "("
                               + cmnService.J_GetDataType("CORRECTION_ID", J_Identity.YES) + ","
                               + cmnService.J_GetDataType("BATCH_HEADER_ID", J_ColumnType.Integer) + ","
