                                 "        '' AS D_STATE_ID," +
                                 "        '' AS D_STATE_NAME," +
                                 "        ''               AS D_PIN_CODE," +
                                 "        ''              AS D_MOBILE_NO," +
                                 "        ''                  AS D_EMAIL," +
                                 "        COR_TRN_CHALLAN.TRN_CHALLAN_ID              AS CHALLAN_ID," +
                                 "        COR_TRN_CHALLAN.SECTION_ID              AS SECTION_ID," +
                                 "        COR_TRN_CHALLAN.DEPOSIT_DATE            AS DEPOSIT_DATE," +
                                 "        COR_TRN_CHALLAN.BSR_CODE                AS BSR_CODE," +
                                 "        COR_TRN_CHALLAN.CHALLAN_NO              AS CHALLAN_NO," +
                                 "        COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO     AS TRANSFER_VOUCHER_NO," +
                                 //"        TRN_DEDUCTEE_DETAILS.PARTY_ID       AS PARTY_ID," +
                                 "        ''       AS PARTY_ID," +
                                 "        SUM(COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT) AS DEDUCTEE_TOTAL," +
                                 "        COR_TRN_CHALLAN.BOOK_ENTRY              AS BOOK_ENTRY " +
                                 "FROM   (((((((COR_TRN_COMPANY INNER JOIN MST_STATE " +
                                 "              ON COR_TRN_COMPANY.STATE_ID       = MST_STATE.STATE_ID) " +
                                 "        INNER JOIN COR_HDR_BATCH " +
                                 "             ON COR_TRN_COMPANY.BATCH_HEADER_ID = COR_HDR_BATCH.BATCH_HEADER_ID) " +
                                 "        INNER JOIN MST_ASSESSMENT " +
                                 "             ON COR_HDR_BATCH.ASST_ID           = MST_ASSESSMENT.ASST_ID) " +
                                 "        INNER JOIN COR_TRN_CHALLAN " +
                                 "             ON COR_HDR_BATCH.BATCH_HEADER_ID   = COR_TRN_CHALLAN.BATCH_HEADER_ID) " +
                                 "        INNER JOIN COR_TRN_DEDUCTEE_DETAILS " +
                                 "             ON COR_TRN_CHALLAN.TRN_CHALLAN_ID  = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID) " +
                                 //"        INNER JOIN MST_DEDUCTEE " +
                                 //"             ON TRN_DEDUCTEE_DETAILS.PARTY_ID  = MST_DEDUCTEE.DEDUCTEE_ID) " +
                                 "        LEFT JOIN  MST_STATE AS MST_STATE_D " +
                                 "            ON MST_DEDUCTEE.STATE_ID         = MST_STATE_D.STATE_ID) " +
                                 "WHERE  COR_HDR_BATCH.BATCH_HEADER_ID          = " + lngBasicInfoID + " " +
                                 //"AND    TRN_DEDUCTEE_DETAILS.PARTY_ID IN     (" + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + ") " +
                                 "GROUP BY COR_TRN_COMPANY.COMPANY_ID," +
                                 "       COR_TRN_COMPANY.COMPANY_NAME," +
