                                                "             ON     TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID)" +
                                                "                    INNER JOIN MST_CATEGORY " +
                                                "             ON     MST_CATEGORY.CATEGORY_ID     = MST_COMPANY.D_CATEGORY_ID)" +
                                                "                    LEFT JOIN MST_REASON " +
                                                "             ON TRN_DEDUCTEE_DETAILS.REASON_ID=MST_REASON.REASON_ID) " +
                                                "             WHERE  TRN_BASIC_INFO.COMPANY_ID          = " + CompanyID + " " +
                                                "             AND    TRN_BASIC_INFO.ASST_ID             = " + FAYearID + " " +
                                                "             AND    TRN_BASIC_INFO.FORM_NO             ='" + FormNo + "' " +
                                                "             AND    TRN_BASIC_INFO.QTR                 ='" + Qtr + "' " +
                                                "             ORDER BY TRN_DEDUCTEE_DETAILS.SL_NO";
                            rptcls.OpenSubreport("crSubRptDeductee_Details_26Q").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strQueryStringDeducteeDetails).Tables[0]);
                        }
                        #endregion //26Q DEDUCTEE DETAILS

                        #region 27Q AND 27EQ DEDUCTEE DETAIL
                        if (FormNo == T_FormNo.F27Q || FormNo == T_FormNo.F27EQ)
                        {
                            strQueryStringDeducteeDetails = "SELECT MST_COMPANY.COMPANY_ID                                                                AS COMPANY_ID," +
                                                    "                    MST_COMPANY.COMPANY_NAME                                                         AS COMPANY_NAME," +
                                                    "                    MST_COMPANY.TAN_NO                                                               AS TAN_NO," +
                                                    "                    TRN_CHALLAN.CHALLAN_ID                                                           AS CHALLAN_ID," +
                                                    "                   " + cmnService.J_SQLDBFormat(strChallanNoDeducteeMatrix, J_SQLColFormat.Case_End) + "    AS CHALLAN_NO," +
                                                    "                   " + cmnService.J_SQLDBFormat(strChallanNoTextMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_NO_TEXT," +
                                                    "                    TRN_CHALLAN.BSR_CODE                                                             AS BSR_CODE," +
                                                    "                    TRN_CHALLAN.DEPOSIT_DATE                                                         AS DEPOSIT_DATE," +
                                                    "                    MST_DEDUCTEE.DEDUCTEE_ID                                                         AS DEDUCTEE_ID," +
                                                    "                    MST_DEDUCTEE.DEDUCTEE_NAME                                                       AS DEDUCTEE_NAME," +
                                                    "                    MST_DEDUCTEE.DEDUCTEE_PAN                                                        AS DEDUCTEE_PAN," +
                                                    "                    TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE                                               AS DEDUCTED_DATE," +
                                                    "                    TRN_DEDUCTEE_DETAILS.PAYMENT_DATE                                                AS PAYMENT_DATE," +
                                                    "                    MST_SECTION.SECTION_NO                                                           AS SECTION_NO," +
                                                    "                    TRN_DEDUCTEE_DETAILS.SL_NO                                                       AS SL_NO," +
                                                    "                    TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT                                              AS PAYMENT_AMOUNT," +
                                                    "                    TRN_DEDUCTEE_DETAILS.RATE                                                        AS RATE," +
                                                    "                    TRN_DEDUCTEE_DETAILS.TAX_AMOUNT                                                  AS TAX_AMOUNT," +
                                                    "                    TRN_DEDUCTEE_DETAILS.SURCHARGE_AMOUNT                                            AS SURCHARGE_AMOUNT," +
                                                    "                    TRN_DEDUCTEE_DETAILS.CESS_AMOUNT                                                 AS CESS_AMOUNT," +
                                                    "                    TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT                                                AS TOTAL_AMOUNT," +
                                                    "                    TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT                                        AS TAX_DEPOSITED_AMOUNT," +
                                                    "                    TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG                                          AS NON_DEDUCTION_FLAG," +
                                                    "                    MST_ASSESSMENT.FA_YEAR                                                           AS FA_YEAR," +
                                                    "                    TRN_BASIC_INFO.FORM_NO                                                           AS FORM_NO," +
                                                    "                    TRN_BASIC_INFO.QTR                                                               AS QTR," +
                                                    //"                   " + cmnService.J_SQLDBFormat("MST_DEDUCTEE.DEDUCTEE_CODE", J_SQLColFormat.Case_End, strDeducteeCodeMatrix) + " AS DEDUCTEE_CODE," +
                                                    "                    MST_DEDUCTEE.DEDUCTEE_CODE                                                       AS DEDUCTEE_CODE," +
                                                    "      " + cmnService.J_SQLDBFormat(strProvEntryMatrix, J_SQLColFormat.Case_End) + " AS CASH_BOOK_ENTRY," +
                                                    "      " + cmnService.J_SQLDBFormat(strGrossTotMatrix, J_SQLColFormat.Case_End) + " AS GROSSING_UP_INDICATOR_TOT_VALUE_PURCHASE," +
                                                    "                    TRN_CHALLAN.TDS                                                                  AS TDS," +
                                                    "                    TRN_CHALLAN.SURCHARGE                                                            AS SURCHARGE," +
                                                    "                    TRN_CHALLAN.EDUCATION_CESS                                                       AS EDUCATION_CESS," +
                                                    "                    TRN_CHALLAN.OTHERS                                                               AS OTHERS," +
                                                    "                    TRN_CHALLAN.INTEREST                                                             AS INTEREST," +
                                                    "                    TRN_CHALLAN.CTRL_TOT_TAX                                                         AS TOTAL_TDS," +
                                                    "                    TRN_CHALLAN.INTEREST_ALLOCATED                                                   AS INTEREST_ALLOCATED," +
                                                    "                    TRN_CHALLAN.OTHERS_ALLOCATED                                                     AS OTHERS_ALLOCATED," +
                                                    "                    TRN_CHALLAN.TOT_TAX                                                              AS TOTAL_ABOVE," +
                                                    "                    MST_COMPANY.PERSON_NAME                                                          AS PERSON_NAME," +
                                                    "                    MST_COMPANY.DESIGNATION                                                          AS DESIGNATION," +
                                                    "                    MST_COMPANY.P_ADDRESS3                                                           AS P_ADDRESS3," +
                                                    "                   '" + TdsMan.T_ReturnQuarterEndDate(cmbCombo4.Text, cmbCombo2.Text) + "' AS QTR_END_DATE," +
                                                    "                    DD_MST_SECTION.SECTION_NO                                                        AS SECTION_NO_DD, " +
                                                    "                    TRN_DEDUCTEE_DETAILS.CERTIFICATE_NO                                              AS CERTIFICATE_NO, " +
                                                    "                    TRN_DEDUCTEE_DETAILS.REASON_ID                                                   AS REASON_ID, " +
                                                    "                    TRN_DEDUCTEE_DETAILS.TDS_APPLICABILITY_ID                                        AS TDS_APPLICABILITY_ID, " +
                                                    "                    MST_TDS_APPLICABILITY.TDS_APPLICABILITY_CODE                                     AS TDS_APPLICABILITY_CODE, " +
                                                    "                    TRN_DEDUCTEE_DETAILS.REMITTANCE_ID                                               AS REMITTANCE_ID, " +
                                                    "                    MST_REMITTANCE.REMITTANCE_DESC                                                   AS REMITTANCE_DESC, " +
                                                    "                    TRN_DEDUCTEE_DETAILS.UNIQUE_ACKN                                                 AS UNIQUE_ACKN, " +
                                                    "                    TRN_DEDUCTEE_DETAILS.COUNTRY_ID                                                  AS COUNTRY_ID, " +
                                                    "                    MST_COUNTRY.COUNTRY_DESC                                                         AS COUNTRY_DESC, " +
                                                    "                    TRN_DEDUCTEE_DETAILS.TOT_VALUE_PURCHASE                                          AS TOT_VALUE_PURCHASE, " +
                                                    "                    MST_REASON.REASON                                                                AS REASON, " +
                                                    "                    MST_REASON.DESCRIPTION                                                           AS DESCRIPTION " +
                                                    "             FROM  ((((((((((((TRN_CHALLAN LEFT JOIN MST_SECTION " +
                                                    "             ON     TRN_CHALLAN.SECTION_ID       = MST_SECTION.SECTION_ID)" +
                                                    "                    INNER JOIN TRN_DEDUCTEE_DETAILS " +
                                                    "             ON     TRN_CHALLAN.CHALLAN_ID       = TRN_DEDUCTEE_DETAILS.CHALLAN_ID)" +
                                                    "                    INNER JOIN MST_SECTION as DD_MST_SECTION " +
                                                    "             ON     DD_MST_SECTION.SECTION_ID       = TRN_DEDUCTEE_DETAILS.SECTION_ID)" +
                                                    "                    INNER JOIN MST_DEDUCTEE " +
                                                    "             ON     TRN_DEDUCTEE_DETAILS.PARTY_ID= MST_DEDUCTEE.DEDUCTEE_ID)" +
                                                    "                    INNER JOIN TRN_BASIC_INFO " +
                                                    "             ON     TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID)" +
                                                    "                    INNER JOIN MST_COMPANY " +
                                                    "             ON     TRN_BASIC_INFO.COMPANY_ID    = MST_COMPANY.COMPANY_ID)" +
                                                    "                    INNER JOIN MST_ASSESSMENT " +
                                                    "             ON     TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID)" +
                                                    "                    INNER JOIN MST_CATEGORY " +
                                                    "             ON     MST_CATEGORY.CATEGORY_ID     = MST_COMPANY.D_CATEGORY_ID)" +
                                                    "                    LEFT JOIN MST_REASON " +
                                                    "             ON     TRN_DEDUCTEE_DETAILS.REASON_ID=MST_REASON.REASON_ID) " +
                                                    "                    LEFT JOIN MST_TDS_APPLICABILITY " +
                                                    "             ON     TRN_DEDUCTEE_DETAILS.TDS_APPLICABILITY_ID=MST_TDS_APPLICABILITY.TDS_APPLICABILITY_ID) " +
                                                    "                    LEFT JOIN MST_REMITTANCE" +
                                                    "             ON     TRN_DEDUCTEE_DETAILS.REMITTANCE_ID=MST_REMITTANCE.REMITTANCE_ID) " +
                                                    "                    LEFT JOIN MST_COUNTRY" +
                                                    "             ON     TRN_DEDUCTEE_DETAILS.COUNTRY_ID=MST_COUNTRY.COUNTRY_ID) " +
                                                    "             WHERE  TRN_BASIC_INFO.COMPANY_ID          = " + CompanyID + " " +
                                                    "             AND    TRN_BASIC_INFO.ASST_ID             = " + FAYearID + " " +
                                                    "             AND    TRN_BASIC_INFO.FORM_NO             ='" + FormNo + "' " +
                                                    "             AND    TRN_BASIC_INFO.QTR                 ='" + Qtr + "' " +
                                                    "             ORDER BY TRN_DEDUCTEE_DETAILS.SL_NO";
