        //---------------------------------------------------
        private void PrintITReturnQForm_RDLC(int CompanyID, int FAYearID, string FormNo, string Qtr, string FAYear)
        {
            long BasicInfoID = 0;
            try
            {
                //--
                //crITR24QForm rptITRForm = new crITR24QForm(); // Commented By Abhishek Dey On 22/04/2019 --
                //crITR24QForm1819 rptITRForm = new crITR24QcrITR24QFormForm1819(); //-- Added By Abhishek Dey On 22/04/2019
                //rptcls = (ReportClass)rptITRForm;
                //--
                strSQL = "SELECT BASIC_INFO_ID FROM TRN_BASIC_INFO " +
                    "     WHERE  COMPANY_ID = " + CompanyID + " " +
                    "     AND    ASST_ID    = " + FAYearID + " " +
                    "     AND    FORM_NO    ='" + FormNo + "' " +
                    "     AND    QTR        ='" + Qtr + "' ";
                BasicInfoID = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));
                if (BasicInfoID > 0)
                {
                    string strQueryStringCompanyDetails = "";
                    string strQueryStringChallanDetails = "";
                    string strQueryStringDeducteeDetails = "";
                    string strQueryStringSalaryDetails1 = "";
                    string strQueryStringSalaryDetails2 = "";
                    string strQtrEnded = "";
                    string strSectionDetails = "";
                    //--
                    if (Qtr == T_Qtr.Q1)
                        strQtrEnded = "June " + FAYear.ToString().Substring(0, 4);
                    else if (Qtr == T_Qtr.Q2)
                        strQtrEnded = "September " + FAYear.ToString().Substring(0, 4);
                    else if (Qtr == T_Qtr.Q3)
                        strQtrEnded = "December " + FAYear.ToString().Substring(0, 4);
                    else if (Qtr == T_Qtr.Q4)
                        strQtrEnded = "March " + FAYear.ToString().Substring(0, 2) + FAYear.ToString().Substring(5, 2);
                    //--
                    long lngChallanExist = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM TRN_CHALLAN WHERE BASIC_INFO_ID = " + BasicInfoID, J_QueryType.DirectQuery)));
