                                J_PreviewReportRDLC8DataSet("\\Reports\\crITR27QForm1819.rdlc", "DataSet1", strQueryStringCompanyDetails,
                                                                                            "DataSet2", strQueryStringChallanDetails,
                                                                                            "DataSet4", strQueryStringDeducteeDetails,
                                                                                            "DataSet3", strDeductorCategory,
                                                                                            "DataSet5", strSectionDetails,
                                                                                            "DataSet6", strRemarks,
                                                                                            "DataSet7", strRemittance,
                                                                                            "DataSet8", strCountry,
                                                                                            null);

                            }
                            else if (FormNo == T_FormNo.F27EQ)
                            {
                                //rptcls.OpenSubreport("crSubRptDeductee_Details_27EQ").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strQueryStringDeducteeDetails).Tables[0]);
                                //J_PreviewReportRDLC3DataSet("\\Reports\\crITR24QForm1819_27EQ.rdlc", "DataSet1", strQueryStringCompanyDetails, "DataSet2", strQueryStringChallanDetails, "DataSet4", strQueryStringDeducteeDetails, null);
                                J_PreviewReportRDLC6DataSet("\\Reports\\crITR27EQForm1819.rdlc", "DataSet1", strQueryStringCompanyDetails,
                                                                                            "DataSet2", strQueryStringChallanDetails,
                                                                                            "DataSet4", strQueryStringDeducteeDetails,
                                                                                            "DataSet3", strDeductorCategory,
                                                                                            "DataSet5", strSectionDetails,
                                                                                            "DataSet6", strRemarks,
                                                                                            null);

                            }
                        }
                        #endregion //27Q AND 27EQ DEDUCTEE DETAIL

                    }
                    #endregion // DEDUCTEE/EMPLOYEE DETAILS END

                    
                    // MAIN REPORT 
