        #region PrintCorrectionStatementQuarterly
        //---------------------------------------------------
        //-- ANIK(2013-02-05)
        //---------------------------------------------------
        private void PrintCorrectionStatementQuarterly()
        {
            try
            {
                #region COMPANY DETAILS
                if (rbnSort1.Checked == true)
                {
                    string[,] strAddressChangeMatrix = {{"COR_HDR_BATCH.ADDRESS_CHANGE = 1", "F", "Yes", "T"},
                                                        {"COR_HDR_BATCH.ADDRESS_CHANGE = 0", "F", "No", "T"}};

                    string[,] strPAddressChangeMatrix = {{"COR_HDR_BATCH.P_ADDRESS_CHANGE = 1", "F", "Yes", "T"},
                                                         {"COR_HDR_BATCH.P_ADDRESS_CHANGE = 0", "F", "No", "T"}};

                    string[,] strMinistryMatrix = {{"COR_TRN_COMPANY.MINISTRY_ID > 0", "F", "MST_MINISTRY.MINISTRY_NAME", "F"},
                                                   {"COR_TRN_COMPANY.MINISTRY_ID = 0", "F", "COR_TRN_COMPANY.MINISTRY_OTHER", "F"}};

                    strQueryString = "SELECT  COR_TRN_COMPANY.TRN_COMPANY_ID        AS COMPANY_ID," +
                        "                     COR_TRN_COMPANY.COMPANY_NAME          AS COMPANY_NAME," +
                        "                     COR_TRN_COMPANY.TAN_NO                AS TAN_NO," +
                        "                     COR_TRN_COMPANY.PAN_NO                AS PAN_NO," +
                        "                     COR_TRN_COMPANY.BRANCH_DIV            AS BRANCH_DIV," +
                        "                     COR_TRN_COMPANY.D_CATEGORY_ID         AS D_CATEGORY_ID," +
                        "                     MST_CATEGORY.CATEGORY_DESCRIPTION     AS CATEGORY_DESCRIPTION," +
                        "                     MST_CATEGORY.CATEGORY_CODE            AS CATEGORY_CODE," +
                        "                  " + cmnService.J_SQLDBFormat(strAddressChangeMatrix, J_SQLColFormat.Case_End) + " AS ADDRESS_CHANGE," +
                        "                     COR_TRN_COMPANY.ADDRESS1              AS ADDRESS1," +
                        "                     COR_TRN_COMPANY.ADDRESS3              AS ADDRESS2," +
                        "                     COR_TRN_COMPANY.ADDRESS5              AS ADDRESS3," +
                        "                     COR_TRN_COMPANY.ADDRESS2              AS ADDRESS4," +
                        "                     COR_TRN_COMPANY.ADDRESS4              AS ADDRESS5," +
                        "                     COR_TRN_COMPANY.STATE_ID              AS STATE_ID," +
                        "                     MST_STATE.STATE_NAME                   AS STATE_NAME," +
                        "                     COR_TRN_COMPANY.PIN_CODE              AS PIN_CODE," +
                        "                     COR_TRN_COMPANY.STD                   AS STD," +
                        "                     COR_TRN_COMPANY.PHONE                 AS PHONE," +
                        "                     COR_TRN_COMPANY.EMAIL                 AS EMAIL," +
                        "                     COR_TRN_COMPANY.PERSON_NAME           AS PERSON_NAME," +
                        "                     COR_TRN_COMPANY.DESIGNATION           AS DESIGNATION," +
                        "                     'TDMAN_FATHER'                        AS FATHER_NAME," +
                        "                  " + cmnService.J_SQLDBFormat(strPAddressChangeMatrix, J_SQLColFormat.Case_End) + " AS P_ADDRESS_CHANGE," +
                        "                     COR_TRN_COMPANY.P_ADDRESS1            AS P_ADDRESS1," +
                        "                     COR_TRN_COMPANY.P_ADDRESS3            AS P_ADDRESS2," +
                        "                     COR_TRN_COMPANY.P_ADDRESS5            AS P_ADDRESS3," +
                        "                     COR_TRN_COMPANY.P_ADDRESS2            AS P_ADDRESS4," +
                        "                     COR_TRN_COMPANY.P_ADDRESS4            AS P_ADDRESS5," +
                        "                     COR_TRN_COMPANY.P_STATE_ID            AS P_STATE_ID," +
                        "                     RP_STATE.STATE_NAME                   AS RP_STATE_NAME," +
                        "                     COR_TRN_COMPANY.P_PIN_CODE            AS P_PIN_CODE," +
                        "                     COR_TRN_COMPANY.P_PHONE               AS P_PHONE," +
                        "                     COR_TRN_COMPANY.P_STD                 AS P_STD," +
                        "                     COR_TRN_COMPANY.P_EMAIL               AS P_EMAIL," +
                        "                     COR_TRN_COMPANY.P_MOBILE              AS P_MOBILE," +
                        "                     COR_TRN_COMPANY.PAO_CODE              AS PAO_CODE," +
                        "                     COR_TRN_COMPANY.PAO_REG_NO            AS PAO_REG_NO," +
                        "                     COR_TRN_COMPANY.DDO_CODE              AS DDO_CODE," +
                        "                     COR_TRN_COMPANY.DDO_REG_NO            AS DDO_REG_NO," +
                        "                     COR_TRN_COMPANY.D_STATE_ID            AS D_STATE_ID," +
                        "                     D_STATE.STATE_NAME                    AS D_STATE_NAME," +
                        "                  " + cmnService.J_SQLDBFormat(strMinistryMatrix, J_SQLColFormat.Case_End) + " AS MINISTRY," +
                        "                     COR_HDR_BATCH.RECEIPT_NO              AS RECEIPT_NO," +
                        "                  " + cmnService.J_SQLDBFormat("COR_HDR_BATCH.DATE_OF_FILING", J_SQLColFormat.DateFormatDDMMYYYY) + " AS DATE_OF_FILING," +
                        "                     COR_TRN_COMPANY.AIN_NO                AS AIN_NO," +
                        "                     COR_TRN_COMPANY.TAN_REG_NO            AS TAN_REG_NO," +
                        "                     COR_TRN_COMPANY.ALT_STD               AS ALT_STD," +
                        "                     COR_TRN_COMPANY.ALT_PHONE             AS ALT_PHONE," +
                        "                     COR_TRN_COMPANY.ALT_EMAIL             AS ALT_EMAIL," +
                        "                     COR_TRN_COMPANY.P_ALT_STD             AS P_ALT_STD," +
                        "                     COR_TRN_COMPANY.P_ALT_PHONE           AS P_ALT_PHONE," +
                        "                     COR_TRN_COMPANY.P_ALT_EMAIL           AS P_ALT_EMAIL," +
                        "                     COR_TRN_COMPANY.P_PAN                 AS P_PAN," +
                        "                     COR_TRN_COMPANY.GSTN                  AS GSTN," +
                        "                     COR_TRN_COMPANY.MINISTRY_OTHER        AS MINISTRY_OTHER " +
                        "             FROM    ((((((COR_TRN_COMPANY INNER JOIN MST_CATEGORY " +
                        "                     ON COR_TRN_COMPANY.D_CATEGORY_ID = MST_CATEGORY.CATEGORY_ID) " +
                        "                     INNER JOIN MST_STATE " +
                        "                     ON COR_TRN_COMPANY.STATE_ID      = MST_STATE.STATE_ID) " +
                        "                     INNER JOIN MST_STATE AS RP_STATE " +
                        "                     ON COR_TRN_COMPANY.P_STATE_ID    = RP_STATE.STATE_ID) " +
                        "                     LEFT JOIN  MST_STATE AS D_STATE " +
                        "                     ON COR_TRN_COMPANY.D_STATE_ID    = D_STATE.STATE_ID) " +
                        "                     LEFT JOIN  MST_MINISTRY " +
                        "                     ON COR_TRN_COMPANY.MINISTRY_ID   = MST_MINISTRY.MINISTRY_ID)" +
                        "                     INNER JOIN COR_HDR_BATCH " +
                        "                     ON COR_TRN_COMPANY.BATCH_HEADER_ID = COR_HDR_BATCH.BATCH_HEADER_ID) " +
                        "             WHERE   COR_HDR_BATCH.BATCH_HEADER_ID      = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription);

                    crQuarterWiseCompanyDetails rptQuarterWiseCompanyDetails = new crQuarterWiseCompanyDetails();
                    rptcls = (ReportClass)rptQuarterWiseCompanyDetails;
                    // FORM SELECTED
                    TextObject objtxtValue;

                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToDate"];
                    objtxtValue.Text = "From : " + TdsMan.T_ReturnQuarterStartDate(Quarter, FinancialYear) + " To : " + TdsMan.T_ReturnQuarterEndDate(Quarter, FinancialYear);

                    strSQL = "SELECT COUNT(COR_TRN_CHALLAN.TRN_CHALLAN_ID) AS COUNT_CHALLAN_ID " +
                        "     FROM   COR_TRN_CHALLAN," +
                        "            COR_HDR_BATCH " +
                        "     WHERE  COR_TRN_CHALLAN.BATCH_HEADER_ID = COR_HDR_BATCH.BATCH_HEADER_ID " +
                        "     AND    COR_HDR_BATCH.BATCH_HEADER_ID   = " + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription);

