        public void PrintAdvDeducteeSearch(string SearchFilters, string SQL, string CompanyName, string TAN, string FinYr, string Qtr, string FormNo)
        {
            try
            {
                crAdvDeducteeSearch rptAdvDeducteeSearch = new crAdvDeducteeSearch();
                rptcls = (ReportClass)rptAdvDeducteeSearch;
                //
                TextObject objtxtValue;
                //
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtCompanyName"];
                objtxtValue.Text = CompanyName;
                //
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFinancialYear"];
                objtxtValue.Text = FinYr;
                //
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtTAN"];
                objtxtValue.Text = TAN;
                //
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtQtr"];
                objtxtValue.Text = Qtr;
                //
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFormNo"];
                objtxtValue.Text = FormNo;
                //
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[4].ReportObjects["txtSearchFilters"];
                objtxtValue.Text = SearchFilters;
                //
                string[,] strArry = { { "txtReportTitle", "Advance Deductee Search" } };
                rptService.J_PreviewReport(ref rptcls, TDSMAN.Classes.TDSMAN.T_pCurrentForm, SQL, strArry);
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
