                               AND    " + ShortDeduction27QTable + @".PAYMENT_DATE IS NOT NULL 
                               AND    " + ShortDeduction27QTable + @".BASIC_INFO_ID    = " + BasicInfoID + " " +
                         //@"AND    " + strShortDeduction27QTable + @".TAX_DEPOSITED_AMOUNT < " + Argumnets + " " +
                         @"AND   (MST_VERIFIED_PAN.VERIFIED_STATUS IN(1, 2) OR  " + ShortDeduction27QTable + @".REASON_ID IN (3,7,15,4,12,17,20,13))";
                    }
                    else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                    {
                        strSQL = @"SELECT TRN_CHALLAN.SL_NO                                        AS CHALLAN_SL_NO,
                                      " + ShortDeduction27QTable + @".SL_NO                               AS DEDUCTEE_SL_NO," +
                                          strTableName + "." + strFieldPAN + ", " +
                                          strTableName + "." + strFieldName + ", " +
                                        @"MST_SECTION.SECTION_NO,
                                      " + ShortDeduction27QTable + @".PAYMENT_DATE, 
                                      " + ShortDeduction27QTable + @".PAYMENT_AMOUNT,
                                      " + ShortDeduction27QTable + @".TAX_DEPOSITED_AMOUNT, 
                                      " + ShortDeduction27QTable + @".SCHEDULED_RATE       AS RATE,
                                          SCHEDULED_TAX_AMOUNT                        AS ACTUAL_TAX_AMOUNT," +
                                          @"'" + strFAYear + "'                                    AS FA_YEAR," +
                                          @"'" + strQuarter + "'                                   AS QTR," +
                                          @"'" + strFormNo + @"'                                    AS FORM_NO,
                                       '' AS IMPORT_DETAILS " +
                                 @"FROM  (((((" + ShortDeduction27QTable + @" 
                                   INNER JOIN " + strTableName + @"
                                        ON " + ShortDeduction27QTable + @".PARTY_ID = " + strTableName + "." + strFieldId + @") 
                                   INNER JOIN TRN_CHALLAN
                                        ON  " + ShortDeduction27QTable + @".CHALLAN_ID     = TRN_CHALLAN.CHALLAN_ID)
                                   INNER JOIN MST_NONSALARY_TAX_SLAB
                                        ON  " + ShortDeduction27QTable + @".SECTION_ID = MST_NONSALARY_TAX_SLAB.SECTION_ID)  
                                   INNER JOIN MST_SECTION
                                        ON " + ShortDeduction27QTable + @".SECTION_ID     = MST_SECTION.SECTION_ID ) 
                                   LEFT JOIN MST_VERIFIED_PAN
                                        ON  " + strTableName + "." + strFieldPAN + @" = MST_VERIFIED_PAN.PAN)
                                   WHERE  " + ShortDeduction27QTable + @".PAYMENT_DATE BETWEEN MST_NONSALARY_TAX_SLAB.FROM_DATE AND MST_NONSALARY_TAX_SLAB.TO_DATE  
                                   AND    " + ShortDeduction27QTable + @".PAYMENT_DATE IS NOT NULL 
                                   AND    " + ShortDeduction27QTable + @".BASIC_INFO_ID    = " + BasicInfoID + " " +
                                 //@"AND    " + strShortDeduction27QTable + @".TAX_DEPOSITED_AMOUNT < " + Argumnets + " " +
                                 @"AND   (MST_VERIFIED_PAN.VERIFIED_STATUS IN(1, 2) OR " + ShortDeduction27QTable + @".REASON_ID IN (3,7,15,4,12,17,20,13))";
                    }
                }
                //
                if (intSectionNo > 0)
                    strSQL = strSQL + " AND MST_SECTION.SECTION_ID =" + intSectionNo + " ";
                if (strDeducteeName != "")
                    strSQL = strSQL + " AND " + strTableName + "." + strFieldName + " LIKE '" + strDeducteeName + "%'";
                if (strDeducteePAN != "")
                    strSQL = strSQL + " AND " + strTableName + "." + strFieldPAN + "  LIKE '" + strDeducteePAN + "%'";

                if (strFormNo == T_FormNo.F27Q)
                    strSQL = strSQL + @" ORDER BY TRN_CHALLAN.SL_NO, " + ShortDeduction27QTable + @".SL_NO ";
                else
                    strSQL = strSQL + @" ORDER BY TRN_CHALLAN.SL_NO ";// + ShortDeduction27QTable + @".SL_NO ";


                // FORM SELECTED 
                //TextObject objtxtValue;

                //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToDate"];
                //objtxtValue.Text = "From : " + TdsMan.T_ReturnQuarterStartDate(strQuarter, strFAYear) + " To : " + TdsMan.T_ReturnQuarterEndDate(strQuarter, strFAYear);

                //string[,] strArry = { { "txtReportTitle", "Short Deduction" },
                //                  { "txtCompanyTANNo",  strCompanyTAN } };
                //
                this.Cursor = Cursors.Default;
                //
                //rptService.J_PreviewReport(ref rptcls, TDSMAN.Classes.TDSMAN.T_pCurrentForm, strSQL, strArry);
                //RDLC Report
                string[,] strArryShortDeductionReport = {{"ReportHeader", "Short Deduction" },
                                                        {"ReportCaption", strCompanyTAN + " FA. Year : " + strFAYear +" Qtr : " + strQuarter},
                                                        {"ReportFromToDate", "From : " + TdsMan.T_ReturnQuarterStartDate(strQuarter, strFAYear) + " To : " + TdsMan.T_ReturnQuarterEndDate(strQuarter, strFAYear) },
                                                        {"ReportFormNo", "Form No : " + strFormNo }
                                                               };
                J_PreviewReportRDLC("\\Reports\\crShortDeduction.rdlc", "DataSet1", strSQL, strArryShortDeductionReport);
            }
            catch (Exception err)
            {

            }
        }
