        #region PrintShortDeductionCorr_RDLC
        public void PrintShortDeductionCorr_RDLC(long BasicInfoID, int intSectionNo, string strDeducteeName, string strDeducteePAN)
        {
            try
            {
                //crShortDeduction rptShortDeduction = new crShortDeduction();
                //rptcls = (ReportClass)rptShortDeduction;
                //--
                string strFAYear = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT MST_ASSESSMENT.FA_YEAR FROM COR_HDR_BATCH, MST_ASSESSMENT WHERE COR_HDR_BATCH.ASST_ID = MST_ASSESSMENT.ASST_ID AND COR_HDR_BATCH.BATCH_HEADER_ID =" + BasicInfoID));
                string strQuarter = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT QTR FROM COR_HDR_BATCH WHERE BATCH_HEADER_ID =" + BasicInfoID));
                string strFormNo = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT FORM_NO FROM COR_HDR_BATCH WHERE BATCH_HEADER_ID =" + BasicInfoID));
                string strCompanyTAN = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COMPANY_NAME + '[' + TAN_NO + ']' FROM COR_HDR_BATCH, COR_HDR_COMPANY WHERE COR_HDR_BATCH.BATCH_HEADER_ID = COR_HDR_COMPANY.BATCH_HEADER_ID AND COR_HDR_BATCH.BATCH_HEADER_ID =" + BasicInfoID));


                //Added by dhruba @ 2016-06-16
                if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                {
                    string strArgumnets = @"CASE WHEN  COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANNOTAVBL' " +
                                                  @"OR COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANAPPLIED' " +
                                                  @"OR COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANINVALID' " +
                                                  @"OR MST_VERIFIED_PAN.VERIFIED_STATUS IN(1, 2) " +
                                               @"THEN ROUND((COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.INVALID_PAN_RATE ) / 100,0) 
                                                 ELSE CASE WHEN SUBSTRING(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN, 4, 1) = 'P' OR SUBSTRING(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN, 4, 1) = 'H' " +
                                                         @"THEN ROUND((COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.NON_COMPANY_RATE ) / 100,0)
                                                           ELSE ROUND((COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.COMPANY_RATE ) / 100,0) 
                                                      END 
                                            END";
                    //
                    strSQL = @"SELECT COR_TRN_CHALLAN.SL_NO                  AS CHALLAN_SL_NO,
                                      COR_TRN_DEDUCTEE_DETAILS.SL_NO         AS DEDUCTEE_SL_NO,
                                      COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN  AS DEDUCTEE_PAN, 
                                      COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME AS DEDUCTEE_NAME, 
                                      MST_SECTION.SECTION_NO,
                                      COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 
                                      COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT,
                                      COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT, 
                                      CASE WHEN (COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANNOTAVBL' 
                                                 OR COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANAPPLIED' 
                                                 OR COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANINVALID')
                                           THEN MST_NONSALARY_TAX_SLAB.INVALID_PAN_RATE
                                           ELSE CASE WHEN (SUBSTRING(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN, 4, 1) = 'P' OR SUBSTRING(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN, 4, 1) = 'H') 
                                                     THEN MST_NONSALARY_TAX_SLAB.NON_COMPANY_RATE 
                                                     ELSE MST_NONSALARY_TAX_SLAB.COMPANY_RATE
                                                END 
                                      END                                               AS RATE," +
                                      strArgumnets + "                                  AS ACTUAL_TAX_AMOUNT," +
                                      @"'" + strFAYear + "' AS FA_YEAR," +
                                      @"'" + strQuarter + "' AS QTR," +
                                      @"'" + strFormNo + @"' AS FORM_NO,
                                    '' AS IMPORT_DETAILS " +
                                 @"FROM  ((((TRN_DEDUCTEE_DETAILS 
                                   INNER JOIN COR_TRN_CHALLAN
                                        ON  COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID     = COR_TRN_CHALLAN.TRN_CHALLAN_ID)
                                   INNER JOIN MST_NONSALARY_TAX_SLAB
                                        ON  COR_TRN_DEDUCTEE_DETAILS.SECTION_ID = MST_NONSALARY_TAX_SLAB.SECTION_ID)  
                                   INNER JOIN MST_SECTION
                                        ON COR_TRN_DEDUCTEE_DETAILS.SECTION_ID     = MST_SECTION.SECTION_ID ) 
                                   LEFT JOIN MST_VERIFIED_PAN
                                        ON  COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = MST_VERIFIED_PAN.PAN) " +
                         //@"FROM   COR_TRN_DEDUCTEE_DETAILS,
                         //         MST_NONSALARY_TAX_SLAB,
                         //         COR_TRN_CHALLAN,
                         //         MST_SECTION
                         //  WHERE  COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID = COR_TRN_CHALLAN.TRN_CHALLAN_ID        
                         //  AND    COR_TRN_DEDUCTEE_DETAILS.SECTION_ID     = MST_NONSALARY_TAX_SLAB.SECTION_ID 
                         //  AND    COR_TRN_DEDUCTEE_DETAILS.SECTION_ID     = MST_SECTION.SECTION_ID  
                         @"WHERE  COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE BETWEEN MST_NONSALARY_TAX_SLAB.FROM_DATE AND MST_NONSALARY_TAX_SLAB.TO_DATE  
                           AND    COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE IS NOT NULL 
                           AND    COR_TRN_DEDUCTEE_DETAILS.BATCH_HEADER_ID    = " + BasicInfoID + " " +
                         @"AND    (MST_VERIFIED_PAN.VERIFIED_STATUS IN(1, 2) OR COR_TRN_DEDUCTEE_DETAILS.REASON_ID IN (3,7,15,4,12,17,20) )
                           AND    COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT < " + strArgumnets + " ";
                }
                else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                {
                    string strArgumnets = @"IIF(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANNOTAVBL' " +
                                           @"OR COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANAPPLIED' " +
                                           @"OR COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANINVALID' " +
                                           @"OR MST_VERIFIED_PAN.VERIFIED_STATUS IN(1, 2), " +
                                           @"ROUND(VAL(FORMAT((COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.INVALID_PAN_RATE ) / 100, '0')),0), 
                                    IIF(MID(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN, 4, 1) = 'P' OR MID(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN, 4, 1) = 'H', " +
                                           @"ROUND(VAL(FORMAT((COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.NON_COMPANY_RATE ) / 100, '0')),0), 
                                    ROUND(VAL(FORMAT((COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.COMPANY_RATE ) / 100, '0')),0)))";
                    //
                    strSQL = @"SELECT COR_TRN_CHALLAN.SL_NO                  AS CHALLAN_SL_NO,
                                  COR_TRN_DEDUCTEE_DETAILS.SL_NO         AS DEDUCTEE_SL_NO,
                                  COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN  AS DEDUCTEE_PAN, 
                                  COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME AS DEDUCTEE_NAME, 
                                  MST_SECTION.SECTION_NO,
                                  COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 
                                  COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT,
                                  COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT, 
                                  IIF(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANNOTAVBL'
                                           OR COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANAPPLIED'
                                           OR COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANINVALID',
                                      MST_NONSALARY_TAX_SLAB.INVALID_PAN_RATE,  
                                           IIF(MID(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN, 4, 1) = 'P' OR MID(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN, 4, 1) = 'H', " +
                                                   @"MST_NONSALARY_TAX_SLAB.NON_COMPANY_RATE, 
                                               MST_NONSALARY_TAX_SLAB.COMPANY_RATE)
                                      )          AS RATE," +
                                      strArgumnets + "                                  AS ACTUAL_TAX_AMOUNT," +
                                      @"'" + strFAYear + "' AS FA_YEAR," +
                                      @"'" + strQuarter + "' AS QTR," +
                                      @"'" + strFormNo + @"' AS FORM_NO,
                                    '' AS IMPORT_DETAILS " +
                        @"FROM  ((((COR_TRN_DEDUCTEE_DETAILS 
                        INNER JOIN COR_TRN_CHALLAN
                            ON  COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID     = COR_TRN_CHALLAN.TRN_CHALLAN_ID)
                        INNER JOIN MST_NONSALARY_TAX_SLAB
                            ON  COR_TRN_DEDUCTEE_DETAILS.SECTION_ID = MST_NONSALARY_TAX_SLAB.SECTION_ID)  
                        INNER JOIN MST_SECTION
                            ON COR_TRN_DEDUCTEE_DETAILS.SECTION_ID     = MST_SECTION.SECTION_ID ) 
                        LEFT JOIN MST_VERIFIED_PAN
                            ON  COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = MST_VERIFIED_PAN.PAN) " +
                         //FROM   COR_TRN_DEDUCTEE_DETAILS,
                         //        MST_NONSALARY_TAX_SLAB,
                         //        COR_TRN_CHALLAN,
                         //        MST_SECTION
                         // WHERE  COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID = COR_TRN_CHALLAN.TRN_CHALLAN_ID        
                         // AND    COR_TRN_DEDUCTEE_DETAILS.SECTION_ID     = MST_NONSALARY_TAX_SLAB.SECTION_ID 
                         // AND    COR_TRN_DEDUCTEE_DETAILS.SECTION_ID     = MST_SECTION.SECTION_ID  
                         @"WHERE    COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE BETWEEN MST_NONSALARY_TAX_SLAB.FROM_DATE AND MST_NONSALARY_TAX_SLAB.TO_DATE  
                           AND    COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE IS NOT NULL 
                           AND    COR_TRN_DEDUCTEE_DETAILS.BATCH_HEADER_ID    = " + BasicInfoID + " " +
                         @"AND    (MST_VERIFIED_PAN.VERIFIED_STATUS IN(1, 2) OR COR_TRN_DEDUCTEE_DETAILS.REASON_ID IN (3,7,15,4,12,17,20) )
                           AND    COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT < " + strArgumnets + " ";
                }
                if (intSectionNo > 0)
                    strSQL = strSQL + " AND MST_SECTION.SECTION_ID =" + intSectionNo + " ";
                if (strDeducteeName != "")
                    strSQL = strSQL + " AND COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME LIKE '" + strDeducteeName + "%'";
                if (strDeducteePAN != "")
                    strSQL = strSQL + " AND COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN  LIKE '" + strDeducteePAN + "%'";

                strSQL = strSQL + @" ORDER BY COR_TRN_CHALLAN.SL_NO, COR_TRN_DEDUCTEE_DETAILS.SL_NO ";


                // FORM SELECTED
                //TextObject objtxtValue;

                //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToDate"];
                //objtxtValue.Text = "From : " + TdsMan.T_ReturnQuarterStartDate(strQuarter, strFAYear) + " To : " + TdsMan.T_ReturnQuarterEndDate(strQuarter, strFAYear);

                //string[,] strArry = { { "txtReportTitle", "Short Deduction (Correction Return)" },
                //                  { "txtCompanyTANNo",  strCompanyTAN } };
                //
                this.Cursor = Cursors.Default;
                //
                //rptService.J_PreviewReport(ref rptcls, TDSMAN.Classes.TDSMAN.T_pCurrentForm, strSQL, strArry);
                //RDLC Report
                string[,] strArryShortDeductionReport = {{"ReportHeader", "Short Deduction (Correction Return)" },
                                                        {"ReportCaption", strCompanyTAN + " FA. Year : " + strFAYear +" Qtr : " + strQuarter},
                                                        {"ReportFromToDate", "From : " + TdsMan.T_ReturnQuarterStartDate(strQuarter, strFAYear) + " To : " + TdsMan.T_ReturnQuarterEndDate(strQuarter, strFAYear) },
                                                        {"ReportFormNo", "Form No : " + strFormNo }
                                                               };
                J_PreviewReportRDLC("\\Reports\\crShortDeduction.rdlc", "DataSet1", strSQL, strArryShortDeductionReport);
            }
            catch (Exception err)
            {

            }
        }
