                                                                     ELSE CONVERT(CHAR(10),'07' + RIGHT(CONVERT(CHAR(10),DATEADD(MONTH, 1,CONVERT(DATETIME, TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE, 103)),103),8),103) 
