                                    " else 1 + DATEDIFF(MONTH,CONVERT(DATETIME, TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE, 103),CONVERT(DATETIME, TRN_CHALLAN.DEPOSIT_DATE, 103)) " +
                                    " end AS TOTAL_DELAY, " +
