        #region PrintLatePaymentRegular_RDLC
        public void PrintLatePaymentRegular_RDLC(long BasicInfoID, string strFormNo, string strQuarter, string strFAYear, string strDeducteeName, string strDeducteePAN, string strCompanyTAN, string ReportFooter)
        {
            //crLatePayment rptLatePayment = new crLatePayment();
            //rptcls = (ReportClass)rptLatePayment;
            //--
            //-- 2019/03/14
