        #region PrintLateDeductionRegular
        public void PrintLateDeductionRegular(long BasicInfoID, string strFormNo, string strQuarter, string strFAYear, string strDeducteeName, string strDeducteePAN, string strCompanyTAN, string ReportFooter)
        {
            crLateDeduction rptLateDeduction = new crLateDeduction();
            rptcls = (ReportClass)rptLateDeduction;
            //--
            string strTableName = "", strFieldName = "", strFieldPAN = "", strFieldId = "";
            if (strFormNo == T_FormNo.F24Q)
            {
                strTableName = "MST_EMPLOYEE"; strFieldName = "EMPLOYEE_NAME"; strFieldPAN = "EMPLOYEE_PAN"; strFieldId = "EMPLOYEE_ID";
            }
            else
            {
                strTableName = "MST_DEDUCTEE"; strFieldName = "DEDUCTEE_NAME"; strFieldPAN = "DEDUCTEE_PAN"; strFieldId = "DEDUCTEE_ID";
            }
            //
            //-- 
            
#region COMMENT
            //            strSQL = @"SELECT  TRN_CHALLAN.SL_NO                     AS CHALLAN_SL_NO,
//                               TRN_DEDUCTEE_DETAILS.SL_NO            AS DEDUCTEE_SL_NO," +
//                               strTableName + "." + strFieldPAN + "  AS DEDUCTEE_PAN, " +
//                               strTableName + "." + strFieldName + " AS DEDUCTEE_NAME, " +
//                              @"TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT  AS PAYMENT_AMOUNT,
//                               TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT AS TAX_DEPOSITED_AMOUNT,
//                               TRN_DEDUCTEE_DETAILS.PAYMENT_DATE AS PAYMENT_DATE,
//                               TRN_DEDUCTEE_DETAILS.PAYMENT_DATE AS DED_DUE_DATE, 
//                               TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE,
//                               1 + DATEDIFF('m'," + cmnService.J_SQLDBFormat(@"TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "," + cmnService.J_SQLDBFormat(@"TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + @") AS TOTAL_DELAY, 
//                               TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT * 0.01 * (
//                               1 + DATEDIFF('m'," + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "," + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + ")) AS LATE_FEE," +
//                              @"'" + strFAYear + "'  AS FA_YEAR," +
//                              @"'" + strQuarter + "' AS QTR," +
//                              @"'" + strFormNo + @"'  AS FORM_NO, 
//                                '' AS IMPORT_DETAILS," +
//                              @"'" + ReportFooter + @"' AS REPORT_FOOTER 
//                          FROM  TRN_DEDUCTEE_DETAILS,
//                                TRN_CHALLAN,
//                                TRN_BASIC_INFO," +
//                                strTableName + @"
//                          WHERE  TRN_DEDUCTEE_DETAILS.CHALLAN_ID = TRN_CHALLAN.CHALLAN_ID 
//                          AND    TRN_DEDUCTEE_DETAILS.PARTY_ID   = " + strTableName + "." + strFieldId + "  " +
//                         @"AND   TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID       = TRN_BASIC_INFO.BASIC_INFO_ID 
//                           AND   TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE IS NOT NULL 
//                           AND   TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE > TRN_DEDUCTEE_DETAILS.PAYMENT_DATE " +
            //                         @"AND   TRN_BASIC_INFO.BASIC_INFO_ID    = " + BasicInfoID + " ";
            #endregion
            if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                strSQL = @"SELECT  TRN_CHALLAN.SL_NO          AS CHALLAN_SL_NO,
                                       TRN_DEDUCTEE_DETAILS.SL_NO AS DEDUCTEE_SL_NO," +
                                   strTableName + "." + strFieldPAN + "  AS DEDUCTEE_PAN, " +
                                   strTableName + "." + strFieldName + " AS DEDUCTEE_NAME, " +
                                  @"TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT AS PAYMENT_AMOUNT,
                                       TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT AS TAX_DEPOSITED_AMOUNT,
                                       TRN_DEDUCTEE_DETAILS.PAYMENT_DATE AS PAYMENT_DATE, 
                                       TRN_DEDUCTEE_DETAILS.PAYMENT_DATE AS DED_DUE_DATE, 
                                       TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE, " +
                                   "1 + DATEDIFF(MONTH,CONVERT(DATETIME, TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 103),CONVERT(DATETIME, TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE, 103))  AS TOTAL_DELAY, " +
                                   "TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT * 0.01 * ( " +
                                   "1 + DATEDIFF(MONTH,CONVERT(DATETIME, TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 103),CONVERT(DATETIME, TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE, 103)))  AS LATE_FEE ," +
                              @"'" + strFAYear + "'  AS FA_YEAR," +
                              @"'" + strQuarter + "' AS QTR," +
                              @"'" + strFormNo + @"'  AS FORM_NO, 
                                '' AS IMPORT_DETAILS," +
                              @"'" + ReportFooter + @"' AS REPORT_FOOTER 
                           FROM    TRN_DEDUCTEE_DETAILS,                       
                                   TRN_CHALLAN, 
                                   TRN_BASIC_INFO," +
                                   strTableName + " " +
                         @"WHERE   TRN_DEDUCTEE_DETAILS.PARTY_ID   = " + strTableName + "." + strFieldId + "  " +
                         @"AND     TRN_DEDUCTEE_DETAILS.CHALLAN_ID = TRN_CHALLAN.CHALLAN_ID 
                              AND     TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID       = TRN_BASIC_INFO.BASIC_INFO_ID 
                              AND      TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE IS NOT NULL 
                              AND      TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE  > TRN_DEDUCTEE_DETAILS.PAYMENT_DATE
                              AND     TRN_BASIC_INFO.BASIC_INFO_ID    = " + BasicInfoID + " ";
            else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                strSQL = @"SELECT  TRN_CHALLAN.SL_NO          AS CHALLAN_SL_NO,
                                       TRN_DEDUCTEE_DETAILS.SL_NO AS DEDUCTEE_SL_NO," +
                                   strTableName + "." + strFieldPAN + "  AS DEDUCTEE_PAN, " +
                                   strTableName + "." + strFieldName + " AS DEDUCTEE_NAME, " +
                                  @"TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT AS PAYMENT_AMOUNT,
                                       TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT AS TAX_DEPOSITED_AMOUNT,
                                       TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, 
                                       TRN_DEDUCTEE_DETAILS.PAYMENT_DATE AS DED_DUE_DATE, 
                                       TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE, " +
                                   "1 + DATEDIFF('m'," + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "," + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + ") AS TOTAL_DELAY, " +
                                   "TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT * 0.01 * ( " +
                                   "1 + DATEDIFF('m'," + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "," + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + ")) AS LATE_FEE," +
                              @"'" + strFAYear + "'  AS FA_YEAR," +
                              @"'" + strQuarter + "' AS QTR," +
                              @"'" + strFormNo + @"'  AS FORM_NO, 
                                '' AS IMPORT_DETAILS," +
                              @"'" + ReportFooter + @"' AS REPORT_FOOTER 
                          FROM    TRN_DEDUCTEE_DETAILS,                       
                                  TRN_CHALLAN, 
                                  TRN_BASIC_INFO," +
                                   strTableName + " " +
                         @"WHERE   TRN_DEDUCTEE_DETAILS.PARTY_ID   = " + strTableName + "." + strFieldId + "  " +
                         @"AND     TRN_DEDUCTEE_DETAILS.CHALLAN_ID = TRN_CHALLAN.CHALLAN_ID 
                          AND      TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID       = TRN_BASIC_INFO.BASIC_INFO_ID 
                          AND      TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE IS NOT NULL 
                          AND      TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE  > TRN_DEDUCTEE_DETAILS.PAYMENT_DATE
                          AND      TRN_BASIC_INFO.BASIC_INFO_ID    = " + BasicInfoID + " ";
            if (strDeducteeName != "")
                strSQL = strSQL + " AND " + strTableName + "." + strFieldName + " LIKE '" + strDeducteeName + "%'";
            if ((strDeducteePAN != "") && (strDeducteeName != ""))
                strSQL = strSQL + " AND " + strTableName + "." + strFieldPAN + " LIKE '" + strDeducteePAN + "%'";

            strSQL = strSQL + @" ORDER BY TRN_CHALLAN.SL_NO, TRN_DEDUCTEE_DETAILS.SL_NO ";


            // FORM SELECTED
            TextObject objtxtValue;

            objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToDate"];
            objtxtValue.Text = "From : " + TdsMan.T_ReturnQuarterStartDate(strQuarter, strFAYear) + " To : " + TdsMan.T_ReturnQuarterEndDate(strQuarter, strFAYear);

            string[,] strArry = {{"txtReportTitle","Late Deduction"},
                                 {"txtCompanyTANNo",strCompanyTAN}};
            //
            this.Cursor = Cursors.Default;
            //
            rptService.J_PreviewReport(ref rptcls, TDSMAN.Classes.TDSMAN.T_pCurrentForm, strSQL, strArry);
        }
