        #region PrintLateFineRegularReturn
        public void PrintLateFineRegularReturn(string strFormNo, string strQuarter, string strFAYear, string strCompanyTAN, string strScheduleLastDate, string strNoOfDelayDays, string strLateFee, string strFeeAlreadyPaid, string strPayableFee, string strDateofFiling)
        {
            crLateFine rptLateFine = new crLateFine();
            rptcls = (ReportClass)rptLateFine;
            //--
            // FORM SELECTED
            TextObject objtxtValue;
            //
            //strLateFee = Convert.ToDouble(strLateFee).ToString();
            //
            objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToDate"];
            objtxtValue.Text = "From : " + TdsMan.T_ReturnQuarterStartDate(strQuarter, strFAYear) + " To : " + TdsMan.T_ReturnQuarterEndDate(strQuarter, strFAYear);
            //
            string[,] strArry = { { "txtReportTitle", "Late Fine" },
                                  { "txtCompanyTANNo",  strCompanyTAN },
                                  { "txtFormNo", strFormNo },
                                  { "txtQuarter", strQuarter },
                                  { "txtFAYear", strFAYear },
                                  { "txtScheduleLastDate", strScheduleLastDate },
                                  { "txtNoOfDelayDays", strNoOfDelayDays },
                                  { "txtLateFee", strLateFee },
                                  { "txtFeeAlreadyPaid", strFeeAlreadyPaid },
                                  { "txtPayableFee", strPayableFee },
                                  { "txtDateofFiling", strDateofFiling } };
            //
            this.Cursor = Cursors.Default;
            //
            DataSet dsLateFine = new DataSet();
            DataTable dtLateFine = new DataTable();

            dtLateFine.Columns.Add("FormNo", typeof(System.String));
            dtLateFine.Columns.Add("Quarter", typeof(System.String));
            dtLateFine.Columns.Add("FAYear", typeof(System.String));
            dtLateFine.Columns.Add("ScheduleLastDate", typeof(System.String));
            dtLateFine.Columns.Add("NoOfDelayDays", typeof(System.String));
            dtLateFine.Columns.Add("LateFee", typeof(System.String));
            dtLateFine.Columns.Add("FeeAlreadyPaid", typeof(System.String));
            dtLateFine.Columns.Add("PayableFee", typeof(System.String));
            dtLateFine.Columns.Add("DateofFiling", typeof(System.String));
            //dtLateFine.Columns.Add("FormNo", typeof(System.String));
            dtLateFine.Rows.Add(strFormNo, strQuarter, strFAYear, strScheduleLastDate, strNoOfDelayDays, strLateFee, strFeeAlreadyPaid, strPayableFee, strDateofFiling);
            dsLateFine.Tables.Add(dtLateFine);
            //
            rptService.J_PreviewReport(ref rptcls, TDSMAN.Classes.TDSMAN.T_pCurrentForm, dsLateFine, strArry);
        }
