        #region PrintInvalidPANChecking
        public void PrintInvalidPANChecking(long BasicInfoID, string strFormNo, int intCompanyId, int intAsstId, string strFAYear, string strQuarter, string strDeducteeName, string strDeducteePAN)
        {
            crDeducteeInvalidPAN rptDeducteeInvalidPAN = new crDeducteeInvalidPAN();
            rptcls = (ReportClass)rptDeducteeInvalidPAN;

            //--
            string strTableName = "", strFieldName = "", strFieldPAN = "", strFieldId = "", strArgumnets = "";
            if (strFormNo == T_FormNo.F24Q)
            {
                strTableName = "MST_EMPLOYEE"; strFieldName = "EMPLOYEE_NAME"; strFieldPAN = "EMPLOYEE_PAN"; strFieldId = "EMPLOYEE_ID";
            }
            else
            {
                strTableName = "MST_DEDUCTEE"; strFieldName = "DEDUCTEE_NAME"; strFieldPAN = "DEDUCTEE_PAN"; strFieldId = "DEDUCTEE_ID";
            }
            //
            strSQL = @" SELECT    MST_COMPANY.COMPANY_NAME,
                                  MST_COMPANY.TAN_NO,
                                  MST_ASSESSMENT.ASST_YEAR,
                                  TRN_CHALLAN.SL_NO,
                                  TRN_DEDUCTEE_DETAILS.SL_NO," +
                                   strTableName + "." + strFieldPAN + " AS DEDUCTEE_PAN," +
                                   strTableName + "." + strFieldName + " AS DEDUCTEE_NAME," +
                                  @"TRN_BASIC_INFO.QTR
                        FROM      TRN_BASIC_INFO,
                                  TRN_CHALLAN,
                                  TRN_DEDUCTEE_DETAILS," +
                                  strTableName + "," +
                                 @"MST_COMPANY,
                                  MST_ASSESSMENT 
                        WHERE     TRN_BASIC_INFO.BASIC_INFO_ID = TRN_CHALLAN.BASIC_INFO_ID
                        AND       TRN_CHALLAN.CHALLAN_ID       = TRN_DEDUCTEE_DETAILS.CHALLAN_ID 
                        AND       TRN_DEDUCTEE_DETAILS.PARTY_ID=  " + strTableName + "." + strFieldId + "  " +
                       @"AND      TRN_BASIC_INFO.COMPANY_ID    = MST_COMPANY.COMPANY_ID 
                        AND       TRN_BASIC_INFO.ASST_ID       = MST_ASSESSMENT.ASST_ID 
                        AND       IIF(" + strTableName + "." + strFieldPAN + " <> 'PANNOTAVBL' " +
                                     @"AND " + strTableName + "." + strFieldPAN + " <> 'PANAPPLIED' " +
                                     @"AND " + strTableName + "." + strFieldPAN + " <> 'PANINVALID' " +
                                     @"AND MID(" + strTableName + "." + strFieldPAN + ", 4, 1) <> 'C' " +
                                     @"AND MID(" + strTableName + "." + strFieldPAN + ", 4, 1) <> 'P' " +
                                     @"AND MID(" + strTableName + "." + strFieldPAN + ", 4, 1) <> 'H' " +
                                     @"AND MID(" + strTableName + "." + strFieldPAN + ", 4, 1) <> 'F' " +
                                     @"AND MID(" + strTableName + "." + strFieldPAN + ", 4, 1) <> 'A' " +
                                     @"AND MID(" + strTableName + "." + strFieldPAN + ", 4, 1) <> 'T' " +
                                     @"AND MID(" + strTableName + "." + strFieldPAN + ", 4, 1) <> 'B' " +
                                     @"AND MID(" + strTableName + "." + strFieldPAN + ", 4, 1) <> 'L' " +
                                     @"AND MID(" + strTableName + "." + strFieldPAN + ", 4, 1) <> 'J' " +
                                     @"AND MID(" + strTableName + "." + strFieldPAN + ", 4, 1) <> 'G' " +
                                     @",'INVALID'
                                     ,'VALID') ='INVALID' 
                        AND       TRN_BASIC_INFO.BASIC_INFO_ID = " + BasicInfoID;
            //if (intCompanyId > 0)
            //    strSQL = strSQL + " AND TRN_BASIC_INFO.COMPANY_ID = " + intCompanyId + "  ";
            //if (intAsstId > 0)
            //    strSQL = strSQL + " AND TRN_BASIC_INFO.ASST_ID = " + intAsstId + "  ";
            //if (strQuarter != "")
            //    strSQL = strSQL + " AND TRN_BASIC_INFO.QTR = '" + strQuarter + "' ";
            //if (strFormNo != "")
            //    strSQL = strSQL + " AND TRN_BASIC_INFO.FORM_NO = '" + strFormNo + "' ";
            if (strDeducteeName != "")
                strSQL = strSQL + " AND MST_DEDUCTEE.DEDUCTEE_NAME LIKE '" + cmnService.J_ReplaceQuote(strDeducteeName) + "%'";
            if (strDeducteePAN != "")
                strSQL = strSQL + " AND   MST_DEDUCTEE.DEDUCTEE_PAN  LIKE '" + cmnService.J_ReplaceQuote(strDeducteePAN) + "%'";

            strSQL = strSQL + @" ORDER BY MST_DEDUCTEE.DEDUCTEE_NAME ";

            // FORM SELECTED
            TextObject objtxtValue;

            objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFromToDate"];
            objtxtValue.Text = "From : " + TdsMan.T_ReturnQuarterStartDate(strQuarter, strFAYear) + " To : " + TdsMan.T_ReturnQuarterEndDate(strQuarter, strFAYear);

            string[,] strArry = {{"txtReportTitle", "Invalid PAN Structure" },
                                 {"txtFormNo", strFormNo}};
            //
            this.Cursor = Cursors.Default;
            //
            rptService.J_PreviewReport(ref rptcls, TDSMAN.Classes.TDSMAN.T_pCurrentForm, strSQL, strArry);
        }
        #endregion         

