                    //"        TRN_DEDUCTEE_DETAILS.PARTY_ID       AS PARTY_ID," +
                                 "        0       AS PARTY_ID," +
                                 "        SUM(COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT) AS DEDUCTEE_TOTAL," +
                                 "        COR_TRN_CHALLAN.BOOK_ENTRY              AS BOOK_ENTRY," +
                                "        '" + TDSMAN.Classes.TDSMAN.T_CERTIFICATE_TDSMAN_FOOTER_ENABLE_OPTION + "' AS CERTIFICATE_TDSMAN_FOOTER_ENABLE_OPTION," +
                                "        '" + TDSMAN.Classes.TDSMAN.T_CERTIFICATE_SECOND_FOOTER_ENABLE_OPTION + "' AS CERTIFICATE_SECOND_FOOTER_ENABLE_OPTION," +
                                "        '" + TDSMAN.Classes.TDSMAN.T_CERTIFICATE_SECOND_FOOTER_TEXT + "'          AS CERTIFICATE_SECOND_FOOTER_TEXT " +
                                 "FROM   (((((COR_TRN_COMPANY INNER JOIN MST_STATE " +
                                 "              ON COR_TRN_COMPANY.STATE_ID       = MST_STATE.STATE_ID) " +
                                 "        INNER JOIN COR_HDR_BATCH " +
                                 "             ON COR_TRN_COMPANY.BATCH_HEADER_ID = COR_HDR_BATCH.BATCH_HEADER_ID) " +
                                 "        INNER JOIN MST_ASSESSMENT " +
                                 "             ON COR_HDR_BATCH.ASST_ID           = MST_ASSESSMENT.ASST_ID) " +
                                 "        INNER JOIN COR_TRN_CHALLAN " +
                                 "             ON COR_HDR_BATCH.BATCH_HEADER_ID   = COR_TRN_CHALLAN.BATCH_HEADER_ID) " +
                                 "        INNER JOIN COR_TRN_DEDUCTEE_DETAILS " +
                                 "             ON COR_TRN_CHALLAN.TRN_CHALLAN_ID  = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID) " +
                                 "WHERE  COR_HDR_BATCH.BATCH_HEADER_ID            = " + lngBasicInfoID + " " +
                                 "AND    COR_TRN_DEDUCTEE_DETAILS.NAME_PAN       IN     (" + J_GenerateDataGridViewConcateItems(grdvDescription) + ") " +
                                 "GROUP BY COR_TRN_COMPANY.TRN_COMPANY_ID," +
                                 "       COR_TRN_COMPANY.COMPANY_NAME," +
                                 "       COR_TRN_COMPANY.TAN_NO," +
                                 "       COR_TRN_COMPANY.PAN_NO," +
                                 "       COR_TRN_COMPANY.ADDRESS1," +
                                 "       COR_TRN_COMPANY.ADDRESS2," +
                                 "       COR_TRN_COMPANY.ADDRESS3," +
                                 "       COR_TRN_COMPANY.ADDRESS4," +
                                 "       COR_TRN_COMPANY.ADDRESS5," +
                                 "       COR_TRN_COMPANY.STATE_ID," +
                                 "       MST_STATE.STATE_NAME," +
                                 "       COR_TRN_COMPANY.PIN_CODE," +
                                 "       COR_TRN_COMPANY.PHONE," +
                                 "       COR_TRN_COMPANY.STD," +
                                 "       COR_TRN_COMPANY.EMAIL," +
                    //"       MST_COMPANY.CIT_TDS_ADDRESS," +
                    //"       MST_COMPANY.CIT_TDS_CITY," +
                    //"       MST_COMPANY.CIT_TDS_PINCODE," +
                                 "       COR_TRN_COMPANY.PERSON_NAME," +
                                 "       COR_TRN_COMPANY.FATHER_NAME," +
                                 "       COR_TRN_COMPANY.DESIGNATION," +
                                 "       MST_ASSESSMENT.ASST_YEAR," +
                                 "       MST_ASSESSMENT.START_DATE," +
                                 "       MST_ASSESSMENT.END_DATE," +
                    //"       MST_DEDUCTEE.DEDUCTEE_ID," +
                                 "       COR_TRN_DEDUCTEE_DETAILS.NAME_PAN," +
                                 "       COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_CODE," +
                                 "       COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME," +
                                 "       COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN," +
                    //"       MST_DEDUCTEE.ADDRESS1," +
                    //"       MST_DEDUCTEE.ADDRESS2," +
                    //"       MST_DEDUCTEE.ADDRESS3," +
                    //"       MST_DEDUCTEE.ADDRESS4," +
                    //"       MST_DEDUCTEE.ADDRESS5," +
                    //"       MST_DEDUCTEE.STATE_ID," +
                    //"       MST_STATE_D.STATE_NAME," +
                    //"       MST_DEDUCTEE.PIN_CODE," +
                    //"       MST_DEDUCTEE.MOBILE_NO," +
                    //"       MST_DEDUCTEE.EMAIL," +
                                 "       COR_TRN_CHALLAN.TRN_CHALLAN_ID," +
                                 "       COR_TRN_CHALLAN.SECTION_ID," +
                                 "       COR_TRN_CHALLAN.DEPOSIT_DATE," +
                                 "       COR_TRN_CHALLAN.BSR_CODE," +
                                 "       COR_TRN_CHALLAN.CHALLAN_NO," +
                                 "       COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO," +
                    //"       TRN_DEDUCTEE_DETAILS.PARTY_ID," +
                                 "       COR_TRN_CHALLAN.BOOK_ENTRY " +
                                 "ORDER BY COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME," +
                                 "       COR_TRN_CHALLAN.SECTION_ID,COR_TRN_CHALLAN.DEPOSIT_DATE";
                //------------------------------------------------- 
                //-- SUB REPORTS
                //-------------------------------------------------
                // FOR SUMMARY OF PAYMENT
                string strSubRptSummaryOfPayment = "SELECT COR_TRN_CHALLAN.TRN_CHALLAN_ID          AS TRN_CHALLAN_ID," +
                                            "              COR_TRN_DEDUCTEE_DETAILS.NAME_PAN       AS PARTY_ID," +
                                            "              COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT AS PAYMENT_AMOUNT," +
                                            "              COR_TRN_CHALLAN.SECTION_ID              AS SECTION_ID," +
                                            "              MST_SECTION.SECTION_NO                  AS SECTION_NO," +
                                            "              MST_SECTION.SECTION_NAME                AS SECTION_NAME," +
                                            "              MST_SECTION.SECTION_DESCRIPTION         AS SECTION_DESCRIPTION," +
                                            "              COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE   AS PAYMENT_DATE " +
                                            "       FROM   COR_HDR_BATCH," +
                                            "              COR_TRN_CHALLAN," +
                                            "              COR_TRN_DEDUCTEE_DETAILS," +
                                            "              MST_SECTION " +
                                            "       WHERE  COR_HDR_BATCH.BATCH_HEADER_ID      = COR_TRN_CHALLAN.BATCH_HEADER_ID " +
                                            "       AND    COR_TRN_CHALLAN.TRN_CHALLAN_ID     = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID " +
                                            //"       AND    COR_TRN_CHALLAN.SECTION_ID         = MST_SECTION.SECTION_ID " +
                                            "       AND    COR_TRN_DEDUCTEE_DETAILS.SECTION_ID= MST_SECTION.SECTION_ID " +
                                            "       AND    COR_HDR_BATCH.BATCH_HEADER_ID      = " + lngBasicInfoID + " " +
                                            "       AND    COR_TRN_DEDUCTEE_DETAILS.NAME_PAN IN (" + J_GenerateDataGridViewConcateItems(grdvDescription) + ") " +
                                            "       ORDER BY COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE";
                //------------------------------------------------- 
                // FOR SUMMARY OF TAX DEDUCTED
                string strSubRptChlnDetails = "SELECT COR_TRN_DEDUCTEE_DETAILS.NAME_PAN                  AS PARTY_ID," +
                                    "                 COR_TRN_CHALLAN.SECTION_ID                         AS SECTION_ID," +
                                    "                 COR_HDR_BATCH.QTR                                  AS QTR," +
                                    "                 COR_HDR_BATCH.RECEIPT_NO                           AS RECEIPT_NO," +
                                    "                 SUM(COR_TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT)         AS TOTAL_AMOUNT," +
                                    "                 SUM(COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT) AS TAX_DEPOSITED_AMOUNT " +
                                    "          FROM   COR_HDR_BATCH," +
                                    "                 COR_TRN_CHALLAN," +
                                    "                 COR_TRN_DEDUCTEE_DETAILS " +
                                    "          WHERE  COR_HDR_BATCH.BATCH_HEADER_ID     = COR_TRN_CHALLAN.BATCH_HEADER_ID " +
                                    "          AND    COR_TRN_CHALLAN.TRN_CHALLAN_ID    = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID " +
                                    "          AND    COR_HDR_BATCH.BATCH_HEADER_ID     = " + lngBasicInfoID + " " +
                                    "          AND    COR_TRN_DEDUCTEE_DETAILS.NAME_PAN IN (" + J_GenerateDataGridViewConcateItems(grdvDescription) + ") " +
                                    "          GROUP BY " +
                                    "                 COR_TRN_DEDUCTEE_DETAILS.NAME_PAN," +
                                    "                 COR_TRN_DEDUCTEE_DETAILS.NAME_PAN," +
                                    "                 COR_TRN_CHALLAN.SECTION_ID," +
                                    "                 COR_HDR_BATCH.RECEIPT_NO," +
                                    "                 COR_HDR_BATCH.QTR";
                //------------------------------------------------- 
                // FOR BOOK ENTRY
                string strSubRptBookEntry = "SELECT  COR_TRN_COMPANY.TRN_COMPANY_ID      AS COMPANY_ID," +
                    "                                COR_TRN_DEDUCTEE_DETAILS.NAME_PAN   AS DEDUCTEE_ID," +
                    "                                COR_TRN_CHALLAN.TRN_CHALLAN_ID      AS CHALLAN_ID," +
                    "                                COR_TRN_CHALLAN.SECTION_ID          AS SECTION_ID," +
                    "                                COR_TRN_CHALLAN.DEPOSIT_DATE        AS DEPOSIT_DATE," +
                    "                                COR_TRN_CHALLAN.BSR_CODE            AS BSR_CODE," +
                    "                                COR_TRN_CHALLAN.CHALLAN_NO          AS CHALLAN_NO," +
                    "                                COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO AS TRANSFER_VOUCHER_NO," +
                    "                                0                                   AS PARTY_ID," +
                    "                                SUM(COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT) AS DEDUCTEE_TOTAL," +
                    "                                COR_TRN_CHALLAN.BOOK_ENTRY          AS BOOK_ENTRY " +
                    "                        FROM   (((COR_TRN_COMPANY " +
                    "                                  INNER JOIN COR_HDR_BATCH " +
                    "                                  ON COR_TRN_COMPANY.BATCH_HEADER_ID = COR_HDR_BATCH.BATCH_HEADER_ID) " +
                    "                                  INNER JOIN COR_TRN_CHALLAN " +
                    "                                  ON  COR_TRN_CHALLAN.BATCH_HEADER_ID   = COR_HDR_BATCH.BATCH_HEADER_ID) " +
                    "                                  INNER JOIN COR_TRN_DEDUCTEE_DETAILS " +
                    "                                  ON COR_TRN_CHALLAN.TRN_CHALLAN_ID        =  COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID) " +
                    "                        WHERE  COR_TRN_CHALLAN.BOOK_ENTRY            = 1 " +
                    "                        AND    COR_HDR_BATCH.BATCH_HEADER_ID         = " + lngBasicInfoID + " " +
                    "                        AND    COR_TRN_DEDUCTEE_DETAILS.NAME_PAN IN (" + J_GenerateDataGridViewConcateItems(grdvDescription) + ") " +
                    "                        GROUP BY COR_TRN_COMPANY.TRN_COMPANY_ID," +
                    //"                                MST_DEDUCTEE.DEDUCTEE_ID," +
                    "                                COR_TRN_DEDUCTEE_DETAILS.NAME_PAN," +
                    "                                COR_TRN_CHALLAN.TRN_CHALLAN_ID," +
                    "                                COR_TRN_CHALLAN.SECTION_ID," +
                    "                                COR_TRN_CHALLAN.DEPOSIT_DATE," +
                    "                                COR_TRN_CHALLAN.BSR_CODE," +
                    "                                COR_TRN_CHALLAN.CHALLAN_NO," +
                    "                                COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO," +
                    "                                COR_TRN_DEDUCTEE_DETAILS.NAME_PAN," +
                    "                                COR_TRN_CHALLAN.BOOK_ENTRY " +
                    "                         ORDER BY COR_TRN_DEDUCTEE_DETAILS.NAME_PAN," +
                    "                                COR_TRN_CHALLAN.SECTION_ID,COR_TRN_CHALLAN.DEPOSIT_DATE";
                // FOR ANNEXTURE
                string strSubRptSummaryOfPaymentAnnexture = "SELECT COR_TRN_CHALLAN.TRN_CHALLAN_ID  AS CHALLAN_ID," +
                                            "              COR_TRN_DEDUCTEE_DETAILS.NAME_PAN        AS PARTY_ID," +
                                            "              COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT AS PAYMENT_AMOUNT," +
                                            "              COR_TRN_CHALLAN.SECTION_ID              AS SECTION_ID," +
                                            "              MST_SECTION.SECTION_NO                  AS SECTION_NO," +
                                            "              MST_SECTION.SECTION_NAME                AS SECTION_NAME," +
                                            "              MST_SECTION.SECTION_DESCRIPTION         AS SECTION_DESCRIPTION," +
                                            "              COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE   AS PAYMENT_DATE," +
                                            "              COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME  AS DEDUCTEE_NAME," +
                                            "              COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN   AS DEDUCTEE_PAN," +
                                            "              MST_ASSESSMENT.ASST_YEAR                AS ASST_YEAR " +
                                            "       FROM   COR_HDR_BATCH," +
                                            "              COR_TRN_CHALLAN," +
                                            "              COR_TRN_DEDUCTEE_DETAILS," +
                                            "              MST_SECTION," +
                    //"              MST_DEDUCTEE," +
                                            "              MST_ASSESSMENT " +
                                            "       WHERE  COR_HDR_BATCH.BATCH_HEADER_ID  = COR_TRN_CHALLAN.BATCH_HEADER_ID " +
                                            "       AND    COR_TRN_CHALLAN.TRN_CHALLAN_ID = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID " +
                                            "       AND    COR_TRN_CHALLAN.SECTION_ID     = MST_SECTION.SECTION_ID " +
                    //"       AND    COR_TRN_DEDUCTEE_DETAILS.PARTY_ID = MST_DEDUCTEE.DEDUCTEE_ID " +
                                            "       AND    COR_HDR_BATCH.ASST_ID        = MST_ASSESSMENT.ASST_ID " +
                                            "       AND    COR_HDR_BATCH.BATCH_HEADER_ID  = " + lngBasicInfoID + " " +
                                            "       AND    COR_TRN_DEDUCTEE_DETAILS.NAME_PAN IN (" + J_GenerateDataGridViewConcateItems(grdvDescription) + ") " +
                                            "       ORDER BY COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE";
                // FOR BOOK ENTRY
                string strSubRptChallanEntry = "SELECT  COR_TRN_COMPANY.TRN_COMPANY_ID      AS COMPANY_ID," +
                        "                               COR_TRN_DEDUCTEE_DETAILS.NAME_PAN   AS DEDUCTEE_ID," +
                        "                               COR_TRN_CHALLAN.TRN_CHALLAN_ID      AS CHALLAN_ID," +
                        "                               COR_TRN_CHALLAN.SECTION_ID          AS SECTION_ID," +
                        "                               COR_TRN_CHALLAN.DEPOSIT_DATE        AS DEPOSIT_DATE," +
                        "                               COR_TRN_CHALLAN.BSR_CODE            AS BSR_CODE," +
                        "                               COR_TRN_CHALLAN.CHALLAN_NO          AS CHALLAN_NO," +
                        "                               COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO AS TRANSFER_VOUCHER_NO," +
                        "                               COR_TRN_DEDUCTEE_DETAILS.NAME_PAN   AS PARTY_ID," +
                        "                               SUM(COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT) AS DEDUCTEE_TOTAL," +
                        "                               COR_TRN_CHALLAN.BOOK_ENTRY          AS BOOK_ENTRY " +
                        "                       FROM   (((COR_TRN_COMPANY INNER JOIN COR_HDR_BATCH " +
                        "                                   ON COR_TRN_COMPANY.BATCH_HEADER_ID = COR_HDR_BATCH.BATCH_HEADER_ID) " +
                        "                               INNER JOIN COR_TRN_CHALLAN  " +
                        "                                   ON COR_HDR_BATCH.BATCH_HEADER_ID   = COR_TRN_CHALLAN.BATCH_HEADER_ID) " +
                        "                               INNER JOIN COR_TRN_DEDUCTEE_DETAILS " +
                        "                                   ON COR_TRN_CHALLAN.TRN_CHALLAN_ID  = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID) " +
                    //"                               INNER JOIN MST_DEDUCTEE  " +
                    //"                                   ON TRN_DEDUCTEE_DETAILS.PARTY_ID   = MST_DEDUCTEE.DEDUCTEE_ID) " +
                        "                       WHERE  COR_TRN_CHALLAN.BOOK_ENTRY        = 0 " +
                        "                       AND    COR_HDR_BATCH.BATCH_HEADER_ID   = " + lngBasicInfoID + " " +
                        "                       AND    COR_TRN_DEDUCTEE_DETAILS.NAME_PAN IN (" + J_GenerateDataGridViewConcateItems(grdvDescription) + ") " +
                        "                       GROUP BY COR_TRN_COMPANY.TRN_COMPANY_ID," +
                    //"                              MST_DEDUCTEE.DEDUCTEE_ID," +
                        "                              COR_TRN_CHALLAN.TRN_CHALLAN_ID," +
                        "                              COR_TRN_CHALLAN.SECTION_ID," +
                        "                              COR_TRN_CHALLAN.DEPOSIT_DATE," +
                        "                              COR_TRN_CHALLAN.BSR_CODE," +
                        "                              COR_TRN_CHALLAN.CHALLAN_NO," +
                        "                              COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO," +
                    //"                              COR_TRN_DEDUCTEE_DETAILS.PARTY_ID," +
                        "                              COR_TRN_DEDUCTEE_DETAILS.NAME_PAN," +
                        "                              COR_TRN_CHALLAN.BOOK_ENTRY " +
                        "                       ORDER BY " +
                    //"                              MST_DEDUCTEE.DEDUCTEE_ID," +
                        "                              COR_TRN_CHALLAN.SECTION_ID,COR_TRN_CHALLAN.DEPOSIT_DATE";
                //-----------------------------------------------------------------------
                TextObject objtxtValue;
                if (TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 4) == "Q1")
                {
                    //TdsMan.T_ReturnQuarterEndDate(cmbQuarter.Text, cmbFinancialYear.Text)
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtStartDate"];
                    objtxtValue.Text = TdsMan.T_ReturnQuarterStartDate(TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 4), TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 2));
                    //--
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtEndDate"];
                    objtxtValue.Text = TdsMan.T_ReturnQuarterEndDate(TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 4), TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 2));
                }
                else if (TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 4) == "Q2")
                {
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtStartDate"];
                    objtxtValue.Text = TdsMan.T_ReturnQuarterStartDate(TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 4), TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 2));
                    //--
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtEndDate"];
                    objtxtValue.Text = TdsMan.T_ReturnQuarterEndDate(TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 4), TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 2));
                }
                else if (TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 4) == "Q3")
                {
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtStartDate"];
                    objtxtValue.Text = TdsMan.T_ReturnQuarterStartDate(TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 4), TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 2));
                    //--
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtEndDate"];
                    objtxtValue.Text = TdsMan.T_ReturnQuarterEndDate(TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 4), TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 2));
                }
                else if (TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 4) == "Q4")
                {
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtStartDate"];
                    objtxtValue.Text = TdsMan.T_ReturnQuarterStartDate(TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 4), TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 2));
                    //--
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtEndDate"];
                    objtxtValue.Text = TdsMan.T_ReturnQuarterEndDate(TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 4), TdsMan.T_GenerateDataGridViewSelectedItem(grdvDescription1, 2));
                }
                //--
                //--
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtPlace"];
                objtxtValue.Text = txtTextBox1.Text;
                //--
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtDate"];
                objtxtValue.Text = txtTextBox2.Text;
                //--
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtDesignation"];
                //objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT DESIGNATION FROM MST_COMPANY WHERE COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo3, cmbCombo3.SelectedIndex))));
                objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT DESIGNATION FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID = " + lngBasicInfoID));
                //--
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFullName"];
                //objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT PERSON_NAME FROM MST_COMPANY WHERE COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo3, cmbCombo3.SelectedIndex))));
                objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT PERSON_NAME FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID = " + lngBasicInfoID));
                //--
                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtCITDesignation"];
                objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT CIT_DESIGNATION FROM MST_CIT_DETAILS WHERE CIT_ID = " + Convert.ToInt32(Support.GetItemData(cmbComparisonCombo1, cmbComparisonCombo1.SelectedIndex))));
                //--
