                    strSQLPAN = "SELECT COR_TRN_COMPANY.PAN_NO AS PAN_NO" +
                      "     FROM   COR_HDR_BATCH," +
                      "            COR_TRN_COMPANY " +
                      "     WHERE  COR_HDR_BATCH.BATCH_HEADER_ID = COR_TRN_COMPANY.BATCH_HEADER_ID" +
                      "     AND    COR_HDR_BATCH.BATCH_HEADER_ID = " + BasicInfoBatchID + " ";
