                    //objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //
                    strSQLFAYear = "SELECT MST_ASSESSMENT.FA_YEAR AS FA_YEAR" +
                        "     FROM   COR_HDR_BATCH," +
                        "            MST_ASSESSMENT " +
                        "     WHERE  COR_HDR_BATCH.ASST_ID         = MST_ASSESSMENT.ASST_ID" +
                        "     AND    COR_HDR_BATCH.BATCH_HEADER_ID = " + BasicInfoBatchID + " ";
                    //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFY"];
                    //objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //
                    strSQLAsstYear = "SELECT MST_ASSESSMENT.ASST_YEAR AS ASST_YEAR" +
                        "     FROM   COR_HDR_BATCH," +
                        "            MST_ASSESSMENT " +
                        "     WHERE  COR_HDR_BATCH.ASST_ID         = MST_ASSESSMENT.ASST_ID" +
                        "     AND    COR_HDR_BATCH.BATCH_HEADER_ID = " + BasicInfoBatchID + " ";
                    //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtAY"];
                    //objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //
                    strSQLFormNo = "SELECT FORM_NO " +
                        "     FROM   COR_HDR_BATCH " +
                        "     WHERE  BATCH_HEADER_ID = " + BasicInfoBatchID + " ";
                    //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFormNo"];
                    //objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //
                    //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtType"];
                    //objtxtValue.Text = Convert.ToString("Correction return");
                    strType = "Correction Return";
                    //
                    #endregion
                    //
                }
                //
                if (strCSVPath == "")
                {
                    //string[,] strArry = { { "txtReportTitle", "Valid PAN(s)" } };
                    //if (Regular == null)
                    //    rptService.J_PreviewReport(ref rptcls, TDSMAN.Classes.TDSMAN.T_pCurrentForm, strQueryString, strArry);
                    //else
                    //    rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                    ////                   
                    string[,] strArryUnmatchedNamesReport = {{"HeaderReport", "Valid PAN(s)" },
                                                        {"HeaderCompanyName",Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQLCompany))},
                                                        {"HeaderTAN",Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQLTAN))},
                                                        {"HeaderPAN",Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQLPAN))},
                                                        {"HeaderFormNo",Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQLFormNo))},
                                                        {"HeaderFaYear",Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQLFAYear))},
                                                        {"HeaderAssessmentYear",Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQLAsstYear))},
                                                        {"HeaderType",strType}
                                                               };
                    //if (Regular == null)
                    //    //rptService.J_PreviewReport(ref rptcls, TDSMAN.Classes.TDSMAN.T_pCurrentForm, strQueryString, strArry);
                    //    J_PreviewReportRDLC("\\Reports\\crUnmatchedNames.rdlc", "DataSet1", strQueryString, strArryUnmatchedNamesReport);
                    //else
                    //    //rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
                    //    J_PreviewReportRDLC("\\Reports\\crUnmatchedNames.rdlc", "DataSet1", strQueryString, strArryUnmatchedNamesReport);
                    TrnBulkPANNameValidationImprovedVersion_New BulkPANNameValidationImprovedVersion = new TrnBulkPANNameValidationImprovedVersion_New();
                    J_PreviewReportRDLC(BulkPANNameValidationImprovedVersion,"\\Reports\\crUnmatchedNames.rdlc", "DataSet1", strQueryString, strArryUnmatchedNamesReport);
                }
                else
                {
                    ExportToCSV(strQueryString, strCSVPath);
                }
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
