                      "     AND    COR_HDR_BATCH.BATCH_HEADER_ID = " + BasicInfoBatchID + " ";
                    //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtPAN"];
                    //objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //
                    strSQLFAYear = "SELECT MST_ASSESSMENT.FA_YEAR AS FA_YEAR" +
                        "     FROM   COR_HDR_BATCH," +
                        "            MST_ASSESSMENT " +
                        "     WHERE  COR_HDR_BATCH.ASST_ID         = MST_ASSESSMENT.ASST_ID" +
                        "     AND    COR_HDR_BATCH.BATCH_HEADER_ID = " + BasicInfoBatchID + " ";
