                    //string[,] strArry = { { "txtReportTitle", "Valid & Inoperative PAN(s)" } };
                    //if (Regular == null)
                    //    rptService.J_PreviewReport(ref rptcls, TDSMAN.Classes.TDSMAN.T_pCurrentForm, strQueryString, strArry);
                    //else
