        public void PrintUnmatchedNames(long BasicInfoBatchID, string Regular, string strCSVPath)
        {
            try
            {
                //
                crUnmatchedNames rptUnmatchedNames = new crUnmatchedNames();
                rptcls = (ReportClass)rptUnmatchedNames;
                //--
                TextObject objtxtValue;
                //--
                if (Regular == null)
                {
                    //
                    #region EXCEL IMPORT
                    strQueryString = "SELECT DISTINCT " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_NAME AS NAME_DESC," +
                        "                    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_PAN           AS PAN," +
                        "                    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + ".RUNNING_SERIAL_NO       AS SL_NO," +
                        "                    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + ".TRF_VCH_CHLN_NO         AS CHALLAN_NO," +
                        "                    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_INVALID_PAN + ".VERIFIED_NAME               AS VERIFIED_NAME " +
                        "             FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + "," +
                        "                    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + "," +
                        "                    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_INVALID_PAN + " " +
                        "             WHERE  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_PAN     = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_INVALID_PAN + ".PAN " +
                        "             AND    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + ".RUNNING_SERIAL_NO = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".CHALLAN_SERIAL_NO " +
                        "             AND    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_INVALID_PAN + ".VERIFIED_NAME         <> '' " +
                        "             ORDER BY " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_PAN, " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + ".RUNNING_SERIAL_NO";
                    //--
                    strSQL = "SELECT MST_COMPANY.COMPANY_NAME AS COMPANY_NAME" +
                       "     FROM   TRN_BASIC_INFO," +
                       "            MST_COMPANY " +
                       "     WHERE  TRN_BASIC_INFO.COMPANY_ID = MST_COMPANY.COMPANY_ID" +
                       "     AND    TRN_BASIC_INFO.BASIC_INFO_ID = " + BasicInfoBatchID + " ";
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtCompany"];
                    objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //                    
                    strSQL = "SELECT MST_COMPANY.TAN_NO AS TAN_NO" +
                        "     FROM   TRN_BASIC_INFO," +
