                        "     WHERE  TRN_BASIC_INFO.COMPANY_ID = MST_COMPANY.COMPANY_ID" +
                        "     AND    TRN_BASIC_INFO.BASIC_INFO_ID = " + BasicInfoBatchID + " ";
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtTAN"];
                    objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //
