                        "     FROM   TRN_BASIC_INFO," +
                        "            MST_COMPANY " +
                        "     WHERE  TRN_BASIC_INFO.COMPANY_ID = MST_COMPANY.COMPANY_ID" +
                        "     AND    TRN_BASIC_INFO.BASIC_INFO_ID = " + BasicInfoBatchID + " ";
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtPAN"];
                    objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //
                    strSQL = "SELECT MST_ASSESSMENT.FA_YEAR AS FA_YEAR" +
                        "     FROM   TRN_BASIC_INFO," +
                        "            MST_ASSESSMENT " +
                        "     WHERE  TRN_BASIC_INFO.ASST_ID = MST_ASSESSMENT.ASST_ID" +
                        "     AND    TRN_BASIC_INFO.BASIC_INFO_ID = " + BasicInfoBatchID + " ";
                    objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFY"];
                    objtxtValue.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //
                    strSQL = "SELECT MST_ASSESSMENT.ASST_YEAR AS ASST_YEAR" +
                        "     FROM   TRN_BASIC_INFO," +
