        #region PrintAllCompanyList
        public void PrintAllCompanyList()
        {
            strQueryString = "SELECT MST_COMPANY.TAN_NO                                  AS TAN_NO," +
                "                    MST_COMPANY.PAN_NO                                  AS PAN_NO," +
                "                    MST_COMPANY.COMPANY_NAME                            AS COMPANY_NAME," +
                "                    MST_COMPANY.PERSON_NAME                             AS PERSON_NAME," +
                "                    MST_COMPANY.GSTN                                    AS GSTN," +
                "                    MST_COMPANY.EMAIL                                   AS EMAIL," +
                "                    MST_COMPANY.STD + '-' + MST_COMPANY.PHONE           AS PHONE_NO," +
                "                    MST_COMPANY.P_STD + '-' + MST_COMPANY.P_PHONE       AS P_PHONE_NO," +
                "                    MST_COMPANY.P_MOBILE                                AS P_MOBILE_NO," +
                "                    MST_COMPANY.AIN_NO                                  AS AIN_NO," +
                "                    MST_CATEGORY.CATEGORY_CODE                          AS CATEGORY_CODE" +
                "              FROM  MST_COMPANY" +
                "         LEFT JOIN  MST_CATEGORY" +
                "                ON  MST_COMPANY.D_CATEGORY_ID   =   MST_CATEGORY.CATEGORY_ID " +
                "          ORDER BY  MST_COMPANY.COMPANY_NAME";
               

            crAllCompanyList rptCompanyWiseDeducteeList = new crAllCompanyList();
            rptcls = (ReportClass)rptCompanyWiseDeducteeList;

            //SETTING REPORT TITLE
            string[,] strArry = { { "txtReportTitle", "All Company List (Deductors)" } };
            rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);

        }

