                    strQueryStringDeducteeDetails = "SELECT COR_TRN_COMPANY.HDR_COMPANY_ID             AS COMPANY_ID, " +
                                    "                    COR_TRN_COMPANY.COMPANY_NAME                  AS COMPANY_NAME, " +
                                    "                    COR_TRN_COMPANY.TAN_NO                        AS TAN_NO, " +
                                    "                    COR_TRN_CHALLAN.TRN_CHALLAN_ID                AS CHALLAN_ID, " +
                                    "                   " + cmnService.J_SQLDBFormat(strChallanNoDeducteeMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + " AS CHALLAN_NO, " +
                                    "                   " + cmnService.J_SQLDBFormat(strChallanNoTextMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + " AS CHALLAN_NO_TEXT, " +
                                    "                    COR_TRN_CHALLAN.BSR_CODE                      AS BSR_CODE, " +
                                    "                    COR_TRN_CHALLAN.DEPOSIT_DATE                  AS DEPOSIT_DATE, " +
                                    "                    COR_TRN_CHALLAN.CTRL_TOT_TAX                  AS TOTAL_TDS, " +
                                    "                    COR_TRN_CHALLAN.INTEREST_ALLOCATED            AS INTEREST_ALLOCATED, " +
                                    "                    COR_TRN_CHALLAN.OTHERS_ALLOCATED              AS OTHERS_ALLOCATED, " +
                                    "                    COR_TRN_CHALLAN.TOT_TAX                       AS TOTAL_ABOVE, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.TRN_DEDUCTEE_DETAIL_ID AS DEDUCTEE_ID, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME        AS DEDUCTEE_NAME, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_REF         AS EMPLOYEE_REF, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN         AS DEDUCTEE_PAN, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.SL_NO                AS SL_NO, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE         AS PAYMENT_DATE, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE        AS DEDUCTED_DATE, " +
                                    "                    MST_SECTION.SECTION_NO                        AS SECTION_NO, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT       AS PAYMENT_AMOUNT, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.RATE                 AS RATE, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.TAX_AMOUNT           AS TAX_AMOUNT, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.SURCHARGE_AMOUNT     AS SURCHARGE_AMOUNT, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.CESS_AMOUNT          AS CESS_AMOUNT, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT         AS TOTAL_AMOUNT, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT AS TAX_DEPOSITED_AMOUNT, " +
                        //"                    " + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG", J_SQLColFormat.Case_End, strRemarks24QMatrix) + " AS NON_DEDUCTION_FLAG, " +
                        //"                    COR_TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG   AS NON_DEDUCTION_FLAG, " +
                                    "                    MST_REASON.REASON                             AS NON_DEDUCTION_FLAG, " +
                                    "                    MST_ASSESSMENT.FA_YEAR                        AS FA_YEAR, " +
                                    "                    COR_HDR_BATCH.FORM_NO                         AS FORM_NO, " +
                                    "                    COR_HDR_BATCH.QTR                             AS QTR, " +
                                    "                    '' AS DEDUCTEE_CODE, " +
                                    "                   " + cmnService.J_SQLDBFormat(strProvEntryMatrix, J_SQLColFormat.Case_End) + " AS CASH_BOOK_ENTRY, " +
                                    "                   " + cmnService.J_SQLDBFormat(strGrossTotMatrix, J_SQLColFormat.Case_End) + " AS GROSSING_UP_INDICATOR_TOT_VALUE_PURCHASE, " +
                                    "                    COR_TRN_CHALLAN.TDS                           AS TDS, " +
                                    "                    COR_TRN_CHALLAN.SURCHARGE                     AS SURCHARGE, " +
                                    "                    COR_TRN_CHALLAN.EDUCATION_CESS                AS EDUCATION_CESS, " +
                                    "                    COR_TRN_CHALLAN.OTHERS                        AS OTHERS, " +
                                    "                    COR_TRN_CHALLAN.INTEREST                      AS INTEREST, " +
                                    "                    COR_TRN_COMPANY.PERSON_NAME                   AS PERSON_NAME, " +
                                    "                    COR_TRN_COMPANY.DESIGNATION                   AS DESIGNATION, " +
                                    "                    COR_TRN_COMPANY.ADDRESS3                      AS P_ADDRESS3, " +
                                    "                    DD_MST_SECTION.SECTION_NO                     AS SECTION_NO_DD, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.REASON_ID            AS REASON_ID, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.CERTIFICATE_NO       AS CERTIFICATE_NO, " +
                                    "                    MST_REASON.REASON                             AS REASON, " +
                                    "                    MST_REASON.DESCRIPTION                        AS REASON_DESCRIPTION," +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.TDS_APPLICABILITY_ID AS TDS_APPLICABILITY_ID, " +
                                    "                    MST_TDS_APPLICABILITY.TDS_APPLICABILITY_CODE  AS TDS_APPLICABILITY_CODE, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.REMITTANCE_ID        AS REMITTANCE_ID, " +
                                    "                    MST_REMITTANCE.REMITTANCE_DESC                AS REMITTANCE_DESC, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.UNIQUE_ACKN          AS UNIQUE_ACKN, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.COUNTRY_ID           AS COUNTRY_ID, " +
                                    "                    MST_COUNTRY.COUNTRY_DESC                      AS COUNTRY_DESC, " +
                                    "                    COR_TRN_DEDUCTEE_DETAILS.TOT_VALUE_PURCHASE   AS TOT_VALUE_PURCHASE " +
                                    "             FROM   ((((((((((COR_TRN_DEDUCTEE_DETAILS  " +
                                    "                             INNER JOIN COR_TRN_CHALLAN  " +
                                    "                                     ON COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID = COR_TRN_CHALLAN.TRN_CHALLAN_ID)  " +
                                    "                             INNER JOIN COR_TRN_COMPANY  " +
                                    "                                     ON COR_TRN_DEDUCTEE_DETAILS.BATCH_HEADER_ID = COR_TRN_COMPANY.BATCH_HEADER_ID)  " +
                                    "                             INNER JOIN COR_HDR_BATCH  " +
                                    "                                     ON COR_TRN_DEDUCTEE_DETAILS.BATCH_HEADER_ID = COR_HDR_BATCH.BATCH_HEADER_ID)  " +
                                    "                             LEFT  JOIN MST_SECTION " +
                                    "                                     ON COR_TRN_CHALLAN.SECTION_ID               = MST_SECTION.SECTION_ID) " +
                                    "                             INNER JOIN MST_ASSESSMENT  " +
                                    "                                     ON COR_HDR_BATCH.ASST_ID                    = MST_ASSESSMENT.ASST_ID)  " +
                                    "                             LEFT JOIN MST_SECTION  AS DD_MST_SECTION" +
                                    "                                     ON COR_TRN_DEDUCTEE_DETAILS.SECTION_ID      = DD_MST_SECTION.SECTION_ID) " +
                                    "                             LEFT JOIN MST_REASON      " +
                                    "                                     ON COR_TRN_DEDUCTEE_DETAILS.REASON_ID       = MST_REASON.REASON_ID) " +
                                    "                             LEFT JOIN MST_TDS_APPLICABILITY " +
                                    "                                     ON COR_TRN_DEDUCTEE_DETAILS.TDS_APPLICABILITY_ID=MST_TDS_APPLICABILITY.TDS_APPLICABILITY_ID) " +
                                    "                             LEFT JOIN MST_REMITTANCE" +
                                    "                                     ON COR_TRN_DEDUCTEE_DETAILS.REMITTANCE_ID=MST_REMITTANCE.REMITTANCE_ID) " +
                                    "                             LEFT JOIN MST_COUNTRY" +
                                    "                                     ON COR_TRN_DEDUCTEE_DETAILS.COUNTRY_ID=MST_COUNTRY.COUNTRY_ID) " +
                                    "             WHERE  COR_TRN_DEDUCTEE_DETAILS.BATCH_HEADER_ID          = " + BatchHeaderID + " " +
                                    "             ORDER BY COR_TRN_CHALLAN.TRN_CHALLAN_ID,  " +
                                    "                      COR_TRN_CHALLAN.SL_NO, " +
                                    "                      COR_TRN_DEDUCTEE_DETAILS.SL_NO, " +
                                    "                      COR_TRN_DEDUCTEE_DETAILS.TRN_DEDUCTEE_DETAIL_ID ";
                    if (FormNo == T_FormNo.F24Q)
                        rptcls.OpenSubreport("crSubRptEmployeeDetails").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strQueryStringDeducteeDetails).Tables[0]);
                    else if (FormNo == T_FormNo.F26Q)
                        rptcls.OpenSubreport("crSubRptDeductee_Details_26Q").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strQueryStringDeducteeDetails).Tables[0]);
                    else if (FormNo == T_FormNo.F27Q)
