                    else if (FormNo == T_FormNo.F27EQ)
                        rptcls.OpenSubreport("crSubRptDeductee_Details_27EQ").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strQueryStringDeducteeDetails).Tables[0]);

