                strSectionDetails = strSectionDetails + "     ORDER BY SECTION_NO ";

                rptcls.OpenSubreport("crSubRptSectionDetail").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSectionDetails).Tables[0]);

