                                "                    0  AS TS_LA_ITEM_4, " +
                                "                    0  AS TS_LA_ITEM_5_DESC, " +
                                "                    0  AS TS_LA_ITEM_5, " +
                                "                    0  AS CVIA_SEC80CCG_GROSS_AMOUNT, " +
                                "                    COR_TRN_SALARY_DETAILS.CVIA_SEC80CCG_DED_AMOUNT, " +
