                    strQueryStringSalaryDetails1 = strQueryStringSalaryDetails1 + " " + cmnService.J_SQLDBFormat(strHigherRateMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + " AS TAX_DEDUCTED_HIGHER_RATE,";
                else
                    strQueryStringSalaryDetails1 = strQueryStringSalaryDetails1 + " 'NO' AS  TAX_DEDUCTED_HIGHER_RATE,";

                strQueryStringSalaryDetails1 = strQueryStringSalaryDetails1 + "                    '" + FAYear + "'                    AS FAYEAR," +
                                                                              "                    COR_TRN_COMPANY.PERSON_NAME         AS PERSON_NAME," +
                                                                              "                    COR_TRN_COMPANY.DESIGNATION         AS DESIGNATION," +
                                                                              "                    COR_TRN_COMPANY.ADDRESS3          AS P_ADDRESS3 " +
                                                                              "             FROM   COR_TRN_SALARY_DETAILS, " +
                                                                              "                    COR_TRN_COMPANY, " +
                                                                              "                    COR_HDR_BATCH ";

                if (FormNo == T_FormNo.F24Q && Qtr == "Q4" && lngSalaryDetailsExist > 0)
                {
                    strQueryStringSalaryDetails1 = strQueryStringSalaryDetails1 + "             WHERE COR_TRN_SALARY_DETAILS.BATCH_HEADER_ID = COR_TRN_COMPANY.BATCH_HEADER_ID " +
                                                                                  "             AND   COR_TRN_SALARY_DETAILS.BATCH_HEADER_ID = COR_HDR_BATCH.BATCH_HEADER_ID " +
                                                                                  "             AND   COR_TRN_SALARY_DETAILS.BATCH_HEADER_ID    = " + BatchHeaderID + " " +
                                                                                  "             ORDER BY COR_TRN_SALARY_DETAILS.SL_NO";
                    ////"                    MST_EMPLOYEE.EMPLOYEE_PAN," +
                    ////"                    TRN_SALARY_DETAILS.SALARY_DETAILS_ID";
                }
                else
                {
                    //------FOR DUMMY QUERY INTO SUBREPORT
                    strQueryStringSalaryDetails1 = strQueryStringSalaryDetails1 + "             WHERE  1=2";
                }
                rptcls.OpenSubreport("crSubRptSalaryDetails").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strQueryStringSalaryDetails1).Tables[0]);

                #endregion

                #endregion //24Q SALARY DETAILS IN QUARTER 4
