                //++++++++++++++++++++++++++++++++++++++++++++++++
                // MAIN REPORT 
                rptService.J_PreviewReport(ref rptcls, this, strQueryStringCompanyDetails);
                //}
                //else
                //    cmnService.J_UserMessage("No return found for the selected parameters.");
            }
            catch (Exception err)
            {
                return;
            }
