        #region PrintCorrectionReturnReports_RDLC
        //ADDED BY ANIK
        public void PrintCorrectionReturnReports_RDLC()
        {
            long BatchHeaderID = 0;
            //-----------------------------------------------
            IDataReader drdShowRecord = null;
            //-----------------------------------------------

            try
            {
                //--REPORT OBJECT 
                //+++++++++++++++++++++++++++++++++++++++++++++++++
                //crITR24QForm rptCorrectionReport = new crITR24QForm();
                //rptcls = (ReportClass)rptCorrectionReport;
                //+++++++++++++++++++++++++++++++++++++++++++++++++

                //+++++++++++++++++++++++++++++++++++++++++++++++++
                //FETCHING THE BATCH HEADER ID
                //+++++++++++++++++++++++++++++++++++++++++++++++++
                BatchHeaderID = Convert.ToInt64(cmnService.J_GenerateDataGridViewSelectedId(grdvDescription));
                //+++++++++++++++++++++++++++++++++++++++++++++++++
                //VARIABLE DECLARATIONS 
                //+++++++++++++++++++++++++++++++++++++++++++++++++
                string strQueryStringCompanyDetails = "";
                string strQueryStringChallanDetails = "";
                string strQueryStringDeducteeDetails = "";
                string strQueryStringSalaryDetails1 = "";
                string strQtrEnded = "";
                string strSectionDetails = "";
                string FAYear = "";
                string Qtr = "";
                string FormNo = "";
                int FAYearID = 0;
                //    //--
                //FETCHING THE NUMBERS ON CHALLAN , DEDUCTEE RECORDS
                //+++++++++++++++++++++++++++++++++++++++++++++++++
                long lngChallanExist = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM COR_TRN_CHALLAN WHERE BATCH_HEADER_ID = " + BatchHeaderID, J_QueryType.DirectQuery)));
                long lngDeducteeExist = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM COR_TRN_DEDUCTEE_DETAILS WHERE BATCH_HEADER_ID = " + BatchHeaderID, J_QueryType.DirectQuery)));
                long lngSalaryDetailsExist = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM COR_TRN_SALARY_DETAILS WHERE BATCH_HEADER_ID = " + BatchHeaderID, J_QueryType.DirectQuery)));
                //---------------------------
                //FETCHING BATCH WISE FORM,QTY,FA_YEAR AND ASSESSMENT_ID
                //++++++++++++++++++++++++++++++++++++++++++++++++++++++
                strSQL = @"SELECT COR_HDR_BATCH.FORM_NO,
                                  COR_HDR_BATCH.QTR,
                                  MST_ASSESSMENT.FA_YEAR,
                                  MST_ASSESSMENT.ASST_ID
                           FROM   COR_HDR_BATCH
                                  INNER JOIN MST_ASSESSMENT
                                  ON COR_HDR_BATCH.ASST_ID = MST_ASSESSMENT.ASST_ID 
                           WHERE  COR_HDR_BATCH.BATCH_HEADER_ID =" + BatchHeaderID;

                drdShowRecord = dmlService.J_ExecSqlReturnReader(strSQL);
                if (drdShowRecord == null)
                    return;
                //--
                while (drdShowRecord.Read())
                {
                    FAYearID = Convert.ToInt32(drdShowRecord["ASST_ID"]);
                    FAYear = Convert.ToString(drdShowRecord["FA_YEAR"]);
                    Qtr = Convert.ToString(drdShowRecord["QTR"]);
                    FormNo = Convert.ToString(drdShowRecord["FORM_NO"]);
                }
                drdShowRecord.Close();
                drdShowRecord.Dispose();
                //++++++++++++++++++++++++++++++++++++++++++++++++++++++
                //--
                if (Qtr == T_Qtr.Q1)
                    strQtrEnded = "June " + FAYear.ToString().Substring(0, 4);
                else if (Qtr == T_Qtr.Q2)
                    strQtrEnded = "September " + FAYear.ToString().Substring(0, 4);
                else if (Qtr == T_Qtr.Q3)
                    strQtrEnded = "December " + FAYear.ToString().Substring(0, 4);
                else if (Qtr == T_Qtr.Q4)
                    strQtrEnded = "March " + FAYear.ToString().Substring(0, 2) + FAYear.ToString().Substring(5, 2);
                //--
                //--       //--
                #region COMPANY DETAILS
                // COMPANY DETAILS
                //string[,] strAddressChangeMatrix = {{"TRN_BASIC_INFO.ADDRESS_CHANGE = 1", "F", "Yes", "T"},
                //                                    {"TRN_BASIC_INFO.ADDRESS_CHANGE = 0", "F", "No", "T"}};

                //string[,] strPAddressChangeMatrix = {{"TRN_BASIC_INFO.P_ADDRESS_CHANGE = 1", "F", "Yes", "T"},
                //                                     {"TRN_BASIC_INFO.P_ADDRESS_CHANGE = 0", "F", "No", "T"}};

                string[,] strMinistryMatrix = {{"COR_TRN_COMPANY.MINISTRY_ID > 0", "F", "MST_MINISTRY.MINISTRY_NAME", "F"},
                                               {"COR_TRN_COMPANY.MINISTRY_ID = 0", "F", "COR_TRN_COMPANY.MINISTRY_OTHER", "F"}};

                string[,] strPRNMatrix = {{"TRN_BASIC_INFO.PRN_NO <> ''", "F", "Yes", "T"},
                                          {"TRN_BASIC_INFO.PRN_NO = ''", "F", "No", "T"}};

                //------------------------------MAIN QUERY

                strQueryStringCompanyDetails = "SELECT COR_TRN_COMPANY.HDR_COMPANY_ID                                                  AS COMPANY_ID," +
                                "                      COR_TRN_COMPANY.COMPANY_NAME                                                    AS COMPANY_NAME," +
                                "                      COR_TRN_COMPANY.TAN_NO                                                          AS TAN_NO," +
                                "                      COR_TRN_COMPANY.PAN_NO                                                          AS PAN_NO," +
                                "                      COR_TRN_COMPANY.BRANCH_DIV                                                      AS BRANCH_DIV," +
                                "                      COR_TRN_COMPANY.D_CATEGORY_ID                                                   AS D_CATEGORY_ID," +
                                "                      MST_CATEGORY.CATEGORY_DESCRIPTION                                               AS CATEGORY_DESCRIPTION," +
                                "                      MST_CATEGORY.CATEGORY_CODE                                                      AS CATEGORY_CODE," +
                                //"                  " + cmnService.J_SQLDBFormat(strAddressChangeMatrix, J_SQLColFormat.Case_End) + "  AS ADDRESS_CHANGE," +
                                "                     ''                                                                               AS ADDRESS_CHANGE," +
                                "                     COR_TRN_COMPANY.ADDRESS1                                                         AS ADDRESS1," +
                                "                     COR_TRN_COMPANY.ADDRESS2                                                         AS ADDRESS2," +
                                "                     COR_TRN_COMPANY.ADDRESS3                                                         AS ADDRESS3," +
                                "                     COR_TRN_COMPANY.ADDRESS4                                                         AS ADDRESS4," +
                                "                     COR_TRN_COMPANY.ADDRESS5                                                         AS ADDRESS5," +
                                "                     COR_TRN_COMPANY.STATE_ID                                                         AS STATE_ID," +
                                "                     MST_STATE.STATE_NAME                                                             AS STATE_NAME," +
