                                                    "       COR_HDR_BATCH.FORM_NO                                                                             AS FORM_NO, " +
                                                    "       COR_HDR_BATCH.QTR                                                                                 AS QTR, " +
                                                    "       COR_TRN_CHALLAN.DEPOSIT_DATE                                                                      AS DEPOSIT_DATE, " +
                                                    "       MST_SECTION.SECTION_ID                                                                            AS SECTION_ID, " +
                                                    "       MST_SECTION.SECTION_NAME                                                                          AS SECTION_NO, " +
                                                    "       MST_SECTION.SECTION_DESCRIPTION                                                                   AS SECTION_DESCRIPTION, " +
                                                    "       COR_TRN_CHALLAN.BSR_CODE                                                                          AS BSR_CODE, " +
                                                    //"       IIF(TRN_CHALLAN.CHALLAN_NO = '', TRN_CHALLAN.TRANSFER_VOUCHER_NO, TRN_CHALLAN.CHALLAN_NO)        AS CHALLAN_NO, " +
                                                    "       " + cmnService.J_SQLDBFormat(strChallanNoMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + "     AS CHALLAN_NO, " +
                                                    "       COR_TRN_CHALLAN.CHEQUE_NO                                                                         AS CHEQUE_NO, " +
                                                    "       COR_TRN_CHALLAN.TDS                                                                               AS TDS, " +
                                                    "       COR_TRN_CHALLAN.SURCHARGE                                                                         AS SURCHARGE, " +
                                                    "       COR_TRN_CHALLAN.EDUCATION_CESS                                                                    AS EDUCATION_CESS, " +
                                                    "       COR_TRN_CHALLAN.INTEREST                                                                          AS INTEREST, " +
                                                    "       COR_TRN_CHALLAN.LATE_FEE                                                                          AS LATE_FEE, " +
                                                    "       COR_TRN_CHALLAN.OTHERS                                                                            AS OTHERS,  " +
                                                    "       COR_TRN_CHALLAN.SL_NO                                                                             AS SL_NO,  " +
                                                    "       " + cmnService.J_SQLDBFormat(strChallanMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + "       AS MODE_OF_TDS_DEPOSIT, " +
                                                    //"       IIF(COR_TRN_CHALLAN.BOOK_ENTRY = 1, 'B', 'C')                                                     AS MODE_OF_TDS_DEPOSIT, " +
                                                    "       MST_MINOR_HEAD.MINOR_HEAD_CODE                                                                    AS MINOR_HEAD, " +
                                                    "       MST_MINOR_HEAD.MINOR_HEAD_DESC                                                                    AS MINOR_HEAD_DETAILS, " +
                                                    "       COR_TRN_CHALLAN.TOT_TAX                                                                           AS TOT_TAX, " +
                                                    "       COR_TRN_COMPANY.PERSON_NAME                                                                       AS PERSON_NAME, " +
                                                    "       COR_TRN_COMPANY.DESIGNATION                                                                       AS DESIGNATION, " +
                                                    //"       MST_COMPANY.P_ADDRESS3                                                                           AS P_ADDRESS3 , " +
                                                    "       COR_TRN_COMPANY.ADDRESS3                                                                          AS P_ADDRESS3 " +
                                                    "FROM  (((((COR_TRN_CHALLAN  " +
                                                    "            INNER JOIN COR_TRN_COMPANY  " +
                                                    "                    ON COR_TRN_CHALLAN.BATCH_HEADER_ID  = COR_TRN_COMPANY.BATCH_HEADER_ID)  " +
                                                    "            INNER JOIN COR_HDR_BATCH  " +
                                                    "                    ON COR_TRN_CHALLAN.BATCH_HEADER_ID  = COR_HDR_BATCH.BATCH_HEADER_ID)  " +
                                                    "            INNER JOIN MST_ASSESSMENT  " +
                                                    "                    ON COR_HDR_BATCH.ASST_ID = MST_ASSESSMENT.ASST_ID)  " +
                                                    "            LEFT JOIN MST_SECTION  " +
                                                    "                    ON COR_TRN_CHALLAN.SECTION_ID       = MST_SECTION.SECTION_ID) " +
                                                    "            LEFT JOIN MST_MINOR_HEAD  " +
                                                    "                    ON  COR_TRN_CHALLAN.MINOR_HEAD_ID   = MST_MINOR_HEAD.MINOR_HEAD_ID)" +
                                                    "WHERE  COR_TRN_CHALLAN.BATCH_HEADER_ID    = " + BatchHeaderID + " " +
                                                    "ORDER BY COR_TRN_CHALLAN.SL_NO ";

                    //rptcls.OpenSubreport("crSubRptChallanDetails").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strQueryStringChallanDetails).Tables[0]);
                }
                #endregion //CHALLAN DETAILS END
                //++++++++++++++++++++++++++++++++++++++++++++++++
                // SECTION DETAIL
                #region SECTION DETAIL FROM MST_SECTION
                strSectionDetails = "     SELECT  SECTION_ID           , " +
                                     "            FORM_NAME            , " +
                                     "            SECTION_TYPE         , " +
                                     "            SECTION_NAME         , " +
                                     "            SECTION_NO           , " +
