                                    "             WHERE  COR_TRN_DEDUCTEE_DETAILS.BATCH_HEADER_ID          = " + BatchHeaderID + " " +
                                    "             ORDER BY COR_TRN_CHALLAN.TRN_CHALLAN_ID,  " +
