        #region PrintDeducteeEntriesWithoutChallan
        public void PrintDeducteeEntriesWithoutChallan(int CompanyID, int FAYearID, string FormNo, string Qtr, string FAYear)
        {
            try
            {

                string strSelectedGroup = "";
                string strSelectedForm = "";
                string strReportTitle = "Deductee Entries Without Challan";
                string strSectionNo = "";

                this.Cursor = Cursors.WaitCursor;
                foreach (int indexChecked in clbListBox1.CheckedIndices)
                {
                    strSectionNo = strSectionNo + "'" + clbListBox1.Items[indexChecked] + "',";
                }
                if (strSectionNo != "")
                    if (cmnService.J_Right(strSectionNo, 1) == ",")
                        strSectionNo = cmnService.J_Mid(strSectionNo, 0, (strSectionNo.Length - 1));

                //GROUP SELECTION 
                if (rbnSort1.Checked == true)
                    strSelectedGroup = T_Group_Order.MonthSection;
                else if (rbnSort2.Checked == true)
                    strSelectedGroup = T_Group_Order.Month;
                else if (rbnSort3.Checked == true)
                    strSelectedGroup = T_Group_Order.MonthSectionDeductee;

                //FORM SELECTION
                if (cmbCombo3.Text == T_FormNo.F24Q)
                    strSelectedForm = T_FormNo.F24Q;
                else if (cmbCombo3.Text == T_FormNo.F26Q || cmbCombo3.Text == T_FormNo.F27Q || cmbCombo3.Text == T_FormNo.F27EQ)
                    strSelectedForm = "";

                //FORM SELECTION WISE TOGGLE THE FIELDS
                string strTableName = "", strFieldName = "", strFieldPAN = "", strFieldId = "", strArgumnets = "";
                if (strSelectedForm == T_FormNo.F24Q)
                {
                    strTableName = "MST_EMPLOYEE"; strFieldName = "EMPLOYEE_NAME"; strFieldPAN = "EMPLOYEE_PAN"; strFieldId = "EMPLOYEE_ID";
                }
                else
                {
                    strTableName = "MST_DEDUCTEE"; strFieldName = "DEDUCTEE_NAME"; strFieldPAN = "DEDUCTEE_PAN"; strFieldId = "DEDUCTEE_ID";
                }

                //CREATING RPT OBJECT GROUP SELECTION WISE 
                if (strSelectedGroup == T_Group_Order.MonthSection)
                {
                    crDeducteeWithoutChallanSectionWise rptDeducteeWithoutChallanSectionWise = new crDeducteeWithoutChallanSectionWise();
                    rptcls = (ReportClass)rptDeducteeWithoutChallanSectionWise;
                    strReportTitle = "Deductee Entries Without Challan [Section Wise]";
                }
                else if (strSelectedGroup == T_Group_Order.Month)
                {
                    crDeducteeWithoutChallanMonthWise rptDeducteeWithoutChallanMonthWise = new crDeducteeWithoutChallanMonthWise();
                    rptcls = (ReportClass)rptDeducteeWithoutChallanMonthWise;

                    strReportTitle = "Deductee Entries Without Challan [Month Wise]";
                }
                else if (strSelectedGroup == T_Group_Order.MonthSectionDeductee)
                {
                    crDeducteeWithoutChallanDeducteeWise rptDeducteeWithoutChallanDeducteeWise = new crDeducteeWithoutChallanDeducteeWise();
                    rptcls = (ReportClass)rptDeducteeWithoutChallanDeducteeWise;
                    strReportTitle = "Deductee Entries Without Challan [Deductee Wise]";
                }
                //--
                strSQL = "SELECT BASIC_INFO_ID FROM TRN_BASIC_INFO " +
                    "     WHERE  COMPANY_ID = " + CompanyID + " " +
                    "     AND    ASST_ID    = " + FAYearID + " " +
                    "     AND    FORM_NO    ='" + FormNo + "' " +
                    "     AND    QTR        ='" + Qtr + "' ";
                long BasicInfoID = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));
                //--
                strSQL = @"SELECT MST_COMPANY.COMPANY_NAME,
                                  MST_COMPANY.TAN_NO,
                                  MST_COMPANY.PAN_NO,
                                  TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID,
                                  TRN_DEDUCTEE_DETAILS.CHALLAN_ID,
                                  TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID,
                                  TRN_DEDUCTEE_DETAILS.PARTY_ID, " +
                                  strTableName + "." + strFieldId + " AS DEDUCTEE_ID, " +
                                  strTableName + "." + strFieldName + " AS DEDUCTEE_NAME, " +
                                  strTableName + "." + strFieldPAN + " AS DEDUCTEE_PAN, " +
                                  @" " + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatMMYYYY) + " AS PAYMENT_DATE_MMYYYY," +
                                  @" " + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatMMM) + " & ' ' & " + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatYYYY) + @" AS PAYMENT_DATE_MONYYYY,
                                  TRN_DEDUCTEE_DETAILS.PAYMENT_DATE,
                                  TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE,
                                  TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT,
                                  TRN_DEDUCTEE_DETAILS.RATE,
                                  TRN_DEDUCTEE_DETAILS.TAX_AMOUNT,
                                  TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT,
                                  TRN_DEDUCTEE_DETAILS.SECTION_ID,
                                  MST_SECTION.SECTION_NAME,
                                  MST_SECTION.SECTION_NO,
                                  MST_SECTION.SECTION_DESCRIPTION,
                                  TRN_DEDUCTEE_DETAILS.REASON_ID,
                                  MST_REASON.REASON,
                                  MST_REASON.DESCRIPTION,
                                  TRN_DEDUCTEE_DETAILS.REASON_ID
                       FROM ((((((TRN_DEDUCTEE_DETAILS
                                  INNER JOIN " + strTableName +
                              @"  ON TRN_DEDUCTEE_DETAILS.PARTY_ID  = " + strTableName + "." + strFieldId + " )" +
                              @"  LEFT JOIN MST_SECTION
                                  ON TRN_DEDUCTEE_DETAILS.SECTION_ID     = MST_SECTION.SECTION_ID)
                                  LEFT JOIN MST_REASON
                                  ON TRN_DEDUCTEE_DETAILS.REASON_ID      = MST_REASON.REASON_ID)
                                  INNER JOIN TRN_BASIC_INFO
                                  ON  TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID)
                                  INNER JOIN MST_COMPANY
                                  ON  TRN_BASIC_INFO.COMPANY_ID          = MST_COMPANY.COMPANY_ID)
                                  INNER JOIN MST_ASSESSMENT
                                  ON  TRN_BASIC_INFO.ASST_ID             = MST_ASSESSMENT.ASST_ID)
                       WHERE      CHALLAN_ID = 0 
                       AND        " + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatMMYYYY) + " IN (" + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + @") 
                       AND        TRN_BASIC_INFO.BASIC_INFO_ID = " + BasicInfoID + " ";
                if (strSectionNo != "")
                    strSQL = strSQL + " AND  MST_SECTION.SECTION_NO            IN(" + strSectionNo + ") ";

                strSQL = strSQL + @" ORDER BY " + cmnService.J_SQLDBFormat("TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatMMYYYY) + @", 
                                          MST_SECTION.SECTION_ID ";

                // FORM SELECTED
                TextObject objtxtValue;

                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtQuarter"];
                objtxtValue.Text = cmbCombo4.Text;

                objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtFAYear"];
                objtxtValue.Text = cmbCombo2.Text;

                string[,] strArry = { { "txtReportTitle", strReportTitle } };
                //
                this.Cursor = Cursors.Default;
                //
                //rptService.J_PreviewReport(ref rptcls, TDSMAN.Classes.TDSMAN.T_pCurrentForm, strSQL, strArry);
                rptService.J_PreviewReport(ref rptcls, this, strSQL, strArry);


                this.Cursor = Cursors.Default;
            }
            catch (Exception err)
            {

            }
        }
        #endregion 

