                                AND (" + cmnService.J_SQLDBFormat("SALARY_DETAILS.TOTAL_SD_RECORDS", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + @" = 0 )";
                    //if (chkBox1.Checked == false)
