        #region PrintCertForm1624Q_RDLC
        private void PrintCertForm1624Q_RDLC()
        {
            try
            {
                string strSQLSubTaxDeductionSummary = "";
                string strSQLSubSalaryDetails = "";
                string strSQLSubAnnexureA = "";
                string strSQLSubAnnexureB = "";

                string strGeneratePDFPath = "";
                string strSignPDFPath = "";
                string strSignatureFilePath = "";
                string strUserMassage = "";
                long lngListOfItems = 0;
                string strEmployeePAN = "";

                string strForm16OutputPDFPath = "";
                string strForm16OutputSignPDFPath = "";

                long lngCounter = 0;
                int intEmployeePANCounter = 0;
                bool blnFetchPAN = true;
                DataSet dsSelectedGridData;

                string[] strSelectedEmpID = cmnService.J_GenerateDataGridViewSelectedId(grdvNewDescription).Split(',');//-- Modified By Abhishek Dey On 25/10/2017 --
                //string[] strSelectedEmpID = cmnService.J_GenerateDataGridViewSelectedId(grdvNewDescription,3).Split(',');//-- Modified By Abhishek Dey On 25/10/2017 --

                string strSQLQueryString = "";

                //J_GenerateDataGridViewSelectedId(dataGridView, 1, out SelectedItemCount);

                string[] strSelectedEmpPAN = new string[strSelectedEmpID.Length];

                bool blnPrintNIL = false; bool blnTaxCreditAmt = false;
                //-------DHRUB ON 05/02/2014
                strSelectedGridItemsWithSearch = "";

                if (dmlService.J_ReturnNoOfRows("SELECT Count(*) FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED, J_QueryType.DirectQuery) > Convert.ToInt64(strSelectedEmpID.Length))
                {
                    dsSelectedGridData = new DataSet();

                    //strSQL = "SELECT ITEM_ID,ITEM_DETAIL FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED;
                    //-- ANIK @ 2017/10/26
                    strSQL = "SELECT ITEM_ID, ITEM_DETAIL, ITEM_NAME FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_REPORT_GRID_ITEMS_SELECTED;
                    dsSelectedGridData = dmlService.J_ExecSqlReturnDataSet(strSQL);

                    //REINITIALIZE STRING ARRAY FOR EXPORT
                    blnFetchPAN = false;
                    strSelectedEmpID = new string[dsSelectedGridData.Tables[0].Rows.Count];
                    strSelectedEmpPAN = new string[dsSelectedGridData.Tables[0].Rows.Count];

                    for (int i = 0; i <= dsSelectedGridData.Tables[0].Rows.Count - 1; i++)
                    {
                        strSelectedGridItemsWithSearch = strSelectedGridItemsWithSearch + Convert.ToString(dsSelectedGridData.Tables[0].Rows[i]["ITEM_ID"]) + ",";
                        //FOR EXPORT TO PDF
                        strSelectedEmpID[i] = Convert.ToString(dsSelectedGridData.Tables[0].Rows[i]["ITEM_ID"]);
                        //strSelectedEmpPAN[i] = Convert.ToString(dsSelectedGridData.Tables[0].Rows[i]["ITEM_DETAIL"]);
                        //-- ANIK @ 2017/10/26
                        strSelectedEmpPAN[i] = cmnService.J_Left(Convert.ToString(dsSelectedGridData.Tables[0].Rows[i]["ITEM_NAME"]), 10);
                    }
                    strSelectedGridItemsWithSearch = strSelectedGridItemsWithSearch.Substring(0, (strSelectedGridItemsWithSearch.Length - 1));
                }
                else
                {
                    strSelectedGridItemsWithSearch = cmnService.J_GenerateDataGridViewSelectedId(grdvNewDescription);//-- Modified By Abhishek Dey On 25/10/2017 --
                    //strSelectedGridItemsWithSearch = cmnService.J_GenerateDataGridViewSelectedId(grdvNewDescription, 3);
                }


                //--------------- QUERY FOR PART A -------------
                //-- FOR pdf & Digital Signature
                if (rbnExport.Checked == true || rbnPrinter.Checked == true)
                {
                    //--
                    //+++++++++++++++++++++++++++++++++++++++++++++
                    //--------------------------------------------
                    //--MODIFIED BY DHRUB ON 2015-09-10 
                    //--------------------------------------------
                    #region EXPORT - TO PDF & DIGITAL SIGNATURE
                    //--
                    //--------------------------------------------
                    //FETCHING EMPLOYEE PAN [ IF SEARCH ENABLED ]
                    //--------------------------------------------
                    if (blnFetchPAN == true)
                    {
                        foreach (DataGridViewRow row in grdvNewDescription.Rows)//-- Modified By Abhishek Dey On 25/10/2017 --
                        {
                            if (row.Cells[0].Value != null && (bool)row.Cells[0].Value == true)
                            {
                                strSelectedEmpPAN[intEmployeePANCounter] = row.Cells[3].Value.ToString();
                                intEmployeePANCounter = intEmployeePANCounter + 1;
                            }
                        }
                    }
                    //-- 
                    intEmployeePANCounter = 0;
                    //--
                    //--------------------------------------------
                    //TAKING COMPANY TAN FROM COMBO
                    //--------------------------------------------
                    string[] strCompanyTAN = cmbCombo2.Text.Split('[', ']');
                    //--
                    //-------------------------------
                    //FETCHING LOCAL MY DOCUMENT PATH 
                    //-------------------------------
                    string strLocalPath = System.Environment.GetFolderPath(System.Environment.SpecialFolder.Personal);
                    //--
                    //-----------------------------------------------
                    //INITIALIZE FOLDER NAME REPORT TITLE WISE 
                    //-----------------------------------------------
                    #region SWITCH CASE PREVIOUSLY COMMENTED CODE
                    //switch (J_Var.J_pReportEnumIndex)
                    //{
                    //    case (int)J_Reports.CertForm1624Q:
                    //
                    #endregion
                    //--
                    strForm16OutputPDFPath = Path.Combine(strCompanyTAN[1] + "_" + cmbCombo1.Text, Path.Combine("Form16", "Temp"));
                    //--
                    //GENERATE PDF PATH
                    if (strLocalPath == txtOutputFolderPath.Text)
                        strGeneratePDFPath = Path.Combine(txtOutputFolderPath.Text, strForm16OutputPDFPath);
                    else
