                    ////////rptcls.OpenSubreport("crSubRptAnnextureB").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSubAnnexureB).Tables[0]);
                    //////// MAIN REPORT
                    //////rptService.J_PreviewReport(ref rptcls, this, strQueryString);
                    //
                    J_PreviewReportWithSubReportRDLCForm16_new("\\Reports\\crCertForm1624QPartB1819.rdlc", "DataSet1", strQueryString, null,
                                                     "crCertForm1624Q1819SalaryDetails", strSubSalaryDetails,
