                    // FOR BOOK ENTRY
                    string strSQLBookEntry = "SELECT  MST_COMPANY.COMPANY_ID          AS COMPANY_ID," +
                        "                                MST_DEDUCTEE.DEDUCTEE_ID        AS DEDUCTEE_ID," +
