                    //------------------------------------------------- 
                    // FOR SUMMARY OF TAX DEDUCTED
                    string strSubRptChlnDetails = "SELECT TRN_DEDUCTEE_DETAILS.PARTY_ID                  AS DEDUCTEE_ID," +
