                    //rptcls.OpenSubreport("crSubRptAnnextureSummaryOfPayment").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSubRptSummaryOfPaymentAnnexture).Tables[0]);
                    //rptcls.OpenSubreport("crSubRptChallanEntry").SetDataSource(dmlService.J_ExecSqlReturnDataSet(strSubRptChallanEntry).Tables[0]);
                    ////-------------------------------------------------------------------------------------
                    // MAIN REPORT
                    string[,] strArryReport = {
                                                { "StartDate", TdsMan.T_ReturnQuarterStartDate(cmbCombo2.Text, cmbCombo1.Text) },
                                                { "EndDate", TdsMan.T_ReturnQuarterEndDate(cmbCombo2.Text, cmbCombo1.Text)} };
                    J_PreviewReportWithSubReportRDLC_new("\\Reports\\crCertForm27D27EQ.rdlc", "DataSet1", strQueryString, strArryReport,
                                                         "crCertForm16A26QSummaryOfPayment", strSubRptSummaryOfPayment,
                                                         "crCertForm16A26QChallanDetails", strSubRptChlnDetails,
                                                         "crCertForm16A26QBookEntry", strSubRptBookEntry,
                                                         "crCertForm16A26QChallanEntry", strSubRptChallanEntry,
                                                         "crCertForm16A26QAnnexureSummaryOfPayment", strSubRptSummaryOfPaymentAnnexture, "");
                    ////-------------------------------------------------------------------------------------
                    //rptService.J_PreviewReport(ref rptcls, this, strQueryString);
                    //-------------------------------------------------------------------------------------
