        #region PrintEmailDetailReport
        public void PrintEmailDetailReport()
        {
            String strLowerCase = "";
            if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
            {
                strLowerCase = "LOWER";
            }
            else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
            {
                strLowerCase = "LCASE";
            }
            //--
            if (cmbCombo2.Text == T_FormNo.F24Q)
            {
                strQueryString = "SELECT TRN_EMAIL_HEADER_LOG.EMAIL_HEADER_LOG_ID AS EMAIL_HEADER_LOG_ID," +
                    "                    TRN_EMAIL_DETAIL_LOG.EMAIL_DETAIL_LOG_ID AS EMAIL_DETAIL_LOG_ID," +
                    "                    TRN_EMAIL_HEADER_LOG.EMAIL_SEND_DATETIME AS EMAIL_SEND_DATETIME," +
                    "                    MST_COMPANY.TAN_NO                       AS TAN_NO," +
                    "                    MST_COMPANY.COMPANY_NAME                 AS COMPANY_NAME," +
                    "                    TRN_BASIC_INFO.FORM_NO " + cmnService.J_ConcateSQLSyntaxOperator() + " ' - ' " + cmnService.J_ConcateSQLSyntaxOperator() + " RIGHT(MST_ASSESSMENT.FA_YEAR, 5) " + cmnService.J_ConcateSQLSyntaxOperator() + " ' - ' " + cmnService.J_ConcateSQLSyntaxOperator() + " TRN_BASIC_INFO.QTR AS FORM_FY_QTR," +
                    "                    MST_EMAIL_CERTIFICATES.CERTIFICATE_DESC  AS CERTIFICATE_DESC, " +
                    "                    " + strLowerCase + "(TRN_EMAIL_DETAIL_LOG.TO_EMAIL_ID) AS TO_EMAIL_ID, " +
                    "                    TRN_EMAIL_DETAIL_LOG.EMAIL_SEND_DATE_TIME AS EMAIL_SEND_DATE_TIME, " +
                    "                    MST_EMPLOYEE.EMPLOYEE_NAME AS PARTY_NAME, " +
                    "                    MST_EMPLOYEE.EMPLOYEE_PAN AS PARTY_PAN " +
                    "             FROM ((((((TRN_EMAIL_HEADER_LOG INNER JOIN MST_EMAIL_CERTIFICATES " +
                    "             ON   TRN_EMAIL_HEADER_LOG.EMAIL_CERTIFICATE_ID = MST_EMAIL_CERTIFICATES.EMAIL_CERTIFICATE_ID) " +
                    "             INNER JOIN TRN_BASIC_INFO " +
                    "             ON  TRN_EMAIL_HEADER_LOG.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID) " +
                    "             INNER JOIN MST_COMPANY " +
                    "             ON  MST_COMPANY.COMPANY_ID = TRN_BASIC_INFO.COMPANY_ID) " +
                    "             INNER JOIN MST_ASSESSMENT " +
                    "             ON  MST_ASSESSMENT.ASST_ID = TRN_BASIC_INFO.ASST_ID) " +
                    "             INNER JOIN TRN_EMAIL_DETAIL_LOG " +
                    "             ON TRN_EMAIL_HEADER_LOG.EMAIL_HEADER_LOG_ID = TRN_EMAIL_DETAIL_LOG.EMAIL_HEADER_LOG_ID) " +
                    "             INNER JOIN MST_EMPLOYEE " +
                    "             ON TRN_EMAIL_DETAIL_LOG.PARTY_ID = MST_EMPLOYEE.EMPLOYEE_ID) " +
                    "             WHERE TRN_EMAIL_HEADER_LOG.EMAIL_HEADER_LOG_ID  IN(" + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + ") ";
            }
            else
            {
                strQueryString = "SELECT TRN_EMAIL_HEADER_LOG.EMAIL_HEADER_LOG_ID AS EMAIL_HEADER_LOG_ID," +
                    "                    TRN_EMAIL_DETAIL_LOG.EMAIL_DETAIL_LOG_ID AS EMAIL_DETAIL_LOG_ID," +
                    "                    TRN_EMAIL_HEADER_LOG.EMAIL_SEND_DATETIME AS EMAIL_SEND_DATETIME," +
                    "                    MST_COMPANY.TAN_NO                       AS TAN_NO," +
                    "                    MST_COMPANY.COMPANY_NAME                 AS COMPANY_NAME," +
                    "                    TRN_BASIC_INFO.FORM_NO " + cmnService.J_ConcateSQLSyntaxOperator() + " ' - ' " + cmnService.J_ConcateSQLSyntaxOperator() + " RIGHT(MST_ASSESSMENT.FA_YEAR, 5) " + cmnService.J_ConcateSQLSyntaxOperator() + " ' - ' " + cmnService.J_ConcateSQLSyntaxOperator() + " TRN_BASIC_INFO.QTR AS FORM_FY_QTR," +
                    "                    MST_EMAIL_CERTIFICATES.CERTIFICATE_DESC  AS CERTIFICATE_DESC, " +
                    "                    " + strLowerCase + "(TRN_EMAIL_DETAIL_LOG.TO_EMAIL_ID) AS TO_EMAIL_ID, " +
                    "                    TRN_EMAIL_DETAIL_LOG.EMAIL_SEND_DATE_TIME AS EMAIL_SEND_DATE_TIME, " +
                    "                    MST_DEDUCTEE.DEDUCTEE_NAME AS PARTY_NAME, " +
                    "                    MST_DEDUCTEE.DEDUCTEE_PAN AS PARTY_PAN " +
                    "             FROM ((((((TRN_EMAIL_HEADER_LOG INNER JOIN MST_EMAIL_CERTIFICATES " +
                    "             ON   TRN_EMAIL_HEADER_LOG.EMAIL_CERTIFICATE_ID = MST_EMAIL_CERTIFICATES.EMAIL_CERTIFICATE_ID) " +
                    "             INNER JOIN TRN_BASIC_INFO " +
                    "             ON  TRN_EMAIL_HEADER_LOG.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID) " +
                    "             INNER JOIN MST_COMPANY " +
                    "             ON  MST_COMPANY.COMPANY_ID = TRN_BASIC_INFO.COMPANY_ID) " +
                    "             INNER JOIN MST_ASSESSMENT " +
                    "             ON  MST_ASSESSMENT.ASST_ID = TRN_BASIC_INFO.ASST_ID) " +
                    "             INNER JOIN TRN_EMAIL_DETAIL_LOG " +
                    "             ON TRN_EMAIL_HEADER_LOG.EMAIL_HEADER_LOG_ID = TRN_EMAIL_DETAIL_LOG.EMAIL_HEADER_LOG_ID) " +
                    "             INNER JOIN MST_DEDUCTEE " +
                    "             ON TRN_EMAIL_DETAIL_LOG.PARTY_ID = MST_DEDUCTEE.DEDUCTEE_ID) " +
                    "             WHERE TRN_EMAIL_HEADER_LOG.EMAIL_HEADER_LOG_ID  IN(" + cmnService.J_GenerateDataGridViewSelectedId(grdvDescription) + ") ";
            }
            crEmailDetailReport rptEmailFormatReport = new crEmailDetailReport();
            rptcls = (ReportClass)rptEmailFormatReport;

            TextObject objtxtValue;
            objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtDate"];
            objtxtValue.Text = "From : " + mskFromDate.Text + " To : " + mskToDate.Text;
            //
            //SETTING REPORT TITLE
            string[,] strArry = { { "txtReportTitle", "TDS / TCS Certificates on Email (Details)" } };
            rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);


        }
        #endregion

        #region PrintEmailSummaryReport_RDLC
        public void PrintEmailSummaryReport_RDLC()
        {
            ComboBoxItem SelectedComboItem = (ComboBoxItem)cmbCombo2.SelectedItem;
            string strComboFormNo = SelectedComboItem.Value.ToString();
            //
            strQueryString = "SELECT TRN_EMAIL_HEADER_LOG.EMAIL_HEADER_LOG_ID AS EMAIL_HEADER_LOG_ID," +
                "                    TRN_EMAIL_HEADER_LOG.EMAIL_SEND_DATETIME AS EMAIL_SEND_DATETIME," +
                "                    MST_COMPANY.TAN_NO                       AS TAN_NO," +
                "                    MST_COMPANY.COMPANY_NAME                 AS COMPANY_NAME," +
                "                    TRN_BASIC_INFO.FORM_NO " + cmnService.J_ConcateSQLSyntaxOperator() + " ' - ' " + cmnService.J_ConcateSQLSyntaxOperator() + " RIGHT(MST_ASSESSMENT.FA_YEAR, 5) " + cmnService.J_ConcateSQLSyntaxOperator() + " ' - ' " + cmnService.J_ConcateSQLSyntaxOperator() + " TRN_BASIC_INFO.QTR AS FORM_FY_QTR," +
                "                    MST_EMAIL_CERTIFICATES.CERTIFICATE_DESC  AS CERTIFICATE_DESC, " +
                "                    COUNT(TRN_EMAIL_DETAIL_LOG.EMAIL_DETAIL_LOG_ID) AS EMAIL_COUNT " +
                "             FROM (((((TRN_EMAIL_HEADER_LOG INNER JOIN MST_EMAIL_CERTIFICATES " +
                "             ON   TRN_EMAIL_HEADER_LOG.EMAIL_CERTIFICATE_ID = MST_EMAIL_CERTIFICATES.EMAIL_CERTIFICATE_ID) " +
                "             INNER JOIN TRN_BASIC_INFO " +
                "             ON  TRN_EMAIL_HEADER_LOG.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID) " +
                "             INNER JOIN MST_COMPANY " +
                "             ON  MST_COMPANY.COMPANY_ID = TRN_BASIC_INFO.COMPANY_ID) " +
                "             INNER JOIN MST_ASSESSMENT " +
                "             ON  MST_ASSESSMENT.ASST_ID = TRN_BASIC_INFO.ASST_ID) " +
                "             INNER JOIN TRN_EMAIL_DETAIL_LOG " +
                "             ON TRN_EMAIL_HEADER_LOG.EMAIL_HEADER_LOG_ID = TRN_EMAIL_DETAIL_LOG.EMAIL_HEADER_LOG_ID) " +
                "             WHERE TRN_EMAIL_HEADER_LOG.EMAIL_SEND_DATETIME >= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(mskFromDate) + cmnService.J_DateOperator() + " " +
                "             AND   TRN_EMAIL_HEADER_LOG.EMAIL_SEND_DATETIME <= " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(mskToDate) + cmnService.J_DateOperator() + " ";
            if (cmbCombo1.SelectedIndex > 0)
            {
                strQueryString = strQueryString + " AND TRN_BASIC_INFO.COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex));
            }
            //--
            if (cmbCombo2.SelectedIndex > 0)
            {
                strQueryString = strQueryString + " AND TRN_BASIC_INFO.FORM_NO = '" + strComboFormNo + "' ";
            }
            //--
            strQueryString = strQueryString + " GROUP BY TRN_EMAIL_HEADER_LOG.EMAIL_HEADER_LOG_ID, " +
                "             TRN_EMAIL_HEADER_LOG.EMAIL_SEND_DATETIME, " +
                "             MST_COMPANY.TAN_NO, " +
                "             MST_COMPANY.COMPANY_NAME, " +
                "             TRN_BASIC_INFO.FORM_NO " + cmnService.J_ConcateSQLSyntaxOperator() + " ' - ' " + cmnService.J_ConcateSQLSyntaxOperator() + " RIGHT(MST_ASSESSMENT.FA_YEAR, 5) " + cmnService.J_ConcateSQLSyntaxOperator() + " ' - ' " + cmnService.J_ConcateSQLSyntaxOperator() + " TRN_BASIC_INFO.QTR," +
                "             MST_EMAIL_CERTIFICATES.CERTIFICATE_DESC " +
                "             ORDER BY EMAIL_SEND_DATETIME DESC";

            //crEmailSummaryReport rptEmailSummaryReport = new crEmailSummaryReport();
            //rptcls = (ReportClass)rptEmailSummaryReport;

            //TextObject objtxtValue;
            //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[2].ReportObjects["txtDate"];
            //objtxtValue.Text = "From : " + mskFromDate.Text + " To : " + mskToDate.Text;
            ////
            //objtxtValue = (TextObject)rptcls.ReportDefinition.Sections[4].ReportObjects["txtFilter"];
            string strReportFooter = "";
            if (cmbCombo1.SelectedIndex > 0)
                strReportFooter = "Selected Company : " + cmbCombo1.Text + "\n";
            if (cmbCombo2.SelectedIndex > 0)
                strReportFooter = strReportFooter + "Selected Form : " + cmbCombo2.Text;
            ////
            ////SETTING REPORT TITLE
            //string[,] strArry = { { "txtReportTitle", "Summary of TDS / TCS Certificates on Email" } };
            //rptService.J_PreviewReport(ref rptcls, this, strQueryString, strArry);
            //RDLC Report
            string[,] strArryEmailSummaryReport = { {"HeaderReportName", "Summary of TDS / TCS Certificates on Email"  },
                                                {"ReportFooter", strReportFooter  },
                                                {"HeaderFromToDate", "From : " + mskFromDate.Text + " To : " + mskToDate.Text  }
                                                };
            J_PreviewReportRDLC("\\Reports\\crEmailSummaryReport.rdlc", "DataSet1", strQueryString, strArryEmailSummaryReport);


        }
        #endregion

