        #region J_GenerateDataGridViewConcateItems
        public string J_GenerateDataGridViewConcateItems(DataGridView dataGridView)
        {
            string strItem = "";
            if (dataGridView.RowCount > 0)
            {
                foreach (DataGridViewRow row in dataGridView.Rows)
                    if (row.Cells[0].Value != null && (bool)row.Cells[0].Value == true)
                        strItem = strItem + ",'" + row.Cells[1].Value.ToString() + row.Cells[2].Value.ToString() + "'";

                if (strItem.Length > 0)
                    strItem = cmnService.J_Mid(strItem, 1, strItem.Length - 1);
            }
            return strItem;
        }
