        private void UpdateTaxCreditAmount(string strEmployeeIds)
        {
            double dblCalculatedTaxCredit = 0;
            double dblCalculatedECess = 0;
            double dblCalculatedSurcharge = 0;
            double dblTaxonTotalIncomeB4TaxCredit = 0;
            string strCategory = string.Empty, strSection115BAC = string.Empty;
            try
            {
                strSQL = @"SELECT TRN_SALARY_DETAILS.SALARY_DETAILS_ID,
                                  TRN_BASIC_INFO.ASST_ID,
                                  TRN_SALARY_DETAILS.TOTAL_INCOME,                                  
                                  TRN_SALARY_DETAILS.TAX_CREDIT_AMOUNT,
                                  MST_EMPLOYEE.CATEGORY,
                                  TRN_SALARY_DETAILS.SECTION_115BAC_FLAG
                            FROM  (((TRN_SALARY_DETAILS
                            INNER JOIN  TRN_BASIC_INFO
                            ON TRN_SALARY_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID)
                            INNER JOIN MST_EMPLOYEE
                            ON MST_EMPLOYEE.EMPLOYEE_ID = TRN_SALARY_DETAILS.EMPLOYEE_ID)
                            INNER JOIN  MST_ASSESSMENT
                            ON MST_ASSESSMENT.ASST_ID = TRN_BASIC_INFO.ASST_ID) 
                            WHERE MST_EMPLOYEE.EMPLOYEE_ID IN (" + strEmployeeIds + ") " +
                            " AND    MST_ASSESSMENT.ASST_ID       = " + Convert.ToInt32(Support.GetItemData(cmbCombo1, cmbCombo1.SelectedIndex)) + " " +
                            " AND    TRN_BASIC_INFO.FORM_NO       ='" + T_FormNo.F24Q + "' ";

                DataSet dsSalaryDetails = new DataSet();
                dsSalaryDetails = dmlService.J_ExecSqlReturnDataSet(strSQL);

                //double dblCalculatedTaxCredit = 0;
                //double dblCalculatedECess = 0;
                //double dblCalculatedSurcharge = 0;
                //string strCategory = string.Empty;
                //int i = 0;
                foreach (DataRow dr in dsSalaryDetails.Tables[0].Rows)
                {
                    //i = i + 1;
                    //TDSMAN.Classes.TDSMAN.T_ROW_COUNTER = i;
                    if (Convert.ToDouble(dr["TAX_CREDIT_AMOUNT"].ToString()) == 0)
                    {
                        if (string.IsNullOrEmpty(Convert.ToString(dr["CATEGORY"].ToString())))
                            strCategory = "G";
                        else
                            strCategory = Convert.ToString(dr["CATEGORY"].ToString());
                        //-- 2020/07/14
                        strSection115BAC = Convert.ToString(dr["SECTION_115BAC_FLAG"].ToString());
                        //--
                        string strAsst = Convert.ToString(dr["ASST_ID"].ToString());
                        int intAsst = Convert.ToInt32(dr["ASST_ID"].ToString());
                        double dblTotalIncome = Convert.ToDouble(dr["TOTAL_INCOME"].ToString());

                        //if (i > 1098)
                        //{
                        //    TdsMan.CalculateIncomeTaxAmount(Convert.ToInt32(dr["ASST_ID"].ToString()), strCategory, Convert.ToDouble(dr["TOTAL_INCOME"].ToString()), out dblCalculatedECess, out dblCalculatedSurcharge, out dblCalculatedTaxCredit);
                        //}
                        //else
                        TdsMan.CalculateIncomeTaxAmount(Convert.ToInt32(dr["ASST_ID"].ToString()), 
                                                        strCategory, 
                                                        Convert.ToDouble(dr["TOTAL_INCOME"].ToString()),
                                                        strSection115BAC,
                                                        out dblCalculatedECess, 
                                                        out dblCalculatedSurcharge, 
                                                        out dblCalculatedTaxCredit, 
                                                        out dblTaxonTotalIncomeB4TaxCredit);

                        // UPDATE TAX_CREDIT_AMOUNT
                        if (dblCalculatedTaxCredit > 0)
                        {
                            strSQL = @"UPDATE TRN_SALARY_DETAILS
                                      SET TAX_CREDIT_AMOUNT = " + dblCalculatedTaxCredit + @"
                                    WHERE SALARY_DETAILS_ID = " + Convert.ToInt32(dr["SALARY_DETAILS_ID"].ToString());

                            dmlService.J_ExecSql(strSQL);
                        }
                    }
                }
            }
            catch (Exception err)
            {
                //cmnService.J_UserMessage(TDSMAN.Classes.TDSMAN.T_ROW_COUNTER.ToString());
                //cmnService.J_UserMessage(err.Message);
                return;
            }
            //public double CalculateIncomeTaxAmount(int AsstId, string Category, double TaxableAmount, out double ECess, out double Surcharge, out double TaxCredit)        

        }
