        #region cmbCombo1_KeyDown
        private void cmbCombo1_KeyDown(object sender, KeyEventArgs e)
        {
            try
            {
                if(J_Var.J_pReportEnumIndex == (int)J_Reports.QuarterWiseReport
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.EmloyeeList
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.ReceiptNoMaster
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.DeducteeList
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.CompanyDetails
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.Form24QSDComparisionReport
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.PartyEmployeeWiseDetail
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.PartyEmployeeWiseSummary
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.ChallanReport
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.ChallanWiseQueryReport
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.QuarterWiseChallanReport
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.QuarterWiseDeducteeReport
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.QuarterWiseReport
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.DeducteeWiseQueryReport
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.DeductionsSummary
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.ITRForm
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.DeducteeEntriesWithoutChallan
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.EmailSummaryReport
                    || J_Var.J_pReportEnumIndex == (int)J_Reports.EmailDetailReport)
                {
                    if (e.KeyCode == Keys.F1)
                    {
                        FormTrn.TrnTANSearch Tan = new TrnTANSearch("RptDialog");
                        Tan.ShowDialog();
                        //--------------
                        if (TDSMAN.Classes.TDSMAN.T_pTAN != "")
                            cmbCombo1.Text = TDSMAN.Classes.TDSMAN.T_pTAN;
                    }
                }
            }
            catch (Exception err)
            {

            }
        }
