        #region J_PreviewReportWithSubReportRDLC
        public bool J_PreviewReportWithSubReportRDLC(string ReportPath, string DataSetName, string SQLQueryString, string[,] ReportParameterNameANDValue,
                                                     string SubReportPath1, string SubreportSQL1,
                                                     string SubReportPath2, string SubreportSQL2,
                                                     string SubReportPath3, string SubreportSQL3,
                                                     string SubReportPath4, string SubreportSQL4,
                                                     string ExportPDFPath)
        {
            RptPreviewRDLC RptPreview = new RptPreviewRDLC();
            RptPreview.reportViewer1.ProcessingMode = ProcessingMode.Local;
            //RptPreview.reportViewer1.LocalReport.ReportPath = (Application.StartupPath + "\\Reports\\crCompanyList.rdlc");
            RptPreview.reportViewer1.LocalReport.ReportPath = (Application.StartupPath + ReportPath);
            //
            DataSet dsDataPrint = new DataSet();
            dsDataPrint = dmlService.J_ExecSqlReturnDataSet(SQLQueryString);
            //
            if (dsDataPrint.Tables[0].Rows.Count > 0)
            {
                if (ReportParameterNameANDValue != null)
                {
                    for (int iCounter = 0; iCounter <= ReportParameterNameANDValue.GetUpperBound(0); iCounter++)
                    {
                        ReportParameter rptParameter = new ReportParameter(ReportParameterNameANDValue[iCounter, 0], ReportParameterNameANDValue[iCounter, 1]);
                        RptPreview.reportViewer1.LocalReport.SetParameters(rptParameter);
                    }
                }
                //
                ReportDataSource rds = new ReportDataSource(DataSetName.ToString(), dsDataPrint.Tables[0]);
                RptPreview.reportViewer1.LocalReport.DataSources.Clear();
                RptPreview.reportViewer1.LocalReport.Refresh();
                RptPreview.reportViewer1.LocalReport.DataSources.Add(rds);
                ////// Add Subreport Processing Event
                //////RptPreview.reportViewer1.LocalReport.SubreportProcessing += new SubreportProcessingEventHandler(SubreportProcessingEvent);
                /////Attach Subreport Processing Event Here
                if (SubReportPath1 != "")
                    RptPreview.reportViewer1.LocalReport.SubreportProcessing += (sender, e) => LocalReport_SubreportProcessing(sender, e, SubReportPath1, SubreportSQL1);
                //
                if (SubReportPath2 != "")
                    RptPreview.reportViewer1.LocalReport.SubreportProcessing += (sender, e) => LocalReport_SubreportProcessing(sender, e, SubReportPath2, SubreportSQL2);
                //
                if (SubReportPath3 != "")
                    RptPreview.reportViewer1.LocalReport.SubreportProcessing += (sender, e) => LocalReport_SubreportProcessing(sender, e, SubReportPath3, SubreportSQL3);
                //
                if (SubReportPath4 != "")
                    RptPreview.reportViewer1.LocalReport.SubreportProcessing += (sender, e) => LocalReport_SubreportProcessing(sender, e, SubReportPath4, SubreportSQL4);
                //
                RptPreview.reportViewer1.RefreshReport();
                //
                if (ExportPDFPath == "")
                {
                    RptPreview.MdiParent = this.MdiParent;
                    RptPreview.Show();
                    //RptPreview.reportViewer1.PrintingBegin();
                    //RptPreview.reportViewer1.DisplayMode = DisplayMode.PrintLayout;
                }
                else
                {
                    ExportRDLCToPDF(RptPreview.reportViewer1.LocalReport, ExportPDFPath);
                }
                return true;
            }
            else
            {
                cmnService.J_UserMessage("Record not found.\nPreview not available");
                return false;
            }

        }
        #endregion


        #region J_PreviewReportWithSubReportRDLC_new
        public bool J_PreviewReportWithSubReportRDLCForm16_new(
            string ReportPath, string DataSetName, string SQLQueryString,
            string[,] ReportParameterNameANDValue,
            string SubReport1, string SubreportSQL1,
            string SubReport2, string SubreportSQL2,
            string SubReport3, string SubreportSQL3,
            string SubReport4, string SubreportSQL4,
            string SubReport5, string SubreportSQL5,
            string ExportPDFPath)
        {
            RptPreviewRDLC RptPreview = new RptPreviewRDLC();
            RptPreview.reportViewer1.ProcessingMode = ProcessingMode.Local;
            RptPreview.reportViewer1.LocalReport.ReportPath = Application.StartupPath + ReportPath;

            // Fetch main report data
            DataSet dsDataPrint = dmlService.J_ExecSqlReturnDataSet(SQLQueryString);

            if (dsDataPrint.Tables[0].Rows.Count > 0)
            {
                // Set report parameters if provided
                if (ReportParameterNameANDValue != null)
                {
                    for (int iCounter = 0; iCounter <= ReportParameterNameANDValue.GetUpperBound(0); iCounter++)
                    {
                        ReportParameter rptParameter = new ReportParameter(
                            ReportParameterNameANDValue[iCounter, 0],
                            ReportParameterNameANDValue[iCounter, 1]
                        );
                        RptPreview.reportViewer1.LocalReport.SetParameters(rptParameter);
                    }
                }

                // Bind main report data
                ReportDataSource rds = new ReportDataSource(DataSetName, dsDataPrint.Tables[0]);
                RptPreview.reportViewer1.LocalReport.DataSources.Clear();
                RptPreview.reportViewer1.LocalReport.DataSources.Add(rds);
                RptPreview.reportViewer1.LocalReport.Refresh();

                // Attach a single SubreportProcessing event handler
                RptPreview.reportViewer1.LocalReport.SubreportProcessing += (sender, e) =>
                {
                    Console.WriteLine("Subreport triggered: " + e.ReportPath);
                    string subReportSQL = null;

                    // Identify the correct SQL query for each subreport
                    if (e.ReportPath == SubReport1) subReportSQL = SubreportSQL1;
                    else if (e.ReportPath == SubReport2) subReportSQL = SubreportSQL2;
                    else if (e.ReportPath == SubReport3) subReportSQL = SubreportSQL3;
                    else if (e.ReportPath == SubReport4) subReportSQL = SubreportSQL4;
                    else if (e.ReportPath == SubReport5) subReportSQL = SubreportSQL5;

                    if (!string.IsNullOrEmpty(subReportSQL))
                    {
                        LocalReport_SubreportProcessingForm16(sender, e, subReportSQL);
                    }
                    else
                    {
                        Console.WriteLine($"No SQL assigned for {e.ReportPath}");
                    }
                };

                // Refresh and show report
                RptPreview.reportViewer1.RefreshReport();
                if (string.IsNullOrEmpty(ExportPDFPath))
                {
                    RptPreview.MdiParent = this.MdiParent;
                    RptPreview.Show();
                }
                else
                {
                    ExportRDLCToPDF(RptPreview.reportViewer1.LocalReport, ExportPDFPath);
                }
                return true;
            }
            else
            {
                cmnService.J_UserMessage("Record not found.\nPreview not available");
                return false;
            }
        }
        #endregion


