        private void LocalReport_SubreportProcessing_notinuse(object sender, SubreportProcessingEventArgs e, string subReportPath, string subReportSQL)
        {
            // Get EmployeeID parameter from the main report
            int PartyID = Convert.ToInt32(e.Parameters["DEDUCTEE_ID"].Values[0]);
            Console.WriteLine($"EmployeeID received: {PartyID}");
            // Fetch subreport data
            DataSet dsSubReport = dmlService.J_ExecSqlReturnDataSet(subReportSQL);
            Console.WriteLine($"No data found for {e.ReportPath}");
            // Filter subreport data based on EmployeeID
            DataTable filteredTable = dsSubReport.Tables[0].AsEnumerable()
                                      .Where(row => row.Field<int>("DEDUCTEE_ID") == PartyID)
                                      .CopyToDataTable();
            Console.WriteLine($"Filtered rows for {e.ReportPath}: {filteredTable.Rows.Count}");
            // Pass filtered data to subreport
            e.DataSources.Add(new ReportDataSource("DataSet1", filteredTable));
        }
        private void LocalReport_SubreportProcessing(object sender, SubreportProcessingEventArgs e, string subReportPath, string subReportSQL)
        {
            try
            {
                // Get DEDUCTEE_ID parameter from the main report
                int PartyID = Convert.ToInt32(e.Parameters["DEDUCTEE_ID"].Values[0]);
                Console.WriteLine($"DEDUCTEE_ID received: {PartyID}");

                // Fetch subreport data from SQL
                DataSet dsSubReport = dmlService.J_ExecSqlReturnDataSet(subReportSQL);

                if (dsSubReport == null || dsSubReport.Tables.Count == 0 || dsSubReport.Tables[0].Rows.Count == 0)
                {
                    Console.WriteLine($"No data returned from SQL for subreport {e.ReportPath}");
                    e.DataSources.Add(new ReportDataSource("DataSet1", new DataTable())); // Pass empty dataset
                    return;
                }

                // Filter subreport data
                var filteredRows = dsSubReport.Tables[0].AsEnumerable()
                                         .Where(row => row.Field<int>("DEDUCTEE_ID") == PartyID);

                DataTable filteredTable;

                if (filteredRows.Any())
                {
                    filteredTable = filteredRows.CopyToDataTable();
                }
                else
                {
                    Console.WriteLine($"No matching DEDUCTEE_ID={PartyID} found for subreport {e.ReportPath}");
                    filteredTable = dsSubReport.Tables[0].Clone(); // Create empty table with same schema
                }

                // Bind filtered data to the subreport
                e.DataSources.Add(new ReportDataSource("DataSet1", filteredTable));
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error in SubreportProcessing: {ex.Message}");
                e.DataSources.Add(new ReportDataSource("DataSet1", new DataTable())); // Fail-safe
            }
        }

