        #region ExportRDLCToPDF
        private void ExportRDLCToPDF(LocalReport report, string exportFilePath)
        {
            try
            {
                string deviceInfo = @"<DeviceInfo>
                                <OutputFormat>PDF</OutputFormat>
                                <PageWidth>8.27in</PageWidth>
                                <PageHeight>11.69in</PageHeight>
                                <MarginTop>0.25in</MarginTop>
                                <MarginLeft>0.25in</MarginLeft>
                                <MarginRight>0.25in</MarginRight>
                                <MarginBottom>0.25in</MarginBottom>
                              </DeviceInfo>";

                Warning[] warnings;
                string[] streamIds;
                string mimeType;
                string encoding;
                string filenameExtension;

                // Render the report to a byte array
                byte[] bytes = report.Render(
                    "PDF", deviceInfo,
                    out mimeType, out encoding,
                    out filenameExtension,
                    out streamIds, out warnings);

                // Write the PDF to the file system
                using (FileStream fs = new FileStream(exportFilePath, FileMode.Create))
                {
                    fs.Write(bytes, 0, bytes.Length);
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show("Failed to export PDF: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }
        #endregion

